window.DSFB_EXTRA_QUESTIONS=[{"id":"s5-q001","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":1,"level":"真题同型 · 500 题强化","question":"In the data–information–knowledge–wisdom hierarchy, what moves data up the hierarchy?","questionZh":"在“数据—信息—知识—智慧”层级中，是什么让数据往上走？","options":["Deleting records","Storing data in the cloud","Collecting more raw data only","Aggregation and processing, increasing utility"],"optionZh":["删除记录","把数据存到云端","只收集更多原始数据","汇总与处理，提升效用"],"answer":3,"explanation":"D 正确：讲义第 12–13 页：数据经过汇总和处理变成信息，再经认知加工成为知识和智慧，效用逐级上升。算法就是把输入变成输出的有限步骤。","lessonId":"dsfb-01","lessonPage":12,"lessonPageTitle":"InternalExternal"},{"id":"s5-q002","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":2,"level":"真题同型 · 500 题强化","question":"Which pair of data types is discussed in the lecture and revisited in Chapter 9 on causal ML?","questionZh":"讲义讨论的、并在第 9 章因果机器学习中再次出现的是哪一对数据类型？","options":["Tabular versus non-tabular data","Internal versus external data","Experimental versus observational data","Real-time versus historical data"],"optionZh":["表格与非表格数据","内部与外部数据","实验数据与观察数据","实时与历史数据"],"answer":2,"explanation":"C 正确：讲义第 14 页特别标注了“Cfr. Chapter 9”。实验（RCT）数据可以直接估计处理效应，观察数据则有混杂偏差。","lessonId":"dsfb-01","lessonPage":14,"lessonPageTitle":"What are different types of data?"},{"id":"s5-q003","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":3,"level":"真题同型 · 500 题强化","question":"How do Provost and Fawcett define data science?","questionZh":"Provost 和 Fawcett 如何定义数据科学？","options":["Methods for storing data in databases","Methods for extracting useful information and knowledge from data","The study of computer hardware","A synonym for business intelligence dashboards"],"optionZh":["在数据库中存储数据的方法","从数据中提取有用信息和知识的方法","研究计算机硬件","商业智能仪表盘的同义词"],"answer":1,"explanation":"B 正确：讲义第 18 页引用《Data Science for Business》第 1 页。课程关注的是用数据提升商业决策的效率。","lessonId":"dsfb-01","lessonPage":18,"lessonPageTitle":"What is data science?"},{"id":"s5-q004","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":4,"level":"真题同型 · 500 题强化","question":"What is the key idea of machine learning according to the lecture?","questionZh":"根据讲义，机器学习的核心思想是什么？","options":["A human programs the function f step by step.","Machine learning only works on images.","Machine learning does not need data.","A computer learns the function f in Y = f(X) from data, instead of a human programming it."],"optionZh":["人一步步编写函数 f。","机器学习只适用于图像。","机器学习不需要数据。","计算机从数据中学习 Y = f(X) 中的函数 f，而不是由人编写。"],"answer":3,"explanation":"D 正确：讲义第 23 页：识别欺诈交易、分析核磁共振图像、自动驾驶等复杂任务很难手工编程，所以让计算机从数据中学习。","lessonId":"dsfb-01","lessonPage":23,"lessonPageTitle":"What is Machine Learning?"},{"id":"s5-q005","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":5,"level":"真题同型 · 500 题强化","question":"Which type of learning uses partially labelled data (X, some Y)?","questionZh":"哪种学习使用部分带标签的数据（X，部分 Y）？","options":["Supervised learning","Unsupervised learning","Semi-supervised learning","Descriptive statistics"],"optionZh":["监督学习","无监督学习","半监督学习","描述性统计"],"answer":2,"explanation":"C 正确：讲义第 36 页：监督学习用 (X, Y)，无监督学习只有 X，半监督学习有 X 和部分 Y，另外还有强化学习。","lessonId":"dsfb-01","lessonPage":36,"lessonPageTitle":"What is Machine Learning?"},{"id":"s5-q006","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":6,"level":"真题同型 · 500 题强化","question":"According to Shmueli (2010), \"To explain or to predict?\", what distinguishes the two approaches to a regression model?","questionZh":"根据 Shmueli（2010）的《To Explain or to Predict?》，回归模型的两种用法区别在哪里？","options":["Explanation and prediction always use the same evaluation.","The statistics approach focuses on the model f (explaining relations), the machine learning approach on the predictions Ŷ.","Machine learning never uses regression models.","Statistics only predicts the future."],"optionZh":["解释和预测总用相同的评估方式。","统计学方法关注模型 f（解释关系），机器学习方法关注预测值 Ŷ。","机器学习从不使用回归模型。","统计学只预测未来。"],"answer":1,"explanation":"B 正确：讲义第 32–33 页：“Purpose: f or Ŷ?”。这也对应第 4 章的单样本方法（解释）与分割样本方法（预测）之分，以及第 9 章 DAG 与 PO 框架之分。","lessonId":"dsfb-01","lessonPage":32,"lessonPageTitle":"What is Machine Learning?"},{"id":"s5-q007","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":7,"level":"真题同型 · 500 题强化","question":"How are AI, machine learning, deep learning and LLMs related in the lecture's diagram?","questionZh":"讲义的图中，AI、机器学习、深度学习和大语言模型是什么关系？","options":["They are four unrelated fields.","Deep learning contains machine learning.","LLMs contain AI.","They are nested: LLMs ⊂ deep learning ⊂ machine learning ⊂ AI."],"optionZh":["它们是四个无关的领域。","深度学习包含机器学习。","大语言模型包含 AI。","它们是嵌套的：LLM ⊂ 深度学习 ⊂ 机器学习 ⊂ AI。"],"answer":3,"explanation":"D 正确：讲义第 37 页的同心圆图。LLM 是深度学习的一种，深度学习是机器学习的一种，机器学习是 AI 的一种。","lessonId":"dsfb-01","lessonPage":37,"lessonPageTitle":"What is Machine Learning?"},{"id":"s5-q008","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":8,"level":"真题同型 · 500 题强化","question":"Which three types of data analytics are distinguished from an application perspective?","questionZh":"从应用角度区分哪三类数据分析？","options":["Supervised, unsupervised and reinforcement","Tabular, text and image","Descriptive, predictive and prescriptive","Internal, external and real-time"],"optionZh":["监督、无监督和强化","表格、文本和图像","描述性、预测性和规范性","内部、外部和实时"],"answer":2,"explanation":"C 正确：讲义第 41 页。描述性找模式，预测性预测结果，规范性把决策纳入分析、直接优化决策（第 9、10、11 章）。","lessonId":"dsfb-01","lessonPage":41,"lessonPageTitle":"How can machine learning be used for business decision-making?"},{"id":"s5-q009","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":9,"level":"真题同型 · 500 题强化","question":"According to the lecture, how can machine learning be used for business decision-making?","questionZh":"根据讲义，如何把机器学习用于商业决策？","options":["By buying the most expensive software","By transforming a decision-making problem into a machine learning task, which requires knowledge of the problem, ML tasks, methods and available data, as well as creativity","By replacing all managers","By maximizing accuracy on the training set"],"optionZh":["购买最贵的软件","把决策问题转化为机器学习任务，这需要了解问题、机器学习任务、方法、可用数据，还需要创造力","取代所有经理","最大化训练集准确率"],"answer":1,"explanation":"B 正确：讲义第 42 页。D 是常见误区：训练集表现说明不了泛化能力，也不等于业务价值。","lessonId":"dsfb-01","lessonPage":42,"lessonPageTitle":"How can machine learning be used for business decision-making?"},{"id":"s5-q010","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":10,"level":"真题同型 · 500 题强化","question":"Which is NOT listed as a key challenge or limitation of using machine learning in business?","questionZh":"以下哪项不是讲义列出的机器学习在商业应用中的关键挑战或局限？","options":["Data","Interpretability and explainability","Feedback loops","The impossibility of using more than one variable"],"optionZh":["数据","可解释性","反馈回路","不能使用超过一个变量"],"answer":3,"explanation":"D 显然不是。讲义第 44 页还列出了知识、创造力和技术能力。反馈回路在第 9 章的流失案例中详细讨论。","lessonId":"dsfb-01","lessonPage":44,"lessonPageTitle":"What are key challenges and limitations of using machine learning?"},{"id":"s5-q011","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":11,"level":"真题同型 · 500 题强化","question":"Which is the correct order of the main phases in the data science process model?","questionZh":"数据科学流程模型中主要阶段的正确顺序是什么？","options":["Analytics → Preprocessing → Identify business problem → Postprocessing","Postprocessing → Analytics → Preprocessing","Preprocessing → Postprocessing → Analytics","Identify business problem and design solution → Preprocessing → Analytics → Postprocessing"],"optionZh":["分析 → 预处理 → 识别业务问题 → 后处理","后处理 → 分析 → 预处理","预处理 → 后处理 → 分析","识别业务问题并设计方案 → 预处理 → 分析 → 后处理"],"answer":3,"explanation":"D 正确：讲义第 46 页：识别业务问题 → 设计分析方案 → 识别数据源 → 选择、清洗、转换数据（预处理）→ 分析数据 → 解释、评估、部署（后处理）。过程是迭代的。","lessonId":"dsfb-01","lessonPage":46,"lessonPageTitle":"Steps in developing a data-driven analytics solution, i.e., methodology:"},{"id":"s5-q012","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":12,"level":"真题同型 · 500 题强化","question":"What do the letters of SEMMA stand for?","questionZh":"SEMMA 的字母分别代表什么？","options":["Select, Evaluate, Merge, Monitor, Apply","Sample, Explore, Modify, Model, Assess","Scale, Encode, Model, Measure, Act","Sample, Estimate, Model, Monitor, Adjust"],"optionZh":["选择、评估、合并、监控、应用","抽样、探索、修改、建模、评估","缩放、编码、建模、测量、行动","抽样、估计、建模、监控、调整"],"answer":1,"explanation":"B 正确：讲义第 48 页：SEMMA 是 SAS 的流程模型，另一个常见的是 CRISP-DM（跨行业数据挖掘标准流程）。","lessonId":"dsfb-01","lessonPage":48,"lessonPageTitle":"Data science process model"},{"id":"s5-q013","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":13,"level":"真题同型 · 500 题强化","question":"Why is customer retention important according to the churn case in Chapter 1?","questionZh":"根据第 1 章的流失案例，为什么客户保留很重要？","options":["Because new customers are always more profitable","Because churn has no impact on revenue","Because long-term customers never need service","Because attracting new customers is 5 to 6 times more expensive than retaining existing ones, and long-term customers generate higher profits"],"optionZh":["因为新客户总是更赚钱","因为流失不影响收入","因为老客户从不需要服务","因为获取新客户的成本是保留老客户的 5 到 6 倍，而且长期客户带来更高利润"],"answer":3,"explanation":"D 正确：讲义第 50–51 页：老客户对竞争对手的营销不那么敏感、服务成本更低，还可能通过口碑带来新客户。","lessonId":"dsfb-01","lessonPage":50,"lessonPageTitle":"Customer churn: outflow of customers from the customer base"},{"id":"s5-q014","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":14,"level":"真题同型 · 500 题强化","question":"A churn prediction model has outcome \"churn\" or \"no churn\". Which type of task is this?","questionZh":"某流失预测模型的结果是“流失”或“不流失”。这是哪类任务？","options":["Regression","Clustering","Binary classification","Association analysis"],"optionZh":["回归","聚类","二分类","关联分析"],"answer":2,"explanation":"C 正确：讲义第 57 页。可用逻辑回归、决策树等方法。讲义还问了“线性回归行不行”，见下一页的讨论。","lessonId":"dsfb-01","lessonPage":57,"lessonPageTitle":"Customer churn prediction"},{"id":"s5-q015","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":15,"level":"真题同型 · 500 题强化","question":"Which is a problem of using linear regression estimated with OLS for a binary churn target?","questionZh":"用 OLS 估计的线性回归来预测二元流失目标，有什么问题？","options":["The output is not guaranteed to lie between 0 and 1, and errors are not normally distributed.","OLS cannot be computed.","The model has no coefficients.","The model always predicts exactly 0 or 1."],"optionZh":["输出不保证在 0 到 1 之间，误差也不服从正态分布。","OLS 无法计算。","模型没有系数。","模型总是恰好预测 0 或 1。"],"answer":0,"explanation":"A 正确：讲义第 60 页。逻辑回归加一个 sigmoid 变换，让输出始终在 0–1 之间，可解释为概率（第 61 页）。","lessonId":"dsfb-01","lessonPage":60,"lessonPageTitle":"-7 -5 -3 -1 1 3 5 7"},{"id":"s5-q016","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":16,"level":"真题同型 · 500 题强化","question":"How are the parameters of a logistic regression model estimated?","questionZh":"逻辑回归模型的参数如何估计？","options":["With OLS, minimizing squared errors","By k-means","By maximum likelihood, i.e., maximizing the probability of observing the sample at hand","By setting all betas to zero"],"optionZh":["用 OLS，最小化平方误差","用 k-means","用最大似然，即最大化观察到当前样本的概率","把所有 beta 设为 0"],"answer":2,"explanation":"C 正确：讲义第 62 页：取负对数似然，再用 Newton-Raphson 等方法最小化。这与第 6 章中“交叉熵等价于最大似然”相呼应。","lessonId":"dsfb-01","lessonPage":62,"lessonPageTitle":"Analyze data: objective function"},{"id":"s5-q017","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":17,"level":"真题同型 · 500 题强化","question":"Which statement about white-box versus black-box models is TRUE?","questionZh":"关于白盒模型与黑盒模型，哪项说法正确？","options":["Linear regression is a black-box model.","Support vector machines are white-box models.","Black-box models are always more accurate.","Linear regression is a white-box model, whereas a support vector machine is a black-box model."],"optionZh":["线性回归是黑盒模型。","支持向量机是白盒模型。","黑盒模型总是更准确。","线性回归是白盒模型，支持向量机是黑盒模型。"],"answer":3,"explanation":"D 正确：讲义第 59 页。白盒模型的系数可以直接解读，黑盒模型能拟合非线性关系但难以解释。C 错：哪个更准取决于数据，第 5 章的偏差-方差讨论说明了这一点。","lessonId":"dsfb-01","lessonPage":59,"lessonPageTitle":"Y Y Y"},{"id":"s5-q018","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":18,"level":"真题同型 · 500 题强化","question":"Which warning about models is given in the lecture?","questionZh":"讲义对“模型”给出了什么提醒？","options":["A model is a simplified or idealized representation of (part of) reality.","A model is a perfect copy of reality.","Only mathematical models are models.","A model cannot be used for decisions."],"optionZh":["模型是对（部分）现实的简化或理想化表示。","模型是现实的完美复制。","只有数学模型才算模型。","模型不能用于决策。"],"answer":0,"explanation":"A 正确：讲义第 28 页：模型有很多种（商业、图形、物理、数学、仿真……），都是简化，因此都会犯错（呼应“所有模型都是错的，但有些是有用的”）。","lessonId":"dsfb-01","lessonPage":28,"lessonPageTitle":"What is Machine Learning?"},{"id":"s5-q019","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":19,"level":"真题同型 · 500 题强化","question":"For which type of decisions is machine learning especially useful according to the lecture?","questionZh":"根据讲义，机器学习尤其适合哪类决策？","options":["One-off strategic decisions without data","Operational decisions that are low-level and high-frequency, where data is available","Decisions that never repeat","Only legal decisions"],"optionZh":["没有数据的一次性战略决策","有数据可用的低层级、高频率运营决策","从不重复的决策","只有法律决策"],"answer":1,"explanation":"B 正确：讲义第 20 页：运营决策量大、重复，有足够数据，机器学习能显著提高效率。这与第 7 章“运营预测适合全局模型”的思路一致。","lessonId":"dsfb-01","lessonPage":20,"lessonPageTitle":"How to use data for improving the efficiency of business decision-making?"},{"id":"s5-q020","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 1: Data Science for Business","number":20,"level":"真题同型 · 500 题强化","question":"Which approach to using machine learning for decision-making first predicts an outcome and then optimizes the decision based on that prediction?","questionZh":"哪种把机器学习用于决策的方法是先预测结果、再基于预测优化决策？","options":["Descriptive analytics","Clustering","Unsupervised learning","Predict-then-optimize"],"optionZh":["描述性分析","聚类","无监督学习","先预测再优化（predict-then-optimize）"],"answer":3,"explanation":"D 正确：讲义第 40 页列出了决策中心学习、预测与优化结合、先预测再优化、规范性分析、因果机器学习、强化学习等路线。第 9 章的 uplift 建模就是先预测 ITE 再选择处理对象。","lessonId":"dsfb-01","lessonPage":40,"lessonPageTitle":"How can machine learning be used for business decision-making?"},{"id":"s5-q021","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":21,"level":"真题同型 · 500 题强化","question":"When identifying potentially useful data for a churn model, which guideline does the lecture give?","questionZh":"为流失模型寻找可能有用的数据时，讲义给出什么指导原则？","options":["Use as few variables as possible from the start.","Only use data from the data warehouse.","Only use socio-demographic variables.","Talk to experts and aim for diversity: the more, and the more diverse the variables, the better."],"optionZh":["从一开始就尽量少用变量。","只用数据仓库里的数据。","只用社会人口变量。","与专家交流，追求多样性：变量越多、越多样越好。"],"answer":3,"explanation":"D 正确：讲义第 10 页：覆盖不同维度（使用、财务、营销、社会人口、社交网络）。筛选会在后面的步骤进行（第 19 页）。","lessonId":"dsfb-02","lessonPage":10,"lessonPageTitle":"2. What data could be useful?"},{"id":"s5-q022","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":22,"level":"真题同型 · 500 题强化","question":"Which term is NOT a synonym of \"target variable\"?","questionZh":"以下哪个术语不是“目标变量”的同义词？","options":["Outcome","Dependent variable","Class variable","Predictor"],"optionZh":["Outcome（结果）","Dependent variable（因变量）","Class variable（类别变量）","Predictor（预测变量）"],"answer":3,"explanation":"D 不是：predictor 是输入变量（自变量、特征、属性）。讲义第 13 页列出了观测、变量、目标变量的各种叫法。","lessonId":"dsfb-02","lessonPage":13,"lessonPageTitle":"Select data: terminology"},{"id":"s5-q023","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":23,"level":"真题同型 · 500 题强化","question":"What does \"flattening\" the data mean in the select data step?","questionZh":"在选择数据步骤中，“扁平化”数据是什么意思？","options":["Removing all categorical variables","Merging data, e.g., from a relational database, into a single tabular data set with one row per unit of observation","Normalizing all variables to [0, 1]","Removing the time dimension by deleting old records"],"optionZh":["删除所有类别变量","把数据（例如来自关系数据库）合并成一张表，每行一个观测单位","把所有变量归一化到 [0, 1]","通过删除旧记录去掉时间维度"],"answer":1,"explanation":"B 正确：讲义第 14 页。还要决定观测单位是什么（客户还是交易），以及如何通过特征工程把时间维度“压平”（如 RFM 变量）。","lessonId":"dsfb-02","lessonPage":14,"lessonPageTitle":"Merging data into a flat table, i.e., a tabular data set"},{"id":"s5-q024","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":24,"level":"真题同型 · 500 题强化","question":"What is the key guideline for selecting a sample?","questionZh":"选择样本的关键原则是什么？","options":["The sample should be as large as possible.","The sample should contain only recent data.","The sample should be representative of the population on which the model will be applied.","The sample should have a balanced class distribution."],"optionZh":["样本应尽可能大。","样本只应包含最近的数据。","样本应能代表模型将要应用的总体。","样本应类别平衡。"],"answer":2,"explanation":"C 正确：讲义第 16 页的大写强调。要思考数据生成过程，找出偏差来源。","lessonId":"dsfb-02","lessonPage":16,"lessonPageTitle":"Select data: sampling"},{"id":"s5-q025","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":25,"level":"真题同型 · 500 题强化","question":"An application scorecard is developed using only applicants who were accepted in the past, since outcomes of rejected applicants are unknown. Which type of bias is this?","questionZh":"申请评分卡只用过去被批准的申请人来建模，因为被拒申请人的结果未知。这是哪种偏差？","options":["Seasonality effect","Sample selection bias","Leakage","Survivorship of outliers"],"optionZh":["季节性效应","样本选择偏差","泄露","异常值存活"],"answer":1,"explanation":"B 正确：讲义第 17 页：模型将用于所有申请人，但训练样本只来自被批准的人，选择机制让样本不具代表性。","lessonId":"dsfb-02","lessonPage":17,"lessonPageTitle":"Select data: sampling"},{"id":"s5-q026","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":26,"level":"真题同型 · 500 题强化","question":"A fraud detection model is trained only on transactions from December. Which bias may occur?","questionZh":"欺诈检测模型只用 12 月的交易训练。可能出现哪种偏差？","options":["Seasonality effects","Sample selection bias due to rejected applicants","Multicollinearity","Overfitting caused by regularization"],"optionZh":["季节性效应","因被拒申请人造成的样本选择偏差","多重共线性","正则化导致的过拟合"],"answer":0,"explanation":"A 正确：节假日的交易模式和全年不同。解决办法是在完整的季节或周期内抽样（真题第 7 题 A 选项）。","lessonId":"dsfb-02","lessonPage":17,"lessonPageTitle":"Select data: sampling"},{"id":"s5-q027","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":27,"level":"真题同型 · 500 题强化","question":"Which techniques are mentioned to deal with an imbalanced class distribution?","questionZh":"讲义提到哪些处理类别不平衡的方法？","options":["Variable selection and normalization","Undersampling, oversampling and SMOTE","Imputation and truncation","Dummy encoding and WOE"],"optionZh":["变量选择和归一化","欠采样、过采样和 SMOTE","填补和截断","哑变量编码和 WOE"],"answer":1,"explanation":"B 正确：讲义第 18 页：重采样可能改善预测表现。真题第 8 题 A 选项把变量选择当成处理不平衡的方法，是错的。","lessonId":"dsfb-02","lessonPage":18,"lessonPageTitle":"Select data: re-sampling"},{"id":"s5-q028","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":28,"level":"真题同型 · 500 题强化","question":"In defining a churn target variable, what is the performance (outcome) window?","questionZh":"定义流失目标变量时，表现（结果）窗口是什么？","options":["The period before t0 in which input variables are measured","The period between t0 (time of prediction) and t1 in which the outcome is observed","The time needed to train the model","The period after deployment"],"optionZh":["t0 之前用来测量输入变量的时期","t0（预测时点）到 t1 之间观察结果的时期","训练模型所需的时间","部署之后的时期"],"answer":1,"explanation":"B 正确：讲义第 21 页。A 是观察窗口（t−1 到 t0）。窗口长度都是设计选择。","lessonId":"dsfb-02","lessonPage":21,"lessonPageTitle":"Case: customer churn"},{"id":"s5-q029","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":29,"level":"真题同型 · 500 题强化","question":"Why might one leave a gap between the observation window and the performance window in a churn model?","questionZh":"为什么流失模型中可能在观察窗口和表现窗口之间留一段间隔？","options":["To give the company reaction time (early warning) to act before customers churn","To make the training set smaller","To avoid needing a target variable","To reduce the number of features"],"optionZh":["给公司留出反应时间（预警），以便在客户流失前采取行动","为了让训练集更小","为了不需要目标变量","为了减少特征数"],"answer":0,"explanation":"A 正确：讲义第 22 页：如果预测的是马上就要走的客户，可能已经来不及挽回（Lost causes），提前预警才能挽留 Persuadables。","lessonId":"dsfb-02","lessonPage":22,"lessonPageTitle":"Case: customer churn"},{"id":"s5-q030","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":30,"level":"真题同型 · 500 题强化","question":"Temperature in degrees Celsius is measured on which scale?","questionZh":"摄氏温度属于哪种测量尺度？","options":["Nominal","Ordinal","Proportional (ratio)","Interval"],"optionZh":["名义","有序","比例","区间"],"answer":3,"explanation":"D 正确：讲义第 25 页：区间尺度的零点和单位都是任意的（0°C 不代表“没有温度”）。比例尺度有真正的零点，如体重、收入。","lessonId":"dsfb-02","lessonPage":25,"lessonPageTitle":"Variables: measurement scale"},{"id":"s5-q031","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":31,"level":"真题同型 · 500 题强化","question":"Clothing sizes XS–S–M–L–XL are measured on which scale?","questionZh":"衣服尺码 XS–S–M–L–XL 属于哪种测量尺度？","options":["Nominal","Interval","Ordinal","Absolute"],"optionZh":["名义","区间","有序","绝对"],"answer":2,"explanation":"C 正确：有顺序但没有可比的距离（S 到 M 和 L 到 XL 的差不一定相同）。名义尺度（如城市）连顺序都没有。","lessonId":"dsfb-02","lessonPage":25,"lessonPageTitle":"Variables: measurement scale"},{"id":"s5-q032","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":32,"level":"真题同型 · 500 题强化","question":"Why is the measurement scale of a variable important for preprocessing?","questionZh":"为什么变量的测量尺度对预处理很重要？","options":["Because some techniques cannot handle categorical variables, which then need to be transformed into continuous variables","Because all models require ordinal variables","Because nominal variables can be averaged","Because it determines the number of observations"],"optionZh":["因为有些方法无法处理类别变量，需要把它们转换为连续变量","因为所有模型都需要有序变量","因为名义变量可以求平均","因为它决定观测数量"],"answer":0,"explanation":"A 正确：讲义第 26 页。例如线性/逻辑回归、神经网络要求数值输入。二元类别变量最简单，0/1 编码即可。","lessonId":"dsfb-02","lessonPage":26,"lessonPageTitle":"Scale"},{"id":"s5-q033","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":33,"level":"真题同型 · 500 题强化","question":"Which is a risk of handling missing values by case-wise deletion?","questionZh":"用整行删除处理缺失值有什么风险？","options":["It always increases model accuracy.","It may remove useful information and introduce bias if missingness is not random.","It creates new categories.","It requires a prediction model."],"optionZh":["它总会提高模型准确率。","可能删掉有用信息，若缺失不是随机的，还会引入偏差。","它会创造新的类别。","它需要一个预测模型。"],"answer":1,"explanation":"B 正确：讲义第 31 页。例如高收入客户更常不填收入，删掉这些行就系统性地少了高收入客户。","lessonId":"dsfb-02","lessonPage":31,"lessonPageTitle":"Treatment of missing values"},{"id":"s5-q034","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":34,"level":"真题同型 · 500 题强化","question":"How are missing values of a categorical variable imputed with the simplest imputation technique?","questionZh":"用最简单的填补方法，类别变量的缺失值如何填补？","options":["With the mean","With zero","With a random value","With the mode"],"optionZh":["用均值","用 0","用随机值","用众数"],"answer":3,"explanation":"D 正确：讲义第 33 页：连续变量用均值，类别变量用众数（出现最多的类别）。","lessonId":"dsfb-02","lessonPage":33,"lessonPageTitle":"Imputation techniques"},{"id":"s5-q035","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":35,"level":"真题同型 · 500 题强化","question":"Which approach \"keeps\" missing values for a continuous variable such as credit score?","questionZh":"对信用分这样的连续变量，哪种方法属于“保留”缺失值？","options":["Delete the column","Replace with the mean only","Add a dummy \"missing value indicator\" (e.g., CS_Miss) and replace the missing values","Contact all customers"],"optionZh":["删除该列","只用均值替换","加一个“缺失指示”哑变量（如 CS_Miss），再替换缺失值","联系所有客户"],"answer":2,"explanation":"C 正确：讲义第 36 页：缺失本身可能有预测力，指示变量保留了这个信息。类别变量则可以新增一个“Missing”类别。","lessonId":"dsfb-02","lessonPage":36,"lessonPageTitle":"Treatment of missing values"},{"id":"s5-q036","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":36,"level":"真题同型 · 500 题强化","question":"Which statement about imputation is FALSE?","questionZh":"关于填补，哪项说法是错误的？","options":["It allows applying techniques that require complete data sets.","It avoids losing the correct information in the rest of the row.","Imputed values are always exactly equal to the true values.","It introduces additional errors and complexity."],"optionZh":["它让需要完整数据的方法得以使用。","它避免丢失该行其他正确的信息。","填补的值总是恰好等于真实值。","它会引入额外的误差和复杂度。"],"answer":2,"explanation":"C 错误：填补只是估计，讲义第 35 页列出的缺点正是会引入误差。数据分析偏务实，要权衡是否值得。","lessonId":"dsfb-02","lessonPage":35,"lessonPageTitle":"Imputation: pros and cons"},{"id":"s5-q037","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":37,"level":"真题同型 · 500 题强化","question":"Ages have mean 35.75 and standard deviation 12.01. Is a customer aged 80 an outlier according to the z-score rule of thumb?","questionZh":"年龄均值为 35.75，标准差为 12.01。按 z 分数经验法则，80 岁的客户是否是异常值？","options":["No, z ≈ 1.77","No, z ≈ 2.5","Yes, z ≈ 44.25","Yes, z ≈ 3.68 > 3"],"optionZh":["不是，z ≈ 1.77","不是，z ≈ 2.5","是，z ≈ 44.25","是，z ≈ 3.68 > 3"],"answer":3,"explanation":"D 正确：z = (80 − 35.75)/12.01 ≈ 3.68，超过 3。C 只算了与均值的差，没有除以标准差。","lessonId":"dsfb-02","lessonPage":40,"lessonPageTitle":"Outlier detection"},{"id":"s5-q038","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":38,"level":"真题同型 · 500 题强化","question":"How does truncation (winsorizing, capping) treat an outlier with z > 3?","questionZh":"截断（winsorizing、封顶）如何处理 z > 3 的异常值？","options":["It deletes the observation.","It replaces the value with the value for which z = 3 (or, e.g., the 99th percentile).","It replaces the value with the mean.","It doubles the value."],"optionZh":["删除该观测。","把该值替换为 z = 3 对应的值（或例如第 99 百分位数）。","用均值替换。","把值翻倍。"],"answer":1,"explanation":"B 正确：讲义第 41 页：让值不那么极端，减小其影响，但保留观测。","lessonId":"dsfb-02","lessonPage":41,"lessonPageTitle":"Outlier treatment"},{"id":"s5-q039","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":39,"level":"真题同型 · 500 题强化","question":"Why should outliers not always be removed in fraud detection?","questionZh":"为什么在欺诈检测中不应总是删除异常值？","options":["Because outliers are always data entry errors","Because outliers may be predictive for the class of interest","Because fraud data has no outliers","Because truncation is not allowed"],"optionZh":["因为异常值总是录入错误","因为异常值可能恰恰能预测我们关注的类别","因为欺诈数据没有异常值","因为不允许截断"],"answer":1,"explanation":"B 正确：讲义第 41 页：一笔异常大的交易可能正是欺诈信号，删掉就丢掉了最有用的信息。","lessonId":"dsfb-02","lessonPage":41,"lessonPageTitle":"Outlier treatment"},{"id":"s5-q040","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":40,"level":"真题同型 · 500 题强化","question":"A record shows Age = 200. How should this be treated according to the lecture?","questionZh":"一条记录显示年龄 = 200。根据讲义应如何处理？","options":["Keep it as a valid observation.","Treat it as a missing value, since it is likely a data entry error.","Use it as the new maximum for normalization.","Duplicate the record."],"optionZh":["保留为有效观测。","当作缺失值处理，因为它很可能是录入错误。","用它作为归一化的新最大值。","复制这条记录。"],"answer":1,"explanation":"B 正确：讲义第 38 页：明显不可能的值来自录入错误，应当按缺失值处理。C 会严重扭曲 min-max 归一化。","lessonId":"dsfb-02","lessonPage":38,"lessonPageTitle":"Outliers"},{"id":"s5-q041","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":41,"level":"真题同型 · 500 题强化","question":"What is the practical advice in the lecture regarding multivariate outliers?","questionZh":"讲义对多变量异常值的实用建议是什么？","options":["Always delete them.","Ignore them in practice; detection would require anomaly detection approaches such as the Mahalanobis distance.","Replace them with zero.","Convert them into a new target variable."],"optionZh":["总是删除。","实践中可以忽略；检测它们需要马氏距离等异常检测方法。","用 0 替换。","把它们变成新的目标变量。"],"answer":1,"explanation":"B 正确：讲义第 42 页：多变量异常值是单看每个变量都正常、组合起来却异常的情况（如年龄 20 岁、收入极高）。","lessonId":"dsfb-02","lessonPage":42,"lessonPageTitle":"Multivariate outliers"},{"id":"s5-q042","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":42,"level":"真题同型 · 500 题强化","question":"Why is feature engineering performed?","questionZh":"为什么要做特征工程？","options":["To reduce the number of observations","To remove the target variable","To enrich the data set to increase predictive performance and to improve interpretability and actionable insight","To make the data set smaller"],"optionZh":["减少观测数","去掉目标变量","丰富数据集以提高预测表现，并增强可解释性和可行动的洞察","让数据集更小"],"answer":2,"explanation":"C 正确：讲义第 45 页。例如欺诈检测中，原始交易字段之外再构造“过去 24 小时同一商户交易次数”等特征。","lessonId":"dsfb-02","lessonPage":45,"lessonPageTitle":"Feature engineering"},{"id":"s5-q043","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":43,"level":"真题同型 · 500 题强化","question":"What are RFM variables in customer churn modelling?","questionZh":"客户流失建模中的 RFM 变量是什么？","options":["Risk, Fraud and Margin variables","Regression, Forecasting and Modelling variables","Random, Fixed and Mixed effects","Recency, Frequency and Monetary variables that summarize behaviour in the observation window"],"optionZh":["风险、欺诈、利润变量","回归、预测、建模变量","随机、固定、混合效应","概括观察窗口内行为的最近度、频率和金额变量"],"answer":3,"explanation":"D 正确：讲义第 46 页：把时间维度“压平”，例如最近一次购买距今多久、购买次数、消费金额。","lessonId":"dsfb-02","lessonPage":46,"lessonPageTitle":"Case: customer churn"},{"id":"s5-q044","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":44,"level":"真题同型 · 500 题强化","question":"Using min-max normalization on x = {150, 250, 50, 100, 150, 550}, what is the normalized value of 250?","questionZh":"对 x = {150, 250, 50, 100, 150, 550} 做 min-max 归一化，250 归一化后是多少？","options":["0.45","0.5","0.25","0.4"],"optionZh":["0.45","0.5","0.25","0.4"],"answer":3,"explanation":"D 正确：(250 − 50)/(550 − 50) = 200/500 = 0.4。A 错用了最大值作分母（250/550）。","lessonId":"dsfb-02","lessonPage":49,"lessonPageTitle":"Variable transformation: normalization"},{"id":"s5-q045","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":45,"level":"真题同型 · 500 题强化","question":"Which statement distinguishes standardization from min-max normalization?","questionZh":"哪项说法区分了标准化和 min-max 归一化？","options":["Standardization rescales to mean 0 and standard deviation 1; min-max normalization rescales to a range such as [0, 1].","They are identical.","Standardization makes the data normally distributed.","Min-max normalization is insensitive to outliers."],"optionZh":["标准化把数据变为均值 0、标准差 1；min-max 归一化把数据缩放到如 [0, 1] 的范围。","两者完全相同。","标准化让数据服从正态分布。","min-max 归一化对异常值不敏感。"],"answer":0,"explanation":"A 正确：讲义第 49、51 页。C 错：标准化只平移和缩放，不改变分布形状。D 错：一个极端值就会把其他所有值都压到 0 附近。","lessonId":"dsfb-02","lessonPage":51,"lessonPageTitle":"Variable transformation: standardization"},{"id":"s5-q046","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":46,"level":"真题同型 · 500 题强化","question":"Why is a logarithmic transformation often applied to amount or ratio variables?","questionZh":"为什么常对金额或比率变量做对数变换？","options":["To reduce right skewness, lessen the impact of outliers and possibly turn a nonlinear relation into a linear one","To increase left skewness","To convert it into a categorical variable","To remove all zeros"],"optionZh":["减少右偏、降低异常值影响，并可能把非线性关系变成线性","增加左偏","把它变成类别变量","去掉所有零值"],"answer":0,"explanation":"A 正确：讲义第 50 页。金额类变量通常右偏（少数极大值）。真题第 7 题 D 选项说成减少左偏、得到对数正态分布，都是错的。","lessonId":"dsfb-02","lessonPage":50,"lessonPageTitle":"Variable transformation: normalization"},{"id":"s5-q047","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":47,"level":"真题同型 · 500 题强化","question":"What is a drawback of advanced transformations such as Box-Cox, Yeo-Johnson or PCA?","questionZh":"Box-Cox、Yeo-Johnson 或 PCA 等高级变换有什么缺点？","options":["They cannot be applied to continuous data.","They increase complexity and reduce interpretability, while performance gains are uncertain.","They always decrease performance.","They require a categorical target."],"optionZh":["它们不能用于连续数据。","它们增加复杂度、降低可解释性，而性能提升并不确定。","它们总会降低性能。","它们需要类别目标。"],"answer":1,"explanation":"B 正确：讲义第 52 页用了三个问号表示性能提升不确定。","lessonId":"dsfb-02","lessonPage":52,"lessonPageTitle":"Variable transformation"},{"id":"s5-q048","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":48,"level":"真题同型 · 500 题强化","question":"Why is numerical encoding (Own = 1, Rent = 2, Other = 3) of a nominal variable problematic in a regression model?","questionZh":"为什么在回归模型中对名义变量做数值编码（Own = 1，Rent = 2，Other = 3）有问题？","options":["Because it creates too many variables","Because it imposes an artificial order and equal distances between categories","Because it removes the variable","Because regression cannot handle numbers"],"optionZh":["因为会产生太多变量","因为它强加了类别之间人为的顺序和相等的距离","因为它删除了该变量","因为回归无法处理数字"],"answer":1,"explanation":"B 正确：模型会认为“Other”是“Own”的三倍，Rent 正好在中间，这在名义变量中毫无意义。","lessonId":"dsfb-02","lessonPage":53,"lessonPageTitle":"Variable transformation: categorical → continuous"},{"id":"s5-q049","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":49,"level":"真题同型 · 500 题强化","question":"How many dummy variables are needed for the Housing variable with categories Own, Rent and Other in a regression model with an intercept?","questionZh":"在带截距的回归模型中，Housing 变量（Own、Rent、Other 三类）需要多少个哑变量？","options":["1","3","2","6"],"optionZh":["1","3","2","6"],"answer":2,"explanation":"C 正确：k 个类别用 k − 1 个哑变量，剩下的类别作为参照组（讲义第 54 页的表里只放了 Housing_own 和 Housing_rent，Other 为参照）。用 3 个会和截距完全共线。","lessonId":"dsfb-02","lessonPage":54,"lessonPageTitle":"Housing Housing_own Housing_rent Housing_other"},{"id":"s5-q050","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":50,"level":"真题同型 · 500 题强化","question":"Why can many dummy variables lead to instability, and what is a remedy?","questionZh":"为什么大量哑变量会导致不稳定？有什么补救办法？","options":["Many dummies mean many parameters estimated on few observations per category; remedies include coarse classification or target encoding","Dummies are always stable; no remedy is needed","Remedy: add more categories","Remedy: use numerical encoding instead"],"optionZh":["哑变量多意味着很多参数要用每类很少的观测估计；补救办法包括粗分类或目标编码","哑变量总是稳定，不需要补救","补救：增加更多类别","补救：改用数值编码"],"answer":0,"explanation":"A 正确：讲义第 55 页：减少类别数（用透视表或卡方分析做粗分类）、减少类别变量数，或者改用目标编码（如 WOE）。","lessonId":"dsfb-02","lessonPage":55,"lessonPageTitle":"To reduce instability we can:"},{"id":"s5-q051","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":51,"level":"真题同型 · 500 题强化","question":"In the coarse classification example, 6,300 of 10,000 applicants are owners and 9,000 of all applicants are good. What is the expected number of good owners under independence?","questionZh":"在粗分类例子中，10,000 名申请人里有 6,300 名房主，所有申请人中 9,000 名是好客户。在独立假设下，好房主的期望人数是多少？","options":["6,300","9,000","6,000","5,670"],"optionZh":["6,300","9,000","6,000","5,670"],"answer":3,"explanation":"D 正确：期望频数 = 6,300 × 9,000/10,000 = 5,670。卡方统计量比较实际频数与这些独立情况下的期望频数。","lessonId":"dsfb-02","lessonPage":58,"lessonPageTitle":"Coarse classification: chi-squared test statistic"},{"id":"s5-q052","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":52,"level":"真题同型 · 500 题强化","question":"When comparing two regroupings of a categorical variable with the chi-squared test statistic, which regrouping is preferred?","questionZh":"用卡方统计量比较类别变量的两种重新分组，偏好哪一种？","options":["The one with the lowest chi-squared value","The one with the most categories","The one with the highest chi-squared value, since goods and bads are distributed more differently across categories","The one with equal-sized categories"],"optionZh":["卡方值最低的那个","类别最多的那个","卡方值最高的那个，因为好坏客户在各类别间的分布差异更大","类别大小相等的那个"],"answer":2,"explanation":"C 正确：讲义第 59 页：统计量越高，分组越能区分好坏客户。完美的预测变量是好坏完全分开。","lessonId":"dsfb-02","lessonPage":59,"lessonPageTitle":"Coarse classification: chi-squared test statistic"},{"id":"s5-q053","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":53,"level":"真题同型 · 500 题强化","question":"Which is a reason to transform a continuous variable into a categorical variable?","questionZh":"以下哪项是把连续变量转换为类别变量的理由？","options":["To capture non-linear relations within a linear model while maintaining interpretability, e.g., in a scorecard","To increase the number of parameters","To remove all missing values automatically","Because continuous variables cannot be stored"],"optionZh":["在保持可解释性的同时，在线性模型中捕捉非线性关系，例如评分卡","增加参数数量","自动删除所有缺失值","因为连续变量无法存储"],"answer":0,"explanation":"A 正确：讲义第 60–62 页还列出：某些方法要求类别变量、业务人员偏好年龄段、部分数据只有类别信息、GDPR 匿名化等。","lessonId":"dsfb-02","lessonPage":62,"lessonPageTitle":"Variable transformation: categorical  continuous"},{"id":"s5-q054","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":54,"level":"真题同型 · 500 题强化","question":"What is the main drawback of equal-width or equal-frequency binning?","questionZh":"等宽或等频分箱的主要缺点是什么？","options":["It does not take the objective (target) into account.","It always creates too few bins.","It cannot be applied to age.","It requires a neural network."],"optionZh":["它没有考虑目标（目标变量）。","它总是产生太少的分箱。","它不能用于年龄。","它需要神经网络。"],"answer":0,"explanation":"A 正确：讲义第 63 页。更聪明的方法是基于 WOE 的目标编码和 IV 驱动分箱，让分界点最大化预测力。","lessonId":"dsfb-02","lessonPage":63,"lessonPageTitle":"Variable transformation: categorical  continuous"},{"id":"s5-q055","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":55,"level":"真题同型 · 500 题强化","question":"How is the weight of evidence (WOE) of a category computed in the lecture?","questionZh":"讲义中类别的证据权重（WOE）如何计算？","options":["ln(Distr. Good / Distr. Bad) × 100","(Distr. Good − Distr. Bad) × 100","Count of goods / count of bads","ln(Distr. Bad)"],"optionZh":["ln(好客户分布 / 坏客户分布) × 100","(好客户分布 − 坏客户分布) × 100","好客户数 / 坏客户数","ln(坏客户分布)"],"answer":0,"explanation":"A 正确：分布指的是该类别占全部好客户（或全部坏客户）的比例。C 是绝对优势比，讲义第 65 页解释了为什么要用相对优势比。","lessonId":"dsfb-02","lessonPage":64,"lessonPageTitle":"Age_cat"},{"id":"s5-q056","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":56,"level":"真题同型 · 500 题强化","question":"A category contains 30% of all goods and 15% of all bads. What is its WOE?","questionZh":"某类别包含全部好客户的 30% 和全部坏客户的 15%。它的 WOE 是多少？","options":["−69.31","15","2","69.31"],"optionZh":["−69.31","15","2","69.31"],"answer":3,"explanation":"D 正确：ln(0.30/0.15) × 100 = ln 2 × 100 ≈ 69.31。为正说明这一类好客户相对更多，风险低于平均。A 是把比值倒过来了。","lessonId":"dsfb-02","lessonPage":64,"lessonPageTitle":"Age_cat"},{"id":"s5-q057","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":57,"level":"真题同型 · 500 题强化","question":"A category contains 30% of all goods and 15% of all bads. What is its contribution to the information value (IV)?","questionZh":"某类别包含全部好客户的 30% 和全部坏客户的 15%。它对信息值（IV）的贡献是多少？","options":["≈ 0.104","0.15","≈ 0.693","≈ 0.0139"],"optionZh":["≈ 0.104","0.15","≈ 0.693","≈ 0.0139"],"answer":0,"explanation":"A 正确：IV 贡献 = (Distr.Good − Distr.Bad) × ln(Distr.Good/Distr.Bad) = 0.15 × 0.693 ≈ 0.104。C 只是 ln 部分。","lessonId":"dsfb-02","lessonPage":67,"lessonPageTitle":"Age Count Distr. Count Goods Distr. Goods Bads Distr. Bads WOE IV"},{"id":"s5-q058","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":58,"level":"真题同型 · 500 题强化","question":"Why does WOE use the logarithm of the relative odds (Distr. Good / Distr. Bad) instead of the absolute odds (Goods / Bads)?","questionZh":"为什么 WOE 用相对优势比（好客户分布 / 坏客户分布）的对数，而不是绝对优势比（好客户数 / 坏客户数）？","options":["Because absolute odds cannot be computed","So that WOE values are independent of the class distribution and easy to interpret (positive versus negative)","Because the logarithm of absolute odds is always zero","To make WOE values larger"],"optionZh":["因为绝对优势比无法计算","这样 WOE 不受类别分布影响，而且容易解读（正负）","因为绝对优势比的对数总是 0","为了让 WOE 值更大"],"answer":1,"explanation":"B 正确：讲义第 65 页。如果对坏客户过采样，绝对优势比会变，但“坏客户中有多少落在这一类”不变。这也是真题第 8 题 B 选项为什么是对的。","lessonId":"dsfb-02","lessonPage":65,"lessonPageTitle":"Why do we take the logarithm of the “relative odds” and not of the “absolute odds”?"},{"id":"s5-q059","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":59,"level":"真题同型 · 500 题强化","question":"What does a WOE of 0 in every category of a variable indicate?","questionZh":"某变量每个类别的 WOE 都为 0，说明什么？","options":["The variable has maximal predictive power.","The variable has missing values.","The variable has no predictive power, since belonging to a category reveals nothing about the class.","The variable must be standardized."],"optionZh":["该变量预测力最强。","该变量有缺失值。","该变量没有预测力，因为属于哪一类不透露任何类别信息。","该变量必须标准化。"],"answer":2,"explanation":"C 正确：讲义第 66 页：每类好坏分布都相同，相对优势比为 1，ln 1 = 0，IV 也为 0。","lessonId":"dsfb-02","lessonPage":66,"lessonPageTitle":"Target encoding: weights-of-evidence"},{"id":"s5-q060","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":60,"level":"真题同型 · 500 题强化","question":"What does the information value (IV) measure?","questionZh":"信息值（IV）衡量什么？","options":["The predictive strength of a variable, usable as a variable filter","The number of missing values","Whether the relation is linear","The correlation between two input variables"],"optionZh":["变量的预测强度，可用作变量筛选","缺失值的数量","关系是否线性","两个输入变量之间的相关性"],"answer":0,"explanation":"A 正确：IV 汇总了所有类别好坏分布的差异。C 错：IV 是一个总数，不反映关系的形状（真题第 6 题）。","lessonId":"dsfb-02","lessonPage":67,"lessonPageTitle":"Age Count Distr. Count Goods Distr. Goods Bads Distr. Bads WOE IV"},{"id":"s5-q061","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":61,"level":"真题同型 · 500 题强化","question":"What is the trade-off when choosing the number of categories in WOE binning?","questionZh":"在 WOE 分箱中选择类别数时需要权衡什么？","options":["More categories always reduce predictive power.","Fewer categories favour interpretability and stability; more categories retain predictive power, up to a point.","The number of categories has no effect.","There must always be exactly five categories."],"optionZh":["类别越多预测力总越低。","类别少有利于可解释性和稳定性；类别多能保留预测力，但只到某个程度。","类别数没有影响。","必须恰好五个类别。"],"answer":1,"explanation":"B 正确：讲义第 69–70 页：只分一类就失去全部预测力；类别增加 IV 上升，但到某点后收益很小。实用做法是画 IV 对类别数的曲线找肘部。","lessonId":"dsfb-02","lessonPage":69,"lessonPageTitle":"Target encoding: weights-of-evidence"},{"id":"s5-q062","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":62,"level":"真题同型 · 500 题强化","question":"The category \"No answer\" has only 3 observations and an extreme WOE of −151. What problem does this illustrate?","questionZh":"“No answer”类别只有 3 个观测，WOE 却是极端的 −151。这说明了什么问题？","options":["WOE values based on few observations are unstable.","WOE cannot be negative.","The category is the most predictive.","The total count is wrong."],"optionZh":["基于少量观测的 WOE 值不稳定。","WOE 不能为负。","这个类别最有预测力。","总数算错了。"],"answer":0,"explanation":"A 正确：讲义第 72 页强调 WOE 的稳定性。3 个观测里多一个坏客户 WOE 就会剧烈变化，补救办法是 Laplace 平滑。","lessonId":"dsfb-02","lessonPage":72,"lessonPageTitle":"Category Count Distr. Count Good Distr. Good Bad Distr. Bad WOE"},{"id":"s5-q063","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":63,"level":"真题同型 · 500 题强化","question":"In WOE with Laplace smoothing, what happens when the smoothing parameter n increases?","questionZh":"在带 Laplace 平滑的 WOE 中，平滑参数 n 增大会怎样？","options":["WOE values move further away from zero.","WOE values are unaffected.","More smoothing: WOE values move closer to zero, so more evidence in the data is needed to obtain extreme values.","The number of categories increases."],"optionZh":["WOE 值离 0 越来越远。","WOE 值不受影响。","平滑更强：WOE 向 0 靠拢，需要更多数据证据才能得到极端值。","类别数增加。"],"answer":2,"explanation":"C 正确：讲义第 73–74 页：n = 0.1 时 “No answer” 的 WOE 从 −151 变为约 −0.8，而大类别（如 Owner）变化较小。","lessonId":"dsfb-02","lessonPage":73,"lessonPageTitle":"Target encoding: weights-of-evidence"},{"id":"s5-q064","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":64,"level":"真题同型 · 500 题强化","question":"Why is WOE called an \"all-in-one\" solution?","questionZh":"为什么 WOE 被称为“一体化”解决方案？","options":["It handles categorical → continuous and continuous → categorical transformations, missing values, outliers, and assesses predictive strength through IV.","It replaces the need for a model.","It works for any type of target variable.","It always increases predictive power."],"optionZh":["它能处理类别→连续和连续→类别的转换、缺失值、异常值，还能通过 IV 评估预测强度。","它不再需要模型。","它适用于任何类型的目标变量。","它总能提高预测力。"],"answer":0,"explanation":"A 正确：讲义第 76 页。缺失值可以单独作为一箱，异常值落入边缘的箱中。C 错：WOE 只适用于二元目标（第 77 页）。D 错：可能有一些预测力损失。","lessonId":"dsfb-02","lessonPage":76,"lessonPageTitle":"Target encoding: weights-of-evidence"},{"id":"s5-q065","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":65,"level":"真题同型 · 500 题强化","question":"How can a categorical input be target-encoded when the target is continuous?","questionZh":"当目标是连续变量时，如何对类别输入做目标编码？","options":["With WOE, as for binary targets","It is not possible.","Replace each category with the average value of the target in that category.","Replace each category with its count."],"optionZh":["和二元目标一样用 WOE","不可能。","用每个类别中目标的平均值替换该类别。","用每个类别的计数替换。"],"answer":2,"explanation":"C 正确：讲义第 77 页。WOE 只适用于二元目标，因为它基于好坏两组的分布。","lessonId":"dsfb-02","lessonPage":77,"lessonPageTitle":"Target encoding for non-binary targets"},{"id":"s5-q066","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":66,"level":"真题同型 · 500 题强化","question":"Which statement from the final remarks of Chapter 2 is TRUE?","questionZh":"关于第 2 章的结束语，哪项说法正确？","options":["Variable transformation is no longer needed for tabular data.","Decision trees incorporate mechanisms for categorical → continuous handling, variable selection, missing values and outliers.","Transforming data is state of the art in computer vision.","Preprocessing can be done with simple cooking recipes."],"optionZh":["表格数据不再需要变量转换。","决策树内置了处理类别变量、变量选择、缺失值和异常值的机制。","数据转换是计算机视觉的最新技术。","预处理可以照简单菜谱完成。"],"answer":1,"explanation":"B 正确：讲义第 78 页。A 错：转换数据目前仍是表格数据学习的关键。C 错：在计算机视觉和 NLP 中已被 Transformer 和基础模型取代。D 错：第 79 页强调要理解业务、有创造力，而不是套菜谱。","lessonId":"dsfb-02","lessonPage":78,"lessonPageTitle":"Final remarks"},{"id":"s5-q067","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":67,"level":"真题同型 · 500 题强化","question":"In customer churn prediction, why may the target variable need to be defined as a \"proxy\"?","questionZh":"在客户流失预测中，为什么目标变量可能需要定义为“代理”变量？","options":["Because churn is always directly observed","Because in a non-contractual setting there is no explicit cancellation, so churn must be defined, e.g., as no purchases in a given period","Because the target must be continuous","Because churn cannot be predicted"],"optionZh":["因为流失总是直接可观察","因为在非合约场景中没有明确的解约，所以流失需要定义，例如在一定时期内没有购买","因为目标必须是连续的","因为流失无法预测"],"answer":1,"explanation":"B 正确：讲义第 20 页区分了合约与非合约场景、主动与被动流失、预期与被迫流失。超市顾客不会“退订”，只能用一段时间不来购物来近似。","lessonId":"dsfb-02","lessonPage":20,"lessonPageTitle":"Select data: target variable"},{"id":"s5-q068","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":68,"level":"真题同型 · 500 题强化","question":"Which statement about variable selection in the select-data step is TRUE?","questionZh":"关于选择数据步骤中的变量选择，哪项说法正确？","options":["Only keep the five variables with the highest IV right away.","Delete all variables with missing values.","Variable selection is the same as sampling.","Start with as many variables as possible; selection, e.g., with filters, is performed in a later step."],"optionZh":["立即只保留 IV 最高的五个变量。","删除所有带缺失值的变量。","变量选择与抽样相同。","从尽可能多的变量开始，筛选（例如用过滤器）在后续步骤进行。"],"answer":3,"explanation":"D 正确：讲义第 19 页：抽样是选行，变量选择是选列；先多收集，后面再筛。A 也有问题：IV 最高的几个变量可能高度相关（真题第 7 题 C）。","lessonId":"dsfb-02","lessonPage":19,"lessonPageTitle":"Select data: variable selection"},{"id":"s5-q069","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 2: Preprocessing","number":69,"level":"真题同型 · 500 题强化","question":"How could outliers of a categorical variable be detected?","questionZh":"如何检测类别变量的异常值？","options":["With a z-score greater than 3","By looking for categories with very low frequencies, e.g., in a frequency table or bar chart","By standardizing the categories","Categorical variables cannot have unusual values"],"optionZh":["用大于 3 的 z 分数","在频数表或柱状图中寻找频率极低的类别","对类别标准化","类别变量不可能有异常值"],"answer":1,"explanation":"B 正确：讲义第 40 页留了这个问题。类别变量没有均值和标准差，z 分数用不了，但可以看出现次数极少或拼写错误的类别。","lessonId":"dsfb-02","lessonPage":40,"lessonPageTitle":"Outlier detection"},{"id":"s5-q070","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":70,"level":"真题同型 · 500 题强化","question":"In a decision tree, what is the node at the top that contains all the data called?","questionZh":"决策树中位于顶端、包含全部数据的节点叫什么？","options":["Leaf node","Child node","Internal node","Root node"],"optionZh":["叶节点","子节点","内部节点","根节点"],"answer":3,"explanation":"D 正确：讲义第 9 页的术语：根节点包含全部数据，经过分裂得到子节点，不再分裂的末端是叶节点。从根到叶的一条路径就是一条决策规则。","lessonId":"dsfb-03","lessonPage":9,"lessonPageTitle":"Terminology"},{"id":"s5-q071","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":71,"level":"真题同型 · 500 题强化","question":"Which three decisions must be made when learning a decision tree?","questionZh":"学习决策树时需要做哪三类决策？","options":["Splitting, stopping and assignment decisions","Sampling, weighting and voting decisions","Encoding, scaling and imputation decisions","Training, testing and deployment decisions"],"optionZh":["分裂决策、停止决策、赋值决策","抽样、加权、投票决策","编码、缩放、填补决策","训练、测试、部署决策"],"answer":0,"explanation":"A 正确：讲义第 10 页：怎么分、什么时候停、叶节点给什么预测。B 是集成方法的问题。","lessonId":"dsfb-03","lessonPage":10,"lessonPageTitle":"Various decision tree learners exist to induce a tree from data:"},{"id":"s5-q072","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":72,"level":"真题同型 · 500 题强化","question":"A leaf contains 600 good and 200 bad customers. What class probability P(Good) does the tree assign, and why is this better than majority voting?","questionZh":"某叶节点有 600 个好客户和 200 个坏客户。树给出的 P(好) 是多少？为什么比多数投票更好？","options":["0.6; it is easier to compute","0.75; it allows differentiation between leaves and flexibility in decision making","1; all customers are labelled good","0.25; it is more conservative"],"optionZh":["0.6；更容易计算","0.75；可以区分不同叶节点，决策更灵活","1；所有客户都被标为好","0.25；更保守"],"answer":1,"explanation":"B 正确：600/(600 + 200) = 0.75。多数投票下 75% 和 80% 的叶节点都只是“好”，概率能区分它们，还能配合第 10 章的成本敏感阈值使用。D 是 P(坏)。","lessonId":"dsfb-03","lessonPage":11,"lessonPageTitle":"Simple: majority voting"},{"id":"s5-q073","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":73,"level":"真题同型 · 500 题强化","question":"Which two effects of a split are taken into account when evaluating candidate splits?","questionZh":"评估候选分裂时，会考虑分裂的哪两个效果？","options":["The reduction in impurity and the number of observations in the resulting subsamples","The depth of the tree and the learning rate","The number of variables and the number of classes","The AUC and the accuracy"],"optionZh":["不纯度的减少，以及分裂后各子样本中的观测数","树的深度和学习率","变量数和类别数","AUC 和准确率"],"answer":0,"explanation":"A 正确：讲义第 14 页。只看子节点有多纯不够，还要考虑每个子节点有多少观测，信息增益就是按观测比例加权的不纯度下降。","lessonId":"dsfb-03","lessonPage":14,"lessonPageTitle":"Two effects of a split are taken into account:"},{"id":"s5-q074","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":74,"level":"真题同型 · 500 题强化","question":"A node contains 50% goods and 50% bads. What are its entropy and Gini (2·p·(1−p))?","questionZh":"某节点有 50% 好、50% 坏。它的熵和 Gini（2·p·(1−p)）分别是多少？","options":["0.5 and 1","0 and 0","1 and 1","1 and 0.5"],"optionZh":["0.5 和 1","0 和 0","1 和 1","1 和 0.5"],"answer":3,"explanation":"D 正确：熵 = −0.5·log2(0.5) − 0.5·log2(0.5) = 1；Gini = 2 × 0.5 × 0.5 = 0.5。两者都在 50/50 时取最大值（最不纯）。","lessonId":"dsfb-03","lessonPage":15,"lessonPageTitle":"Impurity?"},{"id":"s5-q075","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":75,"level":"真题同型 · 500 题强化","question":"A node contains 25% bads and 75% goods. What is its Gini impurity (2·p_bad·p_good)?","questionZh":"某节点有 25% 坏、75% 好。它的 Gini 不纯度（2·p_坏·p_好）是多少？","options":["0.1875","0.375","0.5","0.811"],"optionZh":["0.1875","0.375","0.5","0.811"],"answer":1,"explanation":"B 正确：2 × 0.25 × 0.75 = 0.375。D 是这个节点的熵（−0.25·log2 0.25 − 0.75·log2 0.75 ≈ 0.811）。A 忘了乘 2。","lessonId":"dsfb-03","lessonPage":15,"lessonPageTitle":"Impurity?"},{"id":"s5-q076","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":76,"level":"真题同型 · 500 题强化","question":"A node contains 25% bads and 75% goods. What is its entropy (log base 2)?","questionZh":"某节点有 25% 坏、75% 好。它的熵（以 2 为底）是多少？","options":["≈ 0.811","0.375","1","0.25"],"optionZh":["≈ 0.811","0.375","1","0.25"],"answer":0,"explanation":"A 正确：−0.25 × (−2) − 0.75 × log2(0.75) = 0.5 + 0.311 ≈ 0.811。B 是 Gini。","lessonId":"dsfb-03","lessonPage":15,"lessonPageTitle":"Impurity?"},{"id":"s5-q077","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":77,"level":"真题同型 · 500 题强化","question":"Which impurity measure is used by which decision tree learner according to the lecture?","questionZh":"根据讲义，哪种不纯度度量对应哪种决策树算法？","options":["Gini by ID3 and C4.5, entropy by CART","Entropy by ID3 and C4.5, Gini by CART","Both use only accuracy","CHAID uses Gini"],"optionZh":["ID3 和 C4.5 用 Gini，CART 用熵","ID3 和 C4.5 用熵，CART 用 Gini","两者都只用准确率","CHAID 使用 Gini"],"answer":1,"explanation":"B 正确：讲义第 15 页。CHAID 用的是卡方检验。","lessonId":"dsfb-03","lessonPage":15,"lessonPageTitle":"Impurity?"},{"id":"s5-q078","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":78,"level":"真题同型 · 500 题强化","question":"A parent node has 800 goods and 400 bads (Gini 0.44). A split sends 600 goods to the left child, and 200 goods and 400 bads to the right child (Gini 0.44). What is the information gain?","questionZh":"父节点有 800 个好、400 个坏（Gini 0.44）。分裂后左子节点 600 个好，右子节点 200 个好、400 个坏（Gini 0.44）。信息增益是多少？","options":["0","0.44","0.33","0.22"],"optionZh":["0","0.44","0.33","0.22"],"answer":3,"explanation":"D 正确：左子节点纯（Gini 0），两个子节点各占 600/1200 = 0.5。信息增益 = 0.44 − 0.5 × 0 − 0.5 × 0.44 = 0.22。","lessonId":"dsfb-03","lessonPage":18,"lessonPageTitle":"Gini parent node = 2 ∙"},{"id":"s5-q079","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":79,"level":"真题同型 · 500 题强化","question":"A parent node with 100 observations has 50 goods and 50 bads (Gini 0.5). A split produces a left child with 40 goods and 0 bads, and a right child with 10 goods and 50 bads. What is the Gini-based information gain?","questionZh":"有 100 个观测的父节点，好坏各 50（Gini 0.5）。分裂后左子节点 40 好 0 坏，右子节点 10 好 50 坏。基于 Gini 的信息增益是多少？","options":["≈ 0.22","≈ 0.28","≈ 0.33","0.5"],"optionZh":["≈ 0.22","≈ 0.28","≈ 0.33","0.5"],"answer":2,"explanation":"C 正确：右子节点 Gini = 2 × (10/60) × (50/60) ≈ 0.278，权重 60%；左子节点 Gini 0，权重 40%。信息增益 = 0.5 − 0.6 × 0.278 ≈ 0.5 − 0.167 = 0.333。B 只是右子节点的 Gini。","lessonId":"dsfb-03","lessonPage":17,"lessonPageTitle":"Problem: how to compare the impurity of the resulting subsamples across all potential spli"},{"id":"s5-q080","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":80,"level":"真题同型 · 500 题强化","question":"What is information gain?","questionZh":"什么是信息增益？","options":["The impurity of the parent node minus the weighted average impurity of the child nodes","The accuracy of the child nodes","The number of child nodes","The impurity of the largest child node"],"optionZh":["父节点的不纯度减去子节点不纯度的加权平均","子节点的准确率","子节点的数量","最大子节点的不纯度"],"answer":0,"explanation":"A 正确：权重是各子节点观测数占父节点的比例。信息增益就是“加权的不纯度下降”（真题第 9 题 A 选项的说法把它归到了 Gini 本身）。","lessonId":"dsfb-03","lessonPage":17,"lessonPageTitle":"Problem: how to compare the impurity of the resulting subsamples across all potential spli"},{"id":"s5-q081","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":81,"level":"真题同型 · 500 题强化","question":"How are candidate splits generated for a nominal categorical variable?","questionZh":"对名义类别变量，如何生成候选分裂？","options":["Only splits of the form \"value < threshold\"","All possible combinations (groupings) of its values","Only the most frequent value versus all others","Nominal variables cannot be used in trees"],"optionZh":["只考虑“值 < 阈值”形式的分裂","考虑其取值的所有可能组合（分组）","只考虑最常见的值与其余值","名义变量不能用于决策树"],"answer":1,"explanation":"B 正确：讲义第 19 页：名义变量没有顺序，所以考虑所有分组；连续变量和有序变量则考虑所有“小于”某值的切分。缺失值可以并入使信息增益最大的子节点，或单独成组。","lessonId":"dsfb-03","lessonPage":19,"lessonPageTitle":"Possible splits that are evaluated:"},{"id":"s5-q082","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":82,"level":"真题同型 · 500 题强化","question":"Why should multi-way splits with many child nodes be treated with caution?","questionZh":"为什么要谨慎对待有很多子节点的多路分裂？","options":["Because information gain decreases with more child nodes","Because trees cannot have more than two child nodes","Because more groups typically increase information gain; in the extreme, one child per observation is 100% pure but useless","Because they require a target variable"],"optionZh":["因为子节点越多信息增益越小","因为树不能有超过两个子节点","因为分组越多信息增益通常越大；极端情况下每个观测一个子节点，100% 纯净却毫无用处","因为它们需要目标变量"],"answer":2,"explanation":"C 正确：讲义第 20 页的极端推理：每个子节点只有一个观测，信息增益达到最大，但完全是过拟合。所以要对分组数量进行惩罚或限制。","lessonId":"dsfb-03","lessonPage":20,"lessonPageTitle":"More than two child nodes (multi-way split)?"},{"id":"s5-q083","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":83,"level":"真题同型 · 500 题强化","question":"Why is recursive partitioning called a \"greedy\" approach?","questionZh":"为什么递归划分被称为“贪婪”方法？","options":["Because it uses all the data in every node","Because at each step it selects the best single split, without considering combinations with later splits","Because it always grows the tree to maximum depth","Because it is computationally expensive"],"optionZh":["因为每个节点都用全部数据","因为每一步只选当前最好的单个分裂，不考虑与后续分裂的组合","因为它总是把树长到最深","因为计算量大"],"answer":1,"explanation":"B 正确：每步都尽可能多拿，可能错过“一个看起来一般的分裂加上后续分裂更好”的组合。全局最优的树学习器存在，但搜索空间随变量数、取值数和层数指数增长（讲义第 22 页）。","lessonId":"dsfb-03","lessonPage":21,"lessonPageTitle":"Decision tree learning procedure: recursive partitioning algorithms (RPA)"},{"id":"s5-q084","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":84,"level":"真题同型 · 500 题强化","question":"Income predicts default for customers younger than 30, but not for older customers. What does this indicate?","questionZh":"收入能预测 30 岁以下客户的违约，但不能预测年长客户。这说明什么？","options":["Income is irrelevant.","Age and income are perfectly correlated.","There is an interaction effect between age and income, which decision trees capture naturally.","The tree is underfitting."],"optionZh":["收入无关。","年龄和收入完全相关。","年龄和收入之间存在交互效应，决策树能自然地捕捉。","树欠拟合。"],"answer":2,"explanation":"C 正确：讲义第 24 页：一个变量与目标的关系取决于另一个变量的取值，就是交互效应。先按年龄分，再在年轻人分支里按收入分，正好表达这种关系（CHAID 的 I 就是 Interaction）。","lessonId":"dsfb-03","lessonPage":24,"lessonPageTitle":"Interaction effects!"},{"id":"s5-q085","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":85,"level":"真题同型 · 500 题强化","question":"For which type of pattern is a decision tree NOT well suited?","questionZh":"决策树不擅长哪种模式？","options":["XOR-style interactions","OR-style interactions","Segment-specific rules","Linear relations"],"optionZh":["XOR 式交互","OR 式交互","针对细分群体的规则","线性关系"],"answer":3,"explanation":"D 正确：讲义第 25 页：树用轴平行的矩形切分空间，斜着的线性边界只能用很多台阶近似。而 XOR、OR 这类交互是树的强项。","lessonId":"dsfb-03","lessonPage":25,"lessonPageTitle":"Given the specific abilities of decision trees:"},{"id":"s5-q086","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":86,"level":"真题同型 · 500 题强化","question":"Which is NOT a stopping criterion for growing a decision tree mentioned in the lecture?","questionZh":"以下哪项不是讲义提到的决策树停止生长准则？","options":["Information gain above a minimum threshold","Maximum number of levels or leaves","Minimum number of observations per leaf","Reaching an AUC of exactly 0.5 on the training set"],"optionZh":["信息增益高于最小阈值","最大层数或叶节点数","每个叶节点的最少观测数","训练集 AUC 恰好达到 0.5"],"answer":3,"explanation":"D 不是：讲义第 26 页列出了 A、B、C。讲义也指出，这些方法都不是“最优”，关键是看树在新数据上的表现。","lessonId":"dsfb-03","lessonPage":26,"lessonPageTitle":"How to decide when to stop growing the tree?"},{"id":"s5-q087","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":87,"level":"真题同型 · 500 题强化","question":"Why should we stop growing the tree before reaching minimum impurity on the training data?","questionZh":"为什么要在训练数据上达到最小不纯度之前就停止生长？","options":["Because a fully grown tree memorizes the training data, including noise, and generalizes poorly","Because impurity cannot reach zero","Because deeper trees are always less accurate on training data","Because it saves memory only"],"optionZh":["因为完全生长的树会记住训练数据（包括噪声），泛化能力差","因为不纯度不可能为 0","因为更深的树在训练数据上总是更不准","只是为了节省内存"],"answer":0,"explanation":"A 正确：讲义第 27 页：模型就是转换后的数据，所以对训练数据当然预测得好，但那是过拟合。C 错：越深的树在训练集上越准。","lessonId":"dsfb-03","lessonPage":27,"lessonPageTitle":"The tree should generalize well"},{"id":"s5-q088","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":88,"level":"真题同型 · 500 题强化","question":"In the early stopping graph, training accuracy keeps increasing with tree size, while validation accuracy peaks and then decreases. What should be done?","questionZh":"在早停图中，训练准确率随树的规模不断上升，而验证准确率先达到峰值后下降。应该怎么做？","options":["Choose the largest tree.","Choose the tree size with the highest training accuracy.","Stop growing where validation accuracy is maximal, or choose a smaller tree with the same validation accuracy.","Use the test set to decide."],"optionZh":["选择最大的树。","选择训练准确率最高的树。","在验证准确率最高处停止，或者选一棵验证准确率相同但更小的树。","用测试集来决定。"],"answer":2,"explanation":"C 正确：讲义第 29 页还特别指出，如果更小的树验证准确率一样，就选更小的（更简单）。D 错：测试集应留到最后做独立评估。","lessonId":"dsfb-03","lessonPage":29,"lessonPageTitle":"Early stopping (pre-pruning)"},{"id":"s5-q089","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":89,"level":"真题同型 · 500 题强化","question":"How does post-pruning work?","questionZh":"后剪枝（post-pruning）如何进行？","options":["Stop growing as soon as the information gain is small","Grow the full tree (100% training accuracy) and then cut branches to optimize performance on a validation set","Remove the root node","Grow several trees and vote"],"optionZh":["信息增益一小就停止生长","先长出完整的树（训练准确率 100%），再剪掉分支以优化验证集上的表现","删除根节点","长出多棵树并投票"],"answer":1,"explanation":"B 正确：讲义第 31 页。A 是预剪枝（early stopping），D 是集成方法。","lessonId":"dsfb-03","lessonPage":31,"lessonPageTitle":"Post-pruning:"},{"id":"s5-q090","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":90,"level":"真题同型 · 500 题强化","question":"Using a validation set to decide on the size of a decision tree is an example of:","questionZh":"用验证集决定决策树的大小，是什么的例子？","options":["Hyperparameter tuning","Data leakage","Feature engineering","Clustering"],"optionZh":["超参数调优","数据泄露","特征工程","聚类"],"answer":0,"explanation":"A 正确：讲义第 33 页：同样的做法后面用于神经网络的神经元数、集成的树数等。验证集也叫调参集（tuning set），训练集也叫开发集。","lessonId":"dsfb-03","lessonPage":33,"lessonPageTitle":"Validation set for deciding on the size of the decision tree:"},{"id":"s5-q091","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":91,"level":"真题同型 · 500 题强化","question":"Which is an advantage of decision trees?","questionZh":"以下哪项是决策树的优点？","options":["They are very stable with respect to changes in the training data.","They are insensitive to imbalanced class distributions.","They are interpretable (rules), non-parametric, and robust to missing values and outliers.","They always have the highest predictive power."],"optionZh":["对训练数据的变化非常稳定。","对类别不平衡不敏感。","可解释（规则）、非参数，对缺失值和异常值稳健。","预测力总是最高。"],"answer":2,"explanation":"C 正确：讲义第 36 页。A、B、D 恰好是它的缺点：不稳定（换个训练/验证划分树就不同）、对类别不平衡敏感、预测力偏弱。","lessonId":"dsfb-03","lessonPage":36,"lessonPageTitle":"Advantages"},{"id":"s5-q092","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":92,"level":"真题同型 · 500 题强化","question":"Which is a disadvantage of decision trees mentioned in the lecture?","questionZh":"讲义提到决策树的哪个缺点？","options":["They are sensitive to changes in the training data, i.e., they are unstable classifiers.","They require all variables to be continuous.","They cannot handle missing values.","They need a distributional assumption."],"optionZh":["对训练数据变化敏感，即它们是不稳定的分类器。","要求所有变量都是连续的。","无法处理缺失值。","需要分布假设。"],"answer":0,"explanation":"A 正确：不同的训练/验证划分可能得到很不一样的树。这个缺点恰好让决策树成为集成方法的理想基分类器（第 5 章）。B、C、D 都与树的优点相反。","lessonId":"dsfb-03","lessonPage":36,"lessonPageTitle":"Advantages"},{"id":"s5-q093","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":93,"level":"真题同型 · 500 题强化","question":"Which is NOT a use of decision trees listed in the lecture?","questionZh":"以下哪项不是讲义列出的决策树用途？","options":["Variable selection in preprocessing using information gain","Segmentation prior to developing final predictive models","Coarse classification via multi-way trees","Computing the ATE from observational data without any adjustment"],"optionZh":["在预处理中用信息增益选变量","在建立最终预测模型前做细分","用多路树做粗分类","不做任何调整就从观察数据计算 ATE"],"answer":3,"explanation":"D 不是：讲义第 37 页的用途包括数据探索、变量选择、细分、Logit leaf model（在叶节点上拟合逻辑回归）、粗分类和集成。","lessonId":"dsfb-03","lessonPage":37,"lessonPageTitle":"Predictive model: careful, depending on the setting (requirements)"},{"id":"s5-q094","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":94,"level":"真题同型 · 500 题强化","question":"What is a logit leaf model?","questionZh":"什么是 logit leaf model？","options":["A tree where a logistic regression model is fitted in each leaf","A logistic regression with only one variable","A random forest of logistic regressions","A tree that uses log-odds as impurity"],"optionZh":["在每个叶节点上拟合一个逻辑回归模型的树","只有一个变量的逻辑回归","由逻辑回归组成的随机森林","用对数优势作为不纯度的树"],"answer":0,"explanation":"A 正确：先用树把客户分成有意义的细分群体（基于交互效应），再在每个群体内用逻辑回归，兼顾交互效应和线性关系。","lessonId":"dsfb-03","lessonPage":37,"lessonPageTitle":"Predictive model: careful, depending on the setting (requirements)"},{"id":"s5-q095","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":95,"level":"真题同型 · 500 题强化","question":"A decision tree is used to predict loss given default (LGD), a continuous variable. What type of tree is this?","questionZh":"用决策树预测违约损失率（LGD，一个连续变量）。这是哪种树？","options":["Classification tree","Clustering tree","Regression tree","Association tree"],"optionZh":["分类树","聚类树","回归树","关联树"],"answer":2,"explanation":"C 正确：讲义第 42 页：目标变量是连续的（如 LGD、CLV）就是回归树，叶节点预测该组的平均值。","lessonId":"dsfb-03","lessonPage":42,"lessonPageTitle":"Regression trees"},{"id":"s5-q096","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":96,"level":"真题同型 · 500 题强化","question":"Which impurity measure can be used to evaluate splits in a regression tree?","questionZh":"回归树中可以用什么不纯度度量来评估分裂？","options":["Entropy","Gini","Mean squared error (or an ANOVA F-test)","Lift"],"optionZh":["熵","Gini","均方误差（或方差分析 F 检验）","提升度"],"answer":2,"explanation":"C 正确：讲义第 43 页：节点内的 MSE 衡量取值的离散程度；F 检验比较组间与组内平方和，p 值越低分裂越好。熵和 Gini 用于分类树。","lessonId":"dsfb-03","lessonPage":43,"lessonPageTitle":"Splitting decision"},{"id":"s5-q097","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":97,"level":"真题同型 · 500 题强化","question":"In the ANOVA F-test for a regression tree split, what indicates a good split?","questionZh":"在回归树分裂的方差分析 F 检验中，什么表示分裂好？","options":["A high p-value","A low p-value, i.e., a large between-branch variance relative to within-branch variance","Equal means in all branches","A within-branch sum of squares of zero is required"],"optionZh":["p 值高","p 值低，即分支间方差相对分支内方差很大","所有分支的均值相等","必须分支内平方和为 0"],"answer":1,"explanation":"B 正确：F = [SS_between/(B − 1)] / [SS_within/(N − B)]。分支间差异大、分支内差异小，F 大，p 值低。","lessonId":"dsfb-03","lessonPage":43,"lessonPageTitle":"Splitting decision"},{"id":"s5-q098","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":98,"level":"真题同型 · 500 题强化","question":"What does the prediction function of a regression tree look like for a single input?","questionZh":"对单个输入变量，回归树的预测函数是什么样？","options":["A straight line","A smooth curve","A step function with constant predictions within each segment","A circle"],"optionZh":["一条直线","一条平滑曲线","阶梯函数，每段内预测值恒定","一个圆"],"answer":2,"explanation":"C 正确：讲义第 45 页：例如年龄 < 25 预测收入 1000，25–30 预测 1500，以此类推。与线性回归的直线 y = a + bx 对比明显。","lessonId":"dsfb-03","lessonPage":45,"lessonPageTitle":"Regression trees"},{"id":"s5-q099","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":99,"level":"真题同型 · 500 题强化","question":"In ID3 for regression, which attribute is chosen for a decision node?","questionZh":"回归版 ID3 中，哪个属性被选为决策节点？","options":["The attribute with the largest standard deviation reduction","The attribute with the smallest standard deviation reduction","The attribute with the most categories","A random attribute"],"optionZh":["标准差下降最大的属性","标准差下降最小的属性","类别最多的属性","随机属性"],"answer":0,"explanation":"A 正确：讲义第 53 页 Step 3。真题第 10 题 D 选项说选最小的，所以是错的。","lessonId":"dsfb-03","lessonPage":48,"lessonPageTitle":"ID3 with SDR"},{"id":"s5-q100","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":100,"level":"真题同型 · 500 题强化","question":"Before a split, the standard deviation of the target is 9.32. After splitting on Outlook, the weighted standard deviation of the branches is 7.66. What is the standard deviation reduction (SDR)?","questionZh":"分裂前目标变量的标准差为 9.32。按 Outlook 分裂后，各分支的加权标准差为 7.66。标准差下降（SDR）是多少？","options":["16.98","0.82","7.66","1.66"],"optionZh":["16.98","0.82","7.66","1.66"],"answer":3,"explanation":"D 正确：SDR = 分裂前标准差 − 分裂后加权标准差 = 9.32 − 7.66 = 1.66。","lessonId":"dsfb-03","lessonPage":52,"lessonPageTitle":"ID3 with SDR"},{"id":"s5-q101","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":101,"level":"真题同型 · 500 题强化","question":"In ID3 with SDR, what is used to decide when to stop branching?","questionZh":"在使用 SDR 的 ID3 中，用什么决定何时停止分支？","options":["The coefficient of variation (CV) falling below a threshold and/or too few instances in a branch","The AUC on the training set","The Gini index reaching 0.5","The number of attributes"],"optionZh":["变异系数（CV）低于阈值，和/或分支中实例太少","训练集上的 AUC","Gini 指数达到 0.5","属性个数"],"answer":0,"explanation":"A 正确：讲义第 50、54 页：标准差用于选分裂，CV（如低于 10%）和计数 n（如少于 3）用于决定停止，叶节点的预测值是平均值。","lessonId":"dsfb-03","lessonPage":50,"lessonPageTitle":"ID3 with SDR"},{"id":"s5-q102","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":102,"level":"真题同型 · 500 题强化","question":"In a regression tree built with ID3 and SDR, what is the predicted value in a leaf node?","questionZh":"用 ID3 和 SDR 建立的回归树中，叶节点的预测值是什么？","options":["The median of the parent node","The most frequent value","The maximum value","The average of the target values of the observations in the leaf"],"optionZh":["父节点的中位数","出现最多的值","最大值","叶节点中观测目标值的平均值"],"answer":3,"explanation":"D 正确：讲义第 50 页：Average (x̄) is the predicted value in the leaf nodes。","lessonId":"dsfb-03","lessonPage":50,"lessonPageTitle":"ID3 with SDR"},{"id":"s5-q103","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":103,"level":"真题同型 · 500 题强化","question":"In the cellular phone churn tree, a manager wants to target customers first. How should the tree be used?","questionZh":"在手机流失决策树案例中，经理想先联系一部分客户。应如何使用这棵树？","options":["Target the leaves with the highest estimated churn probability and read their decision rules to interpret who they are","Target the root node","Target leaves with the fewest customers","Ignore the tree and target randomly"],"optionZh":["先联系估计流失概率最高的叶节点，并读出对应决策规则来理解这些客户是谁","联系根节点的客户","联系客户最少的叶节点","忽略这棵树，随机联系"],"answer":0,"explanation":"A 正确：讲义第 40 页的问题：先联系谁、规则是什么、能否解释。树的叶节点给出概率和可读的规则，这正是它可解释性的优势（注意第 9 章会进一步指出要看挽留效果而非流失风险）。","lessonId":"dsfb-03","lessonPage":40,"lessonPageTitle":"Which customers would you target"},{"id":"s5-q104","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":104,"level":"真题同型 · 500 题强化","question":"Why is information gain based on entropy or Gini preferred over directly using the improvement in accuracy (min(p_red, p_green)) to evaluate splits?","questionZh":"为什么用基于熵或 Gini 的信息增益评估分裂，比直接用准确率提升（min(p_red, p_green)）更好？","options":["Because accuracy is always zero","Because entropy and Gini are strictly concave, so splits that improve purity are rewarded even when they do not change the majority class","Because entropy is faster to compute","Because accuracy requires a test set"],"optionZh":["因为准确率总是 0","因为熵和 Gini 是严格凹函数，即使分裂没改变多数类，提高纯度的分裂也会被奖励","因为熵算得更快","因为准确率需要测试集"],"answer":1,"explanation":"B 正确：讲义第 34 页（课外拓展）：用 min(p) 作为不纯度时，很多有用的分裂（两个子节点多数类仍相同）的增益为 0，树会过早停止生长。凹的熵和 Gini 能识别这些改进。","lessonId":"dsfb-03","lessonPage":34,"lessonPageTitle":"Why do we use information gain and not directly improvement in accuracy in evaluating"},{"id":"s5-q105","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":105,"level":"真题同型 · 500 题强化","question":"Why are globally optimal tree learners rarely used?","questionZh":"为什么全局最优的决策树学习器很少使用？","options":["Because they always overfit","Because they cannot handle categorical variables","Because the number of possible trees grows exponentially, making them computationally very expensive","Because greedy trees are always globally optimal"],"optionZh":["因为它们总会过拟合","因为它们无法处理类别变量","因为可能的树的数量呈指数增长，计算代价非常高","因为贪婪树总是全局最优"],"answer":2,"explanation":"C 正确：讲义第 22 页：可能的树的数量随变量数、取值数和一次评估的层数指数增长。D 错：贪婪方法不保证全局最优。","lessonId":"dsfb-03","lessonPage":22,"lessonPageTitle":"Why don’t we?"},{"id":"s5-q106","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":106,"level":"真题同型 · 500 题强化","question":"What does the acronym CHAID stand for, and which statistical test does it use?","questionZh":"CHAID 是什么的缩写？它用什么统计检验？","options":["Chi-squared Automatic Interaction Detection, using the chi-squared test","Classification Hierarchical Automatic ID, using the t-test","Cost-sensitive Hierarchical AI Decision, using AUC","Clustering Hierarchical Agglomerative ID, using Gini"],"optionZh":["卡方自动交互检测（Chi-squared Automatic Interaction Detection），使用卡方检验","分类层次自动识别，使用 t 检验","成本敏感层次 AI 决策，使用 AUC","聚类层次凝聚识别，使用 Gini"],"answer":0,"explanation":"A 正确：讲义第 10、24 页：CHAID 由 Hartigan（1975）提出，名字里就强调了检测交互效应。","lessonId":"dsfb-03","lessonPage":24,"lessonPageTitle":"Interaction effects!"},{"id":"s5-q107","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 3: Predictive Analytics – Decision Trees","number":107,"level":"真题同型 · 500 题强化","question":"Two leaves both have \"good\" as majority class: one with P(Good) = 0.80, another with P(Good) = 0.55. Why is reporting class probabilities useful here?","questionZh":"两个叶节点的多数类都是“好”：一个 P(好) = 0.80，另一个 P(好) = 0.55。为什么输出类别概率在这里有用？","options":["It is not useful; both are classified as good.","It allows treating the leaves differently, e.g., applying a cost-sensitive threshold that may reject the 0.55 leaf.","It increases the depth of the tree.","It changes the impurity of the parent node."],"optionZh":["没用，两个都被判为好。","可以区别对待两个叶节点，例如用成本敏感阈值可能拒绝 0.55 那个叶节点。","能增加树的深度。","能改变父节点的不纯度。"],"answer":1,"explanation":"B 正确：讲义第 11 页：概率带来区分度和决策灵活性。例如第 10 章德国信贷的阈值是 P(坏) > 0.167，0.55 的叶节点 P(坏) = 0.45，应当拒绝。","lessonId":"dsfb-03","lessonPage":11,"lessonPageTitle":"Simple: majority voting"},{"id":"s5-q108","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":108,"level":"真题同型 · 500 题强化","question":"Why should a predictive model be evaluated on observations that were not used to develop it?","questionZh":"为什么预测模型要在未参与建模的观测上评估？","options":["Because training data cannot be stored.","Because test data are always larger.","Because evaluation on training data is not allowed by law.","Because the model \"is\" the training data and will fit it well, so only unseen data shows its generalization power."],"optionZh":["因为训练数据无法保存。","因为测试数据总是更大。","因为法律不允许在训练数据上评估。","因为模型“就是”训练数据，必然拟合得好，只有未见数据才能体现泛化能力。"],"answer":3,"explanation":"D 正确：讲义第 9 页：很容易建一个完美拟合训练集的模型，但我们关心的是将来用于新观测时的表现。","lessonId":"dsfb-04","lessonPage":9,"lessonPageTitle":"Split sample method"},{"id":"s5-q109","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":109,"level":"真题同型 · 500 题强化","question":"What does stratified sampling ensure in the split sample method?","questionZh":"在分割样本法中，分层抽样确保了什么？","options":["That the training set contains only positives","That the distribution of the target variable is the same in training and test set","That the test set is larger than the training set","That there is no randomness"],"optionZh":["训练集只包含正类","目标变量在训练集和测试集中的分布相同","测试集比训练集大","没有任何随机性"],"answer":1,"explanation":"B 正确：在随机抽样的同时保证两个集合的类别比例一致，对不平衡数据尤其重要。","lessonId":"dsfb-04","lessonPage":10,"lessonPageTitle":"Split sample method"},{"id":"s5-q110","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":110,"level":"真题同型 · 500 题强化","question":"Which of the following is an example of data leakage given in the lecture?","questionZh":"以下哪项是讲义给出的数据泄露例子？","options":["Using stratified sampling","Standardizing inputs with training-set statistics","Calculating WOE before the train-test split","Using a validation set for early stopping"],"optionZh":["使用分层抽样","用训练集的统计量标准化输入","在训练/测试划分之前计算 WOE","用验证集做早停"],"answer":2,"explanation":"C 正确：讲义第 11 页：用全部数据（含测试集标签）算 WOE，测试集的信息就漏进了训练过程。另一个例子是 HR 离职预测中的“Exit-talk”变量（离职面谈只有在决定离职后才会发生）。","lessonId":"dsfb-04","lessonPage":11,"lessonPageTitle":"Data leakage!"},{"id":"s5-q111","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":111,"level":"真题同型 · 500 题强化","question":"An HR turnover data set contains the variable \"exit talk held\". Why is this problematic?","questionZh":"某 HR 离职数据集中有变量“是否已进行离职面谈”。这有什么问题？","options":["It is a categorical variable.","It contains information that is not available at prediction time, causing target leakage.","It has too many missing values.","It is perfectly uncorrelated with turnover."],"optionZh":["它是类别变量。","它包含预测时无法获得的信息，造成目标泄露。","它的缺失值太多。","它与离职完全不相关。"],"answer":1,"explanation":"B 正确：离职面谈只会在员工决定离开后发生，模型在测试集上会显得极其准确，但上线后这个变量还不存在，表现会大幅下降。","lessonId":"dsfb-04","lessonPage":11,"lessonPageTitle":"Data leakage!"},{"id":"s5-q112","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":112,"level":"真题同型 · 500 题强化","question":"What is the main purpose of out-of-time evaluation?","questionZh":"跨时间（out-of-time）评估的主要目的是什么？","options":["To check whether the relations captured by the model hold over time","To reduce the size of the training set","To guarantee that no data leakage occurs","To avoid the need for a test set"],"optionZh":["检验模型捕捉的关系是否随时间保持","减小训练集","保证不发生数据泄露","避免需要测试集"],"answer":0,"explanation":"A 正确：讲义第 12 页：用较早的数据训练、较新的数据测试，处理时间维度。代价是最新、可能最有代表性的数据没用于训练。C 错：它不是万能的防泄露方法（真题第 12 题）。","lessonId":"dsfb-04","lessonPage":12,"lessonPageTitle":"Split sample method"},{"id":"s5-q113","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":113,"level":"真题同型 · 500 题强化","question":"A churn model built on customers from Belgium is evaluated on customers from the Netherlands. What type of evaluation is this?","questionZh":"用比利时客户建立的流失模型，在荷兰客户上评估。这是哪种评估？","options":["Out-of-time evaluation","Leave-one-out cross-validation","Single sample evaluation","Out-of-universe evaluation"],"optionZh":["跨时间评估","留一交叉验证","单样本评估","跨总体（out-of-universe）评估"],"answer":3,"explanation":"D 正确：讲义第 16 页：在与建模总体不同的总体（不同客户、不同客户群）上评估，有不同程度的“out-of-universe”。","lessonId":"dsfb-04","lessonPage":16,"lessonPageTitle":"Split sample method"},{"id":"s5-q114","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":114,"level":"真题同型 · 500 题强化","question":"When is n-fold cross-validation preferred over the split sample method?","questionZh":"什么时候 n 折交叉验证比分割样本法更合适？","options":["For small data sets, where setting aside 30% for testing wastes data and a single small test set may be unrepresentative","For very large data sets only","When no target variable is available","When the model has no parameters"],"optionZh":["数据集较小时，留出 30% 测试浪费数据，而且单个小测试集可能不具代表性","只适用于非常大的数据集","没有目标变量时","模型没有参数时"],"answer":0,"explanation":"A 正确：讲义第 17 页：小数据（< 1000 个观测）时，交叉验证每个观测都既用于训练也用于测试，更高效、更可靠。","lessonId":"dsfb-04","lessonPage":17,"lessonPageTitle":"Cross-validation"},{"id":"s5-q115","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":115,"level":"真题同型 · 500 题强化","question":"In 10-fold cross-validation, how many models are developed and on what are they evaluated?","questionZh":"在 10 折交叉验证中，要建多少个模型，在什么上评估？","options":["1 model, evaluated on all folds","10 models, each trained on 9 folds and evaluated on the held-out fold","9 models, each evaluated on the training data","10 models, each trained and evaluated on the same fold"],"optionZh":["1 个模型，在所有折上评估","10 个模型，每个在 9 折上训练，在留出的那 1 折上评估","9 个模型，各在训练数据上评估","10 个模型，每个在同一折上训练和评估"],"answer":1,"explanation":"B 正确：每次留出一折测试，其余九折训练，重复十次，取平均表现。最终模型可以在全部数据上重新训练。","lessonId":"dsfb-04","lessonPage":17,"lessonPageTitle":"Cross-validation"},{"id":"s5-q116","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":116,"level":"真题同型 · 500 题强化","question":"Which statement about leave-one-out cross-validation is TRUE?","questionZh":"关于留一交叉验证，哪项说法正确？","options":["It minimizes the computational requirements.","It uses only one observation for training.","It results in minimal variability across the resulting models, but has high computational requirements.","It is the same as the split sample method."],"optionZh":["它的计算量最小。","它只用一个观测训练。","得到的各模型之间变化最小，但计算量大。","它与分割样本法相同。"],"answer":2,"explanation":"C 正确：讲义第 19 页：每次只留一个观测，N 个模型的训练集几乎相同，所以模型差异很小；但要训练 N 次（真题第 12 题 C 选项把计算量说反了）。","lessonId":"dsfb-04","lessonPage":19,"lessonPageTitle":"Cross-validation"},{"id":"s5-q117","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":117,"level":"真题同型 · 500 题强化","question":"Why is stratified n-fold cross-validation important for an imbalanced class distribution?","questionZh":"为什么对不平衡类别分布，分层 n 折交叉验证很重要？","options":["Because otherwise some folds may contain very few or no positives, making evaluation unreliable","Because it removes the minority class","Because it increases the number of folds","Because it avoids training altogether"],"optionZh":["否则有些折可能只有极少或没有正类，评估不可靠","因为它删除少数类","因为它增加折数","因为它完全不需要训练"],"answer":0,"explanation":"A 正确：如果正类只占 2%，随机分折可能某一折里一个正类都没有，那一折上的敏感度等指标就没法算。","lessonId":"dsfb-04","lessonPage":18,"lessonPageTitle":"Cross-validation"},{"id":"s5-q118","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":118,"level":"真题同型 · 500 题强化","question":"Which statement about the single sample method is TRUE?","questionZh":"关于单样本方法，哪项说法正确？","options":["It evaluates the model on a separate test set.","It rewards reduced training error and punishes model complexity, since more complexity always lowers training error.","It always prefers the most complex model.","It is the data scientist's approach to evaluation."],"optionZh":["它在独立测试集上评估模型。","它奖励训练误差的降低、惩罚模型复杂度，因为复杂度越高训练误差总是越低。","它总是偏好最复杂的模型。","它是数据科学家的评估方法。"],"answer":1,"explanation":"B 正确：讲义第 20 页：这是统计学家的方法（解释性），没有测试集，所以要惩罚复杂度以防过拟合。A 描述的是分割样本法，D 也是。","lessonId":"dsfb-04","lessonPage":20,"lessonPageTitle":"Single sample method"},{"id":"s5-q119","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":119,"level":"真题同型 · 500 题强化","question":"A logistic regression with 5 parameters has log-likelihood log L = −200. What is its AIC?","questionZh":"一个有 5 个参数的逻辑回归，对数似然 log L = −200。它的 AIC 是多少？","options":["205","400","410","390"],"optionZh":["205","400","410","390"],"answer":2,"explanation":"C 正确：AIC = −2 log L + 2 × 参数个数 = 400 + 10 = 410。AIC 越小越好。","lessonId":"dsfb-04","lessonPage":21,"lessonPageTitle":"Single sample method"},{"id":"s5-q120","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":120,"level":"真题同型 · 500 题强化","question":"Model A has AIC 410 and Model B has AIC 395, both fitted on the same data set. Which statement is TRUE?","questionZh":"模型 A 的 AIC 为 410，模型 B 为 395，两者在同一数据集上拟合。哪项说法正确？","options":["Model A is preferred because it has a higher AIC.","AIC cannot be compared between models.","Both models are equally good.","Model B is preferred because the best model has the minimum AIC."],"optionZh":["模型 A 更好，因为 AIC 更高。","AIC 不能在模型之间比较。","两个模型一样好。","模型 B 更好，因为最好的模型 AIC 最小。"],"answer":3,"explanation":"D 正确：讲义第 21 页。B 错：同一数据集上拟合的模型可以比较，只是不能跨数据集比较。","lessonId":"dsfb-04","lessonPage":21,"lessonPageTitle":"Single sample method"},{"id":"s5-q121","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":121,"level":"真题同型 · 500 题强化","question":"Which statement comparing AIC and BIC is TRUE?","questionZh":"关于 AIC 和 BIC 的比较，哪项说法正确？","options":["BIC punishes complexity more than AIC (for data sets with more than a handful of observations).","AIC punishes complexity more than BIC.","Neither takes the number of parameters into account.","The best model has the maximum BIC."],"optionZh":["BIC 对复杂度的惩罚比 AIC 更重（只要样本数不是极少）。","AIC 对复杂度的惩罚比 BIC 更重。","两者都不考虑参数个数。","最好的模型 BIC 最大。"],"answer":0,"explanation":"A 正确：BIC 每个参数惩罚 log(n)，AIC 每个参数惩罚 2。n > e² ≈ 7.4 时 log(n) > 2，所以 BIC 更严格。","lessonId":"dsfb-04","lessonPage":21,"lessonPageTitle":"Single sample method"},{"id":"s5-q122","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":122,"level":"真题同型 · 500 题强化","question":"Scores and actual classes: John (Bad, 0.84), Emma (Good, 0.76), David (Bad, 0.48), Sophie (Good, 0.44), Bob (Good, 0.18). With cut-off 0.50 and Bad = positive, what is the sensitivity?","questionZh":"得分与实际类别：John（坏，0.84）、Emma（好，0.76）、David（坏，0.48）、Sophie（好，0.44）、Bob（好，0.18）。阈值 0.50，坏为正类，敏感度是多少？","options":["2/3","3/5","1/2","1"],"optionZh":["2/3","3/5","1/2","1"],"answer":2,"explanation":"C 正确：两个真坏客户中，John 被识别（TP），David 漏掉（FN），敏感度 = TP/(TP + FN) = 1/2。A 是特异度，B 是准确率。","lessonId":"dsfb-04","lessonPage":24,"lessonPageTitle":"Performance metrics: example"},{"id":"s5-q123","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":123,"level":"真题同型 · 500 题强化","question":"In the same example (John Bad 0.84, Emma Good 0.76, David Bad 0.48, Sophie Good 0.44, Bob Good 0.18; cut-off 0.50), what is the specificity?","questionZh":"同一例子（John 坏 0.84，Emma 好 0.76，David 坏 0.48，Sophie 好 0.44，Bob 好 0.18；阈值 0.50），特异度是多少？","options":["2/3","1/2","1/3","3/5"],"optionZh":["2/3","1/2","1/3","3/5"],"answer":0,"explanation":"A 正确：三个好客户中 Sophie、Bob 被正确判为好（TN = 2），Emma 被误判为坏（FP = 1），特异度 = TN/(TN + FP) = 2/3。","lessonId":"dsfb-04","lessonPage":24,"lessonPageTitle":"Performance metrics: example"},{"id":"s5-q124","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":124,"level":"真题同型 · 500 题强化","question":"In the same example with cut-off 0.50, what are accuracy and error rate?","questionZh":"同一例子，阈值 0.50 时，准确率和错误率分别是多少？","options":["2/5 and 3/5","4/5 and 1/5","1/2 and 1/2","3/5 and 2/5"],"optionZh":["2/5 和 3/5","4/5 和 1/5","1/2 和 1/2","3/5 和 2/5"],"answer":3,"explanation":"D 正确：判对 John、Sophie、Bob 三个，判错 Emma、David 两个。准确率 = 3/5，错误率 = 2/5，两者相加为 1。","lessonId":"dsfb-04","lessonPage":24,"lessonPageTitle":"Performance metrics: example"},{"id":"s5-q125","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":125,"level":"真题同型 · 500 题强化","question":"In the same five-customer example, the cut-off is lowered to 0.40. What happens to sensitivity and specificity?","questionZh":"同样五位客户，阈值降到 0.40。敏感度和特异度会怎样变化？","options":["Sensitivity rises to 1, specificity drops to 1/3.","Both rise.","Sensitivity drops, specificity rises.","Nothing changes."],"optionZh":["敏感度升到 1，特异度降到 1/3。","两者都上升。","敏感度下降，特异度上升。","没有变化。"],"answer":0,"explanation":"A 正确：阈值 0.40 时 John、Emma、David、Sophie 都被判为坏。两个坏客户都被识别，敏感度 = 2/2 = 1；三个好客户中只有 Bob 判对，特异度 = 1/3。降低阈值以误报换取更高的检出率。","lessonId":"dsfb-04","lessonPage":24,"lessonPageTitle":"Performance metrics: example"},{"id":"s5-q126","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":126,"level":"真题同型 · 500 题强化","question":"A fraud model yields TP = 40, FN = 10, FP = 60, TN = 890. What is the sensitivity (recall)?","questionZh":"某欺诈模型结果为 TP = 40、FN = 10、FP = 60、TN = 890。敏感度（召回率）是多少？","options":["0.40","0.80","0.937","0.93"],"optionZh":["0.40","0.80","0.937","0.93"],"answer":1,"explanation":"B 正确：敏感度 = TP/(TP + FN) = 40/50 = 0.80。A 是精确率 40/100。D 是准确率 930/1000。C 是特异度 890/950。","lessonId":"dsfb-04","lessonPage":25,"lessonPageTitle":"Performance metrics"},{"id":"s5-q127","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":127,"level":"真题同型 · 500 题强化","question":"For TP = 40, FN = 10, FP = 60, TN = 890, what is the precision?","questionZh":"对于 TP = 40、FN = 10、FP = 60、TN = 890，精确率是多少？","options":["0.80","0.93","0.60","0.40"],"optionZh":["0.80","0.93","0.60","0.40"],"answer":3,"explanation":"D 正确：精确率 = 被预测为正类中真正为正类的比例 = TP/(TP + FP) = 40/100 = 0.40。A 是召回率。","lessonId":"dsfb-04","lessonPage":27,"lessonPageTitle":"F1 score"},{"id":"s5-q128","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":128,"level":"真题同型 · 500 题强化","question":"For TP = 40, FN = 10, FP = 60, TN = 890 (precision 0.40, recall 0.80), what is the F1 score?","questionZh":"对于 TP = 40、FN = 10、FP = 60、TN = 890（精确率 0.40，召回率 0.80），F1 分数是多少？","options":["0.60","≈ 0.53","0.32","0.93"],"optionZh":["0.60","≈ 0.53","0.32","0.93"],"answer":1,"explanation":"B 正确：F1 = 2 × 0.4 × 0.8 / (0.4 + 0.8) = 0.64/1.2 ≈ 0.533。A 是算术平均，调和平均会更靠近较小的那个数。D 是准确率，在不平衡数据上显得虚高。","lessonId":"dsfb-04","lessonPage":27,"lessonPageTitle":"F1 score"},{"id":"s5-q129","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":129,"level":"真题同型 · 500 题强化","question":"Why is the F1 score often preferred over accuracy for imbalanced class distributions?","questionZh":"为什么在类别不平衡时常用 F1 分数而不是准确率？","options":["Because F1 ignores the positive class.","Because F1 is always higher than accuracy.","Because F1 combines precision and recall on the positive class, while accuracy can be high by simply predicting the majority class.","Because F1 does not depend on the confusion matrix."],"optionZh":["因为 F1 忽略正类。","因为 F1 总是高于准确率。","因为 F1 结合了正类的精确率和召回率，而准确率只要预测多数类就能很高。","因为 F1 不依赖混淆矩阵。"],"answer":2,"explanation":"C 正确：F1 是精确率和召回率的调和平均，只要其中一个很低 F1 就低。Fβ 分数可以调整两者的相对重要性。","lessonId":"dsfb-04","lessonPage":27,"lessonPageTitle":"F1 score"},{"id":"s5-q130","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":130,"level":"真题同型 · 500 题强化","question":"What does the ROC curve plot?","questionZh":"ROC 曲线绘制的是什么？","options":["Precision versus recall","Accuracy versus cut-off","Lift versus percentage targeted","Sensitivity versus 1 − specificity, for every possible cut-off"],"optionZh":["精确率对召回率","准确率对阈值","提升度对目标比例","每个可能阈值下的敏感度对 1 − 特异度"],"answer":3,"explanation":"D 正确：讲义第 28 页：y 轴是敏感度（检出率），x 轴是 1 − 特异度（误报率）。随机模型是对角线。","lessonId":"dsfb-04","lessonPage":28,"lessonPageTitle":"Receiver Operating Characteristic Curve"},{"id":"s5-q131","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":131,"level":"真题同型 · 500 题强化","question":"Which point in ROC space represents a perfect classifier?","questionZh":"ROC 空间中哪个点代表完美分类器？","options":["(0, 1): false positive rate 0 and sensitivity 1","(1, 0)","(0.5, 0.5)","(1, 1)"],"optionZh":["(0, 1)：误报率 0，敏感度 1","(1, 0)","(0.5, 0.5)","(1, 1)"],"answer":0,"explanation":"A 正确：x = 1 − 特异度 = 0（没有误报），y = 敏感度 = 1（没有漏报）。讲义第 38 页样题故意把它写成 (1, 0)，那是最差的点。D 是把所有人都判为正类。","lessonId":"dsfb-04","lessonPage":38,"lessonPageTitle":"Sample question - medium"},{"id":"s5-q132","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":132,"level":"真题同型 · 500 题强化","question":"What is the intuitive interpretation of the AUC?","questionZh":"AUC 的直观含义是什么？","options":["The proportion of correctly classified instances","The probability that a randomly chosen positive instance is ranked higher than a randomly chosen negative instance","The optimal cut-off","The average profit"],"optionZh":["被正确分类实例的比例","随机抽一个正类实例的得分高于随机抽一个负类实例的概率","最优阈值","平均利润"],"answer":1,"explanation":"B 正确：讲义第 29 页引用 Hanley 和 McNeil（1983）。AUC 衡量排序能力，不依赖阈值。A 是准确率。","lessonId":"dsfb-04","lessonPage":29,"lessonPageTitle":"ROC curve and Area under the ROC curve"},{"id":"s5-q133","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":133,"level":"真题同型 · 500 题强化","question":"A model has AUC = 0.35. Which statement is TRUE?","questionZh":"某模型的 AUC = 0.35。哪项说法正确？","options":["This is impossible, since AUC cannot be below 0.5.","The model is better than random.","The model ranks worse than random; inverting its scores would give an AUC of 0.65.","The model is perfect."],"optionZh":["不可能，AUC 不会低于 0.5。","模型优于随机。","模型的排序比随机还差；把得分反过来就得到 AUC 0.65。","模型完美。"],"answer":2,"explanation":"C 正确：AUC < 0.5 说明排序方向反了，1 − 0.35 = 0.65。真题第 11 题 B 选项说低于 0.5 不可能，是错的。","lessonId":"dsfb-04","lessonPage":29,"lessonPageTitle":"ROC curve and Area under the ROC curve"},{"id":"s5-q134","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":134,"level":"真题同型 · 500 题强化","question":"A credit scorecard has AUC = 0.80. What is its accuracy ratio (Gini)?","questionZh":"某信用评分卡的 AUC = 0.80。它的准确率比（Gini）是多少？","options":["0.40","0.80","1.60","0.60"],"optionZh":["0.40","0.80","1.60","0.60"],"answer":3,"explanation":"D 正确：AR = 2 × AUC − 1 = 1.6 − 1 = 0.6。完美模型 AR = 1，随机模型 AR = 0。","lessonId":"dsfb-04","lessonPage":32,"lessonPageTitle":"Accuracy ratio or Gini"},{"id":"s5-q135","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":135,"level":"真题同型 · 500 题强化","question":"A model has a Gini (accuracy ratio) of 0.50. What is its AUC?","questionZh":"某模型的 Gini（准确率比）为 0.50。它的 AUC 是多少？","options":["0.25","0.50","0.75","1.00"],"optionZh":["0.25","0.50","0.75","1.00"],"answer":2,"explanation":"C 正确：AUC = (AR + 1)/2 = 1.5/2 = 0.75。","lessonId":"dsfb-04","lessonPage":32,"lessonPageTitle":"Accuracy ratio or Gini"},{"id":"s5-q136","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":136,"level":"真题同型 · 500 题强化","question":"How is the cumulative accuracy profile (CAP) curve constructed?","questionZh":"累积准确率曲线（CAP）如何构建？","options":["By sorting the population from high to low probability of being positive and plotting the cumulative percentage of positives captured","By plotting precision against recall","By plotting the training error per epoch","By plotting the distribution of the target variable"],"optionZh":["按为正类的概率从高到低排序，绘制累计捕获的正类百分比","绘制精确率对召回率","绘制每个 epoch 的训练误差","绘制目标变量的分布"],"answer":0,"explanation":"A 正确：讲义第 31 页：例如前 30% 得分最高的客户中，模型捕获了 65% 的正类。也叫 Lorenz 曲线、power 曲线或 Gini 曲线。","lessonId":"dsfb-04","lessonPage":31,"lessonPageTitle":"Cumulative accuracy profile (CAP) curve"},{"id":"s5-q137","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":137,"level":"真题同型 · 500 题强化","question":"In the CAP-based accuracy ratio AR = B/(A + B), what is the AR of a random model and of a perfect model?","questionZh":"在基于 CAP 的准确率比 AR = B/(A + B) 中，随机模型和完美模型的 AR 分别是多少？","options":["0.5 and 1","0 and 1","1 and 0","0 and 0.5"],"optionZh":["0.5 和 1","0 和 1","1 和 0","0 和 0.5"],"answer":1,"explanation":"B 正确：随机模型的 CAP 就是对角线，B 面积为 0；完美模型的曲线与完美曲线重合，A 面积为 0，AR = 1。","lessonId":"dsfb-04","lessonPage":32,"lessonPageTitle":"Accuracy ratio or Gini"},{"id":"s5-q138","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":138,"level":"真题同型 · 500 题强化","question":"In the top 10% of customers ranked by a churn model, 30% are churners. The overall churn rate is 5%. What is the top-decile lift?","questionZh":"按流失模型排序的前 10% 客户中，30% 是流失者。总体流失率为 5%。前十分位提升度是多少？","options":["6","1.5","25","3"],"optionZh":["6","1.5","25","3"],"answer":0,"explanation":"A 正确：lift = 该段中正类比例 / 总体正类比例 = 30%/5% = 6。随机排序的提升度永远是 1。","lessonId":"dsfb-04","lessonPage":37,"lessonPageTitle":"Lift curve"},{"id":"s5-q139","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":139,"level":"真题同型 · 500 题强化","question":"What is the lift of a random model at any cut-off?","questionZh":"随机模型在任何阈值下的提升度是多少？","options":["0","0.5","1","It depends on the class distribution."],"optionZh":["0","0.5","1","取决于类别分布。"],"answer":2,"explanation":"C 正确：随机挑选的客户中正类比例与总体一样，比值为 1。","lessonId":"dsfb-04","lessonPage":37,"lessonPageTitle":"Lift curve"},{"id":"s5-q140","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":140,"level":"真题同型 · 500 题强化","question":"A bank can only contact the 5% highest-risk customers. Which measure best reflects model usefulness for this decision?","questionZh":"银行只能联系风险最高的 5% 客户。哪个指标最能反映模型对这个决策的价值？","options":["Overall accuracy at cut-off 0.5","Top 5% lift","R-squared","The number of parameters"],"optionZh":["阈值 0.5 下的总体准确率","前 5% 提升度","R²","参数个数"],"answer":1,"explanation":"B 正确：只看模型排在最前面那一段的表现。AUC 衡量整体排序，但业务只用到前 5%，前 5% 提升度更贴近决策（第 10 章还会进一步用利润衡量）。","lessonId":"dsfb-04","lessonPage":37,"lessonPageTitle":"Lift curve"},{"id":"s5-q141","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":141,"level":"真题同型 · 500 题强化","question":"Why is the Mahalanobis distance preferred over a simple difference of mean scores to measure the separation of positives and negatives?","questionZh":"为什么衡量正负类得分分离程度时，马氏距离比简单的均值差更好？","options":["Because it takes the (pooled) standard deviation of the scores into account","Because it does not need the means","Because it is always larger","Because it uses the class labels to compute the scores"],"optionZh":["因为它考虑了得分的（合并）标准差","因为它不需要均值","因为它总是更大","因为它用类别标签计算得分"],"answer":0,"explanation":"A 正确：M = (μ_P − μ_N)/σ。两组均值相差 10 分，如果分布很宽可能高度重叠，如果很窄则分得很开。相关的发散度（divergence）用平方差除以两组方差的平均。","lessonId":"dsfb-04","lessonPage":36,"lessonPageTitle":"Distance measures"},{"id":"s5-q142","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":142,"level":"真题同型 · 500 题强化","question":"Positives have mean score 600 and negatives 500, with a pooled standard deviation of 50. What is the Mahalanobis distance M?","questionZh":"正类平均得分 600，负类 500，合并标准差为 50。马氏距离 M 是多少？","options":["100","0.5","4","2"],"optionZh":["100","0.5","4","2"],"answer":3,"explanation":"D 正确：M = (600 − 500)/50 = 2。A 只是均值差，没有考虑分布宽度。","lessonId":"dsfb-04","lessonPage":36,"lessonPageTitle":"Distance measures"},{"id":"s5-q143","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":143,"level":"真题同型 · 500 题强化","question":"For multiclass rating problems, why is a plain confusion matrix not sufficient?","questionZh":"对多类别评级问题，为什么单纯的混淆矩阵不够？","options":["Because it has no diagonal.","Because sensitivity can still be computed directly.","Because not all errors have equal impact: the farther from the diagonal, the bigger the error.","Because ratings are continuous."],"optionZh":["因为它没有对角线。","因为仍然可以直接计算敏感度。","因为不是所有错误影响都一样：离对角线越远，错误越大。","因为评级是连续的。"],"answer":2,"explanation":"C 正确：把 A+ 预测成 A 和预测成 C 都是“错”，但严重程度不同。所以讲义介绍了 notch difference graph（按相差几个等级累计准确率）。","lessonId":"dsfb-04","lessonPage":42,"lessonPageTitle":"Not all errors have equal impact"},{"id":"s5-q144","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":144,"level":"真题同型 · 500 题强化","question":"What does a notch difference graph show for a rating model?","questionZh":"评级模型的 notch difference graph（级差图）显示什么？","options":["The cumulative accuracy when allowing for a difference of 0, 1, 2, … rating notches","The ROC curve for each class","The training loss","The class distribution only"],"optionZh":["允许相差 0、1、2……个等级时的累计准确率","每个类别的 ROC 曲线","训练损失","只有类别分布"],"answer":0,"explanation":"A 正确：0 级差时就是普通准确率；允许 1 级差时，预测与真实相差一个等级也算对，以此类推，曲线逐渐升到 100%。","lessonId":"dsfb-04","lessonPage":43,"lessonPageTitle":"Notch difference graph"},{"id":"s5-q145","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":145,"level":"真题同型 · 500 题强化","question":"How can an overall AUC be computed for a multiclass problem (method 1 in the lecture)?","questionZh":"多分类问题如何计算整体 AUC（讲义中的方法 1）？","options":["Use the AUC of the largest class only.","Compute one-vs-rest ROC curves and AUCs per class, and take a weighted average using class prior probabilities as weights.","Multiply all pairwise AUCs.","It cannot be computed."],"optionZh":["只用最大类别的 AUC。","对每个类别做“一对其余”的 ROC 和 AUC，再以类别先验概率为权重取加权平均。","把所有两两 AUC 相乘。","无法计算。"],"answer":1,"explanation":"B 正确：方法 2 是对每一对类别算 AUC 再取平均（Hand 和 Till 的推广）。","lessonId":"dsfb-04","lessonPage":46,"lessonPageTitle":"Method 1:"},{"id":"s5-q146","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":146,"level":"真题同型 · 500 题强化","question":"An LGD model predicts 0.2, 0.4 and 0.6 for three loans with actual LGD 0.3, 0.4 and 0.8. What is the mean squared error (MSE)?","questionZh":"某 LGD 模型对三笔贷款预测 0.2、0.4、0.6，实际 LGD 为 0.3、0.4、0.8。均方误差（MSE）是多少？","options":["≈ 0.0167","0.1","0.05","≈ 0.129"],"optionZh":["≈ 0.0167","0.1","0.05","≈ 0.129"],"answer":0,"explanation":"A 正确：误差为 −0.1、0、−0.2，平方后 0.01、0、0.04，平均 0.05/3 ≈ 0.0167。D 是 RMSE（√0.0167 ≈ 0.129）。B 是 MAD（(0.1 + 0 + 0.2)/3）。C 是平方和没除以 n。","lessonId":"dsfb-04","lessonPage":48,"lessonPageTitle":"Evaluation measures for regression"},{"id":"s5-q147","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":147,"level":"真题同型 · 500 题强化","question":"For the same LGD example (errors −0.1, 0, −0.2), what is the mean absolute deviation (MAD)?","questionZh":"同一 LGD 例子（误差为 −0.1、0、−0.2），平均绝对偏差（MAD）是多少？","options":["0.3","−0.1","≈ 0.0167","0.1"],"optionZh":["0.3","−0.1","≈ 0.0167","0.1"],"answer":3,"explanation":"D 正确：MAD = (|−0.1| + 0 + |−0.2|)/3 = 0.3/3 = 0.1。取绝对值是为了避免正负误差抵消（B 就是正负抵消后的平均误差）。","lessonId":"dsfb-04","lessonPage":48,"lessonPageTitle":"Evaluation measures for regression"},{"id":"s5-q148","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":148,"level":"真题同型 · 500 题强化","question":"Which statement about R-squared is TRUE?","questionZh":"关于 R²，哪项说法正确？","options":["It always decreases when variables are added.","It measures the proportion of variability in the target explained by the model; adjusted R² corrects for the number of variables.","It is used to evaluate clustering.","It must be below zero for a good model."],"optionZh":["增加变量时它总会下降。","它衡量模型解释的目标变量变异比例；调整 R² 会对变量个数进行修正。","它用于评估聚类。","好的模型 R² 必须小于 0。"],"answer":1,"explanation":"B 正确：普通 R² 加变量只会不降，所以需要调整 R² 惩罚变量数。","lessonId":"dsfb-04","lessonPage":48,"lessonPageTitle":"Evaluation measures for regression"},{"id":"s5-q149","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":149,"level":"真题同型 · 500 题强化","question":"How can classification measures such as AUC be re-used to evaluate a regression model?","questionZh":"如何复用 AUC 等分类指标来评估回归模型？","options":["They cannot be re-used.","By rounding predictions to 0 or 1","By turning the continuous target into a binary target with a cut-off (e.g., the median) and using the predicted value as score","By computing the AUC on the training set only"],"optionZh":["无法复用。","把预测四舍五入到 0 或 1","用一个分界点（如中位数）把连续目标变成二元目标，并把预测值当作得分","只在训练集上计算 AUC"],"answer":2,"explanation":"C 正确：讲义第 51 页：这样 AUC 反映模型能否区分高值和低值。第 50 页说明分界点不同，AUC 也会不同（0.72、0.86、0.94）。","lessonId":"dsfb-04","lessonPage":51,"lessonPageTitle":"Evaluation measures for regression"},{"id":"s5-q150","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":150,"level":"真题同型 · 500 题强化","question":"Which of the following is NOT listed as a post-processing evaluation criterion beyond statistical accuracy?","questionZh":"以下哪项不是讲义列出的、统计准确度之外的后处理评估标准？","options":["Interpretability and justifiability","Economic cost","Operational efficiency and regulation","The number of colours in the dashboard"],"optionZh":["可解释性与可论证性","经济成本","运营效率与监管","仪表盘的颜色数量"],"answer":3,"explanation":"D 不是。讲义第 53 页还提到统计显著性、能源消耗、计算时间，以及最重要的：是否解决了业务问题。","lessonId":"dsfb-04","lessonPage":53,"lessonPageTitle":"Post-processing"},{"id":"s5-q151","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":151,"level":"真题同型 · 500 题强化","question":"After evaluation, a data scientist retrains the final model on all available data for deployment. What should be considered?","questionZh":"评估之后，数据科学家用全部数据重新训练最终模型用于部署。应该考虑什么？","options":["Whether the performance of the development-run model is representative of the deployment-run model","Nothing, since more data always gives exactly the same model","The test set should then be deleted.","The AUC of the new model must be computed on the training data."],"optionZh":["开发阶段模型的表现能否代表部署阶段模型的表现","不用考虑，因为数据越多模型总是完全相同","应该删除测试集。","新模型的 AUC 必须在训练数据上计算。"],"answer":0,"explanation":"A 正确：讲义第 14 页：用全部数据训练能最大化表现，但部署模型没有经过独立评估，要比较开发版和部署版模型是否一致。","lessonId":"dsfb-04","lessonPage":14,"lessonPageTitle":"Split sample method"},{"id":"s5-q152","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":152,"level":"真题同型 · 500 题强化","question":"Which evaluation approach corresponds to iterative out-of-time evaluation, as used in forecasting?","questionZh":"哪种评估方法对应于预测中使用的迭代式跨时间评估？","options":["Leave-one-out cross-validation","Rolling window evaluation","Single sample evaluation","Stratified sampling"],"optionZh":["留一交叉验证","滚动窗口评估","单样本评估","分层抽样"],"answer":1,"explanation":"B 正确：讲义第 15 页：窗口随时间向前滚动，每次用过去的数据训练、紧接着的一段测试。还要考虑窗口多长、是否给近期数据更高权重。","lessonId":"dsfb-04","lessonPage":15,"lessonPageTitle":"Split sample method"},{"id":"s5-q153","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":153,"level":"真题同型 · 500 题强化","question":"A model predicts \"no churn\" for all 1,000 customers, of which 50 actually churn. Which statement is TRUE?","questionZh":"某模型把 1,000 位客户全部预测为“不流失”，其中 50 人实际流失。哪项说法正确？","options":["Accuracy is 95% and sensitivity is 0.","Accuracy is 5% and sensitivity is 1.","Accuracy and sensitivity are both 95%.","Specificity is 0."],"optionZh":["准确率 95%，敏感度为 0。","准确率 5%，敏感度为 1。","准确率和敏感度都是 95%。","特异度为 0。"],"answer":0,"explanation":"A 正确：950 个判对，准确率 95%；50 个流失者一个也没找到，敏感度 0。特异度是 950/950 = 1（D 错）。这正是不平衡数据下不能只看准确率的原因。","lessonId":"dsfb-04","lessonPage":25,"lessonPageTitle":"Performance metrics"},{"id":"s5-q154","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":154,"level":"真题同型 · 500 题强化","question":"Which statement is FALSE?","questionZh":"哪项说法是错误的？","options":["AIC and BIC evaluate the trade-off between fit and complexity and are only meaningful for models built on the same data set.","The AUC estimates the probability that a randomly chosen positive is ranked higher than a randomly chosen negative.","The lift of a random model is 1.","Accuracy is independent of the chosen cut-off."],"optionZh":["AIC 和 BIC 评估拟合与复杂度的权衡，只适合比较同一数据集上建立的模型。","AUC 估计随机正类排在随机负类之前的概率。","随机模型的提升度为 1。","准确率与所选阈值无关。"],"answer":3,"explanation":"D 错误：准确率由混淆矩阵算出，混淆矩阵取决于阈值。不依赖阈值的是 AUC。A、B、C 都正确。","lessonId":"dsfb-04","lessonPage":39,"lessonPageTitle":"Sample question - difficult"},{"id":"s5-q155","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 4: Postprocessing","number":155,"level":"真题同型 · 500 题强化","question":"Which statement about the confusion matrix convention is TRUE?","questionZh":"关于混淆矩阵的排列惯例，哪项说法正确？","options":["Rows must always be the actual class.","The positive class must always be \"good\".","Which class is positive and whether rows are predicted or actual is a matter of convention, so always check the layout.","The confusion matrix is only defined for regression."],"optionZh":["行必须总是实际类别。","正类必须总是“好”。","哪类是正类、行代表预测还是实际都是惯例问题，所以一定要先看清排列。","混淆矩阵只对回归有定义。"],"answer":2,"explanation":"C 正确：讲义第 23、26 页反复说明“matter of convention”。Elkan（2001）用行表示预测、列表示实际；其他资料可能转置或交换行顺序，读题时先确认。","lessonId":"dsfb-04","lessonPage":26,"lessonPageTitle":"For your information:"},{"id":"s5-q156","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":156,"level":"真题同型 · 500 题强化","question":"How does k-nearest neighbors classify an unseen instance?","questionZh":"k 近邻如何对一个新实例分类？","options":["By assigning the class (or class probability) based on the observed classes of its k most similar historical instances, e.g., by majority vote","By fitting a logistic regression on all data","By building a decision tree on the k nearest instances","By using the class label to compute the similarity"],"optionZh":["根据与它最相似的 k 个历史实例的已知类别（如多数投票）给出类别或类别概率","在全部数据上拟合逻辑回归","在最近的 k 个实例上建决策树","用类别标签来计算相似度"],"answer":0,"explanation":"A 正确：讲义第 13 页。D 错：计算相似度时不能用类别标签（新实例本来就不知道标签）。","lessonId":"dsfb-05","lessonPage":13,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q157","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":157,"level":"真题同型 · 500 题强化","question":"Which statement about k-nearest neighbors is TRUE?","questionZh":"关于 k 近邻，哪项说法正确？","options":["A model with parameters is estimated during training.","The choice of k has no impact on performance.","No model is trained; the historical data is the model, and k is a hyperparameter that can be tuned.","kNN cannot be used for regression."],"optionZh":["训练时会估计一个带参数的模型。","k 的选择对性能没有影响。","不训练模型，历史数据本身就是模型，k 是可以调整的超参数。","kNN 不能用于回归。"],"answer":2,"explanation":"C 正确：讲义第 14 页。D 错：回归时取近邻结果的平均值。B 错：k 太小容易过拟合，k 太大会过于平滑。","lessonId":"dsfb-05","lessonPage":14,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q158","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":158,"level":"真题同型 · 500 题强化","question":"Why is an odd value of k often preferred in kNN classification with majority voting?","questionZh":"为什么在多数投票的 kNN 分类中常选奇数 k？","options":["To reduce computation time","To avoid ties in a two-class vote","Because even values are not allowed","To make the model linear"],"optionZh":["为了减少计算时间","为了在二分类投票中避免平票","因为偶数不被允许","为了让模型变成线性"],"answer":1,"explanation":"B 正确：两类投票时，k 为奇数就不会出现 2 比 2 这样的平票。","lessonId":"dsfb-05","lessonPage":14,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q159","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":159,"level":"真题同型 · 500 题强化","question":"For a kNN regression with k = 3, the three nearest neighbours have house prices €200k, €230k and €260k. What is the prediction?","questionZh":"k = 3 的 kNN 回归中，三个最近邻的房价分别为 €200k、€230k、€260k。预测值是多少？","options":["€260k","€200k","€690k","€230k"],"optionZh":["€260k","€200k","€690k","€230k"],"answer":3,"explanation":"D 正确：kNN 回归取近邻结果的平均，(200 + 230 + 260)/3 = 230k。C 是总和。","lessonId":"dsfb-05","lessonPage":14,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q160","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":160,"level":"真题同型 · 500 题强化","question":"With k = 5, the nearest neighbours of a loan applicant have labels Bad, Good, Bad, Good, Good. What are the predicted class and class probability of \"Bad\"?","questionZh":"k = 5 时，某贷款申请人的近邻标签为坏、好、坏、好、好。预测类别和“坏”的类别概率是多少？","options":["Bad, 0.6","Good, 0.6","Good, 0.4","Bad, 0.4"],"optionZh":["坏，0.6","好，0.6","好，0.4","坏，0.4"],"answer":2,"explanation":"C 正确：3 个好、2 个坏，多数投票为“好”；“坏”的概率 = 2/5 = 0.4。B 给的是“好”的概率。","lessonId":"dsfb-05","lessonPage":13,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q161","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":161,"level":"真题同型 · 500 题强化","question":"In distance-weighted kNN using weight 1/D², how does a neighbour at distance 2 compare with a neighbour at distance 1?","questionZh":"在用 1/D² 加权的 kNN 中，距离为 2 的近邻与距离为 1 的近邻相比，权重如何？","options":["It gets half the weight.","It gets one quarter of the weight.","It gets the same weight.","It gets twice the weight."],"optionZh":["权重是后者的一半。","权重是后者的四分之一。","权重相同。","权重是后者的两倍。"],"answer":1,"explanation":"B 正确：1/2² = 1/4，而 1/1² = 1，所以只有四分之一。距离越近影响越大，权重最后再归一化成贡献份额。","lessonId":"dsfb-05","lessonPage":16,"lessonPageTitle":"1 3 5 7 9"},{"id":"s5-q162","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":162,"level":"真题同型 · 500 题强化","question":"In the credit example, income (in euros) overpowers age (in years) in the Euclidean distance. What should be done?","questionZh":"在信贷例子中，以欧元计的收入在欧氏距离中压倒了以年计的年龄。应该怎么做？","options":["Remove income.","Use a larger k.","Use the class label as an extra variable.","Standardize or normalize the variables before computing distances."],"optionZh":["删除收入。","使用更大的 k。","把类别标签作为额外变量。","计算距离前对变量标准化或归一化。"],"answer":3,"explanation":"D 正确：讲义第 17 页：欧氏距离对尺度敏感，收入的数值大，所以“更重要”。标准化后各变量贡献才可比。","lessonId":"dsfb-05","lessonPage":17,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q163","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":163,"level":"真题同型 · 500 题强化","question":"Which statement about distance measures in kNN is FALSE?","questionZh":"关于 kNN 中的距离度量，哪项说法是错误的？","options":["Euclidean distance is suited only for continuous variables.","Euclidean distance is sensitive to the scale of the variables.","Euclidean distance is the only distance measure that can be used.","Other measures include Manhattan and Mahalanobis distance."],"optionZh":["欧氏距离只适合连续变量。","欧氏距离对变量尺度敏感。","欧氏距离是唯一能用的距离度量。","其他度量包括曼哈顿距离和马氏距离。"],"answer":2,"explanation":"C 错误：讲义第 17 页列出了欧氏、曼哈顿、马氏等多种距离，类别变量还可以用汉明、Jaccard 等（第 8 章）。","lessonId":"dsfb-05","lessonPage":17,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q164","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":164,"level":"真题同型 · 500 题强化","question":"In the two-stage model of Van Gestel (2005), what does the second model predict?","questionZh":"在 Van Gestel（2005）的两阶段模型中，第二个模型预测什么？","options":["The error made by the first, interpretable model","The same target as the first model, independently","The class distribution","The optimal number of trees"],"optionZh":["第一个可解释模型所犯的误差","独立地预测与第一个模型相同的目标","类别分布","最优的树数量"],"answer":0,"explanation":"A 正确：第一阶段用白盒模型（如逻辑回归）保证可解释性，第二阶段用强大的黑盒模型（如神经网络、SVM）去预测第一阶段的残差，两者相加。","lessonId":"dsfb-05","lessonPage":19,"lessonPageTitle":"Ensembles"},{"id":"s5-q165","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":165,"level":"真题同型 · 500 题强化","question":"What is the basic idea behind ensemble methods?","questionZh":"集成方法背后的基本思想是什么？","options":["Using a single, very deep model","Combining the estimates of a series of models, since different models may capture different patterns in the data (\"wisdom of crowds\")","Removing outliers before training","Using only interpretable models"],"optionZh":["使用单个非常深的模型","组合一系列模型的估计，因为不同模型可能捕捉到数据中不同的模式（“群体智慧”）","训练前删除异常值","只用可解释的模型"],"answer":1,"explanation":"B 正确：讲义第 22 页：ensemble 是法语“一起”。典型做法有 Bagging、Boosting、随机森林（讲义说 smart, smarter, smartest）。","lessonId":"dsfb-05","lessonPage":22,"lessonPageTitle":"Ensembles"},{"id":"s5-q166","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":166,"level":"真题同型 · 500 题强化","question":"Which sampling method is preferred for generating diverse samples for an ensemble?","questionZh":"为集成生成多样化样本时，首选哪种抽样方法？","options":["Cross-validation folds","A single random subsample","Stratified sampling of the test set","Bootstrapping, i.e., sampling with replacement"],"optionZh":["交叉验证折","一次随机子样本","对测试集分层抽样","自助法，即有放回抽样"],"answer":3,"explanation":"D 正确：讲义第 25 页对交叉验证和随机子样本打了“mwah”，对 bootstrap 打了“yes!”。有放回抽样让每个样本互不相同，有的观测重复、有的缺席。","lessonId":"dsfb-05","lessonPage":25,"lessonPageTitle":"Generating samples"},{"id":"s5-q167","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":167,"level":"真题同型 · 500 题强化","question":"Why do ensemble methods \"require\" an unstable base classifier?","questionZh":"为什么集成方法“需要”不稳定的基分类器？","options":["Because stable classifiers cannot be trained on bootstrap samples","Because only unstable classifiers produce probabilities","Because if small changes in the sample barely change the model, combining many models adds little","Because unstable classifiers are always more accurate"],"optionZh":["因为稳定分类器无法在自助样本上训练","因为只有不稳定分类器能产生概率","因为如果样本的小变化几乎不改变模型，组合很多模型也没多少增益","因为不稳定分类器总是更准确"],"answer":2,"explanation":"C 正确：决策树、决策树桩和神经网络对数据扰动敏感，不同样本得到差异很大的模型，平均起来能降低方差。逻辑回归、kNN、SVM 比较稳定，作为基分类器作用不大。","lessonId":"dsfb-05","lessonPage":25,"lessonPageTitle":"Generating samples"},{"id":"s5-q168","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":168,"level":"真题同型 · 500 题强化","question":"Which base learner is LEAST useful in an ensemble according to the lecture?","questionZh":"根据讲义，以下哪个基学习器在集成中最没用？","options":["Decision trees","Logistic regression","Decision stumps","Neural networks"],"optionZh":["决策树","逻辑回归","决策树桩","神经网络"],"answer":1,"explanation":"B 正确：逻辑回归是稳定的分类器，换一个 bootstrap 样本系数变化不大，集成后提升有限。A、C、D 都是讲义列出的常用不稳定基分类器。","lessonId":"dsfb-05","lessonPage":25,"lessonPageTitle":"Generating samples"},{"id":"s5-q169","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":169,"level":"真题同型 · 500 题强化","question":"Six models vote: yes (weight 1), yes (2), no (4), no (6), yes (1), yes (1). What is the outcome of weighted majority voting?","questionZh":"六个模型投票：yes（权重 1）、yes（2）、no（4）、no（6）、yes（1）、yes（1）。加权多数投票的结果是什么？","options":["Yes wins 4 to 2","Yes wins 5 to 10","It is a tie","No wins 10 to 5"],"optionZh":["yes 以 4 比 2 获胜","yes 以 5 比 10 获胜","平票","no 以 10 比 5 获胜"],"answer":3,"explanation":"D 正确：yes 权重 1 + 2 + 1 + 1 = 5，no 权重 4 + 6 = 10。不加权时 yes 以 4 比 2 获胜（A），这说明权重可以改变结果。最优权重本身可能需要训练。","lessonId":"dsfb-05","lessonPage":30,"lessonPageTitle":"Voting schemes"},{"id":"s5-q170","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":170,"level":"真题同型 · 500 题强化","question":"What is stacking?","questionZh":"什么是堆叠（stacking）？","options":["Training a second-level model that uses the predictions of first-level models as inputs","Training models sequentially on reweighted samples","Taking a majority vote of bootstrapped trees","Removing inputs with small weights"],"optionZh":["训练一个第二层模型，以第一层各模型的预测作为输入","在重新加权的样本上依次训练模型","对自助法生成的树做多数投票","删除权重小的输入"],"answer":0,"explanation":"A 正确：讲义第 31 页：第二层模型学习如何组合第一层的预测，而不是用固定的投票规则，相当于自动特征工程。B 是 boosting，C 是 bagging。","lessonId":"dsfb-05","lessonPage":31,"lessonPageTitle":"Stacking"},{"id":"s5-q171","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":171,"level":"真题同型 · 500 题强化","question":"How does bagging (bootstrap aggregating) make a prediction for a regression problem?","questionZh":"Bagging（自助聚合）在回归问题中如何做预测？","options":["By majority voting of the trees","By taking the prediction of the best tree only","By taking the average of the outcomes of the regression trees","By weighting trees according to their error, as in AdaBoost"],"optionZh":["由各棵树多数投票","只取最好那棵树的预测","取各棵回归树结果的平均","像 AdaBoost 那样按误差给树加权"],"answer":2,"explanation":"C 正确：讲义第 33 页：分类用（加权）多数投票，回归取平均。bootstrap 数量 N（约 30）是可以用验证集调的超参数。","lessonId":"dsfb-05","lessonPage":33,"lessonPageTitle":"Bagging"},{"id":"s5-q172","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":172,"level":"真题同型 · 500 题强化","question":"Which statement about bagging is TRUE?","questionZh":"关于 bagging，哪项说法正确？","options":["Each classifier depends on the errors of the previous one.","Misclassified cases get a higher weight in the next iteration.","The individual classifiers are learned independently, so a fast parallel implementation is possible.","It uses only one bootstrap sample."],"optionZh":["每个分类器都依赖前一个分类器的错误。","被分错的样本在下一轮权重更高。","各分类器独立学习，所以可以快速并行实现。","它只用一个自助样本。"],"answer":2,"explanation":"C 正确：讲义第 34 页：bootstrap 样本独立抽取，各棵树独立训练。A、B 描述的是 boosting（顺序训练）。","lessonId":"dsfb-05","lessonPage":34,"lessonPageTitle":"Bagging"},{"id":"s5-q173","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":173,"level":"真题同型 · 500 题强化","question":"How does boosting reweight the training data?","questionZh":"Boosting 如何对训练数据重新加权？","options":["All cases always keep equal weights.","Correctly classified cases get a higher weight.","Weights are chosen at random.","Misclassified cases get a higher weight, so difficult observations receive more attention."],"optionZh":["所有样本始终保持相同权重。","分对的样本权重更高。","权重随机选择。","分错的样本权重更高，难的观测得到更多关注。"],"answer":3,"explanation":"D 正确：讲义第 36 页。真题第 15 题的选项 C 说分错的样本权重更低，正是错的。","lessonId":"dsfb-05","lessonPage":36,"lessonPageTitle":"Boosting"},{"id":"s5-q174","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":174,"level":"真题同型 · 500 题强化","question":"In AdaBoost, a weak classifier has weighted error ε = 0.2. What is its importance α = ½ ln((1 − ε)/ε)?","questionZh":"AdaBoost 中某弱分类器的加权误差 ε = 0.2。它的重要性 α = ½ ln((1 − ε)/ε) 是多少？","options":["≈ 0.69","≈ 1.39","0.8","0"],"optionZh":["≈ 0.69","≈ 1.39","0.8","0"],"answer":0,"explanation":"A 正确：(1 − 0.2)/0.2 = 4，ln 4 ≈ 1.386，再乘 ½ ≈ 0.69。B 忘了乘 ½。误差越小，α 越大，这个分类器的投票越重。","lessonId":"dsfb-05","lessonPage":37,"lessonPageTitle":"AdaBoost (Freund and Schapire, 1999)"},{"id":"s5-q175","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":175,"level":"真题同型 · 500 题强化","question":"In AdaBoost, what is the importance α of a weak classifier with error ε = 0.5?","questionZh":"AdaBoost 中误差 ε = 0.5 的弱分类器，重要性 α 是多少？","options":["1","0.5","Infinity","0"],"optionZh":["1","0.5","无穷大","0"],"answer":3,"explanation":"D 正确：(1 − 0.5)/0.5 = 1，ln 1 = 0。误差 50% 的分类器和乱猜一样，在最终投票中没有权重。","lessonId":"dsfb-05","lessonPage":38,"lessonPageTitle":"Boosting"},{"id":"s5-q176","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":176,"level":"真题同型 · 500 题强化","question":"Which statement about AdaBoost is TRUE?","questionZh":"关于 AdaBoost，哪项说法正确？","options":["The final model is a simple unweighted majority vote.","As the algorithm proceeds, weights tend to concentrate on hard examples.","It can only use misclassification loss.","It cannot be used for multi-class problems."],"optionZh":["最终模型是简单的不加权多数投票。","随着算法进行，权重会集中到难分的样本上。","它只能使用误分类损失。","它不能用于多分类问题。"],"answer":1,"explanation":"B 正确：讲义第 38 页。A 错：最终是按 α 加权投票。C 错：也可以用指数、交叉熵、平方误差等损失。D 错：有 AdaBoost.M1、M2 等多分类变体。","lessonId":"dsfb-05","lessonPage":38,"lessonPageTitle":"Boosting"},{"id":"s5-q177","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":177,"level":"真题同型 · 500 题强化","question":"Which is a disadvantage of boosting mentioned in the lecture?","questionZh":"讲义提到 boosting 的哪个缺点？","options":["It has many parameters to tune.","It is slow and hard to program.","It risks overfitting to hard, i.e., noisy, examples in the data.","It cannot use decision trees."],"optionZh":["要调的参数很多。","速度慢，难以编程。","它有过拟合难分（即带噪声）样本的风险。","它不能使用决策树。"],"answer":2,"explanation":"C 正确：难分的样本往往就是噪声或错误标签，boosting 一直加大它们的权重，就会去拟合噪声。A、B 恰好是它的优点：只需调 T，快速简单。","lessonId":"dsfb-05","lessonPage":39,"lessonPageTitle":"Boosting"},{"id":"s5-q178","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":178,"level":"真题同型 · 500 题强化","question":"How does gradient boosting (e.g., XGBoost, LightGBM) build its ensemble?","questionZh":"梯度提升（如 XGBoost、LightGBM）如何构建集成？","options":["Each new tree is fit to the residuals of the predictions from the earlier trees.","All trees are trained independently on bootstrap samples.","Each tree uses one randomly chosen input only.","The trees are clustered with k-means."],"optionZh":["每棵新树拟合前面各树预测的残差。","所有树独立地在自助样本上训练。","每棵树只用一个随机选择的输入。","用 k-means 对树聚类。"],"answer":0,"explanation":"A 正确：讲义第 39 页。这和前面的两阶段模型思路相似：后面的模型修正前面模型的误差。B 是 bagging。","lessonId":"dsfb-05","lessonPage":39,"lessonPageTitle":"Boosting"},{"id":"s5-q179","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":179,"level":"真题同型 · 500 题强化","question":"How do random forests differ from bagging?","questionZh":"随机森林与 bagging 有何不同？","options":["Random forests use bootstrap samples, bagging does not.","Random forests prune each tree heavily.","Random forests reweight misclassified cases.","At each node, random forests randomly choose a subset of m inputs and split on the best of these."],"optionZh":["随机森林使用自助样本，bagging 不使用。","随机森林对每棵树大量剪枝。","随机森林会加重分错样本的权重。","在每个节点上，随机森林随机选择 m 个输入，并在其中选最好的分裂。"],"answer":3,"explanation":"D 正确：两者都用 bootstrap 样本（A 错，真题第 15 题考过）。随机森林额外在每个节点随机挑变量，让树之间更不相关。B 错：树完全生长，不剪枝。","lessonId":"dsfb-05","lessonPage":41,"lessonPageTitle":"Random forests"},{"id":"s5-q180","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":180,"level":"真题同型 · 500 题强化","question":"A data set has M = 64 inputs. What is the recommended number of inputs m to consider at each split of a random forest, m = floor(log2(M) + 1)?","questionZh":"数据集有 M = 64 个输入。随机森林每次分裂推荐考虑的输入数 m = floor(log2(M) + 1) 是多少？","options":["6","7","8","64"],"optionZh":["6","7","8","64"],"answer":1,"explanation":"B 正确：log2(64) = 6，6 + 1 = 7。讲义第 41 页也列出 m = 1、m = 2 等常见选择。","lessonId":"dsfb-05","lessonPage":41,"lessonPageTitle":"Random forests"},{"id":"s5-q181","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":181,"level":"真题同型 · 500 题强化","question":"Why are random forests faster to train than bagging?","questionZh":"为什么随机森林比 bagging 训练得更快？","options":["Because they use fewer trees","Because they use smaller bootstrap samples","Because there are fewer inputs to evaluate for each splitting decision","Because they do not need bootstrap samples"],"optionZh":["因为它们用的树更少","因为它们用更小的自助样本","因为每次分裂需要评估的输入更少","因为它们不需要自助样本"],"answer":2,"explanation":"C 正确：讲义第 42 页。每个节点只在 m 个随机变量中找最优分裂，而 bagging 要看全部 M 个变量。随机森林只有 T 和 m 两个参数。","lessonId":"dsfb-05","lessonPage":42,"lessonPageTitle":"Random forests"},{"id":"s5-q182","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":182,"level":"真题同型 · 500 题强化","question":"What is the main disadvantage of random forests mentioned in the lecture?","questionZh":"讲义提到的随机森林主要缺点是什么？","options":["Low accuracy","Decreased interpretability because of the many trees","Inability to handle many inputs","It only works for regression"],"optionZh":["准确度低","树太多，可解释性下降","无法处理大量输入","只适用于回归"],"answer":1,"explanation":"B 正确：100 棵树没法像一棵树那样直接读规则。A、C 恰好相反：准确度与 AdaBoost 相当甚至更好，也能处理大量输入。","lessonId":"dsfb-05","lessonPage":42,"lessonPageTitle":"Random forests"},{"id":"s5-q183","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":183,"level":"真题同型 · 500 题强化","question":"How does random forest feature importance help explain the model?","questionZh":"随机森林的特征重要性如何帮助解释模型？","options":["It shows the exact rule used for each prediction.","It gives each feature a score based on how much splits on it decrease impurity across all trees, weighted by the proportion of examples reaching those splits.","It counts how often a feature has missing values.","It equals the correlation of the feature with the target."],"optionZh":["它给出每次预测用的确切规则。","它根据各棵树中基于该特征的分裂使不纯度下降多少（按到达该分裂的样本比例加权），给每个特征打分。","它统计特征缺失值的次数。","它等于特征与目标的相关系数。"],"answer":1,"explanation":"B 正确：讲义第 43 页。它说明哪些变量整体上最有用，但不说明单个预测是怎么来的。","lessonId":"dsfb-05","lessonPage":43,"lessonPageTitle":"Random forests"},{"id":"s5-q184","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":184,"level":"真题同型 · 500 题强化","question":"Which three factors determine the errors made by a modelling method?","questionZh":"决定建模方法误差的三个因素是什么？","options":["Inherent randomness, bias and variance","Accuracy, precision and recall","Support, confidence and lift","Training, validation and test error"],"optionZh":["固有随机性、偏差和方差","准确率、精确率和召回率","支持度、置信度和提升度","训练误差、验证误差和测试误差"],"answer":0,"explanation":"A 正确：讲义第 45 页，引自 Provost & Fawcett。","lessonId":"dsfb-05","lessonPage":45,"lessonPageTitle":"Bias and variance"},{"id":"s5-q185","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":185,"level":"真题同型 · 500 题强化","question":"What is the Bayes error rate?","questionZh":"什么是贝叶斯错误率？","options":["The error of a naïve Bayes classifier","The training error of a decision tree","The lowest possible error rate for a probabilistic classification problem, caused by inherent randomness","The difference between bias and variance"],"optionZh":["朴素贝叶斯分类器的误差","决策树的训练误差","由固有随机性导致的、概率分类问题可能达到的最低错误率","偏差与方差之差"],"answer":2,"explanation":"C 正确：属性完全相同的实例可能有不同的结果，所以即使模型完美，也有一个误差下限。最大理论准确率 = 1 − 贝叶斯错误率。","lessonId":"dsfb-05","lessonPage":46,"lessonPageTitle":"Bias and variance"},{"id":"s5-q186","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":186,"level":"真题同型 · 500 题强化","question":"A linear model is fitted to data generated by an exponential curve. No matter how much data is added, it cannot reach the Bayes rate. Which source of error is this?","questionZh":"用线性模型拟合由指数曲线生成的数据，无论加多少数据都达不到贝叶斯错误率。这是哪种误差来源？","options":["Bias","Variance","Inherent randomness","Data leakage"],"optionZh":["偏差","方差","固有随机性","数据泄露"],"answer":0,"explanation":"A 正确：讲义第 47 页：模型的“容量”不够，结构上就拟合不了，类似欠拟合。另一个讲义例子是用线性回归估计二元目标。","lessonId":"dsfb-05","lessonPage":47,"lessonPageTitle":"Bias and variance"},{"id":"s5-q187","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":187,"level":"真题同型 · 500 题强化","question":"The variability in accuracy of a modelling method across different training samples is called:","questionZh":"建模方法在不同训练样本之间准确度的波动被称为：","options":["Bias","Inherent randomness","Lift","Variance (instability)"],"optionZh":["偏差","固有随机性","提升度","方差（不稳定性）"],"answer":3,"explanation":"D 正确：讲义第 49 页：方差就是我们之前说的“不稳定性”，与过拟合相关。真题第 14 题 A 选项把它叫成 bias，所以是错的。","lessonId":"dsfb-05","lessonPage":49,"lessonPageTitle":"Bias and variance"},{"id":"s5-q188","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":188,"level":"真题同型 · 500 题强化","question":"According to the lecture, bias and variance are characteristics of:","questionZh":"根据讲义，偏差和方差是什么的特性？","options":["A single fitted model","A modelling method, such as OLS linear regression","The test set","The target variable only"],"optionZh":["单个已拟合的模型","建模方法，例如 OLS 线性回归","测试集","只是目标变量"],"answer":1,"explanation":"B 正确：讲义第 50 页：老师把线性回归称为“方法”，用在数据上得到的才是“模型”。例如 OLS 线性回归本身就偏向拟合线性关系。","lessonId":"dsfb-05","lessonPage":50,"lessonPageTitle":"Bias and variance"},{"id":"s5-q189","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":189,"level":"真题同型 · 500 题强化","question":"A churn model that always predicts the average churn rate is an extreme case of:","questionZh":"一个总是预测平均流失率的流失模型，是什么的极端例子？","options":["Low bias, high variance","High bias, low variance","Low bias, low variance","High bias, high variance"],"optionZh":["低偏差、高方差","高偏差、低方差","低偏差、低方差","高偏差、高方差"],"answer":1,"explanation":"B 正确：讲义第 51 页：它不随样本变化（方差低），但完全不区分客户（偏差高）。相反，用 1000 个变量的神经网络是高方差、低偏差。","lessonId":"dsfb-05","lessonPage":51,"lessonPageTitle":"Bias and variance"},{"id":"s5-q190","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":190,"level":"真题同型 · 500 题强化","question":"Which statement about the 1000-variable model in the bias-variance discussion is TRUE?","questionZh":"关于偏差-方差讨论中的 1000 变量模型，哪项说法正确？","options":["It is guaranteed to perform better than a simpler model.","It has low variance because it has many parameters.","Its higher complexity typically gives lower bias but higher variance, and complexity control such as variable selection can help.","It cannot overfit."],"optionZh":["它一定比简单模型表现好。","它参数多，所以方差低。","更高的复杂度通常带来更低的偏差但更高的方差，变量选择等复杂度控制有帮助。","它不会过拟合。"],"answer":2,"explanation":"C 正确：讲义第 51–52 页：我们不知道哪种误差会占主导，也取决于数据量。复杂度控制就是在管理偏差-方差的权衡。","lessonId":"dsfb-05","lessonPage":52,"lessonPageTitle":"Bias and variance"},{"id":"s5-q191","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":191,"level":"真题同型 · 500 题强化","question":"Why do ensemble methods improve predictive ability more for high-variance methods such as decision trees?","questionZh":"为什么集成方法对决策树这类高方差方法提升更大？","options":["Because averaging multiple predictions reduces variance.","Because ensembles increase bias.","Because decision trees have no variance.","Because ensembles reduce the inherent randomness."],"optionZh":["因为对多个预测取平均能降低方差。","因为集成会增加偏差。","因为决策树没有方差。","因为集成能降低固有随机性。"],"answer":0,"explanation":"A 正确：讲义第 53 页。D 错：固有随机性来自数据本身，任何方法都无法降低。","lessonId":"dsfb-05","lessonPage":53,"lessonPageTitle":"Bias and variance … and ensembles"},{"id":"s5-q192","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":192,"level":"真题同型 · 500 题强化","question":"In the Zillow iBuying case, why did the algorithm lead to large losses?","questionZh":"在 Zillow 的 iBuying 案例中，为什么算法导致了巨额亏损？","options":["It could not accurately predict future home prices in a highly volatile market, and errors in one direction were costly.","It used kNN instead of random forests.","It had no training data.","It predicted prices too conservatively."],"optionZh":["它无法在高度波动的市场中准确预测未来房价，而且某一方向的误差代价很高。","它用了 kNN 而不是随机森林。","它没有训练数据。","它的价格预测过于保守。"],"answer":0,"explanation":"A 正确：讲义第 54 页：高估房价就会以过高价格买入，转手时亏损。这提醒我们要考虑误差的方向和代价，与第 10 章的成本敏感思想相呼应。","lessonId":"dsfb-05","lessonPage":54,"lessonPageTitle":"Thinking about errors…"},{"id":"s5-q193","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":193,"level":"真题同型 · 500 题强化","question":"What is the link between decision trees and k-nearest neighbours mentioned in the lecture?","questionZh":"讲义提到的决策树与 k 近邻之间的联系是什么？","options":["Both are unsupervised methods.","Instances in a tree leaf are similar; kNN uses similarity more directly to classify instances.","Both require a closed-form solution.","kNN is a special case of boosting."],"optionZh":["两者都是无监督方法。","同一树叶中的实例是相似的；kNN 更直接地利用相似度来分类。","两者都需要封闭解。","kNN 是 boosting 的特例。"],"answer":1,"explanation":"B 正确：讲义第 7 页：决策树把实例分段，同一叶节点里的实例在特征和结果上都相似；kNN 则直接找最相似的实例来分类。","lessonId":"dsfb-05","lessonPage":7,"lessonPageTitle":"K-Nearest Neighbors"},{"id":"s5-q194","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":194,"level":"真题同型 · 500 题强化","question":"In bootstrapping a data set of N observations, which statement is TRUE?","questionZh":"对含 N 个观测的数据做自助抽样，哪项说法正确？","options":["Each bootstrap sample contains every observation exactly once.","Each bootstrap sample has N observations drawn with replacement, so some appear multiple times and others not at all.","Bootstrap samples contain only misclassified cases.","Bootstrap samples are always smaller than N/2."],"optionZh":["每个自助样本都恰好包含每个观测一次。","每个自助样本有放回地抽 N 个观测，所以有些出现多次，有些不出现。","自助样本只包含被分错的样本。","自助样本总是小于 N/2。"],"answer":1,"explanation":"B 正确：有放回抽样平均约有 63% 的不同观测入选，其余约 37% 没被抽到（out-of-bag）。A 描述的是原始数据的一个重排。","lessonId":"dsfb-05","lessonPage":25,"lessonPageTitle":"Generating samples"},{"id":"s5-q195","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":195,"level":"真题同型 · 500 题强化","question":"Which statement about combining a logistic regression and a decision tree with a combination rule is TRUE?","questionZh":"用组合规则结合逻辑回归和决策树，哪项说法正确？","options":["The threshold of the combined score should be re-optimized, since the optimal threshold for the combination may differ from that of the individual models.","The combination always performs worse than both models.","Combination rules can only be used with two decision trees.","The combination does not produce a score."],"optionZh":["组合得分的阈值应重新优化，因为组合的最优阈值可能与单个模型不同。","组合总比两个模型都差。","组合规则只能用于两棵决策树。","组合不产生得分。"],"answer":0,"explanation":"A 正确：讲义第 27–28 页反复强调“with the optimal threshold”：比较或组合模型时，要在各自的最优阈值下比较，组合后也要重新找阈值。","lessonId":"dsfb-05","lessonPage":27,"lessonPageTitle":"Combination rules"},{"id":"s5-q196","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 5: Nearest Neighbors and Ensembles","number":196,"level":"真题同型 · 500 题强化","question":"For which base method would bagging be expected to bring the smallest improvement?","questionZh":"对哪种基础方法，bagging 预计带来的提升最小？","options":["A fully grown decision tree","A neural network with many hidden neurons","A low-variance method such as logistic regression with few variables","A decision stump"],"optionZh":["完全生长的决策树","隐藏神经元很多的神经网络","低方差方法，例如变量很少的逻辑回归","决策树桩"],"answer":2,"explanation":"C 正确：集成主要通过降低方差提升表现。低方差（稳定）的方法本身变化就小，平均后几乎没有变化。","lessonId":"dsfb-05","lessonPage":53,"lessonPageTitle":"Bias and variance … and ensembles"},{"id":"s5-q197","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":197,"level":"真题同型 · 500 题强化","question":"In the neuron model, what does the combination function compute?","questionZh":"在神经元模型中，组合函数计算的是什么？","options":["The output after applying the sigmoid","The prediction error","The learning rate","The weighted sum of the inputs, Σ wᵢIᵢ"],"optionZh":["经过 sigmoid 之后的输出","预测误差","学习率","输入的加权和 Σ wᵢIᵢ"],"answer":3,"explanation":"D 正确：组合函数通常是输入与权重的线性组合（加上偏置），之后再由激活（transfer/squashing）函数 f 变换得到输出。A 是激活函数的结果。","lessonId":"dsfb-06","lessonPage":9,"lessonPageTitle":" f (sum)"},{"id":"s5-q198","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":198,"level":"真题同型 · 500 题强化","question":"Which statement about the statistical view of neural networks is TRUE?","questionZh":"关于神经网络的统计学视角，哪项说法正确？","options":["Neural networks have no relation with regression models.","A neural network can only represent nonlinear models.","Neural networks are generalizations of existing statistical models such as linear and logistic regression.","Neural networks always require at least two hidden layers."],"optionZh":["神经网络与回归模型没有关系。","神经网络只能表示非线性模型。","神经网络是线性回归、逻辑回归等已有统计模型的推广。","神经网络至少需要两个隐藏层。"],"answer":2,"explanation":"C 正确：讲义第 10–12 页：没有隐藏层、线性激活就是线性回归；没有隐藏层、logistic 激活就是逻辑回归。加入隐藏神经元后才变得更灵活。","lessonId":"dsfb-06","lessonPage":10,"lessonPageTitle":"Background: two views"},{"id":"s5-q199","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":199,"level":"真题同型 · 500 题强化","question":"A neural network with no hidden layer and a logistic activation function in the output neuron is equivalent to:","questionZh":"没有隐藏层、输出神经元使用 logistic 激活函数的神经网络等价于：","options":["Linear regression","Logistic regression","k-means clustering","A decision tree"],"optionZh":["线性回归","逻辑回归","k-means 聚类","决策树"],"answer":1,"explanation":"B 正确：输出 = 1/(1 + e^−(β0 + β1X1 + … + βnXn))，就是逻辑回归。如果输出用线性激活，则是线性回归（A）。","lessonId":"dsfb-06","lessonPage":12,"lessonPageTitle":"Neural network representation: Logistic Regression"},{"id":"s5-q200","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":200,"level":"真题同型 · 500 题强化","question":"Why can a neural network with 40 hidden neurons fit a nonlinear decision boundary while logistic regression cannot?","questionZh":"为什么有 40 个隐藏神经元的神经网络能拟合非线性决策边界，而逻辑回归不能？","options":["Because it uses more training data.","Because combining multiple neurons with nonlinear activations greatly extends modelling flexibility.","Because it does not use weights.","Because it uses a linear activation in the hidden layer."],"optionZh":["因为它用了更多训练数据。","因为组合多个带非线性激活的神经元大大扩展了建模灵活性。","因为它不使用权重。","因为隐藏层用了线性激活。"],"answer":1,"explanation":"B 正确：每个隐藏神经元相当于一个非线性变换，组合起来可以拟合很复杂的边界。D 错：如果隐藏层用线性激活，多层叠加仍然是线性的。","lessonId":"dsfb-06","lessonPage":14,"lessonPageTitle":"Linear versus nonlinear decision boundary"},{"id":"s5-q201","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":201,"level":"真题同型 · 500 题强化","question":"In neural network terminology, what does \"bias\" correspond to in statistics?","questionZh":"在神经网络术语中，“bias（偏置）”对应统计学中的什么？","options":["The intercept","The bias of an estimator","The learning rate","The variance"],"optionZh":["截距","估计量的偏差","学习率","方差"],"answer":0,"explanation":"A 正确：讲义第 15 页的术语表：bias ↔ intercept，weight ↔ coefficient，epoch ↔ iteration，pruning ↔ variable selection，architecture ↔ model。注意不要和偏差-方差中的 bias 混淆。","lessonId":"dsfb-06","lessonPage":15,"lessonPageTitle":"Terminology: neural nets vs. statistics"},{"id":"s5-q202","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":202,"level":"真题同型 · 500 题强化","question":"Which pair of neural network and statistical terms is matched INCORRECTLY?","questionZh":"以下哪组神经网络术语与统计学术语的对应是错误的？","options":["Weight – coefficient","Training – estimating","Pruning – variable selection","Epoch – intercept"],"optionZh":["Weight – 系数","Training – 估计","Pruning – 变量选择","Epoch – 截距"],"answer":3,"explanation":"D 错误：epoch 对应的是迭代（iteration/step），截距对应的是 bias。","lessonId":"dsfb-06","lessonPage":15,"lessonPageTitle":"Terminology: neural nets vs. statistics"},{"id":"s5-q203","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":203,"level":"真题同型 · 500 题强化","question":"A fully connected MLP has 5 inputs, one hidden layer with 4 neurons, and 1 output. How many weight parameters (including biases) does it have?","questionZh":"一个全连接 MLP 有 5 个输入、1 个含 4 个神经元的隐藏层、1 个输出。它共有多少个权重参数（含偏置）？","options":["20","24","25","29"],"optionZh":["20","24","25","29"],"answer":3,"explanation":"D 正确：公式 (k + 1)h + h + 1 = (5 + 1) × 4 + 4 + 1 = 24 + 5 = 29。输入到隐藏层 24 个（含 4 个偏置），隐藏层到输出 4 个权重加 1 个偏置。","lessonId":"dsfb-06","lessonPage":17,"lessonPageTitle":"Architecture"},{"id":"s5-q204","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":204,"level":"真题同型 · 500 题强化","question":"A fully connected MLP has 3 inputs, one hidden layer with 2 neurons, and 1 output. How many weight parameters (including biases) does it have?","questionZh":"一个全连接 MLP 有 3 个输入、1 个含 2 个神经元的隐藏层、1 个输出。共有多少个权重参数（含偏置）？","options":["8","11","9","6"],"optionZh":["8","11","9","6"],"answer":1,"explanation":"B 正确：(3 + 1) × 2 + 2 + 1 = 8 + 3 = 11。A 只算了输入到隐藏层的部分。","lessonId":"dsfb-06","lessonPage":17,"lessonPageTitle":"Architecture"},{"id":"s5-q205","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":205,"level":"真题同型 · 500 题强化","question":"Which statement about the multilayer perceptron (MLP) is FALSE?","questionZh":"关于多层感知机（MLP），哪项说法是错误的？","options":["An MLP with one hidden layer has the universal approximation property.","Every neuron has a bias input.","MLPs contain feedback connections between layers.","Skip-layer networks have direct connections between inputs and output."],"optionZh":["只有一个隐藏层的 MLP 就具有万能逼近性质。","每个神经元都有偏置输入。","MLP 在层与层之间有反馈连接。","跳层网络在输入和输出之间有直接连接。"],"answer":2,"explanation":"C 错误：MLP 是前馈网络，没有反馈连接，有反馈连接的是循环神经网络（RNN）。A、B、D 都是讲义第 18 页的内容。","lessonId":"dsfb-06","lessonPage":18,"lessonPageTitle":"Multilayer Perceptron"},{"id":"s5-q206","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":206,"level":"真题同型 · 500 题强化","question":"What is the output range of the hyperbolic tangent (tanh) activation function?","questionZh":"双曲正切（tanh）激活函数的输出范围是？","options":["Between 0 and 1","Between 0 and +∞","Between −∞ and +∞","Between −1 and 1"],"optionZh":["0 到 1","0 到 +∞","−∞ 到 +∞","−1 到 1"],"answer":3,"explanation":"D 正确：tanh = 2·logistic(2·sum) − 1，范围是 (−1, 1)，是隐藏层的常用默认值。A 是 logistic，C 是线性，B 是指数激活。","lessonId":"dsfb-06","lessonPage":19,"lessonPageTitle":"Activation function f"},{"id":"s5-q207","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":207,"level":"真题同型 · 500 题强化","question":"According to the practical advice in the lecture, which activation functions should be used for a binary classification network?","questionZh":"根据讲义的实用建议，二分类神经网络应该用哪些激活函数？","options":["Linear in the hidden layer and linear in the output layer","Tanh in the hidden layer and logistic in the output layer","Logistic in the hidden layer and exponential in the output layer","ReLU in the output layer only"],"optionZh":["隐藏层线性，输出层线性","隐藏层 tanh，输出层 logistic","隐藏层 logistic，输出层指数","只在输出层用 ReLU"],"answer":1,"explanation":"B 正确：输出层 logistic 能给出 0–1 的概率。回归问题则建议隐藏层 tanh、输出层线性或 tanh。","lessonId":"dsfb-06","lessonPage":20,"lessonPageTitle":"Activation function f"},{"id":"s5-q208","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":208,"level":"真题同型 · 500 题强化","question":"For a regression problem with an unbounded continuous target, which output activation function is most appropriate?","questionZh":"对于目标是无界连续值的回归问题，最合适的输出激活函数是什么？","options":["Logistic","Tanh with outputs between −1 and 1 only","Linear","Step function"],"optionZh":["Logistic","输出只在 −1 到 1 之间的 tanh","线性","阶跃函数"],"answer":2,"explanation":"C 正确：线性激活 f(sum) = sum 不做变换，输出范围是整个实数轴。logistic 会把输出限制在 0–1 之间。","lessonId":"dsfb-06","lessonPage":20,"lessonPageTitle":"Activation function f"},{"id":"s5-q209","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":209,"level":"真题同型 · 500 题强化","question":"In the simple tuning procedure for the number of hidden neurons, on which data set is the number of hidden neurons chosen?","questionZh":"在调整隐藏神经元数量的简单流程中，隐藏神经元数是根据哪个数据集来选的？","options":["The validation set","The training set","The test set","The whole data set"],"optionZh":["验证集","训练集","测试集","整个数据集"],"answer":0,"explanation":"A 正确：在训练集上训练，在验证集上比较不同神经元数，最后在独立测试集上测一次最终表现。用测试集来选（C）会让最终评估过于乐观。","lessonId":"dsfb-06","lessonPage":21,"lessonPageTitle":"Simple tuning"},{"id":"s5-q210","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":210,"level":"真题同型 · 500 题强化","question":"Why does the simple tuning procedure suggest training several networks for each number of hidden neurons?","questionZh":"为什么简单调参流程建议对每个隐藏神经元数都训练多个网络？","options":["To increase the number of parameters","To avoid bad local minima, since different starting weights may lead to different solutions","To reduce the size of the test set","Because the validation set changes every time"],"optionZh":["为了增加参数数量","为了避免差的局部最小值，因为不同的初始权重可能得到不同的解","为了减小测试集","因为验证集每次都会变"],"answer":1,"explanation":"B 正确：误差函数非凸，结果依赖初始权重。多训练几次取平均或最好的，结果更稳健。","lessonId":"dsfb-06","lessonPage":21,"lessonPageTitle":"Simple tuning"},{"id":"s5-q211","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":211,"level":"真题同型 · 500 题强化","question":"Why must neural network weights be found with an iterative optimization algorithm?","questionZh":"为什么神经网络的权重必须用迭代优化算法求解？","options":["Because no closed-form analytical solution exists for nonlinear models such as neural networks.","Because neural networks have only one weight.","Because the error function is always convex.","Because iterative algorithms are always faster than formulas."],"optionZh":["因为神经网络这类非线性模型没有封闭形式的解析解。","因为神经网络只有一个权重。","因为误差函数总是凸的。","因为迭代算法总比公式快。"],"answer":0,"explanation":"A 正确：线性回归有 OLS 的解析解，但神经网络是非线性的，只能从初始权重出发一步步逼近最小值。这也是真题第 2 题的考点。","lessonId":"dsfb-06","lessonPage":23,"lessonPageTitle":"Learning = optimizing the weights = training an ANN"},{"id":"s5-q212","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":212,"level":"真题同型 · 500 题强化","question":"Which error function is typically used to train a neural network for binary classification?","questionZh":"训练二分类神经网络通常使用哪种误差函数？","options":["Mean squared error","Cross-entropy, which is equivalent to maximum likelihood","Mean absolute percentage error","The Gini index"],"optionZh":["均方误差","交叉熵，等价于最大似然","平均绝对百分比误差","基尼指数"],"answer":1,"explanation":"B 正确：讲义第 24 页：分类用交叉熵，回归用均方误差，并注明 CE 等价于最大似然。D 是决策树的分裂准则。","lessonId":"dsfb-06","lessonPage":24,"lessonPageTitle":"Error functions"},{"id":"s5-q213","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":213,"level":"真题同型 · 500 题强化","question":"In gradient descent, how are the weights updated?","questionZh":"在梯度下降中，权重如何更新？","options":["W_new = W_old + η · ∂E/∂W","W_new = W_old · η","W_new = ∂E/∂W","W_new = W_old − η · ∂E/∂W"],"optionZh":["W_new = W_old + η · ∂E/∂W","W_new = W_old · η","W_new = ∂E/∂W","W_new = W_old − η · ∂E/∂W"],"answer":3,"explanation":"D 正确：沿着误差下降最快的方向（负梯度）走一步，步长由学习率 η 控制。A 是沿梯度上坡，误差会变大。","lessonId":"dsfb-06","lessonPage":26,"lessonPageTitle":"Gradient descent learning"},{"id":"s5-q214","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":214,"level":"真题同型 · 500 题强化","question":"A weight is currently 0.50, the gradient ∂E/∂w is 0.20 and the learning rate η is 0.1. What is the updated weight?","questionZh":"某权重当前为 0.50，梯度 ∂E/∂w 为 0.20，学习率 η 为 0.1。更新后的权重是多少？","options":["0.52","0.30","0.48","0.70"],"optionZh":["0.52","0.30","0.48","0.70"],"answer":2,"explanation":"C 正确：w_new = 0.50 − 0.1 × 0.20 = 0.50 − 0.02 = 0.48。A 加上了梯度（方向错了）。B 忘了乘学习率。","lessonId":"dsfb-06","lessonPage":26,"lessonPageTitle":"Gradient descent learning"},{"id":"s5-q215","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":215,"level":"真题同型 · 500 题强化","question":"Which is the correct order of the backpropagation steps after initializing the weights?","questionZh":"初始化权重之后，反向传播的正确步骤顺序是什么？","options":["Update weights → compute output error → propagate observation forward","Propagate observation forward → compute error at output → propagate error backward → update weights","Compute error → initialize weights → stop","Propagate error backward → propagate observation forward → update weights"],"optionZh":["更新权重 → 计算输出误差 → 正向传播观测","正向传播观测 → 计算输出层误差 → 反向传播误差 → 更新权重","计算误差 → 初始化权重 → 停止","反向传播误差 → 正向传播观测 → 更新权重"],"answer":1,"explanation":"B 正确：讲义第 27 页的 6 步：初始化、正向传播、计算输出误差、误差反向传播到前面各层、更新全部权重、重复直到收敛。反向传播是梯度下降的实际实现方式。","lessonId":"dsfb-06","lessonPage":27,"lessonPageTitle":"Backpropagation learning"},{"id":"s5-q216","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":216,"level":"真题同型 · 500 题强化","question":"What happens if the learning rate η is set too high?","questionZh":"学习率 η 设得太高会怎样？","options":["Progress becomes very slow.","The network always finds the global minimum.","The algorithm oscillates and may diverge.","The number of weights increases."],"optionZh":["进展变得很慢。","网络总能找到全局最小值。","算法会振荡，甚至发散。","权重数量增加。"],"answer":2,"explanation":"C 正确：步子太大会越过最低点来回跳，甚至越跳越远。学习率太小（A）则进展缓慢。解决办法是使用自适应学习率。","lessonId":"dsfb-06","lessonPage":29,"lessonPageTitle":"Learning rate η"},{"id":"s5-q217","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":217,"level":"真题同型 · 500 题强化","question":"What is the difference between online and batch learning?","questionZh":"在线学习和批量学习有什么区别？","options":["Online learning updates the weights after each observation; batch learning updates them after the entire data set.","Online learning uses the internet; batch learning does not.","Batch learning updates the weights after each observation.","They are identical."],"optionZh":["在线学习每读一个观测就更新权重；批量学习读完整个数据集才更新。","在线学习使用互联网，批量学习不使用。","批量学习每读一个观测就更新权重。","两者完全相同。"],"answer":0,"explanation":"A 正确：讲义第 29 页。批量学习是标准做法。一个 epoch 是所有训练观测通过网络一次。","lessonId":"dsfb-06","lessonPage":29,"lessonPageTitle":"Learning rate η"},{"id":"s5-q218","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":218,"level":"真题同型 · 500 题强化","question":"What does the momentum parameter do in backpropagation?","questionZh":"反向传播中的动量参数有什么作用？","options":["It sets the number of hidden neurons.","It smooths the current step direction with the previous step.","It removes inputs from the network.","It determines the activation function."],"optionZh":["设定隐藏神经元数量。","用前一步的方向平滑当前步的方向。","从网络中删除输入。","决定激活函数。"],"answer":1,"explanation":"B 正确：动量（0 ≤ 值 ≤ 1）让更新带上前一步的“惯性”，减少振荡、加快在平坦区域的移动，也有助于越过小的局部最小值。","lessonId":"dsfb-06","lessonPage":29,"lessonPageTitle":"Learning rate η"},{"id":"s5-q219","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":219,"level":"真题同型 · 500 题强化","question":"A training set has 10,000 observations and a network is trained for 50 epochs with batch learning. How many times is each observation passed through the network?","questionZh":"训练集有 10,000 个观测，用批量学习训练 50 个 epoch。每个观测会通过网络多少次？","options":["1","200","500,000","50"],"optionZh":["1","200","500,000","50"],"answer":3,"explanation":"D 正确：一个 epoch = 所有训练观测各通过网络一次，所以 50 个 epoch 每个观测通过 50 次。C 是总共的前向传播次数，不是每个观测的次数。","lessonId":"dsfb-06","lessonPage":29,"lessonPageTitle":"Learning rate η"},{"id":"s5-q220","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":220,"level":"真题同型 · 500 题强化","question":"Why can backpropagation get stuck in a local minimum?","questionZh":"为什么反向传播可能陷入局部最小值？","options":["Because the error function of a neural network may be non-convex.","Because the learning rate is always zero.","Because neural networks have no weights.","Because the error function is linear."],"optionZh":["因为神经网络的误差函数可能是非凸的。","因为学习率总是 0。","因为神经网络没有权重。","因为误差函数是线性的。"],"answer":0,"explanation":"A 正确：非凸曲面有多个“坑”，梯度下降在某个坑底梯度为 0 就停下了，不一定是最深的那个。讲义建议的解决方法是预训练（preliminary training）。","lessonId":"dsfb-06","lessonPage":30,"lessonPageTitle":"Problem: local minima"},{"id":"s5-q221","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":221,"level":"真题同型 · 500 题强化","question":"What does preliminary training do?","questionZh":"预训练（preliminary training）做什么？","options":["It trains the network once with a very large learning rate.","It removes the hidden layer.","It tries a small number of random starting weights for a few iterations each and uses the best as new starting values.","It trains on the test set first."],"optionZh":["用很大的学习率训练一次。","删除隐藏层。","尝试少量随机初始权重，每组迭代几次，取最好的作为新起点。","先在测试集上训练。"],"answer":2,"explanation":"C 正确：讲义第 31 页（默认 20 次迭代）。好的初始权重对找到好的解、避免陷入局部最小值至关重要。","lessonId":"dsfb-06","lessonPage":31,"lessonPageTitle":"𝐸𝑟𝑟𝑜𝑟 𝐸"},{"id":"s5-q222","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":222,"level":"真题同型 · 500 题强化","question":"Which is NOT listed as a convergence criterion for stopping weight updates?","questionZh":"以下哪项不是讲义列出的停止更新权重的收敛准则？","options":["The error function shows no progress.","The gradient is close to zero.","A fixed number of epochs has been reached.","The training accuracy reaches 100%."],"optionZh":["误差函数不再改善。","梯度接近 0。","达到固定的 epoch 数。","训练准确率达到 100%。"],"answer":3,"explanation":"D 不是：训练集 100% 准确往往意味着过拟合。讲义第 32 页列出：误差不再改善、权重不再明显变化、梯度接近 0、使用验证集、固定 epoch 数。","lessonId":"dsfb-06","lessonPage":32,"lessonPageTitle":"Convergence criteria"},{"id":"s5-q223","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":223,"level":"真题同型 · 500 题强化","question":"How should categorical inputs be prepared for a neural network according to the lecture?","questionZh":"根据讲义，类别输入应如何为神经网络做准备？","options":["Map categories to arbitrary integers 1, 2, 3, …","Leave them as text.","Remove them.","Use 0/1 dummy coding or weights-of-evidence coding."],"optionZh":["把类别映射成任意整数 1、2、3……","保持为文本。","删除它们。","使用 0/1 哑变量编码或证据权重（WOE）编码。"],"answer":3,"explanation":"D 正确：讲义第 33 页。连续变量则标准化到 [0, 1]、[−1, 1] 或用 z 分数。A 会引入不存在的大小顺序。","lessonId":"dsfb-06","lessonPage":33,"lessonPageTitle":"Data preprocessing"},{"id":"s5-q224","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":224,"level":"真题同型 · 500 题强化","question":"A customer is 50 years old; the mean age is 40 and the standard deviation is 8. What is the z-score of age?","questionZh":"某客户 50 岁，年龄均值为 40，标准差为 8。年龄的 z 分数是多少？","options":["1.25","0.8","10","6.25"],"optionZh":["1.25","0.8","10","6.25"],"answer":0,"explanation":"A 正确：z = (x − 均值)/标准差 = (50 − 40)/8 = 1.25。标准化后各变量尺度相近，训练更稳定。","lessonId":"dsfb-06","lessonPage":33,"lessonPageTitle":"Data preprocessing"},{"id":"s5-q225","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":225,"level":"真题同型 · 500 题强化","question":"What is overfitting?","questionZh":"什么是过拟合？","options":["A model that is too simple to capture the signal","A model that fits the noise in the training data as well as the signal, and therefore generalizes poorly","A model that performs equally well on training and test data","A model with a learning rate that is too low"],"optionZh":["模型太简单，抓不住信号","模型连训练数据中的噪声也拟合了，因此泛化能力差","模型在训练集和测试集上表现一样好","学习率太低的模型"],"answer":1,"explanation":"B 正确：讲义第 35 页：每个数据集都有噪声（录入错误、传感器误差等），过于复杂的模型（隐藏神经元太多）会把噪声也记住。A 是欠拟合。","lessonId":"dsfb-06","lessonPage":35,"lessonPageTitle":"Learning versus Overfitting"},{"id":"s5-q226","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":226,"level":"真题同型 · 500 题强化","question":"How does early stopping avoid overfitting?","questionZh":"早停（early stopping）如何避免过拟合？","options":["It stops training when the training error reaches zero.","It uses the training set to estimate weights and stops updating when the error on a separate validation set starts to increase.","It uses fewer hidden neurons.","It stops after exactly one epoch."],"optionZh":["当训练误差为 0 时停止训练。","用训练集估计权重，当独立验证集上的误差开始上升时停止更新。","使用更少的隐藏神经元。","恰好一个 epoch 后停止。"],"answer":1,"explanation":"B 正确：训练误差会一直下降，但验证误差在某个点后开始上升，那就是过拟合的开始。讲义建议从足够大的网络开始，并指出验证集上的评估指标可以不同于训练目标（如 AUC、利润）。","lessonId":"dsfb-06","lessonPage":37,"lessonPageTitle":"Avoiding overfitting using early stopping"},{"id":"s5-q227","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":227,"level":"真题同型 · 500 题强化","question":"In early stopping, which statement about the evaluation metric on the validation set is TRUE?","questionZh":"在早停中，关于验证集上的评估指标，哪项说法正确？","options":["It must be the same as the training objective function.","It can differ from the objective function, e.g., AUC or a profit-based measure.","It must always be accuracy.","It is computed on the test set."],"optionZh":["它必须与训练目标函数相同。","它可以与目标函数不同，例如 AUC 或基于利润的指标。","它必须是准确率。","它在测试集上计算。"],"answer":1,"explanation":"B 正确：讲义第 37 页明确写了这一点。例如用交叉熵训练，但在验证集上按利润（第 10 章的 MP）决定何时停止。","lessonId":"dsfb-06","lessonPage":37,"lessonPageTitle":"Avoiding overfitting using early stopping"},{"id":"s5-q228","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":228,"level":"真题同型 · 500 题强化","question":"According to Bartlett (1997), what does generalization of a neural network depend on more?","questionZh":"根据 Bartlett（1997），神经网络的泛化能力更依赖什么？","options":["The number of weights","The size of the weights","The learning rate","The number of epochs only"],"optionZh":["权重的数量","权重的大小","学习率","只是 epoch 数"],"answer":1,"explanation":"B 正确：权重小的大网络表现得像一个更小、更简单的网络。所以限制权重大小（正则化）可以防止拟合出凹凸不平的曲面。","lessonId":"dsfb-06","lessonPage":39,"lessonPageTitle":"Avoiding overfitting using regularization"},{"id":"s5-q229","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":229,"level":"真题同型 · 500 题强化","question":"In the regularized objective function Error + λΣw², what happens if λ is set too high?","questionZh":"在正则化目标函数 Error + λΣw² 中，λ 设得太高会怎样？","options":["Overfitting","Underfitting","The weights become very large.","Nothing changes."],"optionZh":["过拟合","欠拟合","权重变得很大。","什么都不变。"],"answer":1,"explanation":"B 正确：惩罚太重，权重被压得太小，模型过于简单，连真实模式都学不到。λ 太低则可能过拟合。λ 要用独立验证集调整。","lessonId":"dsfb-06","lessonPage":40,"lessonPageTitle":"Avoiding overfitting using regularization"},{"id":"s5-q230","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":230,"level":"真题同型 · 500 题强化","question":"Which statement about regularization is TRUE?","questionZh":"关于正则化，哪项说法正确？","options":["Ridge regression uses an L1 penalty.","Regularization increases the size of the weights.","Too much regularization leads to overfitting.","The same principle is used by Ridge (L2) and Lasso (L1) regression."],"optionZh":["岭回归使用 L1 惩罚。","正则化会增大权重。","正则化过强会导致过拟合。","岭回归（L2）和 Lasso（L1）回归使用的是相同的原理。"],"answer":3,"explanation":"D 正确：都是在目标函数中惩罚大的系数。A 错：Ridge 是 L2，Lasso 是 L1。C 错：过强导致欠拟合（真题第 19 题）。","lessonId":"dsfb-06","lessonPage":40,"lessonPageTitle":"Avoiding overfitting using regularization"},{"id":"s5-q231","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":231,"level":"真题同型 · 500 题强化","question":"When is an input considered unimportant in the pruning approach for input selection?","questionZh":"在用于输入选择的剪枝方法中，什么情况下认为某个输入不重要？","options":["When all of its input-to-hidden layer weights are zero or close to zero","When it has the largest weights","When it is a categorical variable","When it has no missing values"],"optionZh":["当它所有输入到隐藏层的权重都为 0 或接近 0 时","当它的权重最大时","当它是类别变量时","当它没有缺失值时"],"answer":0,"explanation":"A 正确：如果一个输入连到所有隐藏神经元的权重都接近 0，它对输出几乎没有影响。剪掉它后重新训练，直到预测力明显下降为止。Hinton 图可以直观显示权重大小。","lessonId":"dsfb-06","lessonPage":41,"lessonPageTitle":"Avoiding overfitting using input selection with pruning"},{"id":"s5-q232","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":232,"level":"真题同型 · 500 题强化","question":"What does a Hinton diagram visualize?","questionZh":"Hinton 图可视化的是什么？","options":["The learning curve over epochs","The ROC curve","The size and sign of the network weights","The cluster structure"],"optionZh":["随 epoch 变化的学习曲线","ROC 曲线","网络权重的大小和正负","聚类结构"],"answer":2,"explanation":"C 正确：方块大小表示权重大小，颜色表示正负。用来判断哪些输入的权重都很小，可以剪掉。","lessonId":"dsfb-06","lessonPage":42,"lessonPageTitle":"Hinton diagrams"},{"id":"s5-q233","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":233,"level":"真题同型 · 500 题强化","question":"Which statement describes the wrapper approach to input selection for neural networks?","questionZh":"哪项描述了神经网络输入选择的包装（wrapper）方法？","options":["Remove the input with the largest weight.","Keep all inputs and increase the regularization.","Remove inputs at random.","Remove each input in turn, re-estimate the network, exclude the input whose absence gives the best network, and repeat until performance drops significantly."],"optionZh":["删除权重最大的输入。","保留所有输入并加强正则化。","随机删除输入。","依次去掉每个输入并重新估计网络，排除去掉后网络表现最好的那个输入，重复直到表现明显下降。"],"answer":3,"explanation":"D 正确：讲义第 43 页的后向（backward）包装法，评估指标可以是 AUC、MSE 等。也可以做前向（forward）版本。代价是要训练很多次网络，计算量大。","lessonId":"dsfb-06","lessonPage":43,"lessonPageTitle":"Avoiding overfitting using input selection with a"},{"id":"s5-q234","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":234,"level":"真题同型 · 500 题强化","question":"For a regression neural network, which error function does the lecture use?","questionZh":"对于回归神经网络，讲义使用哪种误差函数？","options":["Mean squared error","Cross-entropy","Information gain","Lift"],"optionZh":["均方误差","交叉熵","信息增益","提升度"],"answer":0,"explanation":"A 正确：E = ½ Σ (y(xᵢ; w) − tᵢ)²。交叉熵用于分类。","lessonId":"dsfb-06","lessonPage":24,"lessonPageTitle":"Error functions"},{"id":"s5-q235","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 6: Regression and Artificial Neural Networks","number":235,"level":"真题同型 · 500 题强化","question":"The tanh activation can be written as:","questionZh":"tanh 激活函数可以写成：","options":["logistic(sum) − 1","2·logistic(2·sum) − 1","e^sum","max(0, sum)"],"optionZh":["logistic(sum) − 1","2·logistic(2·sum) − 1","e^sum","max(0, sum)"],"answer":1,"explanation":"B 正确：讲义第 19 页给出了这个关系，把 0–1 的 logistic 拉伸平移到 −1 到 1。C 是指数激活，D 是 ReLU。","lessonId":"dsfb-06","lessonPage":19,"lessonPageTitle":"Activation function f"},{"id":"s5-q236","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":236,"level":"真题同型 · 500 题强化","question":"Monthly sales were 100, 120, 110, 130 (most recent last). What is the naïve forecast for next month?","questionZh":"月销量依次为 100、120、110、130（最后一个是最近一期）。下个月的朴素（naïve）预测是多少？","options":["115","100","120","130"],"optionZh":["115","100","120","130"],"answer":3,"explanation":"D 正确：朴素法直接用最近一期观测值作为预测，即 130。A 是均值法（四期平均 115）。","lessonId":"dsfb-07","lessonPage":25,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q237","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":237,"level":"真题同型 · 500 题强化","question":"Monthly sales were 100, 120, 110, 130 (most recent last). What is the forecast for next month using the mean method?","questionZh":"月销量依次为 100、120、110、130（最后一个是最近一期）。用均值法预测下个月是多少？","options":["130","120","115","110"],"optionZh":["130","120","115","110"],"answer":2,"explanation":"C 正确：均值法用全部历史观测的平均值，(100 + 120 + 110 + 130)/4 = 115。A 是朴素法。","lessonId":"dsfb-07","lessonPage":25,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q238","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":238,"level":"真题同型 · 500 题强化","question":"Quarterly demand for the last two years was Q1–Q4: 50, 80, 60, 90 (year 1) and 55, 85, 65, 95 (year 2). What is the seasonal naïve forecast for Q2 of year 3?","questionZh":"过去两年的季度需求 Q1–Q4 为：第一年 50、80、60、90，第二年 55、85、65、95。第三年 Q2 的季节朴素预测是多少？","options":["82.5","95","80","85"],"optionZh":["82.5","95","80","85"],"answer":3,"explanation":"D 正确：季节朴素法取上一个同季节（第二年 Q2）的观测值 85。A 是两年 Q2 的平均，那不是季节朴素法（真题第 29 题就考了这个陷阱）。B 是朴素法。","lessonId":"dsfb-07","lessonPage":25,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q239","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":239,"level":"真题同型 · 500 题强化","question":"Which statement about the simple forecasting methods is TRUE?","questionZh":"关于简单预测方法，哪项说法正确？","options":["The naïve method requires estimating a smoothing parameter.","The mean, naïve and seasonal naïve methods do not require any model parameters to be estimated.","The seasonal naïve method averages all past values from the same season.","Simple methods are never competitive with complex methods."],"optionZh":["朴素法需要估计平滑参数。","均值法、朴素法和季节朴素法都不需要估计模型参数。","季节朴素法会平均同一季节的所有历史值。","简单方法永远比不过复杂方法。"],"answer":1,"explanation":"B 正确：它们只是按固定规则使用历史值，没有要估计的参数。C 错：季节朴素用的是上一个同季节值。D 错：M1 竞赛发现简单方法常常比复杂方法更准。","lessonId":"dsfb-07","lessonPage":25,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q240","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":240,"level":"真题同型 · 500 题强化","question":"What does \"univariate\" time series forecasting mean?","questionZh":"“单变量”时间序列预测是什么意思？","options":["Only one forecast horizon is used.","Only one time series is forecast in the whole company.","Only historical values of the time series itself are used to make forecasts.","Only one model parameter is estimated."],"optionZh":["只使用一个预测期。","整个公司只预测一条时间序列。","只用该时间序列自身的历史值来做预测。","只估计一个模型参数。"],"answer":2,"explanation":"C 正确：讲义第 21 页的定义。加入促销、天气等外部变量（xreg）就不再是单变量了。","lessonId":"dsfb-07","lessonPage":21,"lessonPageTitle":"Classical time series forecasting methods"},{"id":"s5-q241","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":241,"level":"真题同型 · 500 题强化","question":"What does the autocorrelation function (ACF) measure?","questionZh":"自相关函数（ACF）衡量什么？","options":["The linear relationship between lagged values of a time series","The correlation between two different time series","The forecast accuracy on a test set","The number of seasons in a year"],"optionZh":["时间序列与其滞后值之间的线性关系","两条不同时间序列之间的相关性","测试集上的预测准确度","一年中的季节数"],"answer":0,"explanation":"A 正确：例如 lag 12 的自相关很高，提示月度数据有年度季节性；自相关随滞后缓慢下降，提示有趋势。","lessonId":"dsfb-07","lessonPage":23,"lessonPageTitle":"Autocorrelation measures the linear relationship between lagged values of a"},{"id":"s5-q242","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":242,"level":"真题同型 · 500 题强化","question":"Which was a main finding of the first M (Makridakis) competition in 1982?","questionZh":"1982 年第一届 M（Makridakis）竞赛的主要发现之一是什么？","options":["Neural networks clearly outperform all statistical methods.","Simple forecasting methods often produce more accurate forecasts than complex methods.","In-sample fit is the best criterion to select a forecasting method.","Combining forecasts always worsens accuracy."],"optionZh":["神经网络明显优于所有统计方法。","简单预测方法往往比复杂方法更准确。","样本内拟合是选择预测方法的最佳标准。","组合预测总会降低准确度。"],"answer":1,"explanation":"B 正确。M1 还让关注点从样本内拟合转向样本外（未见数据）表现（C 错），并发现组合预测通常更好（D 错）。","lessonId":"dsfb-07","lessonPage":24,"lessonPageTitle":"Time series forecasting: historical events"},{"id":"s5-q243","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":243,"level":"真题同型 · 500 题强化","question":"Which statement about the M3 competition (1998) is TRUE?","questionZh":"关于 M3 竞赛（1998），哪项说法正确？","options":["It provided additional evidence of the benefit of combining multiple forecasts.","It was won by a deep learning model.","It used only one time series.","It showed that forecast combinations are harmful."],"optionZh":["它进一步证明了组合多个预测的好处。","它的冠军是深度学习模型。","它只用了一条时间序列。","它表明组合预测有害。"],"answer":0,"explanation":"A 正确：M3 用了 3003 条序列，进一步支持了集成（组合）的好处，之后研究重点转向组合方案的微调和自动化预测方法。","lessonId":"dsfb-07","lessonPage":27,"lessonPageTitle":"Time series forecasting: historical events"},{"id":"s5-q244","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":244,"level":"真题同型 · 500 题强化","question":"How are exponential smoothing forecasts constructed?","questionZh":"指数平滑预测是如何构造的？","options":["As the simple average of all past observations","As the most recent observation only","As a regression on external variables","As weighted averages of past observations, with weights decaying exponentially as observations get older"],"optionZh":["所有历史观测的简单平均","只用最近一期观测","对外部变量做回归","历史观测的加权平均，观测越旧权重按指数衰减"],"answer":3,"explanation":"D 正确：近期观测权重最大，越早的观测权重越小。A 是均值法（等权重），B 是朴素法（全部权重给最近一期）。指数平滑介于两者之间。","lessonId":"dsfb-07","lessonPage":28,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q245","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":245,"level":"真题同型 · 500 题强化","question":"In simple exponential smoothing with smoothing parameter α, what happens as α approaches 1?","questionZh":"在平滑参数为 α 的简单指数平滑中，α 接近 1 时会怎样？","options":["The forecast approaches the mean method.","The forecast approaches the naïve method, putting almost all weight on the most recent observation.","The forecast becomes zero.","The weights stop decaying."],"optionZh":["预测接近均值法。","预测接近朴素法，几乎所有权重都在最近一期。","预测变成 0。","权重不再衰减。"],"answer":1,"explanation":"B 正确：权重为 α, α(1−α), α(1−α)², …，α = 1 时只剩最近一期。α 越接近 0，权重衰减越慢，越接近对较长历史的平均。","lessonId":"dsfb-07","lessonPage":28,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q246","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":246,"level":"真题同型 · 500 题强化","question":"With simple exponential smoothing and α = 0.5, the last forecast was 100 and the latest observation is 120. What is the new forecast?","questionZh":"简单指数平滑 α = 0.5，上一期预测为 100，最新观测为 120。新的预测是多少？","options":["120","100","110","105"],"optionZh":["120","100","110","105"],"answer":2,"explanation":"C 正确：新预测 = α × 观测 + (1 − α) × 旧预测 = 0.5 × 120 + 0.5 × 100 = 110。","lessonId":"dsfb-07","lessonPage":28,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q247","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":247,"level":"真题同型 · 500 题强化","question":"With simple exponential smoothing and α = 0.2, the last forecast was 50 and the latest observation is 60. What is the new forecast?","questionZh":"简单指数平滑 α = 0.2，上一期预测为 50，最新观测为 60。新的预测是多少？","options":["58","52","55","60"],"optionZh":["58","52","55","60"],"answer":1,"explanation":"B 正确：0.2 × 60 + 0.8 × 50 = 12 + 40 = 52。α 小，预测对最新观测的反应慢。A 是把 α 当成了 0.8。","lessonId":"dsfb-07","lessonPage":28,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q248","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":248,"level":"真题同型 · 500 题强化","question":"A retailer's seasonal swings grow proportionally as the sales level increases. Which way should seasonality enter the model?","questionZh":"某零售商的季节波动随销售水平成比例放大。季节性应该以什么方式进入模型？","options":["Multiplicatively","Additively","It should be ignored.","Only through the trend."],"optionZh":["乘法方式","加法方式","应该忽略。","只通过趋势进入。"],"answer":0,"explanation":"A 正确：加法季节性的波动幅度固定（如每年 12 月多卖 100 件），乘法季节性的波动按水平成比例（如每年 12 月多卖 20%）。Holt-Winters 有加法和乘法两种形式。","lessonId":"dsfb-07","lessonPage":22,"lessonPageTitle":"Classical time series forecasting methods"},{"id":"s5-q249","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":249,"level":"真题同型 · 500 题强化","question":"What does the ETS framework provide?","questionZh":"ETS 框架提供了什么？","options":["A deep learning architecture for global forecasting","A state space formulation of exponential smoothing that gives a statistical framework for model selection and prediction intervals","A method for time series classification","A way to remove seasonality permanently"],"optionZh":["用于全局预测的深度学习架构","指数平滑的状态空间表述，为模型选择和预测区间提供统计框架","一种时间序列分类方法","永久消除季节性的方法"],"answer":1,"explanation":"B 正确：ETS = Error、Trend、Seasonal，每个成分可以是无、加法或乘法。状态空间形式让我们能用似然和信息准则自动选模型、构造预测区间，而不必凭肉眼判断。","lessonId":"dsfb-07","lessonPage":30,"lessonPageTitle":"Hyndman, R. J., Koehler, A. B., Ord, J. K., & Snyder, R. D. (2008). Forecasting with"},{"id":"s5-q250","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":250,"level":"真题同型 · 500 题强化","question":"Which statement about ARIMA models is TRUE?","questionZh":"关于 ARIMA 模型，哪项说法正确？","options":["They describe the (seasonal) autocorrelations in the data, and auto.arima() selects a model automatically by minimizing the AIC.","They can only be used on data without any autocorrelation.","They are global models trained across many series.","They do not have any parameters."],"optionZh":["它们描述数据中的（季节）自相关，auto.arima() 通过最小化 AIC 自动选模型。","只能用于没有自相关的数据。","它们是跨多条序列训练的全局模型。","它们没有参数。"],"answer":0,"explanation":"A 正确：讲义第 32 页。C 错：ARIMA 和 ETS 是典型的局部模型，每条序列单独估计。","lessonId":"dsfb-07","lessonPage":32,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q251","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":251,"level":"真题同型 · 500 题强化","question":"Which statement about information criteria such as the AIC is TRUE?","questionZh":"关于 AIC 等信息准则，哪项说法正确？","options":["They measure only the out-of-sample error.","They always prefer the model with the most parameters.","They add a model complexity penalty to an in-sample fit measure.","They can be compared across different data sets."],"optionZh":["它们只衡量样本外误差。","它们总是偏好参数最多的模型。","它们在样本内拟合度上加了模型复杂度惩罚。","它们可以在不同数据集之间比较。"],"answer":2,"explanation":"C 正确：AIC = 拟合项 + 参数个数惩罚，避免过度复杂的模型。D 错：基于似然，只能比较同一数据上拟合的模型（真题第 12 题考过）。","lessonId":"dsfb-07","lessonPage":32,"lessonPageTitle":"Simple forecasting methods"},{"id":"s5-q252","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":252,"level":"真题同型 · 500 题强化","question":"Why were neural networks and other data-hungry ML methods long considered unsuitable for univariate time series forecasting?","questionZh":"为什么神经网络等数据饥渴型机器学习方法曾长期被认为不适合单变量时间序列预测？","options":["Most individual time series are relatively short, so there is not enough data to fit a good model.","Neural networks cannot output numbers.","Time series always have exactly one season.","Neural networks require categorical inputs."],"optionZh":["大多数单条时间序列较短，没有足够数据拟合好的模型。","神经网络不能输出数值。","时间序列总是只有一个季节。","神经网络需要类别输入。"],"answer":0,"explanation":"A 正确：讲义第 38 页：M3 唯一的 NN 方案表现较差，NN3 的 60 多个算法也没赢过原来的选手。原因是单条序列太短（局部建模）。后来转向全局模型才改变了这一点。","lessonId":"dsfb-07","lessonPage":38,"lessonPageTitle":"Only one NN submission in M3 → it did relatively poorly"},{"id":"s5-q253","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":253,"level":"真题同型 · 500 题强化","question":"What is demand sensing?","questionZh":"什么是需求感知（demand sensing）？","options":["Using only past demand to forecast future demand","Removing outliers from demand data","Using a wide range of demand signals, such as promotions and weather, in addition to prior demand","Forecasting at an aggregated level only"],"optionZh":["只用历史需求预测未来需求","删除需求数据中的异常值","除历史需求外，还使用促销、天气等多种需求信号","只在汇总层面预测"],"answer":2,"explanation":"C 正确：讲义第 41 页引用 Byrne (2012)：利用反映客户偏好变化的各种需求信号。这在大数据时代让机器学习方法有了用武之地。","lessonId":"dsfb-07","lessonPage":41,"lessonPageTitle":"Big data era"},{"id":"s5-q254","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":254,"level":"真题同型 · 500 题强化","question":"When many potentially relevant external regressors (xreg) with unknown lag order are available, what problem arises with classical models such as auto.arima() + xreg?","questionZh":"当有大量可能相关、滞后阶数未知的外部回归变量（xreg）时，auto.arima() + xreg 这类经典模型会遇到什么问题？","options":["The model cannot be estimated at all.","One quickly ends up in a p >> n situation, requiring variable selection.","The forecasts become seasonal naïve forecasts.","The external variables must all be categorical."],"optionZh":["模型完全无法估计。","很快会陷入 p >> n 的局面，需要做变量选择。","预测会变成季节朴素预测。","外部变量必须全部是类别型。"],"answer":1,"explanation":"B 正确：每个指标再乘以多个可能的滞后期，变量数远超历史观测数。讲义第 42–45 页的解决方案是用 LASSO 自动选择领先指标及其滞后阶数。","lessonId":"dsfb-07","lessonPage":42,"lessonPageTitle":"Different flavors of auto.arima() or ets() + lm(residual ~ xreg)"},{"id":"s5-q255","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":255,"level":"真题同型 · 500 题强化","question":"In the tactical sales forecasting example with many macro-economic leading indicators, which method was used to automatically select both the indicators and their lead order?","questionZh":"在使用大量宏观经济领先指标的战术销售预测例子中，用了什么方法来自动选择指标及其领先阶数？","options":["k-means","Seasonal naïve","LASSO","Apriori"],"optionZh":["k-means","季节朴素法","LASSO","Apriori"],"answer":2,"explanation":"C 正确：LASSO 的 L1 惩罚会把不重要变量的系数压为 0，相当于自动做变量选择，适合 p >> n 的情形。目标是用领先指标取代人工的判断性调整。","lessonId":"dsfb-07","lessonPage":45,"lessonPageTitle":"Tactical forecasting in supply chain management"},{"id":"s5-q256","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":256,"level":"真题同型 · 500 题强化","question":"Which statement about local versus global forecasting models is TRUE?","questionZh":"关于局部和全局预测模型，哪项说法正确？","options":["A local model is trained jointly across all time series.","Global models can only use a small number of parameters.","ETS and ARIMA are typical global models.","A global model is trained jointly across time series, so a large training set allows models with many parameters."],"optionZh":["局部模型跨所有时间序列联合训练。","全局模型只能使用很少的参数。","ETS 和 ARIMA 是典型的全局模型。","全局模型跨时间序列联合训练，训练集大，所以可以用参数很多的模型。"],"answer":3,"explanation":"D 正确：讲义第 51 页。A 把局部和全局说反了。C 错：ETS、ARIMA 是局部模型，每条序列单独估计，所以只能用少量参数。","lessonId":"dsfb-07","lessonPage":51,"lessonPageTitle":"From local to global time series forecasting models"},{"id":"s5-q257","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":257,"level":"真题同型 · 500 题强化","question":"Which statement about global forecasting models is TRUE?","questionZh":"关于全局预测模型，哪项说法正确？","options":["They necessarily model the dependence structure between the different time series.","They can only be built with neural networks.","They do not necessarily model a dependence structure between the series, unlike multivariate methods that model it explicitly.","They are the same as multivariate methods."],"optionZh":["它们必然建模不同时间序列之间的依赖结构。","只能用神经网络构建。","它们不一定建模序列之间的依赖结构，而多变量方法会显式建模。","它们与多变量方法相同。"],"answer":2,"explanation":"C 正确：讲义第 52 页：局部/全局的区分与单变量/多变量的区分是互补的两个维度。全局模型只是共享参数，不一定建模序列间的依赖。B 错：树模型（如 LightGBM）也很常用。","lessonId":"dsfb-07","lessonPage":52,"lessonPageTitle":"ML methods such as ANNs and tree-based ensembles can be used both in"},{"id":"s5-q258","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":258,"level":"真题同型 · 500 题强化","question":"A retailer must forecast next week's demand for each of 500,000 products in 800 stores, with promotion and holiday data available. Which approach is most suitable according to the lecture?","questionZh":"某零售商要为 800 家门店的 50 万种商品预测下周需求，并有促销和节假日数据。根据讲义，哪种方法最合适？","options":["A global model trained across all series","Hand-crafting a separate ARIMA specification for each series","Judgemental forecasting by one analyst","The mean method for every product"],"optionZh":["跨所有序列训练的全局模型","为每条序列手工设定单独的 ARIMA","由一位分析师做判断性预测","对每个商品都用均值法"],"answer":0,"explanation":"A 正确：这是讲义第 61 页的“运营预测”：序列极多、边缘情况多，预测人员与序列之比远小于 1，数据足以学习复杂模式，适合全局模型。","lessonId":"dsfb-07","lessonPage":61,"lessonPageTitle":"Strategic forecasting problem"},{"id":"s5-q259","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":259,"level":"真题同型 · 500 题强化","question":"Which forecasting problem is described as a strategic problem in the lecture?","questionZh":"讲义中哪种预测问题被描述为战略性问题？","options":["Predicting next week's demand for every product of Amazon","Predicting overall Amazon retail demand years into the future","Predicting tomorrow's stock price","Predicting the order of web pages visited"],"optionZh":["预测亚马逊每种商品下周的需求","预测亚马逊未来数年的整体零售需求","预测明天的股价","预测网页访问顺序"],"answer":1,"explanation":"B 正确：战略预测是高层、汇总、长周期的，用于长期产能投资、进入市场等决策，需要融入领域知识。A 是运营预测。","lessonId":"dsfb-07","lessonPage":61,"lessonPageTitle":"Strategic forecasting problem"},{"id":"s5-q260","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":260,"level":"真题同型 · 500 题强化","question":"Why is it important to quantify forecast uncertainty?","questionZh":"为什么量化预测不确定性很重要？","options":["Because uncertainty is always zero for good models.","Because forecast uncertainty is frequently crucial for optimal decision making, e.g., setting safety stocks.","Because point forecasts cannot be computed otherwise.","Because it reduces the amount of data needed."],"optionZh":["因为好的模型不确定性总是 0。","因为预测不确定性常常对最优决策至关重要，例如设定安全库存。","因为否则就无法算出点预测。","因为它能减少所需数据量。"],"answer":1,"explanation":"B 正确：讲义第 53 页：没有不确定性就不需要预测。安全库存取决于需求可能偏离预测多少，而不只取决于点预测。","lessonId":"dsfb-07","lessonPage":53,"lessonPageTitle":"From point to probabilistic forecasting"},{"id":"s5-q261","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":261,"level":"真题同型 · 500 题强化","question":"Why are prediction intervals of classical time series models often too narrow?","questionZh":"为什么经典时间序列模型的预测区间往往太窄？","options":["Because they are computed on the test set.","Because they use too many parameters.","Because they always assume multiplicative seasonality.","Because they do not account for all sources of uncertainty, such as model choice and parameter uncertainty."],"optionZh":["因为它们是在测试集上计算的。","因为它们使用了太多参数。","因为它们总假设乘法季节性。","因为它们没有考虑所有不确定性来源，如模型选择和参数不确定性。"],"answer":3,"explanation":"D 正确：讲义第 55 页列出四个来源：随机误差、参数估计、模型选择、历史数据生成过程是否延续。通常只考虑第一个，所以名义 95% 的区间实际只覆盖 71%–87%。","lessonId":"dsfb-07","lessonPage":55,"lessonPageTitle":"“Almost all prediction intervals from [classical] time series models are too narrow. This"},{"id":"s5-q262","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":262,"level":"真题同型 · 500 题强化","question":"Which of the following is NOT one of the four sources of uncertainty in forecasting with time series models listed in the lecture?","questionZh":"以下哪项不是讲义列出的时间序列预测四个不确定性来源之一？","options":["The random error term","The parameter estimates","The choice of model for the historical data","The colour of the forecasting dashboard"],"optionZh":["随机误差项","参数估计","对历史数据的模型选择","预测仪表盘的颜色"],"answer":3,"explanation":"D 显然不是。第四个来源是“历史数据生成过程能否延续到未来”。","lessonId":"dsfb-07","lessonPage":55,"lessonPageTitle":"“Almost all prediction intervals from [classical] time series models are too narrow. This"},{"id":"s5-q263","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":263,"level":"真题同型 · 500 题强化","question":"Which approach won the M4 competition?","questionZh":"哪种方法赢得了 M4 竞赛？","options":["ES-RNN, a hybrid of a global data-driven RNN and local exponential smoothing equations","The seasonal naïve method","A single local ARIMA model","k-means clustering"],"optionZh":["ES-RNN：全局数据驱动 RNN 与局部指数平滑方程的混合模型","季节朴素法","单个局部 ARIMA 模型","k-means 聚类"],"answer":0,"explanation":"A 正确：Smyl（Uber）的 ES-RNN 获胜，FFORMA（用 XGBoost 学习组合权重）名列前茅。结论是“混合是未来的方向”，而不是纯 ML。","lessonId":"dsfb-07","lessonPage":56,"lessonPageTitle":"Top performing solutions"},{"id":"s5-q264","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":264,"level":"真题同型 · 500 题强化","question":"What does FFORMA (Feature-based FORecast Model Averaging) do?","questionZh":"FFORMA（基于特征的预测模型平均）做了什么？","options":["It trains one deep network per time series.","It uses a tree-based meta-learner (XGBoost) to determine optimal combination weights for a pool of standard methods based on time series features.","It removes all seasonal patterns.","It forecasts only with the mean method."],"optionZh":["为每条时间序列训练一个深度网络。","用基于树的元学习器（XGBoost），根据时间序列特征为一组标准方法确定最优组合权重。","它去除所有季节模式。","它只用均值法预测。"],"answer":1,"explanation":"B 正确：FFORMA 不直接预测，而是根据每条序列的特征决定怎么加权组合 ETS、ARIMA 等标准方法的预测。","lessonId":"dsfb-07","lessonPage":56,"lessonPageTitle":"Top performing solutions"},{"id":"s5-q265","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":265,"level":"真题同型 · 500 题强化","question":"According to the M4 conclusions, what is the strength of the local model-driven component in a hybrid approach?","questionZh":"根据 M4 的结论，混合方法中局部模型驱动部分的优势是什么？","options":["It is flexible with millions of parameters.","It needs no assumptions at all.","It is parsimoniously parameterized and therefore needs little data to be accurately fitted.","It is only as good as the data it is fed."],"optionZh":["它很灵活，有数百万参数。","它完全不需要假设。","它参数精简，所以只需要少量数据就能准确拟合。","它的好坏完全取决于输入的数据。"],"answer":2,"explanation":"C 正确：讲义第 57 页：局部模型驱动部分“只和它的假设一样好”，但参数少、需要的数据少。A、D 描述的是全局数据驱动部分：灵活、无强结构假设、但需要大量数据。","lessonId":"dsfb-07","lessonPage":57,"lessonPageTitle":"Conclusion = hybrid is the way forward (vs. pure ML)"},{"id":"s5-q266","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":266,"level":"真题同型 · 500 题强化","question":"Which statement about N-BEATS is TRUE?","questionZh":"关于 N-BEATS，哪项说法正确？","options":["It is a local exponential smoothing method.","It is a deep, pure deep learning architecture for univariate global point forecasting, challenging the conclusion that hybrids are necessary.","It requires external regressors.","It was the winner of the first M competition in 1982."],"optionZh":["它是局部指数平滑方法。","它是用于单变量全局点预测的深层纯深度学习架构，挑战了“必须用混合模型”的结论。","它需要外部回归变量。","它是 1982 年第一届 M 竞赛的冠军。"],"answer":1,"explanation":"B 正确：讲义第 58–59 页：N-BEATS 用双重残差堆叠，没有时间序列特有的组件，在 M3、M4 数据上达到最优表现，但用了 180 个网络的集成。","lessonId":"dsfb-07","lessonPage":59,"lessonPageTitle":"N-BEATS (Oreshkin et al., 2020)"},{"id":"s5-q267","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":267,"level":"真题同型 · 500 题强化","question":"What problem does N-BEATS-S address?","questionZh":"N-BEATS-S 解决什么问题？","options":["Forecast instability caused by forecast updating across successive forecast origins","Missing values in the time series","The lack of external variables","Classification of time series"],"optionZh":["连续预测起点之间更新预测所导致的预测不稳定","时间序列中的缺失值","缺乏外部变量","时间序列分类"],"answer":0,"explanation":"A 正确：每次滚动更新会让对同一未来月份的预测反复变动，导致计划（如原料采购）频繁修改。N-BEATS-S 在损失函数中加入了不稳定性惩罚。","lessonId":"dsfb-07","lessonPage":63,"lessonPageTitle":"N-BEATS-S: forecast updating & instability"},{"id":"s5-q268","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":268,"level":"真题同型 · 500 题强化","question":"What did the empirical evaluation of N-BEATS-S show?","questionZh":"N-BEATS-S 的实证评估表明了什么？","options":["More stable forecasts but a large loss in accuracy","Less stable forecasts and higher accuracy","More stable forecasts without loss in accuracy, sometimes even improved accuracy, acting as a regularization mechanism","No difference with N-BEATS"],"optionZh":["预测更稳定，但准确度大幅下降","预测更不稳定，准确度更高","预测更稳定且没有损失准确度，有时甚至提高了准确度，起到正则化作用","与 N-BEATS 没有差别"],"answer":2,"explanation":"C 正确：讲义第 65 页：稳定性惩罚类似正则化，防止网络过度追随最新数据中的噪声。","lessonId":"dsfb-07","lessonPage":65,"lessonPageTitle":"N-BEATS-S: empirical evaluation"},{"id":"s5-q269","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":269,"level":"真题同型 · 500 题强化","question":"How can a deep learning model produce probabilistic forecasts directly, as in N-N-BEATS?","questionZh":"像 N-N-BEATS 那样，深度学习模型如何直接产生概率预测？","options":["By outputting the parameters of a probability distribution and training with the negative log-likelihood as loss","By using the mean method","By running the model only once","By removing the output layer"],"optionZh":["输出概率分布的参数，并以负对数似然作为损失函数训练","使用均值法","只运行一次模型","删除输出层"],"answer":0,"explanation":"A 正确：讲义第 62 页：例如输出每个时间步正态分布的均值和标准差，用负对数似然训练。这体现了深度学习的灵活性：可以按业务需求定制损失函数。","lessonId":"dsfb-07","lessonPage":62,"lessonPageTitle":"Global DL models for time series forecasting"},{"id":"s5-q270","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":270,"level":"真题同型 · 500 题强化","question":"Why is the M5 competition considered important?","questionZh":"为什么 M5 竞赛被认为很重要？","options":["It was the first open data set representative of real-world operational forecasting problems, with covariates, hierarchy and intermittency.","It used only annual data.","It contained only one time series.","It banned machine learning methods."],"optionZh":["它是第一个能代表真实运营预测问题的公开数据集，包含协变量、层级结构和间歇性需求。","它只用年度数据。","它只包含一条时间序列。","它禁止使用机器学习方法。"],"answer":0,"explanation":"A 正确：沃尔玛的 42,840 条层级序列，预测 28 天，并有独立的准确度和不确定性两个赛道。","lessonId":"dsfb-07","lessonPage":67,"lessonPageTitle":"The M5 competition = first open data set that can be considered representative for"},{"id":"s5-q271","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":271,"level":"真题同型 · 500 题强化","question":"Which methods were hugely popular in the M5 competition?","questionZh":"哪些方法在 M5 竞赛中极为流行？","options":["Seasonal naïve and mean methods","Tree-based gradient boosting methods such as LightGBM and XGBoost","k-means and PAM","Only N-BEATS"],"optionZh":["季节朴素法和均值法","基于树的梯度提升方法，如 LightGBM 和 XGBoost","k-means 和 PAM","只有 N-BEATS"],"answer":1,"explanation":"B 正确：讲义第 69 页：它们处理缺失值方便、速度快、默认参数好、容易加入协变量。冠军方案是每家店 22 个全局 LightGBM 模型的等权集成。","lessonId":"dsfb-07","lessonPage":69,"lessonPageTitle":"XGBoost and LightGBM hugely popular in M5"},{"id":"s5-q272","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":272,"level":"真题同型 · 500 题强化","question":"How does the M5 winning approach differ from the M4 winning approach?","questionZh":"M5 冠军方案与 M4 冠军方案有何不同？","options":["M5 was won by heavy ensembling of off-the-shelf tree-based learners, whereas M4 was won by a true model innovation (RNN hybrid).","Both were won by the seasonal naïve method.","M5 was won by a local ARIMA model.","M4 was won by LightGBM."],"optionZh":["M5 靠大量集成现成的树模型获胜，而 M4 靠真正的模型创新（RNN 混合模型）获胜。","两者都由季节朴素法获胜。","M5 由局部 ARIMA 模型获胜。","M4 由 LightGBM 获胜。"],"answer":0,"explanation":"A 正确：讲义第 70 页对比了两者：M4 是模型创新，M5 是对现成树学习器的重度集成，很多决定基于经验和特征选择。","lessonId":"dsfb-07","lessonPage":70,"lessonPageTitle":"Characteristics of M5 winning method"},{"id":"s5-q273","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":273,"level":"真题同型 · 500 题强化","question":"Which concern about the future of time series forecasting is raised regarding N-BEATS?","questionZh":"讲义对 N-BEATS 提出了关于时间序列预测未来的什么担忧？","options":["It reached state-of-the-art results partly through brute-force ensembling (180 networks), raising questions of efficiency versus model innovation.","It cannot forecast more than one step ahead.","It only works on categorical data.","It requires RCT data."],"optionZh":["它部分依靠暴力集成（180 个网络）达到最优，引出效率与模型创新之间的问题。","它不能预测超过一步。","它只能用于类别数据。","它需要随机对照实验数据。"],"answer":0,"explanation":"A 正确：讲义第 72 页：模型创新 vs 靠堆算力的暴力集成；未来方向包括训练效率与稳定性，以及结合时间序列专属元素和全局建模的混合架构。","lessonId":"dsfb-07","lessonPage":72,"lessonPageTitle":"The future of time series forecasting"},{"id":"s5-q274","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":274,"level":"真题同型 · 500 题强化","question":"What is the main benefit of pre-trained global deep learning models (transfer learning) for forecasting?","questionZh":"预训练全局深度学习模型（迁移学习）对预测的主要好处是什么？","options":["They make data-driven DL forecasting usable even when only limited training data is available for the target task.","They remove the need for any data.","They only work for the series they were trained on.","They are always local models."],"optionZh":["即使目标任务只有很少训练数据，也能使用数据驱动的深度学习预测。","完全不需要任何数据。","只能用于训练时用过的序列。","它们总是局部模型。"],"answer":0,"explanation":"A 正确：先在大量异构数据上预训练，再在新数据上微调（few-shot）或直接使用（zero-shot）。C 正好相反。","lessonId":"dsfb-07","lessonPage":73,"lessonPageTitle":"Pre-trained global deep learning models = transfer learning"},{"id":"s5-q275","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":275,"level":"真题同型 · 500 题强化","question":"What does zero-shot transfer learning mean in forecasting?","questionZh":"预测中的“零样本迁移学习”是什么意思？","options":["Training a model without any data","Training on a source data set and deploying on a new target data set without fine-tuning","Forecasting zero periods ahead","Setting all weights to zero"],"optionZh":["不用任何数据训练模型","在源数据集上训练，不经微调直接部署到新目标数据集","预测未来 0 期","把所有权重设为 0"],"answer":1,"explanation":"B 正确：Oreshkin 等人把 N-BEATS 用于零样本场景。CHRONOS 等时间序列基础模型也具备零样本能力；TabPFN-TS 则是通用表格基础模型加简单特征工程。","lessonId":"dsfb-07","lessonPage":74,"lessonPageTitle":"Zero-shot transfer learning"},{"id":"s5-q276","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 7: Time Series Forecasting","number":276,"level":"真题同型 · 500 题强化","question":"Which evolution in time series forecasting is NOT listed in the lecture?","questionZh":"以下哪项不是讲义列出的时间序列预测演进方向？","options":["From local to global forecasting models","From point to probabilistic forecasting","From global to exclusively hand-crafted judgemental forecasts","Demand sensing and machine learning in the big data era"],"optionZh":["从局部到全局预测模型","从点预测到概率预测","从全局模型转向纯手工的判断性预测","大数据时代的需求感知与机器学习"],"answer":2,"explanation":"C 不在其中：讲义第 40 页的方向是组合简单方法、需求感知 + ML、局部到全局、跟进深度学习、点预测到概率预测。领先指标的例子恰恰是为了取代人工判断调整。","lessonId":"dsfb-07","lessonPage":40,"lessonPageTitle":"Evolutions in time series forecasting"},{"id":"s5-q277","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":277,"level":"真题同型 · 500 题强化","question":"Which statement about the goal of clustering is TRUE?","questionZh":"关于聚类的目标，哪项说法正确？","options":["Clusters should be as similar to each other as possible.","Clustering requires a labelled target variable.","Each cluster must contain the same number of instances.","Instances within a cluster should be homogeneous, and different clusters should be as heterogeneous as possible."],"optionZh":["不同簇之间应尽可能相似。","聚类需要带标签的目标变量。","每个簇必须包含相同数量的实例。","簇内实例应同质，不同簇之间应尽可能异质。"],"answer":3,"explanation":"D 正确：讲义第 8 页：找同质群体，同时希望不同群体之间差异尽可能大，否则就不该分开。B 错：聚类是无监督学习。","lessonId":"dsfb-08","lessonPage":8,"lessonPageTitle":"Clustering"},{"id":"s5-q278","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":278,"level":"真题同型 · 500 题强化","question":"Agglomerative hierarchical clustering:","questionZh":"凝聚式层次聚类：","options":["Starts with the complete data set and splits it into partitions.","Requires the number of clusters k before running.","Starts with single elements and merges them step by step into larger clusters.","Assigns each instance to the nearest centroid."],"optionZh":["从完整数据集开始，逐步拆分。","运行前必须指定簇数 k。","从单个元素开始，逐步合并成更大的簇。","把每个实例分配到最近的质心。"],"answer":2,"explanation":"C 正确：“agglomerate”就是聚合。A 是分裂式（divisive）层次聚类。D 描述的是 k-means。B 错：层次聚类可以事后通过树状图决定簇数。","lessonId":"dsfb-08","lessonPage":9,"lessonPageTitle":"Clustering"},{"id":"s5-q279","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":279,"level":"真题同型 · 500 题强化","question":"Which two ingredients does hierarchical clustering need to decide which clusters to merge or split?","questionZh":"层次聚类需要哪两样东西来决定合并或拆分哪些簇？","options":["A distance metric between observations and a linkage criterion between sets of observations","A target variable and a loss function","A learning rate and a number of epochs","Support and confidence thresholds"],"optionZh":["观测之间的距离度量，以及观测集合之间的连接准则","目标变量和损失函数","学习率和训练轮数","支持度和置信度阈值"],"answer":0,"explanation":"A 正确：讲义第 10 页：距离度量衡量两个点有多远，连接准则（single/complete/average/Ward）把点间距离推广到簇间距离。D 是关联规则的参数。","lessonId":"dsfb-08","lessonPage":10,"lessonPageTitle":"Hierarchical clustering"},{"id":"s5-q280","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":280,"level":"真题同型 · 500 题强化","question":"What is the Euclidean distance between customer (age 50, income 20) and customer (age 30, income 10)?","questionZh":"客户（年龄 50，收入 20）与客户（年龄 30，收入 10）之间的欧氏距离是多少？","options":["30","500","10","≈ 22.36"],"optionZh":["30","500","10","≈ 22.36"],"answer":3,"explanation":"D 正确：√((50−30)² + (20−10)²) = √(400 + 100) = √500 ≈ 22.36。A 是曼哈顿距离 |20| + |10| = 30。B 忘了开根号。","lessonId":"dsfb-08","lessonPage":11,"lessonPageTitle":"Distance measures"},{"id":"s5-q281","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":281,"level":"真题同型 · 500 题强化","question":"What is the Manhattan (city block) distance between the points (50, 20) and (30, 10)?","questionZh":"点 (50, 20) 与 (30, 10) 之间的曼哈顿（城市街区）距离是多少？","options":["≈ 22.36","30","20","500"],"optionZh":["≈ 22.36","30","20","500"],"answer":1,"explanation":"B 正确：曼哈顿距离 = |50 − 30| + |20 − 10| = 20 + 10 = 30。A 是欧氏距离。","lessonId":"dsfb-08","lessonPage":11,"lessonPageTitle":"Distance measures"},{"id":"s5-q282","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":282,"level":"真题同型 · 500 题强化","question":"Before computing Euclidean distances for clustering customers on age (years) and income (euros), what should you do?","questionZh":"用年龄（岁）和收入（欧元）对客户聚类、计算欧氏距离之前，应该先做什么？","options":["Standardize the variables, e.g., using z-scores.","Remove the age variable.","Multiply income by 100.","Nothing; Euclidean distance is scale-invariant."],"optionZh":["对变量标准化，例如使用 z 分数。","删除年龄变量。","把收入乘以 100。","什么都不用做，欧氏距离与尺度无关。"],"answer":0,"explanation":"A 正确：不标准化时，收入以千计，年龄以十计，距离几乎完全由收入决定。D 错：欧氏距离对尺度非常敏感。","lessonId":"dsfb-08","lessonPage":11,"lessonPageTitle":"Distance measures"},{"id":"s5-q283","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":283,"level":"真题同型 · 500 题强化","question":"Item set A = {apple, bread, cheese} and item set B = {bread, cheese, dates}. What is the Jaccard distance between A and B?","questionZh":"项集 A = {apple, bread, cheese}，项集 B = {bread, cheese, dates}。A 与 B 的 Jaccard 距离是多少？","options":["0.25","0.67","0.5","2"],"optionZh":["0.25","0.67","0.5","2"],"answer":2,"explanation":"C 正确：交集 {bread, cheese} 有 2 项，并集 {apple, bread, cheese, dates} 有 4 项。Jaccard 相似度 = 2/4 = 0.5，Jaccard 距离 = 1 − 0.5 = 0.5。","lessonId":"dsfb-08","lessonPage":13,"lessonPageTitle":"Distance measures"},{"id":"s5-q284","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":284,"level":"真题同型 · 500 题强化","question":"Which distance measure is appropriate for comparing two sequences of events, such as two customer journeys?","questionZh":"比较两条事件序列（例如两段客户旅程）时，适合用哪种距离？","options":["Levenshtein distance","Manhattan distance","Euclidean distance","Jaccard distance"],"optionZh":["Levenshtein 距离（编辑距离）","曼哈顿距离","欧氏距离","Jaccard 距离"],"answer":0,"explanation":"A 正确：讲义第 13 页：Levenshtein 距离用于序列，计算把一个序列变成另一个所需的最少编辑次数。Jaccard 用于集合，汉明距离用于等长的类别向量。","lessonId":"dsfb-08","lessonPage":13,"lessonPageTitle":"Distance measures"},{"id":"s5-q285","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":285,"level":"真题同型 · 500 题强化","question":"Two customers are described by categorical vectors (red, small, yes, urban) and (blue, small, no, urban). What is the Hamming distance?","questionZh":"两位客户的类别向量分别为 (red, small, yes, urban) 和 (blue, small, no, urban)。汉明距离是多少？","options":["1","4","0.5","2"],"optionZh":["1","4","0.5","2"],"answer":3,"explanation":"D 正确：汉明距离 = 对应位置不同的个数。颜色和第三项不同，共 2 个。","lessonId":"dsfb-08","lessonPage":13,"lessonPageTitle":"Distance measures"},{"id":"s5-q286","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":286,"level":"真题同型 · 500 题强化","question":"Which linkage method merges the two clusters whose closest pair of objects is nearest, and tends to produce long, chained clusters?","questionZh":"哪种连接方法合并“最近的一对对象”距离最小的两个簇，容易形成又长又链状的簇？","options":["Complete linkage","Single linkage","Average linkage","Ward's method"],"optionZh":["全连接","单连接","平均连接","Ward 法"],"answer":1,"explanation":"B 正确：单连接只看最近的两个点，容易一个接一个串起来，形成长簇。A 全连接看最远的两个点，形成紧凑的簇。","lessonId":"dsfb-08","lessonPage":14,"lessonPageTitle":"Single linkage"},{"id":"s5-q287","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":287,"level":"真题同型 · 500 题强化","question":"Complete linkage joins two clusters when:","questionZh":"全连接在什么情况下合并两个簇？","options":["The minimal distance between two objects of both clusters is minimal.","The mean distance between all observations in both clusters is minimal.","The maximal distance between two objects of both clusters is minimal, yielding tight clusters.","The clusters have the same size."],"optionZh":["两簇对象之间的最小距离最小时。","两簇所有观测间的平均距离最小时。","两簇对象之间的最大距离最小时，结果是紧凑的簇。","两个簇大小相同时。"],"answer":2,"explanation":"C 正确：全连接用最远的两个点定义簇间距离，合并后的簇直径受到控制，所以较紧凑。A 是单连接，B 是平均连接。","lessonId":"dsfb-08","lessonPage":14,"lessonPageTitle":"Single linkage"},{"id":"s5-q288","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":288,"level":"真题同型 · 500 题强化","question":"Which statement about the dendrogram is FALSE?","questionZh":"关于树状图（dendrogram），哪项说法是错误的？","options":["It is a common visualization for hierarchical clustering.","The length of the branches corresponds to the distance between merged objects.","It can help determine the number of clusters for not too large data sets.","It is the standard output of k-means clustering."],"optionZh":["它是层次聚类的常用可视化方式。","分支长度对应被合并对象之间的距离。","对不太大的数据集，它有助于确定簇数。","它是 k-means 聚类的标准输出。"],"answer":3,"explanation":"D 错误：k-means 是划分式聚类，只输出一组 k 个簇，没有层次结构，所以没有树状图。A、B、C 都是讲义第 15 页的内容。","lessonId":"dsfb-08","lessonPage":15,"lessonPageTitle":"Hierarchical clustering: visualization"},{"id":"s5-q289","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":289,"level":"真题同型 · 500 题强化","question":"Which statement about partitional clustering is TRUE?","questionZh":"关于划分式聚类，哪项说法正确？","options":["It produces a hierarchy of nested clusters.","Each instance is placed in exactly one of k non-overlapping clusters, and the user normally specifies k.","It cannot be based on an objective function.","Its only algorithm is k-means."],"optionZh":["它产生嵌套的簇层次结构。","每个实例恰好被分到 k 个互不重叠的簇之一，k 通常由用户指定。","它不能基于目标函数。","它唯一的算法是 k-means。"],"answer":1,"explanation":"B 正确：讲义第 16 页。C 错：k-means 正是最小化簇内平方和。D 错：还有 PAM、模糊 c-means 等。","lessonId":"dsfb-08","lessonPage":16,"lessonPageTitle":"Partitional clustering"},{"id":"s5-q290","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":290,"level":"真题同型 · 500 题强化","question":"Which is NOT a disadvantage of k-means listed in the lecture?","questionZh":"以下哪项不是讲义列出的 k-means 缺点？","options":["The result may depend on the initialization.","It is not suitable for categorical data.","It is not robust with respect to outliers.","It cannot handle large data sets."],"optionZh":["结果可能依赖初始化。","不适合类别数据。","对异常值不稳健。","无法处理大数据集。"],"answer":3,"explanation":"D 不是缺点：讲义第 17 页恰好说 k-means 适合大数据集、简单直观、可以并行。A、B、C 才是它的缺点。","lessonId":"dsfb-08","lessonPage":17,"lessonPageTitle":"K-means"},{"id":"s5-q291","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":291,"level":"真题同型 · 500 题强化","question":"Why is k-means not suited for categorical data?","questionZh":"为什么 k-means 不适合类别数据？","options":["Because it requires computing the mean of each cluster, which is not defined for categories.","Because it requires a target variable.","Because it can only form two clusters.","Because categorical variables have too many outliers."],"optionZh":["因为它需要计算每个簇的均值，而类别变量没有均值。","因为它需要目标变量。","因为它只能形成两个簇。","因为类别变量的异常值太多。"],"answer":0,"explanation":"A 正确：k-means 的更新步骤用簇均值作为新中心，“红色”和“蓝色”的平均没有意义。PAM 用众数和合适的距离可以处理类别数据。","lessonId":"dsfb-08","lessonPage":17,"lessonPageTitle":"K-means"},{"id":"s5-q292","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":292,"level":"真题同型 · 500 题强化","question":"How does PAM (Partitioning Around Medoids) differ from k-means?","questionZh":"PAM（围绕中心点划分）与 k-means 有何不同？","options":["PAM uses medoids, which are actual observations, making it less sensitive to outliers and usable with categorical data.","PAM does not need the number of clusters.","PAM is a hierarchical method.","PAM always produces a dendrogram."],"optionZh":["PAM 使用中心点（medoid，即真实观测），对异常值更不敏感，也可用于类别数据。","PAM 不需要簇数。","PAM 是层次方法。","PAM 总会产生树状图。"],"answer":0,"explanation":"A 正确：medoid 相当于多维的中位数，是数据中真实存在的点，不会被极端值拉偏。PAM 的迭代流程与 k-means 相同，仍需指定 k，也不是层次方法。","lessonId":"dsfb-08","lessonPage":18,"lessonPageTitle":"PAM (Partition Around Medoids)"},{"id":"s5-q293","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":293,"level":"真题同型 · 500 题强化","question":"How can the number of clusters be determined with a scree plot?","questionZh":"如何用碎石图（scree plot）确定簇数？","options":["Choose the number of clusters with the highest AUC.","Plot intra-cluster distance against the number of clusters and look for an elbow.","Always choose k = 2.","Choose the number of clusters that minimizes the intra-cluster distance."],"optionZh":["选择 AUC 最高的簇数。","绘制簇内距离随簇数变化的曲线，寻找“肘部”。","永远选择 k = 2。","选择使簇内距离最小的簇数。"],"answer":1,"explanation":"B 正确：簇越多，簇内距离越小，在肘部之后下降变缓，增加簇的收益不大。D 错：簇内距离在每个点自成一簇时最小（为 0），没有意义。A 错：聚类没有标签，没法算 AUC。","lessonId":"dsfb-08","lessonPage":19,"lessonPageTitle":"Number of clusters"},{"id":"s5-q294","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":294,"level":"真题同型 · 500 题强化","question":"Which approach does the lecture suggest to interpret the resulting clusters?","questionZh":"讲义建议用什么方法解释聚类结果？","options":["Compare cluster averages with population averages, or predict the cluster ID with a decision tree.","Compute the AUC of each cluster.","Remove the smallest cluster.","Rerun k-means until all clusters are equally large."],"optionZh":["比较各簇平均值与总体平均值，或用决策树预测簇编号。","计算每个簇的 AUC。","删除最小的簇。","重复运行 k-means 直到所有簇一样大。"],"answer":0,"explanation":"A 正确：讲义第 20 页。用决策树预测簇编号，可以得到可读的规则来描述每个簇。稳定性则通过在不同样本上用不同方法重复聚类来检查。","lessonId":"dsfb-08","lessonPage":20,"lessonPageTitle":"Interpretation and stability"},{"id":"s5-q295","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":295,"level":"真题同型 · 500 题强化","question":"In fraud detection, how can clustering support the analysis?","questionZh":"在欺诈检测中，聚类能如何帮助分析？","options":["By building clusters of normal behaviour, so that deviating instances can be flagged.","By predicting the fraud amount.","By replacing the need for any labels in the evaluation.","By computing the cost-sensitive threshold."],"optionZh":["构建正常行为的簇，从而标记偏离的实例。","预测欺诈金额。","让评估完全不需要标签。","计算成本敏感阈值。"],"answer":0,"explanation":"A 正确：讲义第 21 页列出“Fraud detection: clusters of normal behavior”。远离所有正常簇的交易值得进一步调查，这在一开始没有标签时特别有用。","lessonId":"dsfb-08","lessonPage":21,"lessonPageTitle":"Applications"},{"id":"s5-q296","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":296,"level":"真题同型 · 500 题强化","question":"In the association rule {diapers, baby food} → {beer}, what is {diapers, baby food}?","questionZh":"关联规则 {diapers, baby food} → {beer} 中，{diapers, baby food} 是什么？","options":["The rule consequent","The rule antecedent","The support","The lift"],"optionZh":["规则后件","规则前件","支持度","提升度"],"answer":1,"explanation":"B 正确：X → Y 中 X 是前件（if 部分），Y 是后件（then 部分）。规则要求 X 与 Y 没有交集。","lessonId":"dsfb-08","lessonPage":27,"lessonPageTitle":"Association analysis"},{"id":"s5-q297","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":297,"level":"真题同型 · 500 题强化","question":"In the lecture's 10-transaction database, {baby food, diapers, beer} occurs in 3 transactions and {baby food, diapers} occurs in 5. What are the support and confidence of the rule {baby food, diapers} → {beer}?","questionZh":"讲义的 10 笔交易数据中，{baby food, diapers, beer} 出现在 3 笔交易，{baby food, diapers} 出现在 5 笔。规则 {baby food, diapers} → {beer} 的支持度和置信度是多少？","options":["Support 50%, confidence 30%","Support 30%, confidence 100%","Support 60%, confidence 30%","Support 30%, confidence 60%"],"optionZh":["支持度 50%，置信度 30%","支持度 30%，置信度 100%","支持度 60%，置信度 30%","支持度 30%，置信度 60%"],"answer":3,"explanation":"D 正确：支持度 = 同时包含三者的交易 / 总交易 = 3/10 = 30%；置信度 = 3 / 包含前件的交易 = 3/5 = 60%。","lessonId":"dsfb-08","lessonPage":29,"lessonPageTitle":"Apriori algorithm"},{"id":"s5-q298","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":298,"level":"真题同型 · 500 题强化","question":"How is the confidence of a rule X → Y defined?","questionZh":"规则 X → Y 的置信度如何定义？","options":["support(X ∪ Y) / support(X)","support(X ∪ Y) / support(Y)","support(X ∪ Y)","support(X) × support(Y)"],"optionZh":["support(X ∪ Y) / support(X)","support(X ∪ Y) / support(Y)","support(X ∪ Y)","support(X) × support(Y)"],"answer":0,"explanation":"A 正确：置信度 = p(Y | X)，即包含 X 的交易中也包含 Y 的比例。C 是规则的支持度。B 是反过来的规则 Y → X 的置信度。","lessonId":"dsfb-08","lessonPage":30,"lessonPageTitle":"Apriori algorithm"},{"id":"s5-q299","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":299,"level":"真题同型 · 500 题强化","question":"In the lecture's 10-transaction database, beer appears in 6 transactions, diapers in 7, and both together in 4. What is the confidence of {diapers} → {beer}?","questionZh":"讲义的 10 笔交易中，beer 出现 6 次，diapers 出现 7 次，两者同时出现 4 次。规则 {diapers} → {beer} 的置信度是多少？","options":["4/6 ≈ 67%","4/10 = 40%","4/7 ≈ 57%","6/7 ≈ 86%"],"optionZh":["4/6 ≈ 67%","4/10 = 40%","4/7 ≈ 57%","6/7 ≈ 86%"],"answer":2,"explanation":"C 正确：置信度 = 同时出现次数 / 前件出现次数 = 4/7。A 是 {beer} → {diapers} 的置信度。B 是支持度。","lessonId":"dsfb-08","lessonPage":25,"lessonPageTitle":"Association analysis"},{"id":"s5-q300","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":300,"level":"真题同型 · 500 题强化","question":"Using beer (6/10), diapers (7/10) and both together (4/10), what is the lift of {diapers} → {beer}, and what does it indicate?","questionZh":"已知 beer 6/10、diapers 7/10、两者同时 4/10，规则 {diapers} → {beer} 的提升度是多少，说明什么？","options":["About 1.43, a complementary effect","About 0.95, a slight negative dependence (substitution)","Exactly 1, independence","About 0.57, strong complementarity"],"optionZh":["约 1.43，互补效应","约 0.95，轻微负相关（替代效应）","恰好为 1，独立","约 0.57，强互补"],"answer":1,"explanation":"B 正确：lift = 0.4 / (0.7 × 0.6) = 0.4 / 0.42 ≈ 0.95 < 1。虽然置信度有 57%，但比啤酒的基础购买率 60% 还低一点。D 的 0.57 是置信度，不是提升度。","lessonId":"dsfb-08","lessonPage":35,"lessonPageTitle":"Interestingness measure (a.k.a. lift)"},{"id":"s5-q301","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":301,"level":"真题同型 · 500 题强化","question":"For the rule Tea → Coffee, support is 20% and confidence 80%, while p(Coffee) = 90%. What does this tell us?","questionZh":"规则 Tea → Coffee 的支持度为 20%，置信度为 80%，而 p(Coffee) = 90%。这说明什么？","options":["Tea buyers are less likely to buy coffee than an average customer, despite the high confidence.","The rule is very strong and should be used for cross-selling.","Tea and coffee are complements.","The rule has lift 4."],"optionZh":["尽管置信度很高，买茶的顾客买咖啡的可能性反而低于平均水平。","这条规则很强，应该用来交叉销售。","茶和咖啡是互补品。","这条规则的提升度为 4。"],"answer":0,"explanation":"A 正确：lift = 0.8 / 0.9 ≈ 0.89 < 1，买茶的人买咖啡的概率（80%）低于全体顾客（90%），是替代效应。这说明只看置信度会被误导。","lessonId":"dsfb-08","lessonPage":34,"lessonPageTitle":"Interestingness measure (a.k.a. lift)"},{"id":"s5-q302","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":302,"level":"真题同型 · 500 题强化","question":"An association rule has lift 1.6. What does this indicate?","questionZh":"某关联规则的提升度为 1.6，这说明什么？","options":["A substitution effect","Independence between antecedent and consequent","A complementary effect: buying X makes buying Y more likely","An error, since lift cannot exceed 1"],"optionZh":["替代效应","前件与后件独立","互补效应：买 X 让买 Y 的可能性更大","计算错误，提升度不能超过 1"],"answer":2,"explanation":"C 正确：lift > 1 表示正相关（互补），lift < 1 表示负相关（替代），lift = 1 表示独立。提升度可以大于 1，D 错。","lessonId":"dsfb-08","lessonPage":35,"lessonPageTitle":"Interestingness measure (a.k.a. lift)"},{"id":"s5-q303","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":303,"level":"真题同型 · 500 题强化","question":"In a database of 200 transactions, 50 contain bread, 80 contain butter, and 30 contain both. What is the lift of {bread} → {butter}?","questionZh":"200 笔交易中，50 笔含面包，80 笔含黄油，30 笔两者都有。规则 {bread} → {butter} 的提升度是多少？","options":["0.6","1.2","1.5","0.375"],"optionZh":["0.6","1.2","1.5","0.375"],"answer":2,"explanation":"C 正确：置信度 = 30/50 = 0.6；support(butter) = 80/200 = 0.4；lift = 0.6/0.4 = 1.5。等价地 0.15 / (0.25 × 0.4) = 1.5。A 是置信度。","lessonId":"dsfb-08","lessonPage":35,"lessonPageTitle":"Interestingness measure (a.k.a. lift)"},{"id":"s5-q304","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":304,"level":"真题同型 · 500 题强化","question":"Which statement about the Apriori algorithm is TRUE?","questionZh":"关于 Apriori 算法，哪项说法正确？","options":["It first finds all frequent itemsets above minsup, then derives rules with confidence above minconf.","It does not require any thresholds to be specified.","It searches through all 2ⁿ − 1 possible itemsets without pruning.","It generates rules first and then computes support."],"optionZh":["先找出支持度高于 minsup 的所有频繁项集，再从中推导置信度高于 minconf 的规则。","它不需要设定任何阈值。","它不加剪枝地搜索全部 2ⁿ − 1 个可能项集。","它先生成规则再计算支持度。"],"answer":0,"explanation":"A 正确：讲义第 31 页的两步法。B 错：minsup 和 minconf 要事先设定。C 错：Apriori 的意义正是剪枝，100 个商品就有约 1.27 × 10³⁰ 种组合，不可能穷举。","lessonId":"dsfb-08","lessonPage":31,"lessonPageTitle":"Apriori algorithm"},{"id":"s5-q305","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":305,"level":"真题同型 · 500 题强化","question":"The Apriori pruning principle states that:","questionZh":"Apriori 的剪枝原则是：","options":["If an itemset is frequent, all its supersets are also frequent.","If an itemset is infrequent, all its supersets are also infrequent.","Only itemsets of size 1 can be frequent.","Infrequent itemsets can become frequent when items are added."],"optionZh":["如果一个项集频繁，它所有的超集也频繁。","如果一个项集不频繁，它所有的超集也不频繁。","只有大小为 1 的项集可能频繁。","加入更多商品后，不频繁的项集可能变频繁。"],"answer":1,"explanation":"B 正确：一个超集出现的次数不可能多于它的任何子集。所以 {1, 2} 不频繁，{1, 2, 3} 也一定不频繁，可以直接剪掉。A 是常见的反向错误（真题第 22 题也考过）。","lessonId":"dsfb-08","lessonPage":32,"lessonPageTitle":"Apriori algorithm"},{"id":"s5-q306","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":306,"level":"真题同型 · 500 题强化","question":"Database: TID 100 {1,3,4}, 200 {2,3,5}, 300 {1,2,3,5}, 400 {2,5}; minsup = 50%. Which itemset is in L3 (frequent 3-itemsets)?","questionZh":"数据库：TID 100 {1,3,4}，200 {2,3,5}，300 {1,2,3,5}，400 {2,5}；minsup = 50%。哪个项集属于 L3（频繁 3 项集）？","options":["{1, 2, 3}","{1, 3, 5}","{2, 3, 4}","{2, 3, 5}"],"optionZh":["{1, 2, 3}","{1, 3, 5}","{2, 3, 4}","{2, 3, 5}"],"answer":3,"explanation":"D 正确：{2,3,5} 出现在 200 和 300 两笔交易中，支持度 2/4 = 50%。A 被剪掉了，因为子集 {1,2} 只出现 1 次，不频繁。{4} 本身只出现 1 次，C 也不可能。","lessonId":"dsfb-08","lessonPage":32,"lessonPageTitle":"Apriori algorithm"},{"id":"s5-q307","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":307,"level":"真题同型 · 500 题强化","question":"In the same database (TID 100 {1,3,4}, 200 {2,3,5}, 300 {1,2,3,5}, 400 {2,5}), what is the confidence of the rule {5} → {2, 3}?","questionZh":"同一数据库（TID 100 {1,3,4}，200 {2,3,5}，300 {1,2,3,5}，400 {2,5}）中，规则 {5} → {2, 3} 的置信度是多少？","options":["2/3 ≈ 67%","100%","50%","3/4 = 75%"],"optionZh":["2/3 ≈ 67%","100%","50%","3/4 = 75%"],"answer":0,"explanation":"A 正确：{5} 出现在 200、300、400 三笔交易中，其中 {2,3,5} 同时出现在 200、300 两笔，置信度 = 2/3。反过来 {2,3} → {5} 的置信度是 2/2 = 100%。","lessonId":"dsfb-08","lessonPage":32,"lessonPageTitle":"Apriori algorithm"},{"id":"s5-q308","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":308,"level":"真题同型 · 500 题强化","question":"From the frequent itemset {beer, baby food, diapers}, how many candidate association rules (with non-empty antecedent and consequent) can be generated?","questionZh":"从频繁项集 {beer, baby food, diapers} 中，能生成多少条候选关联规则（前件、后件都非空）？","options":["3","8","6","9"],"optionZh":["3","8","6","9"],"answer":2,"explanation":"C 正确：三个元素的非空真子集有 2³ − 2 = 6 个，每个子集 s 生成一条规则 s → l − s。讲义第 33 页列出了这 6 条，再保留置信度高于 minconf 的。","lessonId":"dsfb-08","lessonPage":33,"lessonPageTitle":"Apriori algorithm"},{"id":"s5-q309","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":309,"level":"真题同型 · 500 题强化","question":"A supermarket finds the rule {baby food, diapers} → {beer}. Which action is NOT among the options discussed in the lecture?","questionZh":"超市发现规则 {baby food, diapers} → {beer}。以下哪个行动不在讲义讨论的选项中？","options":["Put the products closer together in the store.","Put them far apart so customers walk past other products.","Package them together with a poorly selling item.","Train a neural network to predict the price of beer."],"optionZh":["把这些商品在店里放得更近。","把它们放得很远，让顾客路过其他商品。","把它们和一件滞销商品打包。","训练神经网络预测啤酒价格。"],"answer":3,"explanation":"D 不在其中：讲义第 36 页讨论的是摆放位置、打包、调价、不要一起做广告等营销行动。规则本身不说明该怎么做，需要结合业务判断。","lessonId":"dsfb-08","lessonPage":36,"lessonPageTitle":"Cross-selling and Market Basket Analysis"},{"id":"s5-q310","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":310,"level":"真题同型 · 500 题强化","question":"What are multilevel association rules?","questionZh":"什么是多层次关联规则？","options":["Rules mined at different concept levels of a product taxonomy, e.g., \"Chocolate and Milk → Beer\".","Rules with more than two items in the consequent.","Rules mined on several databases.","Rules with a confidence above 100%."],"optionZh":["在商品分类体系的不同概念层次上挖掘的规则，例如“巧克力和牛奶 → 啤酒”。","后件包含两个以上商品的规则。","在多个数据库上挖掘的规则。","置信度超过 100% 的规则。"],"answer":0,"explanation":"A 正确：例如“草莓牛奶”和“巧克力牛奶”单独都不频繁，但上升到“牛奶”层面就可能频繁。做法是在交易中加入所有上层类别。D 不可能：置信度最多 100%。","lessonId":"dsfb-08","lessonPage":37,"lessonPageTitle":"Extension: Multilevel association rules"},{"id":"s5-q311","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":311,"level":"真题同型 · 500 题强化","question":"Which statement about sequences versus sets is TRUE?","questionZh":"关于序列与集合，哪项说法正确？","options":["Sets are ordered and items can appear multiple times.","The sequence <{A}, {B}> is the same as <{B}, {A}>.","The sequence <{A}, {B}> is the same as <{A, B}>.","Sequences are ordered and items can appear multiple times."],"optionZh":["集合有序，元素可以出现多次。","序列 <{A}, {B}> 与 <{B}, {A}> 相同。","序列 <{A}, {B}> 与 <{A, B}> 相同。","序列有序，元素可以出现多次。"],"answer":3,"explanation":"D 正确：讲义第 41 页：集合无序、每个元素最多出现一次；序列有序、元素可重复。<{A},{B}> 表示先 A 后 B，<{A,B}> 表示同时出现，三者都不同。","lessonId":"dsfb-08","lessonPage":41,"lessonPageTitle":"Sequence analysis"},{"id":"s5-q312","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":312,"level":"真题同型 · 500 题强化","question":"Which customer sequence contains <{milk}, {bread}> as a subsequence?","questionZh":"哪条客户序列包含子序列 <{milk}, {bread}>？","options":["<{bread, beer}, {cheese, wine}>","<{milk, bread, cheese}, {spaghetti}>","<{milk}, {bread}, {cheese, wine}, {spaghetti}>","<{cheese, wine, spaghetti}>"],"optionZh":["<{bread, beer}, {cheese, wine}>","<{milk, bread, cheese}, {spaghetti}>","<{milk}, {bread}, {cheese, wine}, {spaghetti}>","<{cheese, wine, spaghetti}>"],"answer":2,"explanation":"C 正确：milk 在第 1 个元素，bread 在之后的第 2 个元素，满足先后顺序。B 中 milk 和 bread 在同一个元素里（同时购买），不构成“先 milk 后 bread”。","lessonId":"dsfb-08","lessonPage":42,"lessonPageTitle":"id Sequence <{milk}, {bread}> subsequence?"},{"id":"s5-q313","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":313,"level":"真题同型 · 500 题强化","question":"Is <{a}, {b, c}> a subsequence of <{a, d}, {e}, {b, c, f}>?","questionZh":"<{a}, {b, c}> 是不是 <{a, d}, {e}, {b, c, f}> 的子序列？","options":["Yes, because {a} ⊆ {a, d} and {b, c} ⊆ {b, c, f}, in that order.","No, because the element {e} is in between.","No, because {a, d} contains an extra item.","No, because the lengths differ."],"optionZh":["是，因为 {a} ⊆ {a, d}，{b, c} ⊆ {b, c, f}，且顺序正确。","不是，因为中间隔着 {e}。","不是，因为 {a, d} 多了一个元素。","不是，因为长度不同。"],"answer":0,"explanation":"A 正确：子序列的每个元素只需是原序列中某个更靠后元素的子集，中间可以跳过其他元素（B 错），元素里也可以有多余的项（C 错）。","lessonId":"dsfb-08","lessonPage":42,"lessonPageTitle":"id Sequence <{milk}, {bread}> subsequence?"},{"id":"s5-q314","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":314,"level":"真题同型 · 500 题强化","question":"Is <{x}, {x}> a subsequence of <{x, y}, {z}, {x}>?","questionZh":"<{x}, {x}> 是不是 <{x, y}, {z}, {x}> 的子序列？","options":["No, because items cannot appear twice in a sequence.","Yes, because x appears in the first and in the third element.","No, because {z} breaks the pattern.","Yes, but only if y is removed."],"optionZh":["不是，因为同一元素不能在序列中出现两次。","是，因为 x 出现在第 1 个和第 3 个元素中。","不是，因为 {z} 打断了模式。","是，但前提是删除 y。"],"answer":1,"explanation":"B 正确：序列中元素可以重复出现。第一个 {x} ⊆ {x, y}，第二个 {x} ⊆ {x}，位置递增。A 把集合的规则错用到了序列上。","lessonId":"dsfb-08","lessonPage":42,"lessonPageTitle":"id Sequence <{milk}, {bread}> subsequence?"},{"id":"s5-q315","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":315,"level":"真题同型 · 500 题强化","question":"In sequential pattern mining, frequent 2-sequences <{A}, {B}> and <{A}, {C}> are expanded into which candidates?","questionZh":"在序列模式挖掘中，频繁 2-序列 <{A}, {B}> 和 <{A}, {C}> 会扩展成哪些候选？","options":["Only {A, B, C}","<{A}, {B}, {C}>, <{A}, {C}, {B}> and <{A}, {B, C}>","Only <{A}, {B}, {C}>","<{B}, {A}> and <{C}, {A}>"],"optionZh":["只有 {A, B, C}","<{A}, {B}, {C}>、<{A}, {C}, {B}> 和 <{A}, {B, C}>","只有 <{A}, {B}, {C}>","<{B}, {A}> 和 <{C}, {A}>"],"answer":1,"explanation":"B 正确：讲义第 43 页：普通 Apriori 只会扩展成同一个集合 {A, B, C}，但序列有先后之分，B 和 C 可以先后出现（两种顺序）或同时出现，所以有三个候选。","lessonId":"dsfb-08","lessonPage":43,"lessonPageTitle":"Sequence analysis"},{"id":"s5-q316","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":316,"level":"真题同型 · 500 题强化","question":"Which application is a typical use of sequence analysis rather than association analysis?","questionZh":"以下哪项是序列分析（而非关联分析）的典型应用？","options":["Finding products often bought together in one basket","Customer journey analysis: a customer buys X, then Y, then Z","Segmenting customers by income","Predicting default probability"],"optionZh":["找出常在同一购物篮中一起购买的商品","客户旅程分析：先买 X，再买 Y，然后买 Z","按收入对客户分群","预测违约概率"],"answer":1,"explanation":"B 正确：序列分析在关联分析的基础上加入了时间维度。A 是购物篮（关联）分析，C 是聚类，D 是分类。","lessonId":"dsfb-08","lessonPage":40,"lessonPageTitle":"Sequence analysis"},{"id":"s5-q317","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":317,"level":"真题同型 · 500 题强化","question":"How is an autoencoder trained?","questionZh":"自编码器如何训练？","options":["By minimizing the reconstruction error between the input x and its reconstruction x̂.","By maximizing the AUC on a labelled target.","By minimizing the within-cluster sum of squares.","By maximizing the support of frequent itemsets."],"optionZh":["最小化输入 x 与重建结果 x̂ 之间的重建误差。","最大化带标签目标的 AUC。","最小化簇内平方和。","最大化频繁项集的支持度。"],"answer":0,"explanation":"A 正确：编码器把输入压缩成低维表示，解码器再还原，网络学习让还原尽量接近原输入。输入本身就是“目标”，不需要外部标签。","lessonId":"dsfb-08","lessonPage":48,"lessonPageTitle":"Autoencoder"},{"id":"s5-q318","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":318,"level":"真题同型 · 500 题强化","question":"How can an autoencoder be used for fraud detection?","questionZh":"自编码器如何用于欺诈检测？","options":["By clustering transactions with k-means.","By flagging transactions with a large reconstruction error as anomalies.","By predicting the transaction amount.","By computing association rules between fraudsters."],"optionZh":["用 k-means 对交易聚类。","把重建误差大的交易标记为异常。","预测交易金额。","计算欺诈者之间的关联规则。"],"answer":1,"explanation":"B 正确：在（以正常交易为主的）数据上训练后，自编码器擅长还原正常模式。与正常模式差别很大的交易还原不好，误差大，就可能是异常。","lessonId":"dsfb-08","lessonPage":51,"lessonPageTitle":"Autoencoder"},{"id":"s5-q319","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":319,"level":"真题同型 · 500 题强化","question":"What is the latent space of an autoencoder?","questionZh":"自编码器的潜在空间（latent space）是什么？","options":["The set of hidden variables that capture the most essential information needed to reconstruct the input","The output layer containing class probabilities","The training data set","The set of all outliers"],"optionZh":["一组隐藏变量，捕捉重建输入所需的最本质信息","包含类别概率的输出层","训练数据集","所有异常值的集合"],"answer":0,"explanation":"A 正确：讲义第 50 页：潜在变量不能直接观察，却决定了数据的分布。潜在空间是压缩后的表示，可用于特征提取、降维和去噪。","lessonId":"dsfb-08","lessonPage":50,"lessonPageTitle":"Autoencoder"},{"id":"s5-q320","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":320,"level":"真题同型 · 500 题强化","question":"According to the lecture, which equality holds?","questionZh":"根据讲义，以下哪个等式成立？","options":["Descriptive analytics = Business intelligence","Descriptive analytics = Descriptive statistics","Descriptive analytics = Visual analytics","Descriptive analytics = Unsupervised learning"],"optionZh":["描述性分析 = 商业智能","描述性分析 = 描述性统计","描述性分析 = 可视化分析","描述性分析 = 无监督学习"],"answer":3,"explanation":"D 正确：讲义第 59 页只对“= 无监督学习”打了 YES，其余三个都是 NO。BI 偏向报表和仪表盘，描述性统计只是汇总样本，可视化分析是展示方法。","lessonId":"dsfb-08","lessonPage":59,"lessonPageTitle":"Terminology!"},{"id":"s5-q321","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":321,"level":"真题同型 · 500 题强化","question":"Why are descriptive statistics such as the mean NOT considered unsupervised learning methods?","questionZh":"为什么均值等描述性统计不算无监督学习方法？","options":["Because they require a target variable.","Because they summarize a sample but do not learn a function f that can be applied to new instances.","Because they are too complex.","Because they are only used in dashboards."],"optionZh":["因为它们需要目标变量。","因为它们只汇总样本，并不学习一个能应用到新实例上的函数 f。","因为它们太复杂。","因为它们只用于仪表盘。"],"answer":1,"explanation":"B 正确：讲义第 62 页：聚类学到的模型可以把新客户分到某个簇，但均值只是对已有数据的概括，无法对新实例输出 Ŷ。","lessonId":"dsfb-08","lessonPage":62,"lessonPageTitle":"Descriptive analytics"},{"id":"s5-q322","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 8: Clustering, association and sequence rules","number":322,"level":"真题同型 · 500 题强化","question":"How can descriptive analytics serve as a starting point towards predictive analytics, e.g., in fraud detection?","questionZh":"描述性分析如何作为通往预测性分析的起点，例如在欺诈检测中？","options":["When no labelled instances are available yet, descriptive methods help understand the data and build data readiness.","Descriptive methods always outperform predictive ones.","Descriptive analytics replaces the need for labels permanently.","Descriptive analytics is only used after deployment."],"optionZh":["当还没有带标签的实例时，描述性方法帮助理解数据、建立数据准备度。","描述性方法总是优于预测性方法。","描述性分析永远取代对标签的需要。","描述性分析只在部署后使用。"],"answer":0,"explanation":"A 正确：讲义第 64 页：欺诈检测初期往往没有标签，先用聚类或异常检测发现可疑案例，调查后得到标签，再建立预测模型。","lessonId":"dsfb-08","lessonPage":64,"lessonPageTitle":"Descriptive analytics"},{"id":"s5-q323","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":323,"level":"真题同型 · 500 题强化","question":"A telecom company targets customers with a retention offer. Which customers are \"Sleeping Dogs\"?","questionZh":"电信公司向客户发送挽留优惠。哪类客户是“Sleeping Dogs（睡狗）”？","options":["Customers who stay whether or not they are targeted.","Customers who churn whether or not they are targeted.","Customers who churn only if they are not targeted.","Customers who churn only if they are targeted."],"optionZh":["无论是否被联系都不会流失的客户。","无论是否被联系都会流失的客户。","只有不被联系时才会流失的客户。","只有被联系时才会流失的客户。"],"answer":3,"explanation":"D 正确：睡狗本来不打算走，联系反而“吵醒”了他们，导致流失。A 是 Sure things，B 是 Lost causes，C 是 Persuadables。","lessonId":"dsfb-09","lessonPage":10,"lessonPageTitle":"Two issues with traditional predictive modeling solution design:"},{"id":"s5-q324","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":324,"level":"真题同型 · 500 题强化","question":"Which customer group should a retention campaign ideally target?","questionZh":"挽留活动最理想的目标客户是哪一类？","options":["Persuadables","Sure Things","Lost Causes","Sleeping Dogs"],"optionZh":["Persuadables（可说服者）","Sure Things（铁定留下者）","Lost Causes（无可挽回者）","Sleeping Dogs（睡狗）"],"answer":0,"explanation":"A 正确：只有可说服者的结果会因为被联系而变好（不联系会走，联系就留下）。联系 Sure things 和 Lost causes 白花钱，联系 Sleeping dogs 还会适得其反。","lessonId":"dsfb-09","lessonPage":10,"lessonPageTitle":"Two issues with traditional predictive modeling solution design:"},{"id":"s5-q325","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":325,"level":"真题同型 · 500 题强化","question":"Which statement describes the first issue with traditional churn prediction models highlighted in Chapter 9?","questionZh":"第 9 章指出的传统流失预测模型的第一个问题是什么？","options":["They have too many input variables.","They cannot handle imbalanced data.","They are not accurate enough in terms of AUC.","They predict what will happen, instead of what will happen depending on what we do."],"optionZh":["输入变量太多。","它们无法处理不平衡数据。","它们的 AUC 不够高。","它们预测“会发生什么”，而不是“取决于我们做什么会发生什么”。"],"answer":3,"explanation":"D 正确：讲义第 10 页：问题 1 是目标变量不对。我们关心的是干预的效果，而不是客户会不会流失。一个预测很准的流失模型可能挑出一堆 Lost causes。","lessonId":"dsfb-09","lessonPage":10,"lessonPageTitle":"Two issues with traditional predictive modeling solution design:"},{"id":"s5-q326","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":326,"level":"真题同型 · 500 题强化","question":"Why is it problematic to train a new churn model on outcomes recorded after a retention campaign that was targeted using an earlier model?","questionZh":"用早期模型挑选客户做挽留活动后，再用活动后记录的结果训练新流失模型，为什么有问题？","options":["Because the recorded outcomes are influenced by the campaign, creating a feedback loop and biased data.","Because the new model will have too few observations.","Because churn is not observable after a campaign.","Because the earlier model was a logistic regression."],"optionZh":["因为记录的结果受到活动影响，形成反馈回路，数据有偏差。","因为新模型的观测太少。","因为活动后无法观察到流失。","因为早期模型是逻辑回归。"],"answer":0,"explanation":"A 正确：被联系的客户没有流失，可能是活动起了作用（Persuadable），模型却学成“这类客户不会走”。讲义第 12 页称之为反馈回路，违反了独立同分布假设。","lessonId":"dsfb-09","lessonPage":12,"lessonPageTitle":"Two issues with traditional predictive modeling solution design:"},{"id":"s5-q327","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":327,"level":"真题同型 · 500 题强化","question":"According to the lecture, how should the feedback loop problem be tackled?","questionZh":"讲义认为应如何处理反馈回路问题？","options":["By removing all targeted customers from the training data.","By only using data from before any campaign was run.","By incorporating information on previous interventions as an independent variable in the model.","By increasing the number of trees in a random forest."],"optionZh":["从训练数据中删除所有被联系过的客户。","只使用任何活动之前的数据。","把以往干预的信息作为自变量放进模型。","增加随机森林中树的数量。"],"answer":2,"explanation":"C 正确：讲义第 15 页：要预测“以干预为条件的结果”，即干预的因果效应，所以干预本身要作为输入。A、B 是绕开问题而不是解决问题，还会丢失信息。","lessonId":"dsfb-09","lessonPage":15,"lessonPageTitle":"Issue 1: we should predict the outcome conditional on the intervention!"},{"id":"s5-q328","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":328,"level":"真题同型 · 500 题强化","question":"Which statement about the two schools of causal inference is TRUE?","questionZh":"关于因果推断的两大学派，哪项说法正确？","options":["The DAG framework of Pearl focuses on causal effect learning of a treatment we control.","The potential outcomes (PO) framework of Rubin focuses on modelling the effect of a treatment on an outcome, typically a treatment that we control.","Both schools are only concerned with causal discovery.","Causal machine learning differs from causal inference in WHAT is studied."],"optionZh":["Pearl 的 DAG 框架专注于学习我们可控制的处理的因果效应。","Rubin 的潜在结果（PO）框架专注于建模处理对结果的效应，处理通常是我们能控制的。","两个学派都只关心因果发现。","因果机器学习与因果推断的区别在于研究“什么”。"],"answer":1,"explanation":"B 正确：PO 框架“to predict”，估计 ITE/CATE/uplift。A 把两派弄反了：DAG 框架偏“to explain”，做因果发现，原因不一定可控。D 错：因果机器学习的区别在于 HOW（用 ML 方法），DAG 与 PO 的区别才在于 WHAT。","lessonId":"dsfb-09","lessonPage":23,"lessonPageTitle":"Causal inference"},{"id":"s5-q329","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":329,"level":"真题同型 · 500 题强化","question":"In the airport DAG (Price := −3·Distance + ε; Flights := −10·Distance − 5·Price + ε), what is the total causal effect of one extra unit of distance on flights?","questionZh":"在机场 DAG 中（Price := −3·Distance + ε；Flights := −10·Distance − 5·Price + ε），距离每增加一个单位，对航班需求的总因果效应是多少？","options":["−10","+15","−25","+5"],"optionZh":["−10","+15","−25","+5"],"answer":3,"explanation":"D 正确：总效应 = 直接效应 + 间接效应 = −10 + (−3) × (−5) = −10 + 15 = +5。A 只是直接效应，B 只是经由价格的间接效应。","lessonId":"dsfb-09","lessonPage":24,"lessonPageTitle":"Causal inference: DAG"},{"id":"s5-q330","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":330,"level":"真题同型 · 500 题强化","question":"In the same airport DAG, which statement is FALSE?","questionZh":"在同一个机场 DAG 中，哪项说法是错误的？","options":["Holding price fixed, more distance reduces demand.","Holding distance fixed, a higher price reduces demand.","Distance affects demand only directly, not through price.","Remote airports charge lower prices."],"optionZh":["价格固定时，距离越远需求越少。","距离固定时，价格越高需求越少。","距离只直接影响需求，不经过价格。","偏远机场的价格更低。"],"answer":2,"explanation":"C 错误：图中有 Distance → Price → Flights 这条路径，距离还通过价格间接影响需求。D 正确：Price 对 Distance 的系数是 −3。","lessonId":"dsfb-09","lessonPage":24,"lessonPageTitle":"Causal inference: DAG"},{"id":"s5-q331","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":331,"level":"真题同型 · 500 题强化","question":"In a DAG, Distance → Price (coefficient −2), Price → Sales (coefficient −4), and Distance → Sales (coefficient −3). What is the total effect of Distance on Sales?","questionZh":"某 DAG 中 Distance → Price（系数 −2），Price → Sales（系数 −4），Distance → Sales（系数 −3）。距离对销量的总效应是多少？","options":["−9","−3","+5","+8"],"optionZh":["−9","−3","+5","+8"],"answer":2,"explanation":"C 正确：间接效应 = (−2) × (−4) = +8，直接效应 = −3，总效应 = +8 − 3 = +5。D 只算了间接效应，B 只算了直接效应。","lessonId":"dsfb-09","lessonPage":24,"lessonPageTitle":"Causal inference: DAG"},{"id":"s5-q332","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":332,"level":"真题同型 · 500 题强化","question":"The predict-then-optimize approach for uplift modeling consists of:","questionZh":"用于 uplift 建模的“先预测再优化”方法包括：","options":["Predicting churn probabilities and contacting the highest-risk customers.","Running an RCT on every customer.","Optimizing the hyperparameters, then predicting the outcome.","Predicting the individual treatment effect, then selecting instances to treat to maximize the positive outcome rate."],"optionZh":["预测流失概率，联系风险最高的客户。","对每位客户都做随机对照实验。","先优化超参数，再预测结果。","预测个体处理效应，再选择要处理的实例，以最大化正向结果率。"],"answer":3,"explanation":"D 正确：讲义第 26 页：步骤 1 在个体层面预测处理的净效应（ITE）；步骤 2 根据预测优化处理对象的选择。A 是传统流失预测的做法。","lessonId":"dsfb-09","lessonPage":26,"lessonPageTitle":"Causal inference: PO"},{"id":"s5-q333","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":333,"level":"真题同型 · 500 题强化","question":"With Y = 1 meaning \"no churn\", what is the ITE = Y(T=1) − Y(T=0) of a Sleeping Dog?","questionZh":"若 Y = 1 表示“不流失”，Sleeping Dog 的 ITE = Y(T=1) − Y(T=0) 是多少？","options":["−1","0","+1","It cannot be defined."],"optionZh":["−1","0","+1","无法定义。"],"answer":0,"explanation":"A 正确：睡狗被联系会流失（Y(T=1) = 0），不联系不流失（Y(T=0) = 1），ITE = 0 − 1 = −1。Persuadables 是 +1，Sure things 和 Lost causes 都是 0。","lessonId":"dsfb-09","lessonPage":29,"lessonPageTitle":"Sleeping"},{"id":"s5-q334","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":334,"level":"真题同型 · 500 题强化","question":"With Y = 1 meaning \"no churn\", which groups have an ITE equal to 0?","questionZh":"若 Y = 1 表示“不流失”，哪些群体的 ITE 等于 0？","options":["Persuadables and Sleeping Dogs","Lost Causes and Persuadables","Sure Things and Sleeping Dogs","Sure Things and Lost Causes"],"optionZh":["Persuadables 和 Sleeping Dogs","Lost Causes 和 Persuadables","Sure Things 和 Sleeping Dogs","Sure Things 和 Lost Causes"],"answer":3,"explanation":"D 正确：这两类人不管是否被联系，结果都一样（一个总留下，一个总流失），处理没有效果。","lessonId":"dsfb-09","lessonPage":29,"lessonPageTitle":"Sleeping"},{"id":"s5-q335","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":335,"level":"真题同型 · 500 题强化","question":"How is the Conditional Average Treatment Effect (CATE) defined with probabilistic estimates?","questionZh":"用概率估计时，条件平均处理效应（CATE）如何定义？","options":["P(Y=1 | X, T=1) − P(Y=1 | X, T=0)","P(Y=1 | X) − P(Y=0 | X)","P(T=1 | X) − P(T=0 | X)","The average outcome in the treatment group"],"optionZh":["P(Y=1 | X, T=1) − P(Y=1 | X, T=0)","P(Y=1 | X) − P(Y=0 | X)","P(T=1 | X) − P(T=0 | X)","处理组的平均结果"],"answer":0,"explanation":"A 正确：在给定特征 X 的前提下，比较“被处理”和“不被处理”时正向结果的概率差。C 是倾向得分（propensity）的差，不是处理效应。","lessonId":"dsfb-09","lessonPage":29,"lessonPageTitle":"Sleeping"},{"id":"s5-q336","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":336,"level":"真题同型 · 500 题强化","question":"Which statement about the Average Treatment Effect (ATE) is TRUE?","questionZh":"关于平均处理效应（ATE），哪项说法正确？","options":["It is the effect of the treatment for a single individual.","It is the average net effect of the treatment across the population, typically established with A/B tests or RCTs.","It can be measured directly for each customer.","It is always equal to the CATE of every subgroup."],"optionZh":["它是处理对单个个体的效应。","它是处理在整个总体上的平均净效应，通常通过 A/B 测试或随机对照实验确定。","它可以对每个客户直接测量。","它总是等于每个子群的 CATE。"],"answer":1,"explanation":"B 正确：A 是 ITE。C 错：个体的处理效应无法直接观察（因果推断的根本问题）。D 错：各子群的效应可以不同，甚至方向相反（辛普森悖论）。","lessonId":"dsfb-09","lessonPage":30,"lessonPageTitle":"Causal inference: PO"},{"id":"s5-q337","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":337,"level":"真题同型 · 500 题强化","question":"In a randomized experiment, 500 customers receive an offer and 125 respond; 500 do not receive it and 50 respond. What is the estimated ATE?","questionZh":"随机实验中，500 名客户收到优惠，125 人响应；500 名没收到，50 人响应。估计的 ATE 是多少？","options":["25%","35%","15%","75 customers"],"optionZh":["25%","35%","15%","75 名客户"],"answer":2,"explanation":"C 正确：ATE = 处理组响应率 − 对照组响应率 = 125/500 − 50/500 = 25% − 10% = 15%。A 只是处理组的响应率。","lessonId":"dsfb-09","lessonPage":30,"lessonPageTitle":"Causal inference: PO"},{"id":"s5-q338","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":338,"level":"真题同型 · 500 题强化","question":"In prescriptive analytics, what does T* = argmax(Y | X) express?","questionZh":"在规范性分析中，T* = argmax(Y | X) 表示什么？","options":["The treatment that maximizes the expected outcome given the characteristics X.","The maximum value of the outcome.","The probability of treatment given X.","The best model among several candidates."],"optionZh":["给定特征 X 时，使期望结果最大的处理。","结果的最大值。","给定 X 时接受处理的概率。","多个候选模型中最好的那个。"],"answer":0,"explanation":"A 正确：argmax 返回的是“取到最大值的那个自变量”，这里就是最优的处理（决策），而不是最大值本身（B）。","lessonId":"dsfb-09","lessonPage":33,"lessonPageTitle":"Prescriptive analytics"},{"id":"s5-q339","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":339,"level":"真题同型 · 500 题强化","question":"What distinguishes prescriptive analytics from descriptive and predictive analytics?","questionZh":"规范性分析与描述性、预测性分析的区别是什么？","options":["It uses more data.","It only uses deep learning.","It incorporates the decision in the analysis, which allows the decision to be optimized directly.","It does not require any model."],"optionZh":["它使用更多数据。","它只使用深度学习。","它把决策本身纳入分析，因此可以直接优化决策。","它不需要任何模型。"],"answer":2,"explanation":"C 正确：讲义第 34 页：描述性和预测性分析把决策留在分析之外，规范性分析把处理 T 放进模型 Y = f(X, T)，可以支持或自动化决策。","lessonId":"dsfb-09","lessonPage":34,"lessonPageTitle":"Differences with descriptive & predictive analytics?"},{"id":"s5-q340","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":340,"level":"真题同型 · 500 题强化","question":"Which of the following is NOT listed in the lecture as a reason why correlation does not imply causation?","questionZh":"以下哪项不是讲义列出的“相关不等于因果”的原因？","options":["Inversed causality","Hidden confounders","Spurious correlations","Overfitting"],"optionZh":["反向因果","隐藏混杂因子","伪相关","过拟合"],"answer":3,"explanation":"D 不是：过拟合是模型泛化问题。讲义第 38 页列出的是反向因果（如安德莱赫特的球迷例子）、隐藏混杂（如穿鞋睡觉的学生）和伪相关。","lessonId":"dsfb-09","lessonPage":38,"lessonPageTitle":"Challenges"},{"id":"s5-q341","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":341,"level":"真题同型 · 500 题强化","question":"Ice cream sales and shark attacks are positively correlated. What is the most likely explanation?","questionZh":"冰淇淋销量和鲨鱼袭击正相关，最可能的解释是什么？","options":["Eating ice cream attracts sharks.","The correlation must be a calculation error.","Shark attacks cause people to buy ice cream.","A hidden confounder such as hot weather drives both."],"optionZh":["吃冰淇淋会吸引鲨鱼。","这一定是计算错误。","鲨鱼袭击导致人们买冰淇淋。","炎热天气这类隐藏混杂因子同时推动了两者。"],"answer":3,"explanation":"D 正确：天热时人们既多买冰淇淋也多下海游泳。混杂因子会导致因果发现得出错误结论，也会让处理效应估计出错。","lessonId":"dsfb-09","lessonPage":39,"lessonPageTitle":"Case: Machine maintenance"},{"id":"s5-q342","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":342,"level":"真题同型 · 500 题强化","question":"In the machine maintenance case, older machines receive more maintenance and also fail more often. A naive analysis concludes that maintenance causes failures. What is the problem?","questionZh":"机器维护案例中，老机器维护更多，也更常故障。简单分析得出“维护导致故障”。问题在哪里？","options":["Machine age is a confounder that affects both maintenance and failures.","Maintenance has no effect on machines.","The sample is too small.","Failures should be measured in hours."],"optionZh":["机器年龄是同时影响维护和故障的混杂因子。","维护对机器没有任何影响。","样本太小。","故障应该按小时计量。"],"answer":0,"explanation":"A 正确：年龄同时决定了维护频率（处理分配）和故障率（结果），不控制年龄就会得出错误的因果结论，这就是混杂偏差。","lessonId":"dsfb-09","lessonPage":39,"lessonPageTitle":"Case: Machine maintenance"},{"id":"s5-q343","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":343,"level":"真题同型 · 500 题强化","question":"Which statement about Simpson's paradox is TRUE?","questionZh":"关于辛普森悖论，哪项说法正确？","options":["It only occurs in randomized controlled trials.","It proves that subgroup analysis is always wrong.","The average effect in the population can have the opposite sign of the effect within each subgroup.","It means that ATE always equals CATE."],"optionZh":["它只出现在随机对照实验中。","它证明子群分析总是错误的。","总体平均效应的方向可能与每个子群内部的效应方向相反。","它说明 ATE 总是等于 CATE。"],"answer":2,"explanation":"C 正确：讲义第 39 页：“Simpson’s paradox: ATE inverse of CATE”。通常由混杂因子导致各组样本构成不同。RCT 正是用来避免这种问题的。","lessonId":"dsfb-09","lessonPage":39,"lessonPageTitle":"Case: Machine maintenance"},{"id":"s5-q344","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":344,"level":"真题同型 · 500 题强化","question":"Why are randomized controlled trials (RCTs) the traditional solution for learning treatment effects?","questionZh":"为什么随机对照实验（RCT）是学习处理效应的传统方法？","options":["Because they are always cheap and quick.","Because random assignment makes treatment and control groups comparable \"all else equal\", isolating the treatment effect from confounders.","Because they allow observing both potential outcomes for each individual.","Because they do not require a control group."],"optionZh":["因为它们总是便宜又快。","因为随机分配让处理组和对照组“其他条件相同”，从而把处理效应与混杂因子分离。","因为它们能观察每个个体的两个潜在结果。","因为它们不需要对照组。"],"answer":1,"explanation":"B 正确。A 错：讲义第 67 页指出 RCT 可能昂贵、不道德、耗时甚至不可能。C 错：即使是 RCT，每个人也只被分到一组，只能观察一个潜在结果。","lessonId":"dsfb-09","lessonPage":40,"lessonPageTitle":"Solution (for treatment effect learning, not for causal discovery)"},{"id":"s5-q345","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":345,"level":"真题同型 · 500 题强化","question":"Campaign 2 has 500 treated customers (340 respond) and 500 control customers (50 respond). What is the naive ATE estimate?","questionZh":"活动 2 有 500 名处理组客户（340 人响应）和 500 名对照组客户（50 人响应）。朴素 ATE 估计是多少？","options":["40%","68%","10%","58%"],"optionZh":["40%","68%","10%","58%"],"answer":3,"explanation":"D 正确：68% − 10% = 58%。但讲义第 42–43 页揭示：这是观察数据，处理组男性占多数（男性响应更高），所以 58% 高估了真实的 40%。","lessonId":"dsfb-09","lessonPage":41,"lessonPageTitle":"Suppose you are given the following two data sets from two marketing campaigns:"},{"id":"s5-q346","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":346,"level":"真题同型 · 500 题强化","question":"In a population with 50% men and 50% women, the treatment response is 80% (men) and 20% (women), and the control response is 10% for both. What is the true population ATE?","questionZh":"总体中男女各 50%。处理组响应率男性 80%、女性 20%，对照组两者都是 10%。真实的总体 ATE 是多少？","options":["50%","58%","70%","40%"],"optionZh":["50%","58%","70%","40%"],"answer":3,"explanation":"D 正确：男性 ATE = 80% − 10% = 70%，女性 ATE = 20% − 10% = 10%，总体各占一半，ATE = (70% + 10%)/2 = 40%。C 只是男性的效应，B 是有偏的观察数据估计。","lessonId":"dsfb-09","lessonPage":43,"lessonPageTitle":"GROUP MEN Resp. % WOMEN Resp. %"},{"id":"s5-q347","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":347,"level":"真题同型 · 500 题强化","question":"An observational campaign data set has 400 men and 100 women in the treatment group, but 100 men and 400 women in the control group. Men respond much more to treatment. What happens to the naive ATE estimate?","questionZh":"某观察性活动数据中，处理组有 400 名男性、100 名女性，对照组有 100 名男性、400 名女性。男性对处理的响应高得多。朴素 ATE 估计会怎样？","options":["It is unbiased because both groups contain 500 customers.","It is biased downward.","It is biased upward because the treatment group over-represents the more responsive subgroup.","It is zero."],"optionZh":["无偏，因为两组都有 500 人。","偏低。","偏高，因为处理组过度代表了更容易响应的子群。","等于零。"],"answer":2,"explanation":"C 正确：两组人数相同不代表构成相同。处理组集中了高响应的男性，造成混杂偏差，讲义里的朴素估计 58% 高于真实的 40%。","lessonId":"dsfb-09","lessonPage":42,"lessonPageTitle":"GROUP # Resp. # Resp. %"},{"id":"s5-q348","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":348,"level":"真题同型 · 500 题强化","question":"Which assumption states that there are no hidden confounders, i.e., (Y(T=0), Y(T=1)) ⊥ T | X?","questionZh":"哪个假设表示没有隐藏混杂，即 (Y(T=0), Y(T=1)) ⊥ T | X？","options":["The overlap assumption","The ignorability (conditional independence) assumption","The i.i.d. assumption","The linearity assumption"],"optionZh":["重叠假设","可忽略性（条件独立）假设","独立同分布假设","线性假设"],"answer":1,"explanation":"B 正确：可忽略性假设要求决定处理分配的因素都作为协变量出现在数据中。A 重叠假设要求每类个体都有机会被分到任一组。","lessonId":"dsfb-09","lessonPage":48,"lessonPageTitle":"Challenges"},{"id":"s5-q349","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":349,"level":"真题同型 · 500 题强化","question":"In the machine maintenance data, there are no old machines with little maintenance and no new machines with a lot of maintenance. Which assumption is violated?","questionZh":"机器维护数据中，既没有“维护少的老机器”，也没有“维护多的新机器”。违反了哪个假设？","options":["The overlap (common support) assumption","The ignorability assumption","SUTVA","Normality of errors"],"optionZh":["重叠（共同支撑）假设","可忽略性假设","SUTVA","误差正态性"],"answer":0,"explanation":"A 正确：重叠假设要求 δ < P(T | X) < 1 − δ，即每类机器都有可能接受任意处理水平。某些组合完全没有观测，模型只能外推，效应估计不可靠。","lessonId":"dsfb-09","lessonPage":48,"lessonPageTitle":"Challenges"},{"id":"s5-q350","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":350,"level":"真题同型 · 500 题强化","question":"What is the \"fundamental problem of causal inference\"?","questionZh":"什么是“因果推断的根本问题”？","options":["Causal effects cannot be estimated with machine learning.","Treatment and control groups always differ in size.","For an individual, we can observe only one potential outcome, so the individual treatment effect is never observed.","Causal graphs always contain cycles."],"optionZh":["机器学习无法估计因果效应。","处理组与对照组的人数总是不同。","对一个个体只能观察到一个潜在结果，所以个体处理效应永远观察不到。","因果图总是包含环。"],"answer":2,"explanation":"C 正确：不能同时对同一个人既发优惠又不发优惠，所以无法知道某个客户是不是 Persuadable。这意味着我们要预测的目标变量（ITE）在数据中不存在。","lessonId":"dsfb-09","lessonPage":51,"lessonPageTitle":"Challenges"},{"id":"s5-q351","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":351,"level":"真题同型 · 500 题强化","question":"Why is evaluating an ITE (uplift) model difficult?","questionZh":"为什么评估 ITE（uplift）模型很困难？","options":["Because the observed ITE, which we would compare predictions with, is not available.","Because uplift models do not output numbers.","Because AUC is always 0.5 for uplift models.","Because ITE models can only be evaluated on training data."],"optionZh":["因为本该拿来与预测比较的真实 ITE 无法观察。","因为 uplift 模型不输出数值。","因为 uplift 模型的 AUC 总是 0.5。","因为 ITE 模型只能在训练集上评估。"],"answer":0,"explanation":"A 正确：评估需要“真实值 vs 预测值”，但真实 ITE 永远看不到。所以只能在群体层面比较相似客户（uplift 曲线、Qini），或用模拟数据计算 PEHE。","lessonId":"dsfb-09","lessonPage":52,"lessonPageTitle":"Challenges"},{"id":"s5-q352","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":352,"level":"真题同型 · 500 题强化","question":"According to the \"thoughts on methods\" slide, what is the essence of causal machine learning for treatment effect modeling?","questionZh":"根据“方法思考”那页讲义，用因果机器学习做处理效应建模的核心是什么？","options":["Solving the fundamental problem of causal inference.","Using as many layers as possible.","Maximizing AUC.","Handling assignment or confounding bias."],"optionZh":["解决因果推断的根本问题。","使用尽可能多的网络层。","最大化 AUC。","处理分配偏差或混杂偏差。"],"answer":3,"explanation":"D 正确：讲义第 70 页：核心在于处理分配/混杂偏差，而“因果推断的根本问题”更多是一个评估问题。","lessonId":"dsfb-09","lessonPage":70,"lessonPageTitle":"The essence of causal machine learning for treatment effect modeling is in"},{"id":"s5-q353","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":353,"level":"真题同型 · 500 题强化","question":"Which statement about meta-learners is TRUE?","questionZh":"关于元学习器（meta-learners），哪项说法正确？","options":["They can only be implemented with neural networks.","They are modelling strategies to estimate the CATE that can be implemented with any ML base learner.","The S-learner is always the most accurate.","They require observing both potential outcomes for each instance."],"optionZh":["它们只能用神经网络实现。","它们是估计 CATE 的建模策略，可以用任意机器学习基学习器实现。","S-learner 总是最准确。","它们要求观察到每个实例的两个潜在结果。"],"answer":1,"explanation":"B 正确：类似集成方法，meta-learner 是框架，基学习器可以是逻辑回归、随机森林、XGBoost 等。C 错：讲义说哪个合适取决于数据生成过程。","lessonId":"dsfb-09","lessonPage":57,"lessonPageTitle":"Meta-learners"},{"id":"s5-q354","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":354,"level":"真题同型 · 500 题强化","question":"How does the T-learner (two-model learner) estimate the treatment effect?","questionZh":"T-learner（双模型学习器）如何估计处理效应？","options":["It fits one model with the treatment as an input variable.","It transforms the outcome into a new binary label.","It fits separate models on the treatment group and the control group and takes the difference of their predictions.","It uses only the treatment group."],"optionZh":["拟合一个把处理作为输入变量的模型。","把结果变换成新的二元标签。","分别在处理组和对照组上拟合模型，取两者预测的差。","只使用处理组。"],"answer":2,"explanation":"C 正确：τ̂(x) = f_T(x) − f_C(x)。A 描述的是 S-learner，B 是转换结果法。","lessonId":"dsfb-09","lessonPage":58,"lessonPageTitle":"Two-model learner"},{"id":"s5-q355","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":355,"level":"真题同型 · 500 题强化","question":"In the S-learner Y = β0 + β1X + β2T + β3XT, what does including the interaction term XT allow?","questionZh":"在 S-learner Y = β0 + β1X + β2T + β3XT 中，加入交互项 XT 有什么作用？","options":["It allows the treatment effect to vary with X (heterogeneous effects).","It removes the need for a control group.","It forces the treatment effect to be zero.","It turns the model into a T-learner with two separate data sets."],"optionZh":["让处理效应可以随 X 变化（异质效应）。","不再需要对照组。","强制处理效应为 0。","把模型变成使用两个独立数据集的 T-learner。"],"answer":0,"explanation":"A 正确：没有交互项时 β2 就是对所有人相同的 ATE；加上 XT 后，处理效应 = β2 + β3X，随客户特征变化，即 CATE。","lessonId":"dsfb-09","lessonPage":59,"lessonPageTitle":"S – learner"},{"id":"s5-q356","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":356,"level":"真题同型 · 500 题强化","question":"In an S-learner without interaction terms, Y = β0 + β1X + β2T, what does β2 represent?","questionZh":"在不含交互项的 S-learner Y = β0 + β1X + β2T 中，β2 代表什么？","options":["The effect of X on Y","The baseline outcome","The estimated average treatment effect, identical for every individual","The individual treatment effect of each customer"],"optionZh":["X 对 Y 的效应","基线结果","估计的平均处理效应，对每个人都一样","每个客户各自的个体处理效应"],"answer":2,"explanation":"C 正确：T 从 0 变到 1，Y 增加 β2，与 X 无关，所以这个模型只能给出一个对所有人都相同的效应（ATE），灵活性有限。","lessonId":"dsfb-09","lessonPage":59,"lessonPageTitle":"S – learner"},{"id":"s5-q357","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":357,"level":"真题同型 · 500 题强化","question":"In the transformed outcome method, which observations receive the positive label y' = 1?","questionZh":"在转换结果法中，哪些观测被标记为正类 y' = 1？","options":["Treated responders and control responders","Treated non-responders and control responders","Treated responders and control non-responders","Only treated responders"],"optionZh":["处理组响应者和对照组响应者","处理组未响应者和对照组响应者","处理组响应者和对照组未响应者","只有处理组响应者"],"answer":2,"explanation":"C 正确：这两类观测“看起来像”Persuadables：处理后响应了，或者没处理就没响应。处理组未响应者和对照组响应者“看起来像”Sleeping dogs，标为 y' = 0。","lessonId":"dsfb-09","lessonPage":62,"lessonPageTitle":"Transformation of the outcome (y → y’):"},{"id":"s5-q358","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":358,"level":"真题同型 · 500 题强化","question":"In a marketing campaign, y = 1 means the customer responded. A customer in the control group responded (t = 0, y = 1). What is the transformed outcome y'?","questionZh":"结果变量是“响应”（y = 1 表示响应）。一位对照组客户响应了（t = 0，y = 1）。转换后的结果 y' 是多少？","options":["y' = 1","y' = −1","y' is undefined.","y' = 0"],"optionZh":["y' = 1","y' = −1","y' 无定义。","y' = 0"],"answer":3,"explanation":"D 正确：不处理也会响应，说明处理没有帮助（甚至可能反作用），这类观测和 Sleeping dogs 一致，所以 y' = 0。","lessonId":"dsfb-09","lessonPage":62,"lessonPageTitle":"Transformation of the outcome (y → y’):"},{"id":"s5-q359","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":359,"level":"真题同型 · 500 题强化","question":"Which statement about the TARNET architecture is TRUE?","questionZh":"关于 TARNET 架构，哪项说法正确？","options":["It uses completely separate networks without any shared layers.","It uses a shared base network and separate head networks for each treatment option.","It cannot be used with more than one treatment.","It updates all weights using every observation."],"optionZh":["它使用完全独立、没有任何共享层的网络。","它使用一个共享的基础网络，并为每个处理选项设置单独的头部网络。","它不能用于多于一种处理。","它用每个观测更新所有权重。"],"answer":1,"explanation":"B 正确：共享层学习通用表示，处理头和对照头分别学习各自的结果。D 错：处理组观测只更新共享层和处理头，对照组只更新共享层和对照头（部分更新）。C 错：可用于多处理。","lessonId":"dsfb-09","lessonPage":65,"lessonPageTitle":"Deep learning"},{"id":"s5-q360","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":360,"level":"真题同型 · 500 题强化","question":"In the clinical trial example, patients forwarded to new drug B were already in a worse state. What problem does this create when comparing E[Y|B] with E[Y|A]?","questionZh":"临床试验例子中，转去用新药 B 的病人本来病情就更重。比较 E[Y|B] 和 E[Y|A] 时会出现什么问题？","options":["Assignment (selection) bias: the two expectations are not computed over the same patient distribution.","The fundamental problem of causal inference is solved.","Drug B will appear better than it is.","No problem, since both drugs were observed."],"optionZh":["分配（选择）偏差：两个期望不是在相同的病人分布上计算的。","因果推断的根本问题被解决了。","药物 B 会显得比实际更好。","没有问题，因为两种药都被观察到了。"],"answer":0,"explanation":"A 正确：病情更重的人集中在 B 组，B 组结果天然更差，药 B 的效果会被低估（不是 C 的高估）。这就是需要“带平衡的深度学习”去纠正的分配偏差。","lessonId":"dsfb-09","lessonPage":67,"lessonPageTitle":"Obtaining RCT data may be costly, unethical, time-consuming, impossible"},{"id":"s5-q361","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":361,"level":"真题同型 · 500 题强化","question":"How does deep learning with balancing address assignment bias?","questionZh":"带平衡的深度学习如何处理分配偏差？","options":["By deleting treated observations until groups are equal in size.","By using accuracy as the loss function.","By increasing the learning rate.","By adding a penalty such as the Maximum Mean Discrepancy (MMD) between the representations of treated and control groups to the loss."],"optionZh":["删除处理组观测直到两组大小相同。","用准确率作为损失函数。","提高学习率。","在损失函数中加入处理组与对照组表示之间的分布距离惩罚，如最大均值差异（MMD）。"],"answer":3,"explanation":"D 正确：Loss = L_BCE + α·L_MMD。让隐藏层 h(X) 在处理组和对照组之间分布相近，相当于学习一个“去偏”的表示。α 是超参数。","lessonId":"dsfb-09","lessonPage":69,"lessonPageTitle":"Idea! Learn bias-free representation by minimizing"},{"id":"s5-q362","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":362,"level":"真题同型 · 500 题强化","question":"Which statement about evaluating CATE estimates is TRUE?","questionZh":"关于评估 CATE 估计，哪项说法正确？","options":["Standard classification measures can be applied to estimates for the assigned treatment, but this requires RCT data and is an indirect evaluation.","PEHE can always be computed on real-world business data.","CATE can be evaluated directly with accuracy.","CATE estimates cannot be evaluated at all."],"optionZh":["可以对“实际分配的处理”下的估计用标准分类指标评估，但这需要 RCT 数据，而且是间接评估。","PEHE 在真实业务数据上总能计算。","CATE 可以直接用准确率评估。","CATE 估计完全无法评估。"],"answer":0,"explanation":"A 正确。B 错：PEHE（异质效应估计精度，类似 RMSE）需要知道真实 ITE，只能用模拟或半模拟数据。D 太绝对：uplift 曲线、Qini 等都可以评估。","lessonId":"dsfb-09","lessonPage":73,"lessonPageTitle":"Evaluation"},{"id":"s5-q363","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":363,"level":"真题同型 · 500 题强化","question":"How is an uplift curve constructed?","questionZh":"如何构建 uplift 曲线？","options":["By plotting the true positive rate against the false positive rate.","By plotting the predicted probability against the actual outcome.","By ranking instances by predicted uplift and comparing the positive outcome rate of treated and control instances per segment (e.g., decile).","By plotting the training loss over epochs."],"optionZh":["绘制真阳性率对假阳性率的曲线。","绘制预测概率对实际结果的曲线。","按预测 uplift 对实例排序，在每个分段（如十分位）比较处理组与对照组的正向结果率。","绘制训练损失随轮次的变化。"],"answer":2,"explanation":"C 正确：既然个体效应看不到，就比较“相似”的群体：同一十分位里，处理组和对照组结果率的差就是这一段的 uplift。A 是 ROC 曲线。","lessonId":"dsfb-09","lessonPage":74,"lessonPageTitle":"Uplift curve"},{"id":"s5-q364","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":364,"level":"真题同型 · 500 题强化","question":"What does an uplift-by-decile curve of a good uplift model look like?","questionZh":"好的 uplift 模型的“按十分位 uplift”曲线是什么样？","options":["High uplift in the top deciles, decreasing towards the lower deciles (possibly negative at the bottom).","Flat across all deciles.","Increasing from the top to the bottom decile.","Zero in every decile."],"optionZh":["前几个十分位 uplift 高，往后逐渐降低（最后几组甚至为负）。","所有十分位都一样平。","从第一个十分位到最后一个逐渐升高。","每个十分位都为 0。"],"answer":0,"explanation":"A 正确：模型把 Persuadables 排在前面，把 Sleeping dogs 排在最后，所以 uplift 从高到低，底部可能为负。平的曲线（B）说明模型没有区分能力。","lessonId":"dsfb-09","lessonPage":76,"lessonPageTitle":"Visual evaluation approaches"},{"id":"s5-q365","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":365,"level":"真题同型 · 500 题强化","question":"What is the Qini measure?","questionZh":"Qini 指标是什么？","options":["The area under the ROC curve","The area under the uplift curve (AUUC)","The accuracy of the uplift model","The average treatment effect"],"optionZh":["ROC 曲线下面积","uplift 曲线下面积（AUUC）","uplift 模型的准确率","平均处理效应"],"answer":1,"explanation":"B 正确：讲义第 80 页：Qini = AUUC，注意与 AUC 区分。相关指标还有分位 uplift（在指定覆盖比例下获得多少 uplift）和 top-decile Qini。","lessonId":"dsfb-09","lessonPage":80,"lessonPageTitle":"Performance measures"},{"id":"s5-q366","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":366,"level":"真题同型 · 500 题强化","question":"In backtesting, the response rates are: model-selected treated 5.3%, model-selected control 1.2%, randomly-selected treated 2.1%, randomly-selected control 0.8%. What is the true lift attributable to the model?","questionZh":"回测中响应率为：模型选中的处理组 5.3%、模型选中的对照组 1.2%、随机选中的处理组 2.1%、随机选中的对照组 0.8%。模型带来的真实提升（true lift）是多少？","options":["4.1%","1.3%","3.2%","2.8%"],"optionZh":["4.1%","1.3%","3.2%","2.8%"],"answer":3,"explanation":"D 正确：模型组效应 = 5.3% − 1.2% = 4.1%；随机组（活动本身的基线效应）= 2.1% − 0.8% = 1.3%；真实提升 = 4.1% − 1.3% = 2.8%。A 混入了活动本身的效应。","lessonId":"dsfb-09","lessonPage":83,"lessonPageTitle":"Treatment Group Control Group Treatment - Control"},{"id":"s5-q367","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":367,"level":"真题同型 · 500 题强化","question":"In the churn case, an uplift model wins on cumulative uplift while a churn prediction model wins on predictive power. Why is the churn rate lower in the top deciles of the uplift model?","questionZh":"流失案例中，uplift 模型在累积 uplift 上胜出，流失预测模型在预测力上胜出。为什么 uplift 模型前几个十分位的流失率反而更低？","options":["Because the uplift model is badly calibrated.","Because the data set was too small.","Because the top deciles contain only sleeping dogs.","Because uplift models identify persuadables rather than predicting churners."],"optionZh":["因为 uplift 模型校准很差。","因为数据集太小。","因为前几个十分位全是睡狗。","因为 uplift 模型找的是可说服者，而不是预测谁会流失。"],"answer":3,"explanation":"D 正确：讲义第 90 页：uplift 模型识别的是“能被说服的人”，不一定是流失风险最高的人（那些可能是 Lost causes），但它带来的流失率下降（uplift）显著更高。","lessonId":"dsfb-09","lessonPage":90,"lessonPageTitle":"Case: customer churn"},{"id":"s5-q368","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":368,"level":"真题同型 · 500 题强化","question":"A campaign targets a group with 20% persuadables and 20% sleeping dogs (the rest have ITE 0). What does the lecture warn about this situation?","questionZh":"某活动的目标群体中有 20% 可说服者和 20% 睡狗（其余人 ITE 为 0）。讲义对这种情况有什么提醒？","options":["The ATE is 40%, so the campaign is very effective.","The ATE is 0%, even though the campaign has strong effects on 40% of the group; aggregate measures may be misleading.","The ATE is −20%.","Sleeping dogs cannot exist in practice."],"optionZh":["ATE 为 40%，活动非常有效。","尽管活动对 40% 的人有强烈效果，ATE 却是 0%，汇总指标可能具有误导性。","ATE 为 −20%。","现实中不存在睡狗。"],"answer":1,"explanation":"B 正确：+20% 和 −20% 抵消，平均效应为 0。讲义建议“折磨结果而不是折磨数据”：画曲线，看汇总指标下面隐藏的东西，并且只联系可说服者。","lessonId":"dsfb-09","lessonPage":90,"lessonPageTitle":"Case: customer churn"},{"id":"s5-q369","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":369,"level":"真题同型 · 500 题强化","question":"Which approaches does the lecture mention for integrating a virtuous feedback loop in model deployment, balancing exploration and exploitation?","questionZh":"讲义提到哪些方法可以在模型部署中形成良性反馈回路、平衡探索与利用？","options":["RCTs, active learning, and reinforcement learning","Only k-means clustering","Removing all historical data","Using a fixed model forever"],"optionZh":["随机对照实验、主动学习和强化学习","只有 k-means 聚类","删除所有历史数据","永远使用固定模型"],"answer":0,"explanation":"A 正确：讲义第 82 页列出 RCT、主动学习、强化学习，实现迭代学习和持续优化，并衔接第 11 章的 bandits 与强化学习。","lessonId":"dsfb-09","lessonPage":82,"lessonPageTitle":"Challenges: post-processing"},{"id":"s5-q370","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":370,"level":"真题同型 · 500 题强化","question":"What is the lecture's conclusion about predictive versus prescriptive models for churn management?","questionZh":"讲义对流失管理中的预测模型与规范性模型有什么结论？","options":["Predictive models should be abandoned entirely.","Prescriptive models do not need any data.","Both are complementary: who is at risk and why (predictive) and whom to target with what incentive (prescriptive).","Uplift models always have higher AUC."],"optionZh":["应该完全放弃预测模型。","规范性模型不需要任何数据。","两者互补：谁有风险及原因（预测性），以及应该用什么激励联系谁（规范性）。","uplift 模型的 AUC 总是更高。"],"answer":2,"explanation":"C 正确：讲义第 92 页引用 Ascarza 等人的框架，指出两者“Complementary!”，关键是如何最优地结合。预测模型还需要无偏的数据。","lessonId":"dsfb-09","lessonPage":92,"lessonPageTitle":"Case: customer churn"},{"id":"s5-q371","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 9: Uplift Modeling and Causal Machine Learning","number":371,"level":"真题同型 · 500 题强化","question":"V-Bank builds a model to predict which customers will upgrade to a higher segment in the next 24 months, using five years of data during which marketing campaigns were run. Which concern from Chapter 9 applies most directly?","questionZh":"V-Bank 用过去五年（期间开展过营销活动）的数据建模，预测哪些客户会在 24 个月内升级。第 9 章的哪个问题最直接相关？","options":["The model predicts who will upgrade, not who will upgrade because of the campaign, and past campaigns may bias the data.","The data has too few variables.","Segments should be clustered with k-means.","A 24-month horizon is too short for any model."],"optionZh":["模型预测的是谁会升级，而不是谁因为活动才升级，而且过去的活动可能让数据有偏差。","数据变量太少。","应该用 k-means 对客户分层。","24 个月对任何模型都太短。"],"answer":0,"explanation":"A 正确：这正是讲义提出的两个问题：目标变量不对（应预测活动的效果），以及反馈回路（过去的营销影响了记录的结果）。","lessonId":"dsfb-09","lessonPage":11,"lessonPageTitle":"V-Bank segments its customers in 4 segments: bronze, silver, gold and"},{"id":"s5-q372","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":372,"level":"真题同型 · 500 题强化","question":"Which statement about the cost-benefit (CB) matrix is TRUE?","questionZh":"关于成本收益（CB）矩阵，哪项说法正确？","options":["It counts how many instances fall into each combination of predicted and actual class.","It specifies the monetary consequence of each combination of predicted and actual class.","It is only defined when misclassification costs are equal for both classes.","It replaces the need for class probability estimates from a model."],"optionZh":["它统计每种“预测类别 × 实际类别”组合中有多少个样本。","它给出每种“预测类别 × 实际类别”组合的货币后果。","只有当两类误分类成本相等时才能定义它。","有了它就不需要模型给出类别概率。"],"answer":1,"explanation":"B 正确：CB 矩阵是“价目表”，记录每种结果值多少钱。A 描述的是混淆矩阵（计数）。C 恰好相反，CB 矩阵存在的意义就是两类成本通常不相等。D 错：做成本敏感决策时仍要用模型概率去乘这些成本。","lessonId":"dsfb-10","lessonPage":8,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q373","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":373,"level":"真题同型 · 500 题强化","question":"In a CB matrix, imbalanced misclassification costs typically means that:","questionZh":"CB 矩阵中“误分类成本不平衡”通常指：","options":["cb_FN ≠ cb_FP","The data set contains more negatives than positives.","cb_TP = cb_TN = 0 by definition.","The confusion matrix is not square."],"optionZh":["cb_FN ≠ cb_FP","数据中负类比正类多。","按定义 cb_TP = cb_TN = 0。","混淆矩阵不是方阵。"],"answer":0,"explanation":"A 正确：漏判（FN）和误判（FP）的代价不同，比如漏掉欺诈亏整笔金额，误拦只亏调查费。B 说的是类别不平衡（class imbalance），是另一个概念。C 只在选完美模型为基准时成立，不是定义。D 二分类混淆矩阵永远是 2×2。","lessonId":"dsfb-10","lessonPage":8,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q374","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":374,"level":"真题同型 · 500 题强化","question":"In credit card fraud detection with a fixed investigation cost Ca and transaction amount A, which CB matrix entry is correct when using \"no cost\" as the baseline for a correctly passed legitimate transaction?","questionZh":"信用卡欺诈检测中，调查成本固定为 Ca，交易金额为 A。若以“正常交易被放行 = 0”为基准，下列哪个 CB 矩阵单元是正确的？","options":["Predicted no fraud, actual fraud: −Ca","Predicted fraud, actual no fraud: −A","Predicted no fraud, actual fraud: −A","Predicted fraud, actual fraud: +A − Ca as well as an additional +A for the prevented loss"],"optionZh":["预测不是欺诈、实际是欺诈：−Ca","预测是欺诈、实际不是欺诈：−A","预测不是欺诈、实际是欺诈：−A","预测是欺诈、实际是欺诈：+A − Ca，再额外加上 +A 的避免损失"],"answer":2,"explanation":"C 正确：放行了欺诈交易，钱被偷走，损失整笔金额 A。A 把调查费放错了格。B 误拦正常交易只花调查费 Ca，不会损失 A。D 把避免的损失算了两次，讲义特别提醒不要重复计算机会成本。","lessonId":"dsfb-10","lessonPage":9,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q375","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":375,"level":"真题同型 · 500 题强化","question":"The lecture warns against \"double-counting\" when building a CB matrix. Which choice would double-count?","questionZh":"讲义提醒构建 CB 矩阵时不要“重复计算”。下列哪种做法会重复计算？","options":["Setting cb_FN = −A and also setting cb_TP = −Ca + A","Setting cb_FN = −A and cb_TP = −Ca","Setting cb_FN = −A + Ca and cb_TP = 0","Multiplying every entry of the matrix by 100"],"optionZh":["设 cb_FN = −A，同时设 cb_TP = −Ca + A","设 cb_FN = −A，cb_TP = −Ca","设 cb_FN = −A + Ca，cb_TP = 0","把矩阵所有单元乘以 100"],"answer":0,"explanation":"A 会重复计算：漏判已经记了 −A，再给“拦住欺诈”加 +A，同一笔钱的差距就被算了两次（相对差变成 2A）。B 是原始矩阵。C 是相对完美模型的写法，差距仍是 A − Ca，没有重复。D 只是换单位，不改变决策。","lessonId":"dsfb-10","lessonPage":9,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q376","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":376,"level":"真题同型 · 500 题强化","question":"Which pair of inequalities are the \"reasonableness conditions\" for a CB matrix (rows = predicted, columns = actual)?","questionZh":"哪组不等式是 CB 矩阵（行 = 预测，列 = 实际）的“合理性条件”？","options":["cb10 > cb00 and cb01 > cb11","cb00 = cb11 and cb10 = cb01","cb00 < cb11 and cb10 < cb01","cb10 < cb00 and cb01 < cb11"],"optionZh":["cb10 > cb00 且 cb01 > cb11","cb00 = cb11 且 cb10 = cb01","cb00 < cb11 且 cb10 < cb01","cb10 < cb00 且 cb01 < cb11"],"answer":3,"explanation":"D 正确：把真 0 判成 1（cb10）要比判对（cb00）差，把真 1 判成 0（cb01）要比判对（cb11）差，即“判错一定比判对差”。A 两个方向都反了。C、B 比较的是不同列，没有意义。","lessonId":"dsfb-10","lessonPage":10,"lessonPageTitle":"Costs have a negative and benefits a positive value"},{"id":"s5-q377","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":377,"level":"真题同型 · 500 题强化","question":"Suppose cb10 > cb00 and cb11 > cb01. What is the optimal policy?","questionZh":"假设 cb10 > cb00 且 cb11 > cb01，最优策略是什么？","options":["Always predict negative.","Use the cost-sensitive threshold T_CS.","Always predict positive.","Predict randomly."],"optionZh":["永远预测负类。","使用成本敏感阈值 T_CS。","永远预测正类。","随机预测。"],"answer":2,"explanation":"C 正确：预测 1 那一行的两个数都比预测 0 那一行大，无论真实类别是什么，预测 1 都更赚钱，所以永远预测正类。这时第一条合理性条件被违反，模型变得多余。","lessonId":"dsfb-10","lessonPage":10,"lessonPageTitle":"Costs have a negative and benefits a positive value"},{"id":"s5-q378","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":378,"level":"真题同型 · 500 题强化","question":"Which statement about violating the reasonableness conditions is FALSE?","questionZh":"关于违反合理性条件，哪项说法是错误的？","options":["If only the first condition is violated, the optimal policy is to always predict positive.","If only the second condition is violated, the optimal policy is to always predict negative.","When one row dominates the other, a classification model adds no value to the decision.","If both conditions are violated, the optimal policy is still to always predict positive."],"optionZh":["只违反第一条时，最优策略是永远预测正类。","只违反第二条时，最优策略是永远预测负类。","当一行完全优于另一行时，分类模型对决策没有价值。","两条都违反时，最优策略仍然是永远预测正类。"],"answer":3,"explanation":"D 错误：两条都违反意味着每一列里“判错”都比“判对”更赚，相当于标签反了，应该按模型反着预测，而不是永远预测正类。A、B、C 都是讲义第 10 页的结论。","lessonId":"dsfb-10","lessonPage":10,"lessonPageTitle":"Costs have a negative and benefits a positive value"},{"id":"s5-q379","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":379,"level":"真题同型 · 500 题强化","question":"Which transformation of a CB matrix may CHANGE the optimal classification decisions?","questionZh":"对 CB 矩阵做哪种变换可能会改变最优分类决策？","options":["Multiplying every entry by 0.92 to convert dollars to euros.","Adding the same constant to every entry.","Multiplying only the false negative entry by 3.","Subtracting the benefit of a true negative from every entry."],"optionZh":["把每个单元乘以 0.92，把美元换成欧元。","给每个单元加同一个常数。","只把假阴性单元乘以 3。","每个单元都减去真阴性的收益。"],"answer":2,"explanation":"C 会改变决策：只改一格就改变了两类错误的相对代价，阈值随之移动。A 是乘以正常数（换货币），B、D 是给所有单元加减同一个常数（换基准），讲义第 11 页说明这两类变换都不改变最优决策。","lessonId":"dsfb-10","lessonPage":11,"lessonPageTitle":"CB’ Actual"},{"id":"s5-q380","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":380,"level":"真题同型 · 500 题强化","question":"By scaling and shifting, any CB matrix can be transformed into a simpler CB' with cb'00 = 0 and cb'10 = 1. What is the main drawback mentioned for CB'?","questionZh":"通过缩放和平移，任何 CB 矩阵都能变成 cb'00 = 0、cb'10 = 1 的简化矩阵 CB'。讲义提到 CB' 的主要缺点是什么？","options":["It leads to different classification decisions than the original matrix.","It can only be used for multi-class problems.","Its entries are harder to interpret in monetary terms.","It violates the reasonableness conditions by construction."],"optionZh":["它会得出与原矩阵不同的分类决策。","它只能用于多分类问题。","它的单元不再容易按货币含义解读。","按构造它一定违反合理性条件。"],"answer":2,"explanation":"C 正确：讲义在 CB' 旁边打了“Interpretability?”，单元变成了相对比值（如 A/Ca），不再直接是欧元。A 错，讲义明确说决策不变。B、D 都没有依据。","lessonId":"dsfb-10","lessonPage":11,"lessonPageTitle":"CB’ Actual"},{"id":"s5-q381","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":381,"level":"真题同型 · 500 题强化","question":"For fraud detection the CB matrix is [[0, −A], [−Ca, −Ca]] (rows: predicted no fraud / fraud). After transforming it to CB' with cb'00 = 0 and cb'10 = 1, what is cb'01?","questionZh":"欺诈检测的 CB 矩阵为 [[0, −A], [−Ca, −Ca]]（行：预测非欺诈 / 欺诈）。变换为 cb'00 = 0、cb'10 = 1 的 CB' 后，cb'01 等于多少？","options":["A / Ca","−A / Ca","Ca / A","1"],"optionZh":["A / Ca","−A / Ca","Ca / A","1"],"answer":0,"explanation":"A 正确：要把 cb10 = −Ca 变成 1，需要每个单元乘以 −1/Ca。于是 cb01 = −A × (−1/Ca) = A/Ca，cb11 = −Ca × (−1/Ca) = 1。注意乘以负数会把“最大化利润”翻成“最小化成本”，讲义第 12 页的 CB' 正是 [[0, A/Ca], [1, 1]]。","lessonId":"dsfb-10","lessonPage":12,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q382","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":382,"level":"真题同型 · 500 题强化","question":"When a CB matrix is defined relative to a perfect model as baseline, which entries are zero?","questionZh":"以完美模型为基准定义 CB 矩阵时，哪些单元为 0？","options":["The false positive and false negative entries.","All entries in the predicted-positive row.","The true positive and true negative entries.","All entries in the actual-negative column."],"optionZh":["假阳性和假阴性单元。","预测为正类那一行的所有单元。","真阳性和真阴性单元。","实际为负类那一列的所有单元。"],"answer":2,"explanation":"C 正确：完美模型永远判对，所以“判对”的两格是基准 0，只剩判错的两格记录额外成本。B 是“永远预测正类”模型的基准。D 不对应任何常用基准。","lessonId":"dsfb-10","lessonPage":13,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q383","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":383,"level":"真题同型 · 500 题强化","question":"Relative to a perfect baseline, what is the extra cost of a false negative in the fraud case (amount A, investigation cost Ca)?","questionZh":"以完美模型为基准，欺诈案例中假阴性的额外成本是多少（金额 A，调查成本 Ca）？","options":["−A","−Ca","−A − Ca","−A + Ca"],"optionZh":["−A","−Ca","−A − Ca","−A + Ca"],"answer":3,"explanation":"D 正确：完美模型会拦下这笔欺诈，付出 Ca；我们漏判损失 A。相对完美模型的额外成本 = −A − (−Ca) = −A + Ca。A 是原始矩阵的数值，不是相对完美模型的。","lessonId":"dsfb-10","lessonPage":13,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q384","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":384,"level":"真题同型 · 500 题强化","question":"How can you identify the baseline that was implicitly used to define a CB matrix?","questionZh":"如何判断一张 CB 矩阵隐含采用了什么基准？","options":["Look at which cells are zero.","Look at the largest value in the matrix.","Compare the matrix with the confusion matrix.","The baseline is always the random model."],"optionZh":["看哪些单元是 0。","看矩阵里最大的数。","把它和混淆矩阵比较。","基准永远是随机模型。"],"answer":0,"explanation":"A 正确：讲义第 14 页注明“baseline is indicated by the zero cells”。真阳真阴为 0 → 完美模型；预测正类那行为 0 → 永远预测正类的模型；预测负类那行为 0 → 永远预测负类的模型。","lessonId":"dsfb-10","lessonPage":14,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q385","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":385,"level":"真题同型 · 500 题强化","question":"A CB matrix has both cells of the \"predicted negative\" row equal to 0. Which baseline model does this correspond to?","questionZh":"一张 CB 矩阵中“预测为负类”那一行两个单元都是 0。它对应哪个基准模型？","options":["A perfect model.","A model that always predicts negative.","A model that always predicts positive.","A random model."],"optionZh":["完美模型。","永远预测负类的模型。","永远预测正类的模型。","随机模型。"],"answer":1,"explanation":"B 正确：如果什么都预测为负类不花也不赚（那一行全是 0），说明成本是相对“永远预测负类”来衡量的。例如欺诈中“全部放行”的模型。","lessonId":"dsfb-10","lessonPage":14,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q386","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":386,"level":"真题同型 · 500 题强化","question":"For the fraud CB matrix [[0, −A], [−Ca, −Ca]], what is the implicit baseline?","questionZh":"欺诈 CB 矩阵 [[0, −A], [−Ca, −Ca]] 隐含的基准是什么？","options":["A perfect model.","A model that always predicts fraud.","There is no baseline because only one cell is zero; the zero sets the outcome of passing a legitimate transaction as reference.","A model that always predicts no fraud."],"optionZh":["完美模型。","永远预测欺诈的模型。","只有一个单元是 0，基准就是“放行正常交易”这个结果被设为参照点。","永远预测非欺诈的模型。"],"answer":2,"explanation":"C 正确：只有 cb00 = 0，说明作者只是把“正常交易被放行”定为 0（等于给所有单元减去了真阴性的收益），它并不对应一个完整的基准模型。若是“永远预测非欺诈”的基准，cb01 也应为 0。","lessonId":"dsfb-10","lessonPage":15,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q387","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":387,"level":"真题同型 · 500 题强化","question":"Which statement about obtaining cost-benefit values in practice is FALSE?","questionZh":"关于实际中如何获得成本收益数值，哪项说法是错误的？","options":["Rough estimates by experts may be used.","Costs may be assumed inversely proportional to the class distribution.","The sensitivity of results can be checked by varying the parameters.","Since exact costs are unknown, cost-sensitive methods cannot be applied."],"optionZh":["可以使用专家的粗略估计。","可以假设成本与类别分布成反比。","可以通过改变参数来检验结果的敏感性。","既然确切成本未知，就无法使用成本敏感方法。"],"answer":3,"explanation":"D 错误：讲义第 16 页列出了专家估计、按类别分布倒数、敏感性分析、用 EMP 把不确定性纳入等多种办法，成本未知并不妨碍使用。","lessonId":"dsfb-10","lessonPage":16,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q388","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":388,"level":"真题同型 · 500 题强化","question":"In fraud detection the transaction amount differs for every transaction. Which cost setting does this describe?","questionZh":"欺诈检测中每笔交易金额都不同。这描述的是哪种成本设定？","options":["Instance-dependent costs","Class-dependent costs","Uniform costs","Zero-one loss"],"optionZh":["实例相关成本（一笔一价）","类别相关成本（统一价）","均匀成本","0-1 损失"],"answer":0,"explanation":"A 正确：成本取决于每个样本自己的属性（金额 A_i），即 instance-dependent。B 是每类一个固定成本。讲义也提到简单的折中：把实例成本取平均，就退化成类别相关成本。","lessonId":"dsfb-10","lessonPage":16,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q389","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":389,"level":"真题同型 · 500 题强化","question":"What is the simple solution mentioned in the lecture to avoid the added complexity of instance-dependent costs?","questionZh":"讲义中为了避免实例相关成本带来的复杂性，提到的简单做法是什么？","options":["Drop all high-amount transactions.","Set all costs to 1.","Average the instance-dependent costs to obtain class-dependent costs.","Use accuracy instead."],"optionZh":["删除所有大额交易。","把所有成本设为 1。","把实例成本取平均，得到类别相关成本。","改用准确率。"],"answer":2,"explanation":"C 正确：讲义第 16 页写明“averaging instance-dependent costs yields class-dependent costs”。代价是丢失了个体差异，比如大额交易的风险被低估。","lessonId":"dsfb-10","lessonPage":16,"lessonPageTitle":"Cost-Benefit matrix"},{"id":"s5-q390","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":390,"level":"真题同型 · 500 题强化","question":"In the German credit data 30% of applicants are bad and 70% good. Using costs inversely proportional to the class distribution (cb10 normalised to −1), what is cb01?","questionZh":"德国信贷数据中坏客户 30%、好客户 70%。若按类别分布的倒数设定成本（cb10 标准化为 −1），cb01 是多少？","options":["−0.43","−1","−5","−2.33"],"optionZh":["−0.43","−1","−5","−2.33"],"answer":3,"explanation":"D 正确：cb01 = −(1/30%) × 70% = −2.33，cb10 = −(1/70%) × 70% = −1。少数类（坏客户）被漏掉的代价按比例放大。C 的 −5 是专家给的矩阵，不是按倒数算的。","lessonId":"dsfb-10","lessonPage":18,"lessonPageTitle":"CB Actual class"},{"id":"s5-q391","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":391,"level":"真题同型 · 500 题强化","question":"In the German credit CB matrix (predicted good / actual bad = −5, predicted bad / actual good = −1, others 0), what does −5 represent?","questionZh":"德国信贷 CB 矩阵中（预测好/实际坏 = −5，预测坏/实际好 = −1，其余为 0），−5 代表什么？","options":["The cost of rejecting a good applicant.","The total profit of the portfolio.","The benefit of correctly rejecting a bad applicant.","The cost of accepting an applicant who defaults."],"optionZh":["拒绝一个好客户的成本。","整个组合的总利润。","正确拒绝坏客户的收益。","批准了一个后来违约的客户的成本。"],"answer":3,"explanation":"D 正确：行是预测、列是实际。“预测好、实际坏”就是把贷款批给了会违约的人，损失最大，所以是 −5。A 对应 −1。C 在这张表里是 0。","lessonId":"dsfb-10","lessonPage":17,"lessonPageTitle":"CB Actual class"},{"id":"s5-q392","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":392,"level":"真题同型 · 500 题强化","question":"What is the implicit baseline of the German credit CB matrix [[0, −5], [−1, 0]]?","questionZh":"德国信贷 CB 矩阵 [[0, −5], [−1, 0]] 隐含的基准是什么？","options":["A perfect model","A model that always accepts","A model that always rejects","A random model"],"optionZh":["完美模型","永远批准的模型","永远拒绝的模型","随机模型"],"answer":0,"explanation":"A 正确：两个“判对”的格子（真阴性、真阳性）都为 0，只记录判错的额外成本，这正是以完美模型为基准的特征。","lessonId":"dsfb-10","lessonPage":17,"lessonPageTitle":"CB Actual class"},{"id":"s5-q393","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":393,"level":"真题同型 · 500 题强化","question":"How is the total Profit P computed from the confusion matrix CF and the CB matrix?","questionZh":"如何由混淆矩阵 CF 和 CB 矩阵计算总利润 P？","options":["P = TN·cb_TN + FN·cb_FN + FP·cb_FP + TP·cb_TP","P = (TP + TN) / N","P = cb_TP − cb_FP","P = TP·cb_TP only, since negatives bring no profit"],"optionZh":["P = TN·cb_TN + FN·cb_FN + FP·cb_FP + TP·cb_TP","P = (TP + TN) / N","P = cb_TP − cb_FP","P 只等于 TP·cb_TP，因为负类不产生利润"],"answer":0,"explanation":"A 正确：Frobenius 内积就是两张表对应格相乘再求和。B 是准确率。C 没有乘以数量。D 忽略了其他三格，而 FN、FP 往往正是最大的损失来源。","lessonId":"dsfb-10","lessonPage":20,"lessonPageTitle":"Profit"},{"id":"s5-q394","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":394,"level":"真题同型 · 500 题强化","question":"A test set yields TN = 600, FN = 40, FP = 100, TP = 60. With cb_TN = 0, cb_FN = −5, cb_FP = −1, cb_TP = 0, what is the total profit P?","questionZh":"测试集结果为 TN = 600、FN = 40、FP = 100、TP = 60。若 cb_TN = 0、cb_FN = −5、cb_FP = −1、cb_TP = 0，总利润 P 是多少？","options":["−100","−200","−300","−500"],"optionZh":["−100","−200","−300","−500"],"answer":2,"explanation":"C 正确：P = 600×0 + 40×(−5) + 100×(−1) + 60×0 = −200 − 100 = −300。B 只算了 FN，A 只算了 FP。","lessonId":"dsfb-10","lessonPage":20,"lessonPageTitle":"Profit"},{"id":"s5-q395","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":395,"level":"真题同型 · 500 题强化","question":"Using the previous test set (N = 800, P = −300), what is the Average Profit AP?","questionZh":"沿用上一题测试集（N = 800，P = −300），平均利润 AP 是多少？","options":["−0.375","−0.300","−3.75","−0.5"],"optionZh":["−0.375","−0.300","−3.75","−0.5"],"answer":0,"explanation":"A 正确：AP = P / N = −300 / 800 = −0.375。AP 去掉了测试集大小的影响，方便比较不同大小的测试集。","lessonId":"dsfb-10","lessonPage":21,"lessonPageTitle":"Average Profit"},{"id":"s5-q396","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":396,"level":"真题同型 · 500 题强化","question":"Why is the Average Profit (AP) preferred over the total Profit (P) as an evaluation measure?","questionZh":"为什么评估时更偏好平均利润 AP 而不是总利润 P？","options":["AP does not depend on the threshold.","AP is independent of the size of the test set.","AP is always positive.","AP ignores misclassification costs."],"optionZh":["AP 不依赖阈值。","AP 不受测试集大小影响。","AP 总是正数。","AP 忽略误分类成本。"],"answer":1,"explanation":"B 正确：P 随样本数线性增长，AP = P/N 是每个样本的平均利润。A 错：讲义第 21 页特别指出 P 和 AP 都依赖阈值 T。C、D 显然错。","lessonId":"dsfb-10","lessonPage":21,"lessonPageTitle":"Average Profit"},{"id":"s5-q397","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":397,"level":"真题同型 · 500 题强化","question":"Which statement about AP is TRUE?","questionZh":"关于 AP，哪项说法正确？","options":["AP is computed directly from probability estimates without any threshold.","AP equals accuracy when costs are unknown.","AP depends on the threshold T used to turn probabilities into class predictions.","AP is the same as the Maximum Profit."],"optionZh":["AP 直接由概率估计计算，不需要阈值。","成本未知时 AP 等于准确率。","AP 依赖把概率变成类别预测的阈值 T。","AP 就是最大利润。"],"answer":2,"explanation":"C 正确：混淆矩阵由阈值决定，AP 由混淆矩阵算出，所以阈值变 AP 就变。A 描述的是 AAEP。D：MP 是在所有阈值中 AP 的最大值。","lessonId":"dsfb-10","lessonPage":21,"lessonPageTitle":"Average Profit"},{"id":"s5-q398","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":398,"level":"真题同型 · 500 题强化","question":"Four applicants have p(bad|x) = 0.84, 0.54, 0.46, 0.12 and actual classes bad, good, bad, good. CB: accepting a bad = −5, rejecting a good = −1, others 0. With threshold 0.5, what is the total profit?","questionZh":"四位申请人的 p(坏|x) 分别为 0.84、0.54、0.46、0.12，实际为坏、好、坏、好。CB：批准坏客户 = −5，拒绝好客户 = −1，其余为 0。阈值 0.5 时，总利润是多少？","options":["−1","−5","−6","0"],"optionZh":["−1","−5","−6","0"],"answer":2,"explanation":"C 正确：阈值 0.5 → 预测为坏、坏、好、好。第 1 人判对（0）；第 2 人好客户被拒（−1）；第 3 人坏客户被批准（−5）；第 4 人判对（0）。总计 −6，AP = −1.5。","lessonId":"dsfb-10","lessonPage":22,"lessonPageTitle":"Average Profit"},{"id":"s5-q399","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":399,"level":"真题同型 · 500 题强化","question":"Using the same four applicants but threshold 0.167, what is the total profit?","questionZh":"同样四位申请人，阈值改为 0.167，总利润是多少？","options":["−1","−6","−2","0"],"optionZh":["−1","−6","−2","0"],"answer":0,"explanation":"A 正确：阈值 0.167 → 前三人都被判为坏，第 4 人（0.12）判为好。只有第 2 人好客户被拒（−1），第 3 人这次被正确拒绝（0）。总计 −1，比阈值 0.5 的 −6 好得多。","lessonId":"dsfb-10","lessonPage":23,"lessonPageTitle":"ID 𝒑(𝒚 = 𝟎|𝒙) 𝒑(𝒚 = 𝟏|𝒙) ෝ𝒚 𝒚 𝑷 ෝ𝒚, 𝒚"},{"id":"s5-q400","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":400,"level":"真题同型 · 500 题强化","question":"Why does lowering the threshold from 0.5 to 0.167 improve profit in the German credit example?","questionZh":"在德国信贷例子中，为什么把阈值从 0.5 降到 0.167 能提高利润？","options":["Because it increases accuracy.","Because fewer applicants are rejected.","Because the model becomes better calibrated.","Because missing a bad applicant costs five times more than rejecting a good one, so it pays to flag more applicants as bad."],"optionZh":["因为它提高了准确率。","因为被拒绝的申请人变少了。","因为模型的校准变好了。","因为漏掉坏客户的代价是错拒好客户的 5 倍，多标记一些人为坏客户更划算。"],"answer":3,"explanation":"D 正确：阈值越低，越多人被判为坏客户，以多错拒几个好客户（每个 −1）为代价，避免批准坏客户（每个 −5）。A 不一定：准确率可能反而下降。C：阈值不改变模型概率。B 正好相反。","lessonId":"dsfb-10","lessonPage":23,"lessonPageTitle":"ID 𝒑(𝒚 = 𝟎|𝒙) 𝒑(𝒚 = 𝟏|𝒙) ෝ𝒚 𝒚 𝑷 ෝ𝒚, 𝒚"},{"id":"s5-q401","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":401,"level":"真题同型 · 500 题强化","question":"In the cost matrix C (costs as positive values), how is the Average Cost (AC) related to the Average Profit (AP) computed with the corresponding CB matrix?","questionZh":"在成本矩阵 C（成本记为正数）中，平均成本 AC 与对应 CB 矩阵算出的平均利润 AP 是什么关系？","options":["AC = AP","AC = 1 − AP","AC = −AP","AC = AP / N"],"optionZh":["AC = AP","AC = 1 − AP","AC = −AP","AC = AP / N"],"answer":2,"explanation":"C 正确：C 矩阵与 CB 矩阵只差一个负号，例如 AP = −1.5 时 AC = 1.5。最大化 AP 等价于最小化 AC。","lessonId":"dsfb-10","lessonPage":22,"lessonPageTitle":"Average Profit"},{"id":"s5-q402","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":402,"level":"真题同型 · 500 题强化","question":"Which statement about the \"two-threshold point strategy\" is TRUE?","questionZh":"关于“双阈值策略”，哪项说法正确？","options":["It uses two different models for positives and negatives.","Instances with intermediate scores, where the class distributions overlap most, are referred to human experts.","It selects the two thresholds that maximize accuracy.","It is only applicable to regression models."],"optionZh":["它对正类和负类分别使用两个模型。","处于中间分数、两类分布重叠最严重的实例交给人工专家判断。","它选出使准确率最高的两个阈值。","它只适用于回归模型。"],"answer":1,"explanation":"B 正确：低分自动通过、高分自动拒绝，中间模糊区交给人工审核，体现“human input & control”。A、C、D 都不符合讲义。","lessonId":"dsfb-10","lessonPage":24,"lessonPageTitle":"Threshold tuning"},{"id":"s5-q403","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":403,"level":"真题同型 · 500 题强化","question":"In the threshold tuning table for credit scoring, increasing the threshold T on p(bad|x) typically leads to:","questionZh":"在信用评分的阈值调整表中，提高针对 p(坏|x) 的阈值 T，通常会导致：","options":["A lower acceptance rate and higher sensitivity.","No change in the confusion matrix.","Higher sensitivity and lower specificity.","A higher acceptance rate and lower sensitivity."],"optionZh":["通过率下降，敏感度上升。","混淆矩阵不变。","敏感度上升，特异度下降。","通过率上升，敏感度下降。"],"answer":3,"explanation":"D 正确：阈值越高，越少人被判为坏客户，所以更多人被批准（通过率上升），坏客户被识别出来的比例（敏感度）下降，特异度上升。","lessonId":"dsfb-10","lessonPage":25,"lessonPageTitle":"Threshold tuning"},{"id":"s5-q404","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":404,"level":"真题同型 · 500 题强化","question":"In the threshold tuning table, the lowest average cost (175.11) is reached at T = 0.55, while accuracy keeps increasing up to T = 0.65. What does this illustrate?","questionZh":"阈值调整表中，平均成本最低（175.11）出现在 T = 0.55，而准确率一直增长到 T = 0.65。这说明什么？","options":["The accuracy-maximizing threshold is not necessarily the profit-maximizing threshold.","Accuracy and average cost are always minimized at the same threshold.","The table contains a calculation error.","Threshold tuning should be based on sensitivity only."],"optionZh":["使准确率最高的阈值不一定是使利润最高的阈值。","准确率和平均成本总在同一阈值取得最优。","表格有计算错误。","阈值调整只应看敏感度。"],"answer":0,"explanation":"A 正确：准确率把所有错误当成一样，平均成本则区分两种错误的代价，两者的最优阈值可以不同。这也是第 45 页题目里“准确率越高利润越高”是错误说法的原因。","lessonId":"dsfb-10","lessonPage":25,"lessonPageTitle":"Threshold tuning"},{"id":"s5-q405","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":405,"level":"真题同型 · 500 题强化","question":"What does threshold tuning yield?","questionZh":"阈值调整（threshold tuning）得到的是什么？","options":["The theoretical cost-sensitive threshold T_CS.","The optimal model parameters.","An empirical, profit-maximizing threshold T*.","The calibrated probabilities."],"optionZh":["理论成本敏感阈值 T_CS。","最优模型参数。","一个经验性的、利润最大化的阈值 T*。","校准后的概率。"],"answer":2,"explanation":"C 正确：在数据上把阈值从小到大试一遍，选 AP 最大（AC 最小）的那个，就是 T*。A 是用公式算出的理论阈值，两者可能不同。B、D 阈值调整都不改变。","lessonId":"dsfb-10","lessonPage":25,"lessonPageTitle":"Threshold tuning"},{"id":"s5-q406","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":406,"level":"真题同型 · 500 题强化","question":"Which statement about the Maximum Profit (MP) measure is FALSE?","questionZh":"关于最大利润（MP）指标，哪项说法是错误的？","options":["MP is the AP at the optimal threshold T*.","MP can be used for model evaluation and selection.","MP can be used as an objective for learning a model.","MP depends on the threshold chosen by the analyst."],"optionZh":["MP 是最优阈值 T* 处的 AP。","MP 可用于模型评估与选择。","MP 可以用作模型学习的目标。","MP 取决于分析师选的阈值。"],"answer":3,"explanation":"D 错误：MP 已经在所有阈值中取了最大值，不再依赖人为选定的某个阈值。A、B、C 都是讲义第 26 页的内容。","lessonId":"dsfb-10","lessonPage":26,"lessonPageTitle":"Maximum Profit"},{"id":"s5-q407","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":407,"level":"真题同型 · 500 题强化","question":"An applicant is actually bad (y = 1). The model gives p(good|x) = 0.16 and p(bad|x) = 0.84. With cb01 = −5 and cb11 = 0, what is the Actual Expected Profit (AEP) for this applicant?","questionZh":"某申请人实际是坏客户（y = 1），模型给出 p(好|x) = 0.16、p(坏|x) = 0.84。cb01 = −5、cb11 = 0，该申请人的实际期望利润（AEP）是多少？","options":["−4.2","−0.84","0","−0.80"],"optionZh":["−4.2","−0.84","0","−0.80"],"answer":3,"explanation":"D 正确：AEP = p(0|x)·cb01 + p(1|x)·cb11 = 0.16 × (−5) + 0.84 × 0 = −0.80。已知真实类别 y = 1，所以用 CB 矩阵“实际 = 1”那一列。","lessonId":"dsfb-10","lessonPage":27,"lessonPageTitle":"CB Actual"},{"id":"s5-q408","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":408,"level":"真题同型 · 500 题强化","question":"Which statement about the Average Actual Expected Profit (AAEP) is TRUE?","questionZh":"关于平均实际期望利润（AAEP），哪项说法正确？","options":["It requires choosing a classification threshold.","It is threshold-independent and in a way evaluates the calibration of the model's probabilities.","It can be computed without knowing the actual class labels.","It is identical to the Maximum Profit."],"optionZh":["它需要先选定分类阈值。","它不依赖阈值，某种程度上在评估模型概率的校准程度。","不知道真实标签也能计算。","它与最大利润完全相同。"],"answer":1,"explanation":"B 正确：AAEP 直接用概率乘以“实际类别那一列”的成本收益，不需要阈值，概率越贴合真实情况得分越好。C 错：它恰恰需要真实标签。","lessonId":"dsfb-10","lessonPage":27,"lessonPageTitle":"CB Actual"},{"id":"s5-q409","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":409,"level":"真题同型 · 500 题强化","question":"Two models both classify a bad applicant correctly at threshold 0.5. Model 1 gives p(bad|x) = 0.55; Model 2 gives 0.95. Which measure distinguishes them?","questionZh":"两个模型在阈值 0.5 下都正确识别了一个坏客户。模型 1 给出 p(坏|x) = 0.55，模型 2 给出 0.95。哪个指标能区分它们？","options":["Average Profit at T = 0.5","Accuracy at T = 0.5","Average Actual Expected Profit","The confusion matrix at T = 0.5"],"optionZh":["阈值 0.5 下的平均利润","阈值 0.5 下的准确率","平均实际期望利润（AAEP）","阈值 0.5 下的混淆矩阵"],"answer":2,"explanation":"C 正确：A、B、D 都只看“是否过线”，两个模型结果一样。AAEP 用概率本身计算，模型 2 更有把握且正确，期望损失更小，所以得分更高。","lessonId":"dsfb-10","lessonPage":27,"lessonPageTitle":"CB Actual"},{"id":"s5-q410","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":410,"level":"真题同型 · 500 题强化","question":"In the customer churn profit formula, what does the parameter γ represent?","questionZh":"在客户流失利润公式中，参数 γ 代表什么？","options":["The proportion of customers that is targeted.","The cost of the incentive.","The base churn rate.","The proportion of targeted would-be churners that is successfully retained."],"optionZh":["被联系的客户比例。","激励的成本。","基础流失率。","被联系的潜在流失者中被成功挽留的比例。"],"answer":3,"explanation":"D 正确：γ 是挽留成功率。A 是 α，C 是 β0，B 是 δ。","lessonId":"dsfb-10","lessonPage":28,"lessonPageTitle":"Case: Customer churn prediction"},{"id":"s5-q411","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":411,"level":"真题同型 · 500 题强化","question":"In the churn profit formula, what profit is associated with a targeted customer who would not have churned anyway (a \"false would-be churner\")?","questionZh":"在流失利润公式中，被联系但本来就不会流失的客户（“假潜在流失者”）带来的利润是多少？","options":["CLV − c − δ","−c","−c − δ","0"],"optionZh":["CLV − c − δ","−c","−c − δ","0"],"answer":2,"explanation":"C 正确：这类客户本来就不走，联系他们白花了联系成本 c，还白送了激励 δ（他们会接受优惠）。B 是被联系但没挽留成功的真流失者。A 是被成功挽留的真流失者。","lessonId":"dsfb-10","lessonPage":28,"lessonPageTitle":"Case: Customer churn prediction"},{"id":"s5-q412","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":412,"level":"真题同型 · 500 题强化","question":"In the churn profit formula, a targeted would-be churner who is NOT retained involves which profit?","questionZh":"在流失利润公式中，被联系但没有挽留成功的潜在流失者带来多少利润？","options":["−c","−c − δ","CLV − c − δ","−CLV"],"optionZh":["−c","−c − δ","CLV − c − δ","−CLV"],"answer":0,"explanation":"A 正确：联系了但客户仍然离开，只花了联系成本 c，激励没被接受所以不花 δ。D 不对，因为不管模型如何这个客户都会流失，CLV 损失不由这次活动造成。","lessonId":"dsfb-10","lessonPage":28,"lessonPageTitle":"Case: Customer churn prediction"},{"id":"s5-q413","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":413,"level":"真题同型 · 500 题强化","question":"In P = Nα{[γCLV + δ(1 − γ)]β0λ(α) − δ − c} − A, through which term does the quality of the churn prediction model affect the profit?","questionZh":"在 P = Nα{[γCLV + δ(1 − γ)]β0λ(α) − δ − c} − A 中，流失预测模型的好坏通过哪一项影响利润？","options":["The lift λ(α)","The incentive cost δ","The fixed campaign cost A","The customer lifetime value CLV"],"optionZh":["提升度 λ(α)","激励成本 δ","活动固定成本 A","客户终身价值 CLV"],"answer":0,"explanation":"A 正确：β = β0·λ(α)，即被选中客户中真流失者的比例 = 基础流失率 × 模型的 lift。模型越好，lift 越高，目标名单越准，利润越高。B、C、D 都是业务参数，与模型无关。","lessonId":"dsfb-10","lessonPage":30,"lessonPageTitle":"Case: Customer churn prediction"},{"id":"s5-q414","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":414,"level":"真题同型 · 500 题强化","question":"In the churn setting, maximizing the average profit over α is equivalent to:","questionZh":"在流失场景中，对 α 最大化平均利润等价于：","options":["Maximizing the AUC.","Finding the optimal, profit-maximizing threshold T*.","Minimizing the incentive cost δ.","Contacting all customers."],"optionZh":["最大化 AUC。","找到最优的利润最大化阈值 T*。","最小化激励成本 δ。","联系所有客户。"],"answer":1,"explanation":"B 正确：选择联系前 α 比例的客户，就等于在模型分数上画一条线。最优 α* 对应最优阈值 T*，此时的平均利润就是 MP。","lessonId":"dsfb-10","lessonPage":30,"lessonPageTitle":"Case: Customer churn prediction"},{"id":"s5-q415","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":415,"level":"真题同型 · 500 题强化","question":"Which statement about the Expected Maximum Profit (EMP) is TRUE?","questionZh":"关于期望最大利润（EMP），哪项说法正确？","options":["It assumes all cost-benefit parameters are known exactly.","It is a threshold-dependent version of the AAEP.","It takes the uncertainty of cost-benefit parameters into account by integrating MP over a probability distribution of these parameters.","It can only be computed for credit scoring."],"optionZh":["它假设所有成本收益参数都确切已知。","它是 AAEP 依赖阈值的版本。","它对成本收益参数设定概率分布，并对 MP 积分，从而纳入参数的不确定性。","它只能用于信用评分。"],"answer":2,"explanation":"C 正确：例如流失场景中挽留成功率 γ 不确定，给 γ 一个分布 h(γ)，在每个可能值下取最优阈值算利润，再按概率加权平均。A 描述的是 MP。","lessonId":"dsfb-10","lessonPage":31,"lessonPageTitle":"Expected Maximum Profit"},{"id":"s5-q416","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":416,"level":"真题同型 · 500 题强化","question":"In EMP for customer churn prediction (EMP_CCP), the uncertainty is specified on which parameter?","questionZh":"在客户流失预测的 EMP（EMP_CCP）中，不确定性设定在哪个参数上？","options":["The number of customers N","The base churn rate β0","The retention rate γ","The threshold T"],"optionZh":["客户数 N","基础流失率 β0","挽留成功率 γ","阈值 T"],"answer":2,"explanation":"C 正确：讲义第 31 页的公式对 γ 积分，即 EMP_CCP = ∫ AP(T*; CF, CB) · h(γ) dγ。挽留成功率是最难事先知道的参数。","lessonId":"dsfb-10","lessonPage":31,"lessonPageTitle":"Expected Maximum Profit"},{"id":"s5-q417","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":417,"level":"真题同型 · 500 题强化","question":"A free lottery ticket pays €1 with probability 80% and €10 with probability 20%. Which statement is TRUE?","questionZh":"一张免费彩票有 80% 概率得 €1，20% 概率得 €10。哪项说法正确？","options":["The expected profit is €5.50, the average of the two prizes.","You will win exactly €2.80 with this ticket.","The expected profit is €2.80, interpreted as the average win per ticket when buying many tickets.","The expected profit is €8.20."],"optionZh":["期望利润是 €5.50，即两个奖金的平均。","这张彩票你会恰好赢得 €2.80。","期望利润是 €2.80，含义是买很多张时平均每张赢的钱。","期望利润是 €8.20。"],"answer":2,"explanation":"C 正确：EP = 0.8 × 1 + 0.2 × 10 = €2.80。单张票只会得 €1 或 €10，永远不会正好是 €2.80，期望利润是重复很多次后的平均。A 忽略了概率。","lessonId":"dsfb-10","lessonPage":34,"lessonPageTitle":"Expected Profit"},{"id":"s5-q418","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":418,"level":"真题同型 · 500 题强化","question":"What is the Predicted Expected Profit of predicting class 1 for instance x?","questionZh":"把实例 x 预测为类别 1 的“预测期望利润”是什么？","options":["p(0|x)·cb00 + p(1|x)·cb01","p(0|x)·cb10 + p(1|x)·cb11","p(0|x)·cb01 + p(1|x)·cb11","p(1|x)·cb11 only"],"optionZh":["p(0|x)·cb00 + p(1|x)·cb01","p(0|x)·cb10 + p(1|x)·cb11","p(0|x)·cb01 + p(1|x)·cb11","只有 p(1|x)·cb11"],"answer":1,"explanation":"B 正确：预测为 1，就看 CB 矩阵“预测 = 1”这一行（cb10、cb11），分别乘以真实为 0 和 1 的概率。A 是预测为 0 的 PEP。C 是已知实际 y = 1 时的 AEP（看一列）。","lessonId":"dsfb-10","lessonPage":35,"lessonPageTitle":"Expected Profit"},{"id":"s5-q419","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":419,"level":"真题同型 · 500 题强化","question":"According to Elkan's cost-sensitive decision rule, the optimal prediction for an instance x is:","questionZh":"根据 Elkan 的成本敏感决策规则，实例 x 的最优预测是：","options":["The class with the highest probability p(j|x).","The class with the lowest misclassification cost.","Always the positive class.","The class with the largest Predicted Expected Profit."],"optionZh":["概率 p(j|x) 最高的类别。","误分类成本最低的类别。","永远是正类。","预测期望利润最大的类别。"],"answer":3,"explanation":"D 正确：讲义第 36 页原话：“the optimal prediction for an example x is the class i that yields the largest Predicted Expected Profit”。A 是成本不敏感的做法（相当于阈值 0.5）。","lessonId":"dsfb-10","lessonPage":36,"lessonPageTitle":"Given the (cost-insensitive) classification model 𝑴"},{"id":"s5-q420","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":420,"level":"真题同型 · 500 题强化","question":"A transaction of €1,500 has a fraud probability of 1%. The investigation cost is Ca = €10. What should the bank do?","questionZh":"一笔 €1,500 的交易欺诈概率为 1%，调查成本 Ca = €10。银行应该怎么做？","options":["Block it, because the expected loss of passing (€15) exceeds the cost of investigating (€10).","Pass it, because 1% is below 50%.","Pass it, because the expected loss of passing is €1.50.","Block it, because €1,500 is a large amount."],"optionZh":["拦截，因为放行的期望损失（€15）超过调查成本（€10）。","放行，因为 1% 低于 50%。","放行，因为放行的期望损失是 €1.50。","拦截，因为 €1,500 是大额。"],"answer":0,"explanation":"A 正确：PEP(拦截) = −Ca = −€10；PEP(放行) = −p·A = −0.01 × 1,500 = −€15。−10 > −15，所以拦截。B 是成本不敏感的想法。C 算错了。D 理由不完整：要和调查成本比。","lessonId":"dsfb-10","lessonPage":40,"lessonPageTitle":"Cost-sensitive decision-making"},{"id":"s5-q421","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":421,"level":"真题同型 · 500 题强化","question":"Same setting as the lecture, but now the investigation cost rises to Ca = €50. Which transaction should still be blocked?","questionZh":"与讲义相同的设定，但调查成本升到 Ca = €50。哪笔交易仍应被拦截？","options":["€100 with 20% fraud probability","€500 with 1% fraud probability","€1,500 with 1% fraud probability","€10,000 with 80% fraud probability"],"optionZh":["€100，欺诈概率 20%","€500，欺诈概率 1%","€1,500，欺诈概率 1%","€10,000，欺诈概率 80%"],"answer":3,"explanation":"D 正确：放行的期望损失分别为 €20、€5、€15、€8,000。只有 €8,000 超过 €50 的调查成本，所以只拦最后一笔。调查成本越高，越少交易值得拦截。","lessonId":"dsfb-10","lessonPage":40,"lessonPageTitle":"Cost-sensitive decision-making"},{"id":"s5-q422","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":422,"level":"真题同型 · 500 题强化","question":"In fraud detection, a transaction should be classified as fraud when:","questionZh":"在欺诈检测中，一笔交易何时应被判为欺诈？","options":["p(1|x) > 0.5","p(1|x) > A / Ca","p(1|x) > Ca / A","p(1|x) > Ca"],"optionZh":["p(1|x) > 0.5","p(1|x) > A / Ca","p(1|x) > Ca / A","p(1|x) > Ca"],"answer":2,"explanation":"C 正确：拦截的期望利润是 −Ca，放行是 −p·A。−Ca > −p·A 即 p > Ca/A。所以每笔交易的阈值不同：金额越大，阈值越低。B 把分子分母弄反了。","lessonId":"dsfb-10","lessonPage":41,"lessonPageTitle":"Cost-sensitive decision-making"},{"id":"s5-q423","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":423,"level":"真题同型 · 500 题强化","question":"For a fixed investigation cost Ca, how does the instance-dependent threshold T_CS,i = Ca / A_i change for larger transaction amounts?","questionZh":"调查成本 Ca 固定时，实例相关阈值 T_CS,i = Ca / A_i 随交易金额增大如何变化？","options":["It increases, so large transactions are blocked less often.","It decreases, so even a small fraud probability can justify blocking a large transaction.","It stays the same because Ca is fixed.","It becomes negative."],"optionZh":["升高，所以大额交易更少被拦截。","降低，所以大额交易即使欺诈概率很小也值得拦截。","不变，因为 Ca 固定。","变成负数。"],"answer":1,"explanation":"B 正确：金额越大，漏掉的代价越大，阈值 Ca/A_i 越低。例如 Ca = €10 时，€10,000 的交易只要欺诈概率超过 0.1% 就值得调查。","lessonId":"dsfb-10","lessonPage":41,"lessonPageTitle":"Cost-sensitive decision-making"},{"id":"s5-q424","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":424,"level":"真题同型 · 500 题强化","question":"What is the general cost-sensitive classification threshold T_CS for p(1|x)?","questionZh":"针对 p(1|x) 的通用成本敏感分类阈值 T_CS 是什么？","options":["(cb00 − cb10) / (cb11 − cb10 + cb00 − cb01)","(cb11 − cb01) / (cb00 − cb10)","cb01 / cb10","0.5 regardless of costs"],"optionZh":["(cb00 − cb10) / (cb11 − cb10 + cb00 − cb01)","(cb11 − cb01) / (cb00 − cb10)","cb01 / cb10","0.5，与成本无关"],"answer":0,"explanation":"A 正确：令两个 PEP 相等，并用 p(0|x) = 1 − p(1|x) 解出阈值，即得 A。分子是“把真 0 判错”的代价，分母是两种判错代价之和。","lessonId":"dsfb-10","lessonPage":42,"lessonPageTitle":"Cost-sensitive decision-making"},{"id":"s5-q425","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":425,"level":"真题同型 · 500 题强化","question":"For the German credit CB matrix cb00 = 0, cb01 = −5, cb10 = −1, cb11 = 0, what is T_CS?","questionZh":"德国信贷 CB 矩阵 cb00 = 0、cb01 = −5、cb10 = −1、cb11 = 0，T_CS 是多少？","options":["0.5","0.2","0.833","0.167"],"optionZh":["0.5","0.2","0.833","0.167"],"answer":3,"explanation":"D 正确：T_CS = (0 − (−1)) / (0 − (−1) + 0 − (−5)) = 1/6 ≈ 0.167。在这个概率下，预测好和预测坏的期望利润都是 −0.833，正好打平。","lessonId":"dsfb-10","lessonPage":43,"lessonPageTitle":"Case: credit scoring"},{"id":"s5-q426","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":426,"level":"真题同型 · 500 题强化","question":"A CB matrix has cb00 = 0, cb01 = −9, cb10 = −1, cb11 = 0. What is the cost-sensitive threshold T_CS?","questionZh":"CB 矩阵为 cb00 = 0、cb01 = −9、cb10 = −1、cb11 = 0，成本敏感阈值 T_CS 是多少？","options":["0.9","0.111","0.1","0.5"],"optionZh":["0.9","0.111","0.1","0.5"],"answer":2,"explanation":"C 正确：T_CS = (0 + 1) / (0 + 1 + 0 + 9) = 1/10 = 0.1。漏判的代价是误判的 9 倍，所以只要正类概率超过 10% 就该预测为正类。B 是 1/9，忘了分母要加上分子那一项。","lessonId":"dsfb-10","lessonPage":43,"lessonPageTitle":"Case: credit scoring"},{"id":"s5-q427","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":427,"level":"真题同型 · 500 题强化","question":"Misclassification costs are equal: cb01 = cb10 = −1 and cb00 = cb11 = 0. What is T_CS?","questionZh":"两种误分类成本相等：cb01 = cb10 = −1，cb00 = cb11 = 0。T_CS 是多少？","options":["0","1","0.25","0.5"],"optionZh":["0","1","0.25","0.5"],"answer":3,"explanation":"D 正确：T_CS = 1 / (1 + 1) = 0.5。这说明常用的 0.5 阈值其实隐含了“两种错误代价相等”的假设。","lessonId":"dsfb-10","lessonPage":43,"lessonPageTitle":"Case: credit scoring"},{"id":"s5-q428","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":428,"level":"真题同型 · 500 题强化","question":"Which statement comparing the empirical threshold T* and the theoretical threshold T_CS is TRUE?","questionZh":"关于经验阈值 T* 和理论阈值 T_CS 的比较，哪项说法正确？","options":["They are always identical.","T_CS requires a test set with labels, T* does not.","They may differ, for instance when the model's probability estimates are poorly calibrated.","T* can only be obtained for fraud detection."],"optionZh":["它们总是相同。","T_CS 需要带标签的测试集，T* 不需要。","它们可能不同，例如模型的概率估计校准较差时。","T* 只能用于欺诈检测。"],"answer":2,"explanation":"C 正确：T_CS 假设模型输出的概率是准确的；T* 在真实数据上试出来，会自动修正概率偏差。B 反了：T* 需要带标签的数据去试，T_CS 只用公式。","lessonId":"dsfb-10","lessonPage":42,"lessonPageTitle":"Cost-sensitive decision-making"},{"id":"s5-q429","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":429,"level":"真题同型 · 500 题强化","question":"Which statement about Predicted Expected Profit (P-EP) and Actual Expected Profit (A-EP) is TRUE?","questionZh":"关于预测期望利润（P-EP）与实际期望利润（A-EP），哪项说法正确？","options":["Both require the actual class to be known.","P-EP is used to evaluate a model across instances; A-EP is used to decide on a prediction.","P-EP is used to decide on the optimal prediction for a new instance; A-EP uses the known actual class to evaluate predictions.","They are mathematically identical."],"optionZh":["两者都需要已知真实类别。","P-EP 用于跨实例评估模型；A-EP 用于决定预测。","P-EP 用于为新实例决定最优预测；A-EP 利用已知真实类别评估预测。","两者在数学上完全相同。"],"answer":2,"explanation":"C 正确：P-EP 固定“预测类别”，看 CB 矩阵的一行，用于事前决策；A-EP 固定“实际类别”，看 CB 矩阵的一列，用于事后评估。B 把两者说反了。","lessonId":"dsfb-10","lessonPage":44,"lessonPageTitle":"Expected Profit"},{"id":"s5-q430","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":430,"level":"真题同型 · 500 题强化","question":"For an observation with predicted class ŷ = 0, the P-EP is calculated as:","questionZh":"对预测类别 ŷ = 0 的观测，P-EP 的计算方式是：","options":["p(0|x)·cb00 + p(1|x)·cb01","p(0|x)·cb00 + p(1|x)·cb10","p(0|x)·cb10 + p(1|x)·cb11","cb00 + cb01"],"optionZh":["p(0|x)·cb00 + p(1|x)·cb01","p(0|x)·cb00 + p(1|x)·cb10","p(0|x)·cb10 + p(1|x)·cb11","cb00 + cb01"],"answer":0,"explanation":"A 正确：预测为 0，看 CB 矩阵第 0 行（cb00、cb01），分别乘以真实为 0、1 的概率。B 是实际 y = 0 时的 A-EP（看第 0 列）。","lessonId":"dsfb-10","lessonPage":44,"lessonPageTitle":"Expected Profit"},{"id":"s5-q431","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":431,"level":"真题同型 · 500 题强化","question":"Which statement is NOT true?","questionZh":"哪项说法不正确？","options":["The average profit depends on the threshold used to turn probability estimates into class predictions.","The empirical, profit-maximizing threshold can be different from the theoretical, cost-sensitive threshold.","A two-threshold point strategy involves humans in the middle score range where positives and negatives overlap.","The higher the accuracy of a predictive model, the higher the average profit."],"optionZh":["平均利润依赖于把概率转成类别预测的阈值。","经验利润最大化阈值可能与理论成本敏感阈值不同。","双阈值策略让人工参与正负类重叠的中间分数区间。","预测模型准确率越高，平均利润就越高。"],"answer":3,"explanation":"D 不正确：准确率把两类错误一视同仁，而利润按代价加权。准确率更高的模型可能犯了更多昂贵的错误，利润反而更低。A、B、C 都是讲义内容。","lessonId":"dsfb-10","lessonPage":45,"lessonPageTitle":"Question"},{"id":"s5-q432","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":432,"level":"真题同型 · 500 题强化","question":"Which statement about the cost matrix C used for Misclassification Cost (MC) is TRUE?","questionZh":"关于用于计算误分类成本（MC）的成本矩阵 C，哪项说法正确？","options":["Positive values represent benefits and negative values represent costs.","It is unrelated to the CB matrix.","It must always have zeros on the off-diagonal.","Positive values represent costs and negative values represent benefits."],"optionZh":["正值代表收益，负值代表成本。","它与 CB 矩阵无关。","它的非对角线必须为 0。","正值代表成本，负值代表收益。"],"answer":3,"explanation":"D 正确：C 矩阵与 CB 矩阵符号相反：P ↔ MC，AP ↔ AC，AAEP ↔ AEC。C 反了：通常是对角线（判对）为 0，只记录误分类成本。","lessonId":"dsfb-10","lessonPage":47,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q433","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":433,"level":"真题同型 · 500 题强化","question":"For instance-dependent fraud costs (C_FN,i = A_i, C_FP = C_TP = Ca, C_TN = 0), the expected cost of transaction i with actual class y_i and predicted class ŷ_i is:","questionZh":"在实例相关的欺诈成本下（C_FN,i = A_i，C_FP = C_TP = Ca，C_TN = 0），实际类别 y_i、预测类别 ŷ_i 的交易 i 的成本是：","options":["y_i(1 − ŷ_i)A_i + ŷ_i·Ca","(1 − y_i)ŷ_i·A_i","y_i·ŷ_i·A_i − Ca","ŷ_i·A_i + y_i·Ca"],"optionZh":["y_i(1 − ŷ_i)A_i + ŷ_i·Ca","(1 − y_i)ŷ_i·A_i","y_i·ŷ_i·A_i − Ca","ŷ_i·A_i + y_i·Ca"],"answer":0,"explanation":"A 正确：只有“真欺诈被放行”（y = 1、ŷ = 0）才损失 A_i；只要预测为欺诈（ŷ = 1）就付调查费 Ca，不论真假。B、C、D 都把条件搭配错了。","lessonId":"dsfb-10","lessonPage":48,"lessonPageTitle":"C Actual class"},{"id":"s5-q434","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":434,"level":"真题同型 · 500 题强化","question":"How does CSLogit differ from standard logistic regression?","questionZh":"CSLogit 与标准逻辑回归有何不同？","options":["CSLogit uses a different link function than the sigmoid.","CSLogit replaces the likelihood by the average expected cost plus a regularization term as the objective function.","CSLogit does not produce probability estimates.","CSLogit can only use class-dependent costs."],"optionZh":["CSLogit 使用 sigmoid 以外的连接函数。","CSLogit 用“平均期望成本 + 正则项”替代似然作为目标函数。","CSLogit 不产生概率估计。","CSLogit 只能使用类别相关成本。"],"answer":1,"explanation":"B 正确：模型形式仍是逻辑回归（仍输出概率），只是训练目标从最大似然改为最小化 AEC + λ‖β‖₁。D 错：它的卖点正是能用实例相关成本。","lessonId":"dsfb-10","lessonPage":49,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q435","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":435,"level":"真题同型 · 500 题强化","question":"What type of regularization term is included in the CSLogit objective function on the slides?","questionZh":"讲义中 CSLogit 的目标函数包含哪种正则项？","options":["L2 (ridge)","Dropout","L1 (LASSO)","No regularization"],"optionZh":["L2（岭回归）","Dropout","L1（LASSO）","无正则化"],"answer":2,"explanation":"C 正确：L = AEC(β0, β) + λ‖β‖₁，即 LASSO 的 L1 范数，用于控制模型复杂度并可把不重要变量的系数压为 0。","lessonId":"dsfb-10","lessonPage":49,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q436","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":436,"level":"真题同型 · 500 题强化","question":"Why can CSLogit be trained by gradient-based optimization of the average expected cost, whereas average profit at a fixed threshold is hard to optimize directly?","questionZh":"为什么 CSLogit 可以用梯度方法优化平均期望成本，而固定阈值下的平均利润很难直接优化？","options":["Because expected cost uses probabilities and is smooth in the parameters, whereas thresholded predictions make profit a step function.","Because average profit is always zero.","Because expected cost does not depend on costs.","Because CSLogit has no parameters."],"optionZh":["因为期望成本用概率计算，对参数是平滑的；而阈值化预测让利润变成阶梯函数。","因为平均利润总是 0。","因为期望成本不依赖成本。","因为 CSLogit 没有参数。"],"answer":0,"explanation":"A 正确：阈值化后的预测只有 0/1，参数微小变化不改变利润，梯度为 0 或不存在。用概率 p(1|x) 代替硬预测，期望成本对参数可导。这也回答了讲义第 46 页“为什么评估指标常与训练目标不同”。","lessonId":"dsfb-10","lessonPage":49,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q437","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":437,"level":"真题同型 · 500 题强化","question":"What is the baseline model f0 used for the Savings measure in fraud detection?","questionZh":"欺诈检测中 Savings 指标使用的基准模型 f0 是什么？","options":["A model that predicts all transactions as fraud.","A perfect model.","A model that predicts all transactions as no fraud.","A random model."],"optionZh":["把所有交易都判为欺诈的模型。","完美模型。","把所有交易都判为非欺诈的模型。","随机模型。"],"answer":2,"explanation":"C 正确：f0 相当于“不用检测模型、全部放行”，它的误分类成本就是所有被盗金额之和 Σ y_i A_i。Savings 衡量模型比这个基准省下了多少。","lessonId":"dsfb-10","lessonPage":51,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q438","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":438,"level":"真题同型 · 500 题强化","question":"The total stolen amount without a model is €100,000. With model f, the misclassification cost is €40,000. What are the Savings?","questionZh":"不使用模型时被盗总额为 €100,000，使用模型 f 后误分类成本为 €40,000。Savings 是多少？","options":["40%","60%","€60,000","1.5"],"optionZh":["40%","60%","€60,000","1.5"],"answer":1,"explanation":"B 正确：Savings = (MC(f0) − MC(f)) / MC(f0) = (100,000 − 40,000) / 100,000 = 60%。它是相对比例，不是金额，所以 C 不对。","lessonId":"dsfb-10","lessonPage":51,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q439","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":439,"level":"真题同型 · 500 题强化","question":"Which statement about the Savings measure is FALSE?","questionZh":"关于 Savings 指标，哪项说法是错误的？","options":["Savings is the relative reduction in misclassification cost compared to using no detection model.","A perfect model with Ca > 0 obtains Savings below 100%.","Savings can never be negative, because the model is compared to an empty model.","Savings uses the total stolen amount as denominator."],"optionZh":["Savings 是相对于不使用检测模型时误分类成本的相对减少。","若 Ca > 0，完美模型的 Savings 也低于 100%。","Savings 不可能为负，因为模型是与空模型比较的。","Savings 以被盗总额为分母。"],"answer":2,"explanation":"C 错误：如果模型拦截大量正常交易，调查费总和可能超过被盗金额，MC(f) > MC(f0)，Savings 就为负。B 正确：完美模型也要为每笔欺诈付 Ca，所以达不到 100%。","lessonId":"dsfb-10","lessonPage":51,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q440","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":440,"level":"真题同型 · 500 题强化","question":"In the transfer fraud experiment on the slides (1,068,781 transactions, 631 fraud cases), why is accuracy an unsuitable evaluation measure?","questionZh":"讲义中的转账欺诈实验（1,068,781 笔交易，631 笔欺诈），为什么准确率不适合作为评估指标？","options":["Because the data set is too large to compute accuracy.","Because fraud is only about 0.06% of transactions, so predicting \"no fraud\" for all gives near-perfect accuracy while detecting nothing.","Because accuracy requires instance-dependent costs.","Because logistic regression cannot output accuracy."],"optionZh":["因为数据量太大，无法计算准确率。","因为欺诈只占约 0.06%，全部预测“非欺诈”就能得到接近完美的准确率，却什么也没检测到。","因为准确率需要实例相关成本。","因为逻辑回归无法输出准确率。"],"answer":1,"explanation":"B 正确：631 / 1,068,781 ≈ 0.06%，全判为正常就有 99.94% 的准确率。加上每笔交易金额不同，必须用 Savings 这类按金额计算的指标。","lessonId":"dsfb-10","lessonPage":52,"lessonPageTitle":"CSLogit: Cost-Sensitive Logistic Regression"},{"id":"s5-q441","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Chapter 10: Cost-sensitive Evaluation, Decision-making and Learning","number":441,"level":"真题同型 · 500 题强化","question":"Which statement about the overall approach of Chapter 10 is TRUE?","questionZh":"关于第 10 章的整体思路，哪项说法正确？","options":["Cost-sensitive learning is only possible after threshold tuning.","Costs can be taken into account at three stages: evaluation (e.g., MP), decision-making (e.g., T_CS), and learning (e.g., CSLogit).","Cost-sensitive methods only apply to fraud detection.","A model trained with likelihood cannot be used for cost-sensitive decisions."],"optionZh":["只有先做阈值调整才能进行成本敏感学习。","成本可以在三个阶段被考虑：评估（如 MP）、决策（如 T_CS）和学习（如 CSLogit）。","成本敏感方法只适用于欺诈检测。","用似然训练的模型不能用于成本敏感决策。"],"answer":1,"explanation":"B 正确：本章四节对应“定义成本 → 按利润评估 → 按期望利润决策 → 训练时纳入成本”。D 错：普通逻辑回归配合阈值调整或 T_CS 也能做成本敏感决策。","lessonId":"dsfb-10","lessonPage":46,"lessonPageTitle":"4. Cost-sensitive Learning with CSLogit"},{"id":"s5-q442","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":442,"level":"真题同型 · 500 题强化","question":"Which of the following is NOT one of the \"Five C's\" of the judgmental approach to credit scoring?","questionZh":"以下哪项不是信用评分判断法“五个 C”之一？","options":["Character","Capacity","Collateral","Correlation"],"optionZh":["Character（品格）","Capacity（能力）","Collateral（抵押）","Correlation（相关性）"],"answer":3,"explanation":"D 不是：五个 C 是 character、capital、collateral、capacity、condition。统计方法则基于输入变量与违约风险之间的多元相关性建模。","lessonId":"credit-01","lessonPage":8,"lessonPageTitle":"Approaches to credit scoring:"},{"id":"s5-q443","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":443,"level":"真题同型 · 500 题强化","question":"Which is NOT a benefit of statistical credit scoring models listed in the lecture?","questionZh":"以下哪项不是讲义列出的统计信用评分模型的好处？","options":["Speed and accuracy","Consistency","Reduced operating costs","Elimination of all default risk"],"optionZh":["速度与准确度","一致性","降低运营成本","消除所有违约风险"],"answer":3,"explanation":"D 不是：模型只能更好地评估和管理风险，不能消除风险。讲义第 9 页还列出减少坏账损失和改进组合管理。","lessonId":"credit-01","lessonPage":9,"lessonPageTitle":"Benefits of statistical credit scoring models"},{"id":"s5-q444","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":444,"level":"真题同型 · 500 题强化","question":"In the application scorecard example, an applicant aged 32 (120 points), a known customer (180 points), with salary $1,150 (160 points) applies. The cut-off is 500. What is the decision?","questionZh":"申请评分卡例子中，申请人 32 岁（120 分），是老客户（180 分），工资 $1,150（160 分）。分数线为 500。决定是什么？","options":["Accept, since 460 > 400","Accept, since 540 ≥ 500","Refuse, since 460 < 500","The score cannot be computed"],"optionZh":["批准，因为 460 > 400","批准，因为 540 ≥ 500","拒绝，因为 460 < 500","无法计算得分"],"answer":2,"explanation":"C 正确：120 + 180 + 160 = 460，低于 500 分数线，拒绝授信。评分卡把每个特征的取值转换成分数再相加。","lessonId":"credit-01","lessonPage":11,"lessonPageTitle":"Application scoring"},{"id":"s5-q445","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":445,"level":"真题同型 · 500 题强化","question":"Which default definition is fixed in the Basel accord for application scoring?","questionZh":"Basel 协议为申请评分确定的违约定义是什么？","options":["Any late payment of one day","Payment arrears between 90 and 180 days, typically 90 days past due","Bankruptcy filing only","A credit score below 500"],"optionZh":["任何一天的逾期","90 到 180 天之间的逾期，通常为逾期 90 天","只有申请破产","信用分低于 500"],"answer":1,"explanation":"B 正确：讲义第 12、48 页：违约指债务人不太可能偿还或逾期超过 90 天，此前美国 120/180 天、英国 90/180 天的例外已不再允许。","lessonId":"credit-01","lessonPage":12,"lessonPageTitle":"Evaluate default risk at time applicant applies for loan!"},{"id":"s5-q446","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":446,"level":"真题同型 · 500 题强化","question":"Application scoring is described as which type of prediction?","questionZh":"申请评分被描述为哪种类型的预测？","options":["Videoclip-to-snapshot prediction","Snapshot-to-snapshot prediction","Snapshot-to-videoclip prediction","Time series forecasting"],"optionZh":["视频片段到快照的预测","快照到快照的预测","快照到视频片段的预测","时间序列预测"],"answer":1,"explanation":"B 正确：讲义第 14 页：用贷款发放时（t0）的一个快照（申请数据、征信数据），预测约 18 个月后（t18）的另一个快照（是否违约）。A 是行为评分。","lessonId":"credit-01","lessonPage":14,"lessonPageTitle":"Application scoring"},{"id":"s5-q447","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":447,"level":"真题同型 · 500 题强化","question":"Why is behavioural scoring called \"videoclip-to-snapshot\" prediction?","questionZh":"为什么行为评分被称为“视频片段到快照”的预测？","options":["Because it uses videos of customers","Because it predicts several future time points","Because it uses only data at the time of application","Because it summarizes customer behaviour over an observation window to predict the default status at the end of a performance window"],"optionZh":["因为它使用客户的视频","因为它预测多个未来时点","因为它只用申请时的数据","因为它概括客户在观察窗口内的行为，来预测表现窗口结束时的违约状态"],"answer":3,"explanation":"D 正确：讲义第 17 页：例如用过去 12 个月的账户余额趋势、逾期历史等，预测之后 12 个月是否违约。","lessonId":"credit-01","lessonPage":17,"lessonPageTitle":"Behavioral scoring"},{"id":"s5-q448","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":448,"level":"真题同型 · 500 题强化","question":"Which is NOT a use of behavioural scoring mentioned in the lecture?","questionZh":"以下哪项不是讲义提到的行为评分用途？","options":["Setting credit limits","Collection strategies","Approving loans for brand-new applicants without history","Debt provisioning and profit scoring"],"optionZh":["设定信用额度","催收策略","为没有任何历史的新申请人审批贷款","债务拨备和利润评分"],"answer":2,"explanation":"C 不是：新申请人没有行为历史，只能用申请评分。行为评分还用于授权超额、续期审核等。","lessonId":"credit-01","lessonPage":18,"lessonPageTitle":"Behavioral scoring can be used for:"},{"id":"s5-q449","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":449,"level":"真题同型 · 500 题强化","question":"Which statement about application scoring is TRUE?","questionZh":"关于申请评分，哪项说法正确？","options":["Its main aim is ranking customers, so calibrated probabilities of default are not needed for loan approval.","It requires lifetime PDs.","It uses the full payment history of the applicant at the bank.","It typically uses more than 100 characteristics."],"optionZh":["主要目的是给客户排序，所以审批贷款不需要校准过的违约概率。","它需要终身 PD。","它使用申请人在银行的全部还款历史。","它通常使用 100 个以上特征。"],"answer":0,"explanation":"A 正确：讲义第 15 页：排序足以决定批准谁；但 Basel 要求校准好的 PD，所以需要后续的评级与校准（第 49 页）。D 错：通常 10–15 个特征。","lessonId":"credit-01","lessonPage":15,"lessonPageTitle":"New customers applying for credit"},{"id":"s5-q450","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":450,"level":"真题同型 · 500 题强化","question":"In Altman's z-model for public industrial companies, how is a firm with Z = 1.5 classified?","questionZh":"在适用于上市工业企业的 Altman z 模型中，Z = 1.5 的企业如何分类？","options":["Healthy, since Z > 1","In the grey zone","Healthy, since Z > 1.2","Unhealthy, since Z < 1.81"],"optionZh":["健康，因为 Z > 1","处于灰色区域","健康，因为 Z > 1.2","不健康，因为 Z < 1.81"],"answer":3,"explanation":"D 正确：讲义第 20 页：Z > 2.99 为健康，Z < 1.81 为不健康，中间是灰色区域。Altman 模型用线性判别分析，针对企业（不是零售）。","lessonId":"credit-01","lessonPage":20,"lessonPageTitle":"Predict bankrupt versus non-bankrupt given accounting ratios and other info"},{"id":"s5-q451","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":451,"level":"真题同型 · 500 题强化","question":"For which kind of portfolio is the agency rating approach typically used?","questionZh":"评级机构方法通常用于哪类组合？","options":["Low default portfolios such as sovereign exposures, where too few defaults exist to build a statistical model","Credit card portfolios with millions of customers","Mortgage portfolios with rich default data","Portfolios where the bank already has internal PD models"],"optionZh":["低违约组合，例如主权敞口，违约太少无法建统计模型","有数百万客户的信用卡组合","有大量违约数据的房贷组合","银行已有内部 PD 模型的组合"],"answer":0,"explanation":"A 正确：讲义第 22 页：没有违约数据时，购买穆迪、标普、惠誉等的外部评级，每个评级附带历史违约率，近似 PD。","lessonId":"credit-01","lessonPage":22,"lessonPageTitle":"In case no default data?"},{"id":"s5-q452","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":452,"level":"真题同型 · 500 题强化","question":"How does the shadow rating approach work?","questionZh":"影子评级方法如何运作？","options":["The bank uses only expert opinions.","Ratings are purchased for a representative sample of obligors, and a statistical model (e.g., cumulative logistic regression) is developed to estimate ratings for other obligors.","Ratings are copied from competitors.","Ratings are assigned randomly."],"optionZh":["银行只使用专家意见。","为有代表性的样本购买评级，再建立统计模型（如累积逻辑回归）来估计其他债务人的评级。","从竞争对手那里抄评级。","随机分配评级。"],"answer":1,"explanation":"B 正确：讲义第 25 页：用偿付能力、流动性、股价等变量“模仿”评级机构的评级，适用于没有外部评级的债务人。","lessonId":"credit-01","lessonPage":25,"lessonPageTitle":"Purchase ratings from ratings agency for representative sample of obligors"},{"id":"s5-q453","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":453,"level":"真题同型 · 500 题强化","question":"Which type of capital is the capital a bank should hold according to the Basel Accords?","questionZh":"根据 Basel 协议银行应持有的资本属于哪种类型？","options":["Economic capital","Actual capital","Regulatory capital","Tier 3 capital"],"optionZh":["经济资本","实际资本","监管资本","三级资本"],"answer":2,"explanation":"C 正确：讲义第 29 页：监管资本由监管规定；经济资本基于银行内部建模；实际资本是银行真正持有的。","lessonId":"credit-01","lessonPage":29,"lessonPageTitle":"Regulatory capital"},{"id":"s5-q454","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":454,"level":"真题同型 · 500 题强化","question":"Under Basel I, what is the capital requirement for a $100 mortgage with a 50% risk weight?","questionZh":"在 Basel I 下，风险权重 50% 的 $100 房贷需要多少资本？","options":["$50","$8","$0.50","$4"],"optionZh":["$50","$8","$0.50","$4"],"answer":3,"explanation":"D 正确：RWA = 100 × 50% = $50，资本 = 8% × 50 = $4。A 是风险加权资产，B 是没有乘风险权重。","lessonId":"credit-01","lessonPage":31,"lessonPageTitle":"Fixed risk weights (RW)"},{"id":"s5-q455","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":455,"level":"真题同型 · 500 题强化","question":"Which was a reason for introducing a new accord after Basel I?","questionZh":"以下哪项是在 Basel I 之后引入新协议的理由？","options":["Basel I took the solvency of the debtor into account too precisely.","Basel I used fixed risk weights that did not reflect the solvency of the debtor and allowed regulatory arbitrage.","Basel I covered operational risk too heavily.","Basel I required internal models."],"optionZh":["Basel I 对债务人偿付能力考虑得太精细。","Basel I 使用固定风险权重，不反映债务人的偿付能力，导致监管套利。","Basel I 对操作风险覆盖过重。","Basel I 要求内部模型。"],"answer":1,"explanation":"B 正确：讲义第 32 页：固定权重下，同为企业贷款的 AAA 公司和濒临破产的公司资本要求相同；还未充分承认抵押品，也没有覆盖操作风险和市场风险。","lessonId":"credit-01","lessonPage":32,"lessonPageTitle":"Need for new Accord"},{"id":"s5-q456","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":456,"level":"真题同型 · 500 题强化","question":"Which are the three pillars of Basel II?","questionZh":"Basel II 的三大支柱是什么？","options":["PD, LGD and EAD","Credit risk, market risk and liquidity risk","Tier 1, Tier 2 and Tier 3 capital","Minimum capital requirement, supervisory review process, and market discipline and public disclosure"],"optionZh":["PD、LGD 和 EAD","信用风险、市场风险和流动性风险","一级、二级、三级资本","最低资本要求、监管审查、市场纪律与信息披露"],"answer":3,"explanation":"D 正确：讲义第 33 页。第一支柱涵盖信用风险（标准法、IRB 初级/高级法）、操作风险和市场风险。","lessonId":"credit-01","lessonPage":33,"lessonPageTitle":"Credit risk"},{"id":"s5-q457","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":457,"level":"真题同型 · 500 题强化","question":"Under Basel III (by 2015), what is the minimum common equity Tier 1 capital ratio?","questionZh":"根据 Basel III（到 2015 年），普通股一级资本充足率的最低要求是多少？","options":["2% of RWA","4% of RWA","8% of RWA","4.5% of RWA"],"optionZh":["RWA 的 2%","RWA 的 4%","RWA 的 8%","RWA 的 4.5%"],"answer":3,"explanation":"D 正确：讲义第 36 页：普通股一级资本 4.5%（Basel II 为 2%），一级资本 6%（Basel II 为 4%），另加 2.5% 的资本留存缓冲和 0%–2.5% 的逆周期缓冲。","lessonId":"credit-01","lessonPage":36,"lessonPageTitle":"Basel III"},{"id":"s5-q458","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":458,"level":"真题同型 · 500 题强化","question":"What does the non-risk-based leverage ratio introduced in Basel III require?","questionZh":"Basel III 引入的非风险杠杆率要求什么？","options":["Tier 1 capital of at least 3% of total assets, including off-balance-sheet exposures","Tier 1 capital of at least 8% of RWA","No capital for mortgages","Capital equal to expected loss"],"optionZh":["一级资本至少为总资产（含表外敞口）的 3%","一级资本至少为 RWA 的 8%","房贷不需要资本","资本等于预期损失"],"answer":0,"explanation":"A 正确：讲义第 37 页。不按风险加权，正是为了应对内部模型的模型风险（第 35 页）。","lessonId":"credit-01","lessonPage":37,"lessonPageTitle":"Basel III"},{"id":"s5-q459","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":459,"level":"真题同型 · 500 题强化","question":"Under the standardized approach, a corporate loan of $1 million rated AA has a risk weight of 20%. What is the regulatory capital?","questionZh":"在标准法下，一笔 $100 万、评级 AA 的企业贷款风险权重为 20%。监管资本是多少？","options":["$200,000","$80,000","$16,000","$1,600"],"optionZh":["$200,000","$80,000","$16,000","$1,600"],"answer":2,"explanation":"C 正确：RWA = 1,000,000 × 20% = $200,000，资本 = 8% × 200,000 = $16,000。A 是 RWA。","lessonId":"credit-01","lessonPage":43,"lessonPageTitle":"Example: corporate loan of $1 mio with maturity 5 years, unsecured, S&P rating AA"},{"id":"s5-q460","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":460,"level":"真题同型 · 500 题强化","question":"Under the standardized approach, a non-mortgage retail loan of €10,000 has a 75% risk weight. What is the regulatory capital?","questionZh":"在标准法下，一笔 €10,000 的非房贷零售贷款风险权重为 75%。监管资本是多少？","options":["€800","€600","€7,500","€750"],"optionZh":["€800","€600","€7,500","€750"],"answer":1,"explanation":"B 正确：RWA = 10,000 × 75% = €7,500，资本 = 8% × 7,500 = €600。房贷的风险权重为 35%。","lessonId":"credit-01","lessonPage":42,"lessonPageTitle":"For retail"},{"id":"s5-q461","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":461,"level":"真题同型 · 500 题强化","question":"Which is a limitation of the Basel standardized approach?","questionZh":"以下哪项是 Basel 标准法的局限？","options":["It requires banks to estimate PD, LGD and EAD internally.","It does not use any risk weights.","It relies on external ratings with inconsistencies and insufficient coverage, without an individual risk profile or LGD/EAD.","It is only allowed for retail exposures."],"optionZh":["它要求银行内部估计 PD、LGD 和 EAD。","它不用任何风险权重。","它依赖外部评级，存在不一致和覆盖不足，没有个体风险画像，也没有 LGD/EAD。","它只允许用于零售敞口。"],"answer":2,"explanation":"C 正确：讲义第 43 页。很多中小企业和个人根本没有外部评级。A 描述的是 IRB 法。","lessonId":"credit-01","lessonPage":43,"lessonPageTitle":"Example: corporate loan of $1 mio with maturity 5 years, unsecured, S&P rating AA"},{"id":"s5-q462","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":462,"level":"真题同型 · 500 题强化","question":"Which four key risk parameters does the IRB approach rely on?","questionZh":"IRB 法依赖哪四个关键风险参数？","options":["AUC, Gini, KS and lift","Tier 1, Tier 2, RWA and leverage","Support, confidence, lift and conviction","PD, EAD, LGD and maturity (M)"],"optionZh":["AUC、Gini、KS 和提升度","一级资本、二级资本、RWA 和杠杆","支持度、置信度、提升度和确信度","PD、EAD、LGD 和期限（M）"],"answer":3,"explanation":"D 正确：讲义第 44 页：PD 是一年违约概率，EAD 是违约时的敞口金额，LGD 是违约损失占敞口的比例，M 是期限。","lessonId":"credit-01","lessonPage":44,"lessonPageTitle":"IRB approach relies on four key risk parameters"},{"id":"s5-q463","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":463,"level":"真题同型 · 500 题强化","question":"In the foundation IRB approach, which parameter does the bank estimate internally?","questionZh":"在 IRB 初级法中，银行内部估计哪个参数？","options":["Only PD; LGD and EAD are set by the regulator","PD, LGD and EAD","Only LGD","None"],"optionZh":["只有 PD；LGD 和 EAD 由监管机构设定","PD、LGD 和 EAD","只有 LGD","都不估计"],"answer":0,"explanation":"A 正确：讲义第 45 页。高级 IRB 法三个都由银行内部估计（B）。零售敞口不允许用初级法，必须内部估计 LGD 和 EAD。","lessonId":"credit-01","lessonPage":45,"lessonPageTitle":"Internal Ratings Based (IRB) Approach"},{"id":"s5-q464","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":464,"level":"真题同型 · 500 题强化","question":"A bank's model estimates a one-year PD of 0.01% for its best rating. Which PD must be used under Basel IRB?","questionZh":"银行模型对最好评级估计的一年 PD 为 0.01%。在 Basel IRB 下必须使用哪个 PD？","options":["0.01%","0.03%","1%","0%"],"optionZh":["0.01%","0.03%","1%","0%"],"answer":1,"explanation":"B 正确：讲义第 48 页：PD 取一年估计 PD 与 0.03% 中的较大者（下限）。","lessonId":"credit-01","lessonPage":48,"lessonPageTitle":"For both"},{"id":"s5-q465","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":465,"level":"真题同型 · 500 题强化","question":"For corporate exposures under IRB, what is the minimum number of ratings required?","questionZh":"IRB 下企业敞口最少需要多少个评级？","options":["At least 7 ratings for non-defaulted obligors plus 1 rating for defaulters","Exactly 3 ratings","No minimum","At least 15 ratings for defaulters"],"optionZh":["至少 7 个非违约评级，外加 1 个违约评级","恰好 3 个评级","没有最低要求","违约者至少 15 个评级"],"answer":0,"explanation":"A 正确：讲义第 47 页。零售则没有最低评级数，但要避免债务人过度集中在某个评级中。","lessonId":"credit-01","lessonPage":47,"lessonPageTitle":"For corporates, central governments and central banks (wholesale)"},{"id":"s5-q466","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":466,"level":"真题同型 · 500 题强化","question":"Which statement about the Basel IRB risk weight function is TRUE?","questionZh":"关于 Basel IRB 风险权重函数，哪项说法正确？","options":["Regulatory capital K·EAD covers only unexpected loss; expected loss (PD·LGD) is covered by provisions.","Regulatory capital equals expected plus unexpected loss.","The risk weight function does not depend on PD.","RWA must always be computed first."],"optionZh":["监管资本 K·EAD 只覆盖非预期损失；预期损失（PD·LGD）由拨备覆盖。","监管资本等于预期损失加非预期损失。","风险权重函数不依赖 PD。","必须先计算 RWA。"],"answer":0,"explanation":"A 正确：讲义第 64 页。D 错：RWA 不必显式计算，可以反推：RWA = 12.5 × K × EAD。真题第 18 题 C 选项就是 B 这个错误说法。","lessonId":"credit-01","lessonPage":64,"lessonPageTitle":"Regulatory Capital = K (PD, LGD) . EAD"},{"id":"s5-q467","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":467,"level":"真题同型 · 500 题强化","question":"Under IRB, a loan has K = 0.05 and EAD = €200,000. What are the regulatory capital and the RWA?","questionZh":"在 IRB 下，一笔贷款 K = 0.05，EAD = €200,000。监管资本和 RWA 分别是多少？","options":["€10,000 and €80,000","€16,000 and €200,000","€10,000 and €125,000","€10,000 and €2,500,000"],"optionZh":["€10,000 和 €80,000","€16,000 和 €200,000","€10,000 和 €125,000","€10,000 和 €2,500,000"],"answer":2,"explanation":"C 正确：资本 = K × EAD = 0.05 × 200,000 = €10,000；RWA = 12.5 × 10,000 = €125,000（因为资本 = 8% × RWA）。","lessonId":"credit-01","lessonPage":64,"lessonPageTitle":"Regulatory Capital = K (PD, LGD) . EAD"},{"id":"s5-q468","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":468,"level":"真题同型 · 500 题强化","question":"For a credit card portfolio (PD 3%, LGD 50%, EAD $10,000), a 10% overestimate of LGD or of EAD increases capital from $343.7 to $378.0, while a 10% overestimate of PD gives $367.3. What does this show?","questionZh":"某信用卡组合（PD 3%，LGD 50%，EAD $10,000）中，LGD 或 EAD 高估 10% 都让资本从 $343.7 增至 $378.0，而 PD 高估 10% 只增至 $367.3。这说明什么？","options":["Capital is linear in LGD and EAD, but not in PD.","Capital is linear in PD only.","PD has no impact on capital.","All three parameters have identical effects."],"optionZh":["资本对 LGD 和 EAD 是线性的，对 PD 则不是。","资本只对 PD 线性。","PD 对资本没有影响。","三个参数的影响完全相同。"],"answer":0,"explanation":"A 正确：$378.0 正好是 $343.7 的 1.1 倍，而 PD 的影响不到 10%。这也是真题第 16 题 B 选项“对 PD 和 LGD 都线性”为什么是错的。","lessonId":"credit-01","lessonPage":66,"lessonPageTitle":"Consider credit card portfolio with PD = 0.03; LGD = 0.5; EAD =$10,000"},{"id":"s5-q469","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":469,"level":"真题同型 · 500 题强化","question":"In the Vasicek model underlying the Basel formula, at what confidence level is the economy put in its worst state?","questionZh":"在 Basel 公式所依据的 Vasicek 模型中，经济被放在什么置信水平的最差状态？","options":["95%","99%","99.9%","50%"],"optionZh":["95%","99%","99.9%","50%"],"answer":2,"explanation":"C 正确：讲义第 60–61 页：设定 α* 使 P(PD ≤ α*) = 99.9%，即资本不足以吸收非预期损失的概率为千分之一（千年一遇）。","lessonId":"credit-01","lessonPage":60,"lessonPageTitle":"𝑓 and εi mutually independent standard normally distributed variables"},{"id":"s5-q470","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":470,"level":"真题同型 · 500 题强化","question":"In the Merton/Vasicek model, what does a higher asset correlation ρ imply?","questionZh":"在 Merton/Vasicek 模型中，更高的资产相关性 ρ 意味着什么？","options":["A higher probability of common (joint) defaults, and thus more capital needed","Lower capital requirements","Independent defaults","A lower PD for each obligor"],"optionZh":["共同违约的概率更高，因此需要更多资本","更低的资本要求","违约相互独立","每个债务人的 PD 更低"],"answer":0,"explanation":"A 正确：讲义第 58 页。资产价值一起涨跌，坏年景时会有很多人同时违约。不同业务分段的 ρ 不同，例如住房按揭 0.15，循环零售 0.04。","lessonId":"credit-01","lessonPage":58,"lessonPageTitle":"Higher asset correlation"},{"id":"s5-q471","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":471,"level":"真题同型 · 500 题强化","question":"Under IFRS 9, which PD is used for a loan whose credit risk has increased significantly since initial recognition?","questionZh":"在 IFRS 9 下，自初始确认以来信用风险显著增加的贷款使用哪种 PD？","options":["12-month PD (stage 1)","No PD is needed","Through-the-cycle one-year PD","Lifetime PD (stage 2)"],"optionZh":["12 个月 PD（第一阶段）","不需要 PD","跨周期一年 PD","终身 PD（第二阶段）"],"answer":3,"explanation":"D 正确：讲义第 70 页：第一阶段（风险未显著增加）用 12 个月 PD；第二阶段（显著增加）和第三阶段（已减值）用终身 PD。","lessonId":"credit-01","lessonPage":70,"lessonPageTitle":"Stages of credit risk"},{"id":"s5-q472","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":472,"level":"真题同型 · 500 题强化","question":"Which comparison between Basel and IFRS 9 is TRUE?","questionZh":"关于 Basel 与 IFRS 9 的比较，哪项说法正确？","options":["Basel uses a point-in-time rating philosophy; IFRS 9 uses through-the-cycle.","Basel uses downturn LGD with direct and indirect costs; IFRS 9 uses best-estimate LGD with only direct costs.","IFRS 9 requires conservative regulatory PD floors.","Basel focuses only on expected loss for provisioning."],"optionZh":["Basel 用时点评级理念，IFRS 9 用跨周期理念。","Basel 用包含直接和间接成本的衰退期 LGD；IFRS 9 用只含直接成本的最佳估计 LGD。","IFRS 9 要求保守的监管 PD 下限。","Basel 只关注拨备用的预期损失。"],"answer":1,"explanation":"B 正确：讲义第 71 页。A 说反了：Basel 偏 TTC（长期平均 PD），IFRS 9 偏 PIT（报告日）。C 是 Basel 的特点。D 是 IFRS 9 的特点。","lessonId":"credit-01","lessonPage":71,"lessonPageTitle":"IFRS9"},{"id":"s5-q473","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 1","number":473,"level":"真题同型 · 500 题强化","question":"What fundamental change did IFRS 9 introduce in provisioning?","questionZh":"IFRS 9 在拨备上带来了什么根本性变化？","options":["A move from incurred credit losses to expected credit losses","A move from expected losses to incurred losses","The removal of PD models","Provisioning only for unexpected loss"],"optionZh":["从“已发生信用损失”转向“预期信用损失”","从预期损失转向已发生损失","取消 PD 模型","只为非预期损失计提拨备"],"answer":0,"explanation":"A 正确：讲义第 69 页：由信贷危机推动，取代 IAS 39，2018 年 1 月 1 日生效。美国对应的是 CECL（2020 年）。","lessonId":"credit-01","lessonPage":69,"lessonPageTitle":"Accounting standard put forward by International Accounting Standards Board"},{"id":"s5-q474","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":474,"level":"真题同型 · 500 题强化","question":"In the Basel IRB model architecture, what happens at level 2?","questionZh":"在 Basel IRB 模型架构中，第 2 层做什么？","options":["Data collection","Building the scorecard with logistic regression","Validating the IT system","Defining risk ratings and calibrating PD/LGD/EAD per rating"],"optionZh":["数据收集","用逻辑回归建立评分卡","验证 IT 系统","定义风险评级，并为每个评级校准 PD/LGD/EAD"],"answer":3,"explanation":"D 正确：讲义第 5 页：第 0 层是数据（内部、外部、专家判断），第 1 层是模型（如逻辑回归评分卡），第 2 层是评级定义与校准。","lessonId":"credit-02","lessonPage":5,"lessonPageTitle":"Basel IRB model architecture"},{"id":"s5-q475","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":475,"level":"真题同型 · 500 题强化","question":"Why does PD model development require \"reject inference\"?","questionZh":"为什么 PD 模型开发需要“拒绝推断”？","options":["Because outcomes of rejected applicants are unobserved, so a model trained on accepted applicants only suffers from sample selection bias","Because rejected applicants always default","Because the regulator rejects most models","Because WOE cannot be computed"],"optionZh":["因为被拒申请人的结果观察不到，只用被批准申请人训练的模型存在样本选择偏差","因为被拒申请人总会违约","因为监管机构拒绝大多数模型","因为无法计算 WOE"],"answer":0,"explanation":"A 正确：讲义第 8 页把 reject inference 列为数据预处理要点，对应第 2 章讲的样本选择偏差。同页还提到要覆盖经济周期（Basel 要求 5/7 年数据）。","lessonId":"credit-02","lessonPage":8,"lessonPageTitle":"Data preprocessing"},{"id":"s5-q476","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":476,"level":"真题同型 · 500 题强化","question":"According to the benchmarking study cited in the lecture, which AUC range is typical for behavioural credit scoring?","questionZh":"根据讲义引用的基准研究，行为信用评分的典型 AUC 范围是多少？","options":["50%–60%","70%–85%","95%–100%","80%–90%"],"optionZh":["50%–60%","70%–85%","95%–100%","80%–90%"],"answer":3,"explanation":"D 正确：讲义第 11 页：申请评分 AUC 约 70%–85%（B），行为评分约 80%–90%，因为行为数据更丰富（真题第 17 题 A 选项）。","lessonId":"credit-02","lessonPage":11,"lessonPageTitle":"Performance benchmarks"},{"id":"s5-q477","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":477,"level":"真题同型 · 500 题强化","question":"Why are ratings defined on top of credit scores?","questionZh":"为什么要在信用分之上定义评级？","options":["Because scores cannot be computed for all customers","Because scores are considered too fine-grained; a rating is a homogeneous pool of obligors with similar default risk","Because ratings are required to train logistic regression","Because ratings replace PD calibration"],"optionZh":["因为不能为所有客户计算分数","因为分数被认为太细；评级是违约风险相似的债务人组成的同质池","因为训练逻辑回归需要评级","因为评级取代了 PD 校准"],"answer":1,"explanation":"B 正确：讲义第 13 页。而且评级比单个分数更稳定，资本要求也更稳定（真题第 18 题 B 选项）。","lessonId":"credit-02","lessonPage":13,"lessonPageTitle":"Defining ratings"},{"id":"s5-q478","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":478,"level":"真题同型 · 500 题强化","question":"Which approach to defining ratings sets the boundaries so that default rates double per rating decrease?","questionZh":"哪种评级定义方法把边界设成每降一级违约率翻倍？","options":["Mapping onto the rating agency scale","Equal-width binning of scores","Exponential risk evolution","Random assignment"],"optionZh":["映射到评级机构的等级","分数等宽分箱","指数风险演进","随机分配"],"answer":2,"explanation":"C 正确：讲义第 15 页。另一种方法（第 14 页）是让内部评级尽量模仿评级机构报告的一年违约率。","lessonId":"credit-02","lessonPage":15,"lessonPageTitle":"Defining ratings"},{"id":"s5-q479","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":479,"level":"真题同型 · 500 题强化","question":"Which statement about point-in-time (PIT) ratings is TRUE?","questionZh":"关于时点（PIT）评级，哪项说法正确？","options":["They take into account obligor-specific, cyclical and non-cyclical information, so ratings change rapidly with the macroeconomic situation.","They only use non-cyclical information.","They show no rating migration in a downturn.","They are the philosophy preferred by Basel."],"optionZh":["它们考虑债务人特有的、周期性和非周期性信息，所以评级随宏观经济快速变化。","它们只用非周期性信息。","经济下行时评级不迁移。","它们是 Basel 偏好的理念。"],"answer":0,"explanation":"A 正确：讲义第 17 页：PIT 的 PD 是对未来 12 个月违约的最佳估计，适合 IFRS 9。B、C 描述的是 TTC，Basel 偏向 TTC（D 错）。","lessonId":"credit-02","lessonPage":17,"lessonPageTitle":"Rating philosophy"},{"id":"s5-q480","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":480,"level":"真题同型 · 500 题强化","question":"When the economy enters a downturn, what happens under a through-the-cycle (TTC) rating system?","questionZh":"经济进入下行期时，跨周期（TTC）评级系统会发生什么？","options":["Obligors migrate to lower ratings, and default rates per rating stay unchanged.","Capital requirements fall sharply.","All obligors move to the default rating.","Obligors keep their ratings, while the actual default rate in each rating increases."],"optionZh":["债务人迁移到较低评级，各评级的违约率保持不变。","资本要求大幅下降。","所有债务人都进入违约评级。","债务人保持原评级，但各评级的实际违约率上升。"],"answer":3,"explanation":"D 正确：讲义第 18 页。A 描述的是 PIT：降级导致资本要求上升，有顺周期性。TTC 评级稳定，资本要求更稳定。","lessonId":"credit-02","lessonPage":18,"lessonPageTitle":"Point-in-Time Ratings Through-the-Cycle Ratings"},{"id":"s5-q481","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":481,"level":"真题同型 · 500 题强化","question":"Which statement about PD calibration is TRUE?","questionZh":"关于 PD 校准，哪项说法正确？","options":["It only needs one year of data.","It assigns a PD to each rating using long-term historical data, with calibrated PD = best estimate PD + conservative add-on, and requires at least 5 years of data.","It ignores sampling variability.","It is done before building the scorecard."],"optionZh":["只需要一年数据。","它用长期历史数据为每个评级分配 PD，校准 PD = 最佳估计 PD + 保守附加，并要求至少 5 年数据。","它忽略抽样波动。","它在建立评分卡之前进行。"],"answer":1,"explanation":"B 正确：讲义第 19 页：校准要应对抽样波动、外部经济状况和内部因素（如策略变化）三种变异来源。","lessonId":"credit-02","lessonPage":19,"lessonPageTitle":"PD calibration"},{"id":"s5-q482","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":482,"level":"真题同型 · 500 题强化","question":"A rating has an observed default rate of 2% over 10,000 obligors. Using a binomial confidence interval with N⁻¹(0.99) ≈ 2.33, what is the conservative (upper) PD?","questionZh":"某评级在 10,000 名债务人中观察到违约率 2%。用二项置信区间，N⁻¹(0.99) ≈ 2.33，保守（上限）PD 是多少？","options":["≈ 4.33%","≈ 2.33%","≈ 2.00%","≈ 2.03%"],"optionZh":["≈ 4.33%","≈ 2.33%","≈ 2.00%","≈ 2.03%"],"answer":1,"explanation":"B 正确：标准误 = √(0.02 × 0.98 / 10,000) = √0.00000196 ≈ 0.0014；上限 = 2% + 2.33 × 0.14% ≈ 2% + 0.33% = 2.33%。A 直接把 2.33 当百分点加了上去。","lessonId":"credit-02","lessonPage":20,"lessonPageTitle":"PD calibration"},{"id":"s5-q483","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":483,"level":"真题同型 · 500 题强化","question":"How can default rates be linked to the macro-economy for PD calibration?","questionZh":"PD 校准时如何把违约率与宏观经济联系起来？","options":["Using clustering","Using association rules","Using time series models such as DR_t = β0 + β1·DR_{t−1} + β2·GDP_{t−1} + …","It is not possible."],"optionZh":["用聚类","用关联规则","用时间序列模型，例如 DR_t = β0 + β1·DR_{t−1} + β2·GDP_{t−1} + …","不可能。"],"answer":2,"explanation":"C 正确：讲义第 21 页：GDP、通胀、失业率等关键变量加上滞后效应，可用 ARIMA、GARCH 等（第 7 章）。需要足够长的历史数据。","lessonId":"credit-02","lessonPage":21,"lessonPageTitle":"PD calibration"},{"id":"s5-q484","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":484,"level":"真题同型 · 500 题强化","question":"How is LGD related to the recovery rate?","questionZh":"LGD 与回收率是什么关系？","options":["LGD = recovery rate","LGD = recovery rate × EAD","LGD = 1 / recovery rate","LGD = 1 − recovery rate"],"optionZh":["LGD = 回收率","LGD = 回收率 × EAD","LGD = 1 / 回收率","LGD = 1 − 回收率"],"answer":3,"explanation":"D 正确：讲义第 23 页。Basel 规定使用经济损失，包括处置抵押品的折价、行政成本、法律成本和时间延迟等。","lessonId":"credit-02","lessonPage":23,"lessonPageTitle":"LGD according to Basel"},{"id":"s5-q485","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":485,"level":"真题同型 · 500 题强化","question":"In a workout, the EAD is 100 and the discounted net recoveries amount to 70. What is the workout LGD?","questionZh":"在催收处置中，EAD 为 100，折现后的净回收为 70。处置法 LGD 是多少？","options":["70%","100%","0%","30%"],"optionZh":["70%","100%","0%","30%"],"answer":3,"explanation":"D 正确：回收率 = 70/100 = 70%，LGD = 1 − 70% = 30%。A 是回收率。处置法（workout LGD）是最常用的 LGD 测量方法。","lessonId":"credit-02","lessonPage":24,"lessonPageTitle":"Ways of measuring LGD"},{"id":"s5-q486","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":486,"level":"真题同型 · 500 题强化","question":"How should incomplete workouts be handled when constructing an LGD data set?","questionZh":"构建 LGD 数据集时应如何处理尚未完成的处置案例？","options":["Always delete them.","Always assume full recovery.","Use their information in a conservative manner, e.g., with expert or predictive models estimating the final LGD.","Treat them as non-defaults."],"optionZh":["总是删除。","总是假设全部回收。","以保守的方式利用它们的信息，例如用专家或预测模型估计最终 LGD。","当作未违约处理。"],"answer":2,"explanation":"C 正确：讲义第 26–27 页引用 EBA 指引。用当前 LGD 作估计非常保守；有些银行忽略 3 或 5 年后的回收。A 会让数据偏向处置快的案例，B 太乐观。","lessonId":"credit-02","lessonPage":27,"lessonPageTitle":"Incomplete workouts"},{"id":"s5-q487","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":487,"level":"真题同型 · 500 题强化","question":"At what moment should LGD risk drivers be measured according to the EBA guidelines?","questionZh":"根据 EBA 指引，LGD 风险驱动因素应在什么时间点测量？","options":["At the end of the workout","Before the moment of default, typically at least 1 year before","At the moment the loan is fully repaid","It does not matter"],"optionZh":["处置结束时","违约之前，通常至少提前 1 年","贷款全部还清时","无所谓"],"answer":1,"explanation":"B 正确：讲义第 28 页：LGD 估计要用在尚未违约的敞口上，所以必须用违约前就能得到的信息，否则就是数据泄露。","lessonId":"credit-02","lessonPage":28,"lessonPageTitle":"LGD drivers"},{"id":"s5-q488","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":488,"level":"真题同型 · 500 题强化","question":"How does a higher loan-to-value (LTV) ratio typically affect LGD?","questionZh":"更高的贷款价值比（LTV）通常如何影响 LGD？","options":["It increases LGD, since the collateral buffer is smaller relative to the loan","It decreases LGD","It has no effect on LGD","It only affects PD"],"optionZh":["提高 LGD，因为抵押品相对贷款的缓冲更小","降低 LGD","对 LGD 没有影响","只影响 PD"],"answer":0,"explanation":"A 正确：LTV = 贷款 / 抵押品价值。LTV 越高，违约后卖掉抵押品能覆盖的部分越少（真题第 17 题 B 选项）。","lessonId":"credit-02","lessonPage":30,"lessonPageTitle":"LGD drivers"},{"id":"s5-q489","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":489,"level":"真题同型 · 500 题强化","question":"What is a problem of modelling LGD with ordinary linear regression?","questionZh":"用普通线性回归建模 LGD 有什么问题？","options":["It cannot use any input variables.","It cannot be estimated with OLS.","It always overfits.","Its output is not bounded between 0 and 1."],"optionZh":["它不能使用任何输入变量。","它不能用 OLS 估计。","它总会过拟合。","它的输出不受 0 到 1 的限制。"],"answer":3,"explanation":"D 正确：讲义第 36 页。LGD 是比例，但线性回归可能预测出负数或大于 1 的值。Beta 回归或带权重的逻辑回归可以解决这个问题。","lessonId":"credit-02","lessonPage":36,"lessonPageTitle":"Linear regression"},{"id":"s5-q490","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":490,"level":"真题同型 · 500 题强化","question":"What is the correct order of steps in beta regression for LGD?","questionZh":"LGD 的 Beta 回归步骤正确顺序是什么？","options":["Linear regression → estimate α and β → transform with cumulative Beta → inverse normal","Estimate α and β (method of moments) → transform LGDs with the cumulative Beta distribution → apply the inverse standard normal → linear regression","Logistic regression → WOE binning → Beta transformation","Inverse normal → cumulative Beta → linear regression → method of moments"],"optionZh":["线性回归 → 估计 α 和 β → 用累积 Beta 变换 → 逆正态","估计 α 和 β（矩估计） → 用累积 Beta 分布变换 LGD → 应用逆标准正态 → 线性回归","逻辑回归 → WOE 分箱 → Beta 变换","逆正态 → 累积 Beta → 线性回归 → 矩估计"],"answer":1,"explanation":"B 正确：讲义第 42 页的四步。预测时反过来做，就能得到落在 0–1 之间的 LGD 预测。Beta 分布很灵活，双峰 LGD 可以用 Beta 混合模型。","lessonId":"credit-02","lessonPage":42,"lessonPageTitle":"Beta regression"},{"id":"s5-q491","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":491,"level":"真题同型 · 500 题强化","question":"An account has LGD = 25%. How is it represented to model LGD with logistic regression?","questionZh":"某账户 LGD = 25%。用逻辑回归建模 LGD 时如何表示它？","options":["As a single \"bad\" observation","It is removed from the data.","As one \"bad\" observation with weight 0.25 and one \"good\" observation with weight 0.75","As 25 bad observations and 25 good observations"],"optionZh":["作为一个“坏”观测","从数据中删除。","作为一个权重 0.25 的“坏”观测和一个权重 0.75 的“好”观测","作为 25 个坏观测和 25 个好观测"],"answer":2,"explanation":"C 正确：讲义第 43 页：把连续 LGD 转换成带权重的二元变量（或复制观测），然后可以做 WOE 分箱、用 IV 选变量，再建成 LGD 评分卡。","lessonId":"credit-02","lessonPage":43,"lessonPageTitle":"Logistic Regression"},{"id":"s5-q492","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":492,"level":"真题同型 · 500 题强化","question":"Why are advanced LGD models such as neural networks and random forests mainly used for benchmarking?","questionZh":"为什么神经网络和随机森林等高级 LGD 模型主要用于基准比较？","options":["Because they cannot be trained on LGD data","Because they are always less accurate","Because regulators forbid them completely","Because of their loss of interpretability"],"optionZh":["因为它们无法在 LGD 数据上训练","因为它们总是更不准确","因为监管机构完全禁止","因为它们失去了可解释性"],"answer":3,"explanation":"D 正确：讲义第 45 页。监管模型需要解释清楚，黑盒模型可以用来检验简单模型是否丢失了太多预测力。","lessonId":"credit-02","lessonPage":45,"lessonPageTitle":"Advanced LGD models"},{"id":"s5-q493","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":493,"level":"真题同型 · 500 题强化","question":"What does Basel II require for LGD estimates in the advanced approach?","questionZh":"在高级法中，Basel II 对 LGD 估计有什么要求？","options":["The LGD must reflect economic downturn conditions where necessary to capture the relevant risks.","LGD must equal the long-run average PD.","LGD must always be 45%.","LGD must be estimated without collateral information."],"optionZh":["必要时 LGD 必须反映经济衰退情形，以捕捉相关风险。","LGD 必须等于长期平均 PD。","LGD 必须总是 45%。","估计 LGD 时不能用抵押品信息。"],"answer":0,"explanation":"A 正确：讲义第 47 页（Basel II 第 468 段）。如果各时期 LGD 没有差异，就不需要衰退期校准；如果有差异，用衰退期的数值。","lessonId":"credit-02","lessonPage":47,"lessonPageTitle":"LGD calibration"},{"id":"s5-q494","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":494,"level":"真题同型 · 500 题强化","question":"Which statement about EAD for on-balance-sheet exposures such as term loans is TRUE?","questionZh":"关于表内敞口（如定期贷款）的 EAD，哪项说法正确？","options":["EAD can be adjusted downward for expected prepayments.","EAD equals the credit limit.","EAD is zero.","EAD is the nominal outstanding balance, floored at the current outstanding balance, with no downward adjustment for amortization or prepayments."],"optionZh":["EAD 可以因预期提前还款向下调整。","EAD 等于信用额度。","EAD 为零。","EAD 是名义未偿余额，以当前未偿余额为下限，不因摊还或提前还款向下调整。"],"answer":3,"explanation":"D 正确：讲义第 49 页。对信用卡、循环贷等表外敞口，还要考虑未提取的额度。","lessonId":"credit-02","lessonPage":49,"lessonPageTitle":"Defining EAD"},{"id":"s5-q495","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":495,"level":"真题同型 · 500 题强化","question":"A credit card has a limit of €10,000, a drawn balance of €4,000 and a CCF of 0.5. What is the EAD?","questionZh":"某信用卡额度为 €10,000，已用余额 €4,000，CCF 为 0.5。EAD 是多少？","options":["€5,000","€4,000","€10,000","€7,000"],"optionZh":["€5,000","€4,000","€10,000","€7,000"],"answer":3,"explanation":"D 正确：EAD = 已用 + CCF × (额度 − 已用) = 4,000 + 0.5 × 6,000 = €7,000。A 错把 CCF 乘在了整个额度上。保守做法是 CCF = 1，即 EAD = 额度（C）。","lessonId":"credit-02","lessonPage":50,"lessonPageTitle":"Defining EAD"},{"id":"s5-q496","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":496,"level":"真题同型 · 500 题强化","question":"A defaulted facility had a limit of €10,000 and a drawn amount of €4,000 at Δt before default; at default, the EAD was €8,000. What is the realized CCF?","questionZh":"一笔违约的授信在违约前 Δt 时额度为 €10,000、已用 €4,000；违约时 EAD 为 €8,000。实现的 CCF 是多少？","options":["0.8","0.4","0.5","≈ 0.67"],"optionZh":["0.8","0.4","0.5","≈ 0.67"],"answer":3,"explanation":"D 正确：CCF = (EAD − 已用)/(额度 − 已用) = (8,000 − 4,000)/(10,000 − 4,000) = 4,000/6,000 ≈ 0.67。A 是 EAD/额度。","lessonId":"credit-02","lessonPage":51,"lessonPageTitle":"Need 2 time points"},{"id":"s5-q497","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":497,"level":"真题同型 · 500 题强化","question":"How does the fixed-horizon method construct an EAD development sample?","questionZh":"固定期限法如何构建 EAD 开发样本？","options":["It groups defaults into calendar periods, e.g., 1 November to 31 October.","It uses only the last day before default.","It collects risk factors and drawn/undrawn amounts a fixed interval (e.g., 12 months) before the default date, regardless of the calendar date of default.","It uses no time information."],"optionZh":["按日历期间（如 11 月 1 日到次年 10 月 31 日）对违约分组。","只用违约前最后一天的数据。","在违约日之前固定时长（如 12 个月）收集风险因素和已用/未用金额，与违约发生的日历日期无关。","不使用任何时间信息。"],"answer":2,"explanation":"C 正确：讲义第 53 页。A 描述的是队列法（cohort method，第 52 页）。两者都是为了解决计算 CCF 时 Δt 怎么选的问题。","lessonId":"credit-02","lessonPage":53,"lessonPageTitle":"EAD development sample"},{"id":"s5-q498","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":498,"level":"真题同型 · 500 题强化","question":"The distribution of observed CCFs is U-shaped. Which modelling approach does the lecture suggest?","questionZh":"观察到的 CCF 分布呈 U 形。讲义建议用什么建模方法？","options":["k-means clustering","Apriori","A beta-distribution-based approach, as for LGD","The naïve forecasting method"],"optionZh":["k-means 聚类","Apriori","与 LGD 一样，基于 Beta 分布的方法","朴素预测法"],"answer":2,"explanation":"C 正确：讲义第 54 页：EAD 建模的第 1 层可以用分段、回归或两阶段模型，U 形分布可以借用 LGD 部分的 Beta 分布方法。评价指标与 LGD 相同（R²、MSE、CAP 曲线等）。","lessonId":"credit-02","lessonPage":54,"lessonPageTitle":"EAD modeling"},{"id":"s5-q499","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":499,"level":"真题同型 · 500 题强化","question":"In the credit risk model lifecycle (EBA/GL/2017/16), which step follows calibration?","questionZh":"在信用风险模型生命周期（EBA/GL/2017/16）中，校准之后是哪一步？","options":["Independent validation","Deleting the model","Collecting new data only","Supervisory approval before validation"],"optionZh":["独立验证","删除模型","只收集新数据","先监管批准再验证"],"answer":0,"explanation":"A 正确：讲义第 56 页的顺序：1 模型开发、2 校准、3 独立验证、4 监管批准、5 内部流程实施、6 应用风险参数、7 估计值复核（回测与基准比较）。验证团队类似审计，独立于开发团队。","lessonId":"credit-02","lessonPage":56,"lessonPageTitle":"Independent validation:"},{"id":"s5-q500","source":"按 SERIES 4 真题风格与上传课件原创 · 500 题强化（非原题复刻）","course":"Credit Risk Modeling: lecture 2","number":500,"level":"真题同型 · 500 题强化","question":"A loan has PD = 2%, LGD = 40% and EAD = €50,000. What is the expected loss?","questionZh":"一笔贷款 PD = 2%，LGD = 40%，EAD = €50,000。预期损失是多少？","options":["€20,000","€1,000","€400","€4,000"],"optionZh":["€20,000","€1,000","€400","€4,000"],"answer":2,"explanation":"C 正确：EL = PD × LGD × EAD = 0.02 × 0.4 × 50,000 = €400。A 只算了 LGD × EAD（违约后的损失），B 只算了 PD × EAD。预期损失由拨备覆盖，监管资本覆盖非预期损失。","lessonId":"credit-02","lessonPage":10,"lessonPageTitle":"Scorecard: logistic regression"}];
